# ============================================================================
#  make_zhstdlib2.ps1 -- 步骤 2：乙类（自含实现）头 -> 中文版
#
#  每个头两层（方案 §〇）：
#    第一层  标准::细节::<中文名>实现   —— 抄自微软，成员名全中文
#    第二层  标准::<中文名>             —— 在中文的基础上派生，补回英文原名
#
#  六步配方（方案 §3.1）+ 编译器当改名校对（§3.2 坑②）：
#    1 换守卫  2 搬名域 标准::细节 + 使用 名域 std;   3 类型名   4 成员名
#    5 手工理嵌套名域   6 追加派生层
#
#  ⚠ 三条已经踩过的坑（都写进方案）：
#    · 不能整文件全局字符串替换（会把 #include <xpolymorphic_allocator.h> 改坏）
#    · 成员名会撞借用类型的同名成员 -> 让编译器报行列号，按【字节】偏移改回
#    · 中文标识符不能以数字开头（后置构词：字符16位）
#
#  用法：powershell -File tools\make_zhstdlib2.ps1 -Header typeindex
# ============================================================================
param([string] $Header = 'typeindex', [switch] $ExportJson)

$ErrorActionPreference = 'Stop'
$root  = Split-Path -Parent $MyInvocation.MyCommand.Path | Split-Path -Parent
$cxx   = Join-Path $root 'build\Release\bin\chinese++.exe'
$vsInc = 'C:\Program Files\Microsoft Visual Studio\2022\Community\VC\Tools\MSVC\14.44.35207\include'
$out   = Join-Path $root 'zhstdlib'
$utf8  = New-Object System.Text.UTF8Encoding($false)

# ---------------------------------------------------------------------------
#  表：每个头一条。加新头 = 加一条。
# ---------------------------------------------------------------------------
$H = @{
  'mutex' = @{
    zh      = '互斥量'
    # §16.29「乙」：顺带引真头 —— 只写 `#包含 <互斥量>` 也能用 std::mutex
    realInclude = @('mutex')
    types   = [ordered]@{
      '_Mutex_base'            = '_互斥量基类'
      # §16.38 第 ① 类（类内别名）
      '_Indices'               = '_下标集'
      'mutex'                  = '互斥量实现'
      'condition_variable'     = '条件变量实现'
      'condition_variable_any' = '条件变量任意实现'
      'unique_lock'            = '独占锁实现'
      'lock_guard'             = '锁守卫实现'
      'adopt_lock_t'           = '接管锁类型'
      'defer_lock_t'           = '延迟锁类型'
      'try_to_lock_t'          = '尝试锁类型'
      # 本文件自己定义的内部自由函数：被 `_STD X` 限定引用。
      # 普通成员表覆盖不到它们（步 4c 只处理 types+data），必须在这里登记改名，
      # 否则报「namespace 'std' 中没有名为 '_Unlock_locks' 的成员」。
      # 编译器自己的提示就是答案：「你是不是想直接写 '_Try_lock_from_locks'？」
      '_Unlock_locks'          = '_解锁各锁'
      '_Try_lock_from_locks'   = '_从各锁尝试加锁'
      # §16.28：本文件自己的内部小工具，长名无二义
      '_Unlock_call_guard'     = '_解锁调用守卫'
      '_Unlock_one_guard'      = '_解锁单个守卫'
      '_UInt_is_zero'          = '_无符号整数为零'
      # §16.28：scoped_lock 是【公开 std 类】却一直留在拷贝层没翻，
      #   于是中文侧【根本没有对应类型】（标准::scoped_lock / 标准::作用域锁 都不存在）。
      #   这是欠账，不是边界 —— 公开类必须中文在前（§一 第 1/3 条）。
      'scoped_lock'            = '作用域锁实现'
    }
    # ⚠ 注意：`mutex` 既是类名，也是 unique_lock 的成员函数名 —— 两者都变「互斥量实现」，
    #   于是 独占锁::互斥量实现() 读起来别扭但不歧义（记为妥协）。
    # §3.7.2 销账：<mutex> 正文包含 <xcall_once.h>，这里指向我们自己的汉语内部件，
    # 于是只用 <互斥量> 就能拿到 标准::一次标志 与 标准::一次调用。
    zhIncludes = @{ 'xcall_once.h' = '调用一次'; 'thread' = '线程' }
    members = [ordered]@{
      '_First' = '_首个'
      '_Last' = '_最后'
      '_Result' = '_结果'
      '_Rep' = '_表示';
      '_Pass_fn' = '_传递函数'
      '_Mymtx' = '_我的互斥量'
      '_Validate' = '_校验'
      '_Verify_ownership_levels' = '_校验所有权层级'
      '_Register' = '_注册'
      '_Unregister' = '_注销'
      '_Try_lock_range' = '_尝试加锁范围'
      '_Try_lock1' = '_尝试加锁1'
      '_Lock' = '_加锁'
      'lock' = '加锁'; 'unlock' = '解锁'; 'try_lock' = '尝试加锁'
      'try_lock_for' = '限时加锁'; 'try_lock_until' = '加锁至时刻'
      'native_handle' = '原生句柄'; 'owns_lock' = '持有锁'
      'release' = '释放'; 'swap' = '交换'
      'adopt_lock' = '接管锁'; 'defer_lock' = '延迟锁'; 'try_to_lock' = '尝试锁'
    }
    data    = [ordered]@{}
    # ⚠ 实测教训：不要照【标准文档】的 API 写派生层，要照【微软这个版本实际有的】写。
    #   · native_handle / native_handle_type 在 MSVC 里已被官方删除（GH-3820，
    #     <mutex> 第 75、615 行就写着 "have intentionally been removed"），
    #     照标准写就会生成 基类::原生句柄() -> 没有这个成员。
    #   · once_flag 也**不在** <mutex> 里（grep 原文 0 命中），
    #     照标准写就会生成 类型 一次标志 : 公开 细节::一次标志实现 -> 缺少 类名。
    derive  = @( @('lock','加锁'), @('try_lock','尝试加锁'), @('unlock','解锁') )
    stdHash = $false
    tparam  = @{ decl = ''; args = '' }
    # 一个头里有多个对外类 —— 主类由机制生成，其余在这里手写
    extra = @'

名域 标准 {

// 独占锁（std::unique_lock）
模板 <类型名 互斥类型>
类型 独占锁 : 公开 细节::独占锁实现<互斥类型> {
公开:
    使用 基类 = 细节::独占锁实现<互斥类型>;
    使用 基类::基类;
    模板 <类型名... 参数> 声明类型(自动) lock(参数&&... 值) { 返回 基类::加锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) try_lock(参数&&... 值) { 返回 基类::尝试加锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) unlock(参数&&... 值) { 返回 基类::解锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) owns_lock(参数&&... 值) 常量 { 返回 基类::持有锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) release(参数&&... 值) { 返回 基类::释放(static_cast<参数&&>(值)...); }
};

// 锁守卫（std::lock_guard）
模板 <类型名 互斥类型>
类型 锁守卫 : 公开 细节::锁守卫实现<互斥类型> {
公开:
    使用 基类 = 细节::锁守卫实现<互斥类型>;
    使用 基类::基类;
};

// 作用域锁（std::scoped_lock）
// ⚠ 它是【变参模板】（`template <class... _Mutexes>`），所以派生层也要带参数包。
//   它的存在本身是一条欠账的消除：此前 scoped_lock 留在拷贝层没翻，
//   中文侧根本没有这个类型（§16.28）。
模板 <类型名... 互斥类型集>
类型 作用域锁 : 公开 细节::作用域锁实现<互斥类型集...> {
公开:
    使用 基类 = 细节::作用域锁实现<互斥类型集...>;
    使用 基类::基类;
};

// 自由函数（这两个自由函数是 <mutex> 自己定义的，已随正文搬进 细节）
模板 <类型名 互斥类型> 内联 空型 加锁(互斥类型& 甲, 互斥类型& 乙) { 细节::加锁(甲, 乙); }

}  // 名域 标准
'@
    tests = @(
      @('只引中文头','#包含 <互斥量>`n整数 主函数(){ 标准::互斥量 甲; 甲.加锁(); 甲.解锁(); 标准::锁守卫<标准::互斥量> 卫(甲); 返回 0; }'),
      @('与微软原头并存','#包含 <互斥量>`n#包含 <mutex>`n整数 主函数(){ 标准::互斥量 甲; 甲.加锁(); std::mutex 乙; 乙.lock(); 乙.unlock(); 返回 0; }'),
      @('英文名与中文名并用 + 独占锁','#包含 <互斥量>`n整数 主函数(){ 标准::互斥量 甲; 标准::独占锁<标准::互斥量> 锁(甲); 布尔 有 = 锁.持有锁(); 布尔 有2 = 锁.owns_lock(); 锁.解锁(); 布尔 松了 = !锁.owns_lock(); 返回 (整数)(有 || 有2) - 1 + (松了 ? 0 : 1); }'),
      # ⚠ 用【内层花括号】把两个作用域锁的作用期分开：第一把在离开内层时解锁，
      #   第二把才去锁同一把互斥量。不分开写就是同一线程重复加锁（UB），
      #   测试会"过"但测的不是我们想测的东西。
      @('作用域锁（变参，中文侧此前根本没有这个类型）','#包含 <互斥量>`n整数 主函数(){ 标准::互斥量 甲; 标准::互斥量 乙; { 标准::作用域锁<标准::互斥量, 标准::互斥量> 两把(甲, 乙); } { 标准::作用域锁<标准::互斥量> 一把(甲); } { 标准::作用域锁<> 零把; } 返回 0; }')
    )
  }
  'shared_mutex' = @{
    zh      = '共享互斥量'
    realInclude = @('shared_mutex')   # §16.29「乙」
    # ⚠ types 的【第一个】= 派生层的基类（生成器 $cls = types.Values | Select -First 1）
    types   = [ordered]@{
      'shared_mutex'          = '共享互斥量实现'
      # §16.38 第 ① 类（类内别名）
      '_Read_cnt_t'           = '_读计数类型'
      'shared_timed_mutex'    = '限时共享互斥量实现'
      'shared_lock'           = '共享锁实现'
      # 跨头类型名：这几个译名是 <互斥量> / <条件变量> 定下的（方案 §3.8.2）
      'mutex'                 = '互斥量实现'
      'lock_guard'            = '锁守卫实现'
      'unique_lock'           = '独占锁实现'
      'condition_variable'    = '条件变量实现'
      # 三个 tag 类型也定义在 <mutex> 里
      'adopt_lock_t'          = '接管锁类型'
      'defer_lock_t'          = '延迟锁类型'
      'try_to_lock_t'         = '尝试锁类型'
    }
    # 已经抄完的头才开（步 0，见 §3.8.1）
    zhIncludes = @{ 'mutex' = '互斥量'; 'condition_variable' = '条件变量' }
    members = [ordered]@{
      '_Rep' = '_表示';
      '_Mymtx' = '_我的互斥量'
      'lock' = '加锁'; 'unlock' = '解锁'; 'try_lock' = '尝试加锁'
      'lock_shared' = '共享加锁'; 'unlock_shared' = '共享解锁'
      'try_lock_shared' = '尝试共享加锁'
      'try_lock_for' = '限时加锁'; 'try_lock_until' = '加锁至时刻'
      'try_lock_shared_for' = '限时共享加锁'; 'try_lock_shared_until' = '共享加锁至时刻'
      'owns_lock' = '持有锁'; 'release' = '释放'; 'swap' = '交换'
      # §16.79 本头**自己定义**的内部助手（实测 shared_mutex 里有定义；`_Lock` 在
      #   <mutex> 里也有 -> 按"定义方各自翻本头这份"处理；译名与 内存内部件 一致：
      #   `_Lock` 在那边已译作 `_加锁`，跨头译名守卫强制统一）。
      #   ⚠ `_Smtx_try_lock_exclusive/_shared` 与 `native_handle` 【本轮不动】：
      #     前两个在借来的 xthreads.h 里也有同名定义、后者是公开 API（要配 derive 补英文），
      #     留到下一轮与别的同类一起做。
      '_Lock' = '_加锁'
      '_Validate' = '_校验'
      # §16.80 `native_handle` 是**公开 API**（`std::shared_mutex::native_handle()`）——
      #   翻它的同时**必须**在 derive 里把英文补回（否则用户写 `甲.native_handle()` 就没了 =
      #   §16.41.2 说的"翻一半就是回归"）。它的正文调的是 `_Mtx_native_handle(...)`
      #   （另一个词，不受影响）。
      'native_handle' = '原生句柄'
    }
    # ⚠ `shared_lock::mutex()` 这个取值函数名和类型名 `mutex` 撞车：
    #   types 表先跑，`mutex` 已被改成 `互斥量实现`，所以它读作 互斥量实现()。
    #   与 <互斥量> 里 `unique_lock::mutex()` 是同一个妥协（方案 §六）。
    data    = [ordered]@{}
    derive  = @( @('lock','加锁'), @('unlock','解锁'), @('try_lock','尝试加锁'),
                 @('lock_shared','共享加锁'), @('unlock_shared','共享解锁'),
                 @('try_lock_shared','尝试共享加锁'),
                 @('native_handle','原生句柄') )
    stdHash = $false
    tparam  = @{ decl = ''; args = '' }
    extra = @'

名域 标准 {

// 限时共享互斥量（std::shared_timed_mutex）
类型 限时共享互斥量 : 公开 细节::限时共享互斥量实现 {
公开:
    使用 基类 = 细节::限时共享互斥量实现;
    使用 基类::基类;
    模板 <类型名... 参数> 声明类型(自动) lock(参数&&... 值) { 返回 基类::加锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) unlock(参数&&... 值) { 返回 基类::解锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) try_lock(参数&&... 值) { 返回 基类::尝试加锁(static_cast<参数&&>(值)...); }
    // ⚠ shared_lock 【没有】lock_shared/unlock_shared（那是 shared_mutex 的成员）。
    //   这两行是我凭空写的转发，一直被空测掩盖（见方案 §十五）。已删除。
    模板 <类型名... 参数> 声明类型(自动) try_lock_shared(参数&&... 值) { 返回 基类::尝试共享加锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) try_lock_for(参数&&... 值) { 返回 基类::限时加锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) try_lock_until(参数&&... 值) { 返回 基类::加锁至时刻(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) try_lock_shared_for(参数&&... 值) { 返回 基类::限时共享加锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) try_lock_shared_until(参数&&... 值) { 返回 基类::共享加锁至时刻(static_cast<参数&&>(值)...); }
};

// 共享锁（std::shared_lock）
模板 <类型名 互斥类型>
类型 共享锁 : 公开 细节::共享锁实现<互斥类型> {
公开:
    使用 基类 = 细节::共享锁实现<互斥类型>;
    使用 基类::基类;
    模板 <类型名... 参数> 声明类型(自动) lock(参数&&... 值) { 返回 基类::加锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) try_lock(参数&&... 值) { 返回 基类::尝试加锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) unlock(参数&&... 值) { 返回 基类::解锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) lock_shared(参数&&... 值) { 返回 基类::共享加锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) try_lock_shared(参数&&... 值) { 返回 基类::尝试共享加锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) unlock_shared(参数&&... 值) { 返回 基类::共享解锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) owns_lock(参数&&... 值) 常量 { 返回 基类::持有锁(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) release(参数&&... 值) { 返回 基类::释放(static_cast<参数&&>(值)...); }
};

}  // 名域 标准
'@
    tests = @(
      @('只引中文头','#包含 <共享互斥量>`n整数 主函数(){ 标准::共享互斥量 甲; { 甲.加锁(); 甲.解锁(); } { 甲.共享加锁(); 甲.共享解锁(); } 返回 0; }'),
      # §16.80 欠账销账：`native_handle` 是**公开 API**，翻它的同时靠 derive 补回英文 ——
      #   这条测试把【中文名】与【英文原名】都真调用一次（§16.64 判据：
      #   新翻的名字要有真调用测试，靠机制兜等于靠运气兜）。
      @('原生句柄 / native_handle 都真能调','#包含 <共享互斥量>`n整数 主函数(){ 标准::共享互斥量 甲; (空型)甲.原生句柄(); (空型)甲.native_handle(); 返回 0; }'),
      @('与微软原头并存','#包含 <共享互斥量>`n#包含 <shared_mutex>`n整数 主函数(){ 标准::共享互斥量 甲; 甲.加锁(); std::shared_mutex 乙; 乙.lock(); 返回 0; }'),
      @('英文名与中文名并用 + 共享锁','#包含 <共享互斥量>`n整数 主函数(){ 标准::共享互斥量 甲; 标准::共享锁<标准::共享互斥量> 锁(甲); 布尔 有 = 锁.持有锁(); 锁.解锁(); 锁.加锁(); 锁.unlock(); 布尔 松 = !锁.持有锁(); 返回 (整数)有 - 1 + (松 ? 0 : 1); }'),
      @('限时共享互斥量','#包含 <共享互斥量>`n整数 主函数(){ 标准::限时共享互斥量 甲; { 甲.加锁(); 甲.解锁(); } 布尔 好 = 甲.尝试共享加锁(); if (好) 甲.共享解锁(); 返回 0; }')
    )
  }
  'stop_token' = @{
    zh      = '停止令牌'
    realInclude = @('stop_token')   # §16.29「乙」
    # types 第一个 = 派生层基类（= 对外主类型）
    types   = [ordered]@{
      'stop_token'           = '停止令牌实现'
      'stop_source'          = '停止源实现'
      'stop_callback'        = '停止回调实现'
      'nostopstate_t'        = '无停止状态类型'
      '_Stop_state'          = '_停止状态'
      '_Stop_callback_base'  = '_停止回调基类'
      # §16.38 第 ① 类（类内别名）
      '_Callback_fn'         = '_回调函数指针'
    }
    members = [ordered]@{
      '_Store_and_unlock' = '_存储并解锁';
      '_Transfer_ownership' = '_转移所有权';
      'request_stop'   = '请求停止'
      'stop_requested' = '已请求停止'
      'stop_possible'  = '可停止'
      'get_token'      = '取令牌'
      # §16.68 本头**自己定义**的 `_Stop_state` / `_Stop_callback_base` 内部助手
      #   （实测只有 stop_token 有定义）-> 翻；它们不是公开 API，不需要派生层补英文。
      '_Attach'        = '_附着'
      '_Detach'        = '_脱离'
      '_Do_attach'     = '_执行附着'
      '_Invoke_by_stop' = '_按停止调用'
      # ⚠ `swap` 故意【不】改名（实测踩到）：
      #   原文 `_STD swap(_State, _Other._State)` 要的是 std::swap（交换内部指针）。
      #   一旦把 swap 改成 交换，步 4c 会把 `_STD 交换(...)` 去限定成 `交换(...)`，
      #   于是它解析到【同名的成员函数】交换(停止令牌实现&)，报
      #     "函数调用使用的实参太多；只应给出单个实参" / "调用非静态成员函数时没有对象实参"。
      #   判据：成员名出现在 `_STD X(...)` 里、而那个 X 本意是 std 的自由函数时，不能改名。
      # 内部件（同头自用，各自独立于公开名）
      '_Request_stop'   = '_请求停止'
      '_Stop_requested' = '_已请求停止'
      '_Stop_possible'  = '_可停止'
    ;
      '_Lock_and_load' = '_加锁并载入';

      '_Locked_pointer' = '_已加锁指针';
}
    zhIncludes = @{ 'xmemory' = '内存内部件' }
    data    = [ordered]@{}
    # ⚠ swap 不放进来：它是类内定义的 friend 自由函数，只能靠 ADL 找到，
    #   `基类::交换` 这种限定查找找不到它（生成器的转发用的是限定查找）。
    #   这与 <mutex>/<条件变量>/<共享互斥量> 的 derive 表一致（都没放 swap）。
    derive  = @( @('stop_requested','已请求停止'), @('stop_possible','可停止') )
    # ⚠ 抄来那层的成员返回的是【细节::停止令牌实现】，而对外类型是派生出来的
    #   标准::停止令牌 —— 派生类没有"从基类回来"的路，要手写接管构造。
    #   （同 <任意> 的 make_any 情形，见方案 §3.19.2。）
    deriveExtra = @'
    停止令牌(细节::停止令牌实现&& 内) noexcept : 基类(static_cast<细节::停止令牌实现&&>(内)) {}
    停止令牌(常量 细节::停止令牌实现& 内) : 基类(内) {}
'@
    stdHash = $false
    tparam  = @{ decl = ''; args = '' }
    extra = @'

名域 标准 {

// 顶层 tag 类型也要能在 标准 里直接写（成员转发机制只管类里的嵌套名）
使用 无停止状态类型 = 细节::无停止状态类型;

// 无停止状态（std::nostopstate）—— 它是个全局常量，不是类成员，所以手写
内联 常量表达式 无停止状态类型 无停止状态{};

// 停止源（std::stop_source）
类型 停止源 : 公开 细节::停止源实现 {
公开:
    使用 基类 = 细节::停止源实现;
    使用 基类::基类;
    模板 <类型名... 参数> 声明类型(自动) request_stop(参数&&... 值) { 返回 基类::请求停止(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) get_token(参数&&... 值) { 返回 基类::取令牌(static_cast<参数&&>(值)...); }
};

// 停止回调（std::stop_callback）
模板 <类型名 回调类型>
类型 停止回调 : 公开 细节::停止回调实现<回调类型> {
公开:
    使用 基类 = 细节::停止回调实现<回调类型>;
    使用 基类::基类;
};

}  // 名域 标准
'@
    tests = @(
      @('只引中文头','#包含 <停止令牌>`n整数 主函数(){ 标准::停止源 源; 标准::停止令牌 令 = 源.取令牌(); 布尔 好 = 令.可停止(); 源.请求停止(); 返回 (整数)好 - 1; }'),
      @('与微软原头并存','#包含 <停止令牌>`n#包含 <stop_token>`n整数 主函数(){ 标准::停止源 源; 源.请求停止(); std::stop_source 乙; 乙.request_stop(); 返回 0; }'),
      @('英文名与中文名并用','#包含 <停止令牌>`n整数 主函数(){ 标准::停止源 源; 标准::停止令牌 令 = 源.get_token(); 源.request_stop(); 布尔 好 = 令.stop_requested(); 返回 (整数)好 - 1; }'),
      @('停止回调 + 无停止状态','#包含 <停止令牌>`n结构 回调器 { 空型 operator()() {} };`n整数 主函数(){ 标准::停止源 空源(标准::无停止状态); 标准::停止源 源; 标准::停止回调<回调器> 回(源.取令牌(), 回调器{}); 源.请求停止(); 返回 0; }')
    )
  }
  'thread' = @{
    zh      = '线程'
    realInclude = @('thread')   # §16.29「乙」
    # types 第一个 = 派生层基类
    types   = [ordered]@{
      'thread'       = '线程实现'
      # §16.38 第 ① 类（类内别名）
      '_Tuple'       = '_元组'
      'jthread'      = '可停线程实现'
      # 嵌套名域 this_thread 也是标识符，照样改名；派生层里用 名域 本线程 补英文
      'this_thread'  = '本线程'
      # §16.34：内部件（长名，无二义）。
      # ⚠ `id` 【不】登记：见方案 §3.13 表第 732 行 —— `id` 太短，
      #   全局 \bid\b 替换有二义，属【有理由的边界】，与上面这些都不同。
      '_Clamped_rel_time_ms_count_result' = '_钳位相对时间毫秒计数结果'
      # 跨头类型名（<停止令牌> 定下的译名）
      'stop_token'   = '停止令牌实现'
      'stop_source'  = '停止源实现'
    }
    zhIncludes = @{ 'stop_token' = '停止令牌' }
    members = [ordered]@{
      '_First' = '_首个';
      '_Indices' = '_下标集';
      '_Last' = '_最后';
      '_Rep' = '_表示';
      '_Get_invoke' = '_取调用'
      '_Get_underlying_id' = '_取底层标识'
      '_Invoke' = '_调用'
      'join' = '汇合'; 'detach' = '分离'; 'joinable' = '可汇合'
      'get_id' = '取标识'; 'native_handle' = '原生句柄'
      'hardware_concurrency' = '硬件并发数'
      'yield' = '让出'
      'sleep_for' = '睡眠时长'; 'sleep_until' = '睡至时刻'
      'get_stop_source' = '取停止源'; 'get_stop_token' = '取停止令牌'
      # 跨头成员名：<停止令牌> 已定 请求停止 / 取令牌（跨头译名检查会强制一致）
      'request_stop' = '请求停止'
      'get_token'    = '取令牌'
    }
    # ⚠ 同样不放 swap（§3.12：类内 friend + `_STD swap` 调用形态，不能改名）
    data    = [ordered]@{}
    derive  = @( @('join','汇合'), @('detach','分离'), @('joinable','可汇合'),
                 @('get_id','取标识'), @('hardware_concurrency','硬件并发数') )
    stdHash = $false
    tparam  = @{ decl = ''; args = '' }
    extra = @'

名域 标准 {

// 可停线程（std::jthread）
类型 可停线程 : 公开 细节::可停线程实现 {
公开:
    使用 基类 = 细节::可停线程实现;
    使用 基类::基类;
    模板 <类型名... 参数> 声明类型(自动) join(参数&&... 值) { 返回 基类::汇合(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) detach(参数&&... 值) { 返回 基类::分离(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) joinable(参数&&... 值) 常量 { 返回 基类::可汇合(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) get_id(参数&&... 值) 常量 { 返回 基类::取标识(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) request_stop(参数&&... 值) { 返回 基类::请求停止(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) get_stop_source(参数&&... 值) { 返回 基类::取停止源(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) get_stop_token(参数&&... 值) 常量 { 返回 基类::取停止令牌(static_cast<参数&&>(值)...); }
};

// 本线程（std::this_thread）—— 名域里的自由函数，成员转发机制管不到，手写
名域 本线程 {
    // ⚠ 名域没有派生，所以中文名也要再出口一次 —— 类靠继承，名域靠 using 声明。
    //   （空测掩盖至今：只写了英文转发，于是 标准::本线程::让出 根本不存在。）
    使用 细节::本线程::让出;
    使用 细节::本线程::取标识;
    使用 细节::本线程::睡眠时长;
    使用 细节::本线程::睡至时刻;
    模板 <类型名... 参数> 声明类型(自动) get_id(参数&&... 值) { 返回 细节::本线程::取标识(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) yield(参数&&... 值) { 返回 细节::本线程::让出(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) sleep_for(参数&&... 值) { 返回 细节::本线程::睡眠时长(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) sleep_until(参数&&... 值) { 返回 细节::本线程::睡至时刻(static_cast<参数&&>(值)...); }
}

}  // 名域 标准
'@
    tests = @(
