      '_Flip_unchecked' = '_翻转非检查'
      '_Getword' = '_取字'
      '_Set_unchecked' = '_置位非检查'
      '_Subscript' = '_下标'
      '_To_string' = '_转字符串'
      '_Trim' = '_修剪'
      '_Xinv' = '_抛无效参数'
      '_Xoflo' = '_抛溢出'
      '_Xran' = '_抛范围错'
      # ⚠ 不登记（借来的/契约名）：_Allocate _Hash_representation _Ok reference
      'set' = '置位'; 'reset' = '复位'; 'flip' = '翻转'; 'test' = '测试'
      'count' = '计数'; 'size' = '尺寸'
      'all' = '全为真'; 'any' = '有真'; 'none' = '全为假'
      'to_string' = '转字符串'; 'to_ulong' = '转无符号长'; 'to_ullong' = '转无符号长长'
    ;
      '_Ok' = '_成功';
}
    data    = [ordered]@{}
    derive  = @( @('set','置位'), @('reset','复位'), @('flip','翻转'), @('test','测试'),
                 @('count','计数'), @('size','尺寸'), @('all','全为真'), @('any','有真'),
                 @('none','全为假'), @('to_string','转字符串'),
