    stdExtra = '模板 <size_t 位数>
    结构 hash<标准::位集<位数>> : hash<标准::细节::位集实现<位数>> {};'
    tests = @(
      @('只引中文头','#包含 <位集>`n整数 主函数(){ 标准::位集<8> 甲; 甲.置位(1); 布尔 有 = 甲.测试(1); 甲.复位(1); 甲.翻转(); 返回 (有 && 甲.计数() == 8) ? 0 : 1; }'),
      @('与微软原头并存','#包含 <位集>`n#包含 <bitset>`n整数 主函数(){ 标准::位集<8> 甲("1010"); std::bitset<8> 乙("1010"); 返回 (整数)甲.计数() - (整数)乙.count(); }'),
      @('英文名与中文名并用 + 转字符串','#包含 <位集>`n整数 主函数(){ 标准::位集<4> 甲; 甲.set(0); 甲.set(1); 自动 串 = 甲.to_string(); 自动 串2 = 甲.转字符串(); 返回 (串.size() == 4 && 串2.size() == 4) ? 0 : 1; }'),
      @('位运算 + std::hash 特化必须认识对外类型','#包含 <位集>`n整数 主函数(){ 标准::位集<8> 甲("1100"); 标准::位集<8> 乙("0110"); 自动 丙 = 甲 | 乙; std::hash<标准::位集<8>> 哈; 返回 (丙.计数() == 3 && 哈(甲) == 哈(甲)) ? 0 : 1; }')
    )
  }
  'set' = @{
    zh      = '集合'
    realInclude = @('set')   # §16.29「乙」
    # ===========================================================================
    #  §16.44 【销账】把 <集合> 切换到我们自己的 树内部件（xtree）！
    #
    #  为什么现在能切：§16.43 把 xtree 的 16 个类型名 + 39 个 `_Tree` 自己的成员名翻完了。
    #  切换要改的就三处：
    #    ① `#include <xtree>` 改成 `#include <树内部件>`（zhIncludes）
    #    ② 本头正文里引用的两个 xtree 名字跟着改（`_Tree`→`_树`、`_Tree_node`→`_树节点`）
    #    ③ 上一条测试证明它真的编得过（不是"看起来应该行"）
    #  **实测本头只引用这两个名字**（grep 原文：`_Tree` 5 次、`_Tree_node` 1 次），
    #  所以切换面很小 —— 这正是"先分类再动手"省下来的成本。
    #
    #  ⚠ 之前那句注释说「<set> 的 API 几乎全部继承自**借用的** _Tree（在 <xtree> 里，我们没翻）」
    #    已经过时：_Tree 现在是我们自己的（`细节::_树`），本头继承的就是它。
    # ===========================================================================
    zhIncludes = @{ 'xtree' = '树内部件' }
    # ⚠ 这个头自己定义的成员只有 ctor / emplace / swap；API 基本都从 `细节::_树` 继承。
    #   -> 中文名靠 extra 里【手写中文转发】调基类的英文名（§3.16 的第一种手写层用法）。
    types   = [ordered]@{ 'set' = '集合实现'
                          'multiset' = '多重集合实现'
                          '_Tset_traits' = '_集合特征'
                          # §16.44：跟着 树内部件 一起改（跨头译名一致性检查会强制一致）
                          '_Tree'      = '_树'
                          '_Tree_node' = '_树节点'
                          # §16.45 【销账】_Tree 是我们自己的了 -> 这一族可以同步翻：
                          '_Alnode'                = '_结点分配器'
                          '_Alnode_traits'         = '_结点分配器特征'
                          # §16.37 那时判为第 ③ 类（被借来的 std::_Tree 读取）而【不能翻】；
                          #   现在 _Tree = 细节::_树（§16.44），定义处与读取点都在我们手里，
                          #   于是「两边一起改」成立 —— 这就把那条欠账真正销掉了。
                          '_In_place_key_extractor' = '_就地键提取器'
                          # §16.47 与 树内部件 同步改的契约名（分类见 树内部件 条目里的长注释）。
                          #   `insert_return_type` 是本头自己定义的（xtree 里 0 次），一并翻。
                          'iterator'               = '迭代器'
                          'const_iterator'         = '常量迭代器'
                          # ⚠ reverse_iterator / const_reverse_iterator / size_type 不翻
                          #   （② / 同名两个主人，见 树内部件 条目）
                          'const_reference'        = '常量引用'
                          'key_type'               = '键类型'
                          'key_compare'            = '键比较器'
                          'value_compare'          = '值比较'
                          'node_type'              = '结点类型'
                          'allocator_type'         = '分配器类型'
                          'insert_return_type'     = '插入返回类型'
                          # §16.37 【实测结论：不能翻】`_In_place_key_extractor` 是
                          #   `_Tset_traits` 里的成员，而 `_Tree` 会去读它：
                          #     xtree:1011:68: error:
                          #       '标准::细节::_集合特征<...>' 中没有名为 '_In_place_key_extractor' 的成员
                          #   => 属 §16.35.5 第 ③ 类（std 模板读的契约成员名）。
                          #   ⚠ 现在 _Tree 是我们自己的了（§16.44），所以【两边一起改】的通路已经打开 ——
                          #     但那要连 树内部件 里的读取点一起改，属下一批。
                          # ⚠ _Alnode / _Alnode_traits 同理（`typename _Mybase::X`）。
                          }
    members = [ordered]@{
      '_Getal' = '_取分配器';
      '_In_place_key_extract_set' = '_就地键提取集合';
      '_Alloc' = '_分配器';
      '_First' = '_首个';
      '_Valty' = '_值参数类型';
      '_Unchecked_end_iter' = '_非检查结束迭代器';
      '_Last' = '_最后';
      '_Insert_range_unchecked' = '_插入范围非检查'; 'emplace' = '就地构造'
      # §17.27.60 台账收尾（阶段(3) 第一批）：这些名字的定义方是 通用内部件（我们的 xutility 拷贝，
      #   §17.27.52 已给定义方解毒）；本头能看到它 -> 调用点跟改，指向我们那份。
      '_Ubegin' = '_解包首'
      '_Uend' = '_解包尾'
      '_Pass_fn' = '_传递函数'
                          # §17.9 `_Kfn`（有序那一条链）：本头 traits 是【定义侧】，
                          #   与 树内部件 的 `_Traits::_Kfn(...)` 调用侧同批翻成 `_取键`。
                          #   与 §17.8 的无序链各自闭包、互不相干。
                          '_Kfn' = '_取键'
                          # §16.44 同步改名：本头正文调 `_Mybase::_Unchecked_begin/_Unchecked_end`，
                          #   而 树内部件 已把它们翻成 _非检查开始/_非检查结束。
                          #   **这就是"上层与内部件必须同步改"的实证**：不同步，编译器就报
                          #   "`_树<...>` 中没有名为 '_Unchecked_begin' 的成员"。
                          '_Unchecked_begin' = '_非检查开始'
                          '_Unchecked_end'   = '_非检查结束' }
    data    = [ordered]@{}
    derive  = @( @('emplace','就地构造') )
    # ⚠ <set> 是在 deriveExtra 机制【之前】做的，主类 集合 一直没有中文转发
    #   （空测掩盖至今：插入/计数/尺寸 等名字根本不存在）。这里补齐九个。
    deriveExtra = @'
    模板 <类型名... 参数> 声明类型(自动) 插入(参数&&... 值) { 返回 基类::insert(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 擦除(参数&&... 值) { 返回 基类::erase(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 查找(参数&&... 值) { 返回 基类::find(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 计数(参数&&... 值) 常量 { 返回 基类::count(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 尺寸(参数&&... 值) 常量 { 返回 基类::size(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 为空(参数&&... 值) 常量 { 返回 基类::empty(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 清空(参数&&... 值) { 返回 基类::clear(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 包含(参数&&... 值) 常量 { 返回 基类::contains(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 开始(参数&&... 值) { 返回 基类::begin(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 结束(参数&&... 值) { 返回 基类::end(static_cast<参数&&>(值)...); }
'@
    # 嵌套类型名：§16.47 把方向**反过来**（§9.1）—— 抄来那层现在是汉语，
    # 派生层负责把【英文原名】补回来。所以配对是 @('英文名','汉语名')。
    #   ⚠ 漏一个就是回归：用户本来能写的 标准::集合<T>::value_type 之类会消失。
    #   ⚠ 只覆盖【主类 集合】；手写的 多重集合 必须在 extra 里自己补（见下）。
    deriveTypes = @( @('iterator','迭代器'), @('const_iterator','常量迭代器'),
                     @('const_reference','常量引用'),
                     @('key_type','键类型'), @('key_compare','键比较器'),
                     @('value_compare','值比较'), @('node_type','结点类型'),
                     @('allocator_type','分配器类型'), @('insert_return_type','插入返回类型'),
                     # ↓ 这三个是【边界】：抄来那层里不能翻（② 类 / 同名两个主人），
                     #   所以中文名只能用旧方向在这里补（§16.35.5 的"方向故意混用"）。
                     @('尺寸类型','size_type'),
                     @('反向迭代器','reverse_iterator'),
                     @('常量反向迭代器','const_reverse_iterator') )
    stdHash = $false
    tparam  = @{ decl = '模板 <类型名 键, 类型名 比较 = std::less<键>, 类型名 分配器 = std::allocator<键>>'; args = '<键, 比较, 分配器>' }
    extra = @'

名域 标准 {

// 多重集合（std::multiset）
模板 <类型名 键, 类型名 比较 = std::less<键>, 类型名 分配器 = std::allocator<键>>
类型 多重集合 : 公开 细节::多重集合实现<键, 比较, 分配器> {
公开:
    使用 基类 = 细节::多重集合实现<键, 比较, 分配器>;
    使用 基类::基类;
    // ⚠ §16.47：deriveTypes 只管主类 集合，管不到这里。
    //   抄来那层已把这一族契约名翻成汉语，所以英文原名必须【在这里手写补回】——
    //   不写就是"翻一半"（§16.41.2）：原来能用的 标准::多重集合<T>::iterator 会消失。
    使用 iterator               = 基类::迭代器;
    使用 const_iterator         = 基类::常量迭代器;
    使用 反向迭代器             = 基类::reverse_iterator;         // 边界名，旧方向
    使用 常量反向迭代器         = 基类::const_reverse_iterator;   // 边界名，旧方向
    使用 尺寸类型              = 基类::size_type;              // 边界名，旧方向
    使用 const_reference        = 基类::常量引用;
    使用 key_type               = 基类::键类型;
    使用 key_compare            = 基类::键比较器;
    使用 value_compare          = 基类::值比较;
    使用 node_type              = 基类::结点类型;
    使用 allocator_type         = 基类::分配器类型;
    // ⚠ 这里【没有】insert_return_type —— 它是 set/map 专有的（multiset 不可摘结点），
    //   实测：'标准::细节::多重集合实现<int>' 中没有名为「插入返回类型」的类型。
    //   判据：手写层补的每一行都要确认【那个类的基类里真的有这个名字】。
    模板 <类型名... 参数> 声明类型(自动) 插入(参数&&... 值) { 返回 基类::insert(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 擦除(参数&&... 值) { 返回 基类::erase(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 查找(参数&&... 值) { 返回 基类::find(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 计数(参数&&... 值) 常量 { 返回 基类::count(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 尺寸(参数&&... 值) 常量 { 返回 基类::size(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 为空(参数&&... 值) 常量 { 返回 基类::empty(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 清空(参数&&... 值) { 返回 基类::clear(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 开始(参数&&... 值) { 返回 基类::begin(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 结束(参数&&... 值) { 返回 基类::end(static_cast<参数&&>(值)...); }
};

}  // 名域 标准
'@
    tests = @(
      @('只引中文头','#包含 <集合>`n整数 主函数(){ 标准::集合<整数> 甲; 甲.插入(1); 甲.插入(2); 返回 甲.计数(1) == 1 ? 0 : 1; }'),
      @('与微软原头并存','#包含 <集合>`n#包含 <set>`n整数 主函数(){ 标准::集合<整数> 甲; 甲.insert(1); std::set<int> 乙; 乙.insert(1); 返回 (整数)甲.尺寸() - (整数)乙.size(); }'),
      @('中英并用 + 中文迭代器名','#包含 <集合>`n整数 主函数(){ 标准::集合<整数> 甲; 甲.插入(3); 甲.插入(1); 标准::集合<整数>::迭代器 头 = 甲.开始(); 整数 和 = 0; for (; 头 != 甲.结束(); ++头) { 和 += *头; } 返回 和 - 4; }'),
      @('多重集合','#包含 <集合>`n整数 主函数(){ 标准::多重集合<整数> 甲; 甲.插入(1); 甲.插入(1); 返回 (整数)甲.计数(1) - 2; }')
    )
  }
  'map' = @{
    zh      = '映射'
    realInclude = @('map')   # §16.29「乙」
    # §16.44 【销账】与 <集合> 同批：把 <映射> 也切到我们自己的 树内部件。
    #   实测本头引用 xtree 的面：类型 3 个（_Tree/_Tree_node/_Tree_temp_node）、
    #   被我们改过名的基类成员 8 个（_Getal/_Getcomp? 不，是 _Getal/_Get_scary/
    #   _Check_grow_by_1/_Find_hint/_Find_lower_bound/_Lower_bound_duplicate/
    #   _Unchecked_begin/_Unchecked_end）。**都是"照着编译错误一次就能列全"的量**。
    zhIncludes = @{ 'xtree' = '树内部件' }
    types   = [ordered]@{ 'map' = '映射实现'
                          'multimap' = '多重映射实现'
                          '_Tmap_traits' = '_映射特征'
                          # §16.44 跟着 树内部件 一起改
                          '_Tree'           = '_树'
                          '_Tree_node'      = '_树节点'
                          '_Tree_temp_node' = '_树临时节点'
                          # §16.45 【销账】与 <集合> 同批（_Tree 已是我们的，可同步翻）
                          '_Alnode'                = '_结点分配器'
                          '_Alnode_traits'         = '_结点分配器特征'
                          '_Nodeptr'               = '_结点指针'
                          '_In_place_key_extractor' = '_就地键提取器'
                          # §16.47 与 树内部件 同步改的契约名（分类见 树内部件 条目里的长注释）
                          'iterator'               = '迭代器'
                          'const_iterator'         = '常量迭代器'
                          'mapped_type'            = '映射类型'
                          'const_reference'        = '常量引用'
                          'key_type'               = '键类型'
                          'key_compare'            = '键比较器'
                          'value_compare'          = '值比较'
                          'node_type'              = '结点类型'
                          'allocator_type'         = '分配器类型'
                          'insert_return_type'     = '插入返回类型'
                          # ⚠ 不翻：value_type(④ 迭代器契约) / size_type(同名两个主人) /
                          #        reverse_iterator(② std 模板名) / const_reverse_iterator
                          #   —— 它们的中文名在 deriveTypes 里用【旧方向】补
                          #  §16.37 【实测结论：不能翻】`_In_place_key_extractor` 被 `_Tree` 读取
                          #   （xtree:1011）-> 第 ③ 类。现在 _Tree 是我们自己的了，
                          #   「两边一起改」的通路已打开，属下一批。
                          # ⚠ _Alnode / _Alnode_traits / _Nodeptr 同理（`typename _Mybase::X`），
                          #   但它们【没被 树内部件 改名】，所以现在照旧可用。
                          }   # ⚠ value_compare 故意【不】改名：它是 _Tree 的成员类型名，
                          #   改名会让 xtree 里的读取点找不到它。中文名欠账，
                          #   消除路径 = 与 树内部件 同步改（通路已开）。
    members = [ordered]@{
      '_Alloc' = '_分配器';
      '_First' = '_首个';
      '_Insert_range_unchecked' = '_插入范围非检查';
      '_Last' = '_最后';
      '_Range_key_type' = '_范围键类型';
      '_Range_mapped_type' = '_范围映射类型';
      '_Range_to_alloc_type' = '_范围到分配器类型';
      '_Result' = '_结果';
      '_Try_emplace' = '_尝试就地构造';
      '_Try_emplace_hint' = '_按提示尝试就地构造';
      '_Ty' = '_类型';
      '_Unchecked_end_iter' = '_非检查结束迭代器';
      '_Valty' = '_值参数类型';
      '_In_place_key_extract_map' = '_就地键提取映射';
      # §17.27.60 台账收尾（阶段(3) 第一批）：这些名字的定义方是 通用内部件（我们的 xutility 拷贝，
      #   §17.27.52 已给定义方解毒）；本头能看到它 -> 调用点跟改，指向我们那份。
      '_Ubegin' = '_解包首'
      '_Uend' = '_解包尾'
      '_Pass_fn' = '_传递函数'
      # §17.9 `_Kfn`（有序那一条链，traits 定义侧）——与 树内部件 同批，见 <集合> 那边的说明。
      '_Kfn' = '_取键'
      # at/insert/... 是 <map> 自己定义的（能改名）
      'at' = '取值'   # ⚠ insert 不改名：现在 _Mybase 是【我们自己的】细节::_树，
                      #   而我们没有翻 _Tree 的公开 API 名（insert/erase/find/…）——
                      #   它们是 map/set 的 std 契约，要与上层同步改，属下一批。
      'insert_or_assign' = '插入或赋值'; 'try_emplace' = '尝试就地构造'
      # emplace 必须与 <栈>/<集合> 一致（跨头译名检查会强制）
      'emplace' = '就地构造'
      # §16.44 同步改名：本头正文调 `_Mybase::X`，而 树内部件 已把这些 X 翻成汉语。
      #   **这是"上层与内部件必须同步改"的实证**（不同步，编译器直接报"没有名为…的成员"）。
      '_Getal'                = '_取分配器'
      '_Get_scary'            = '_取检查值'
      '_Check_grow_by_1'      = '_检查增一'
      '_Find_hint'            = '_按提示查找'
      '_Find_lower_bound'     = '_查找下界'
      '_Lower_bound_duplicate' = '_下界重复项'
      '_Unchecked_begin'      = '_非检查开始'
      '_Unchecked_end'        = '_非检查结束'
      # ⚠ 这一个不是调在 `_Mybase::` 上，而是调在 `_Get_scary()` 返回的
      #   `_Scary_val`（= _树值<...>）上 —— 所以先前 grep `_Mybase::_` 时没抓到它，
      #   是**编译器**把它列出来的。判据：同步改名的清单不能只靠一种 grep 模式，
      #   要以编译错误为准（编译器是完备的，正则不是）。
      '_Insert_node'          = '_插入节点'
    ;
      '_Insert_or_assign' = '_插入或赋值';

      '_Release' = '_释放';

      'comp' = '比较器';

      # 'insert' = '插入';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下

      # 'clear' = '清空';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下
;
      'clear' = '清空';
}
    data    = [ordered]@{}
    derive  = @( @('at','取值'), @('insert_or_assign','插入或赋值'),
                 @('try_emplace','尝试就地构造'), @('emplace','就地构造') , @('clear','清空'))
    deriveTypes = @( @('iterator','迭代器'), @('const_iterator','常量迭代器'),
                     @('mapped_type','映射类型'), @('const_reference','常量引用'),
                     @('key_type','键类型'), @('key_compare','键比较器'),
                     @('value_compare','值比较'), @('node_type','结点类型'),
                     @('allocator_type','分配器类型'), @('insert_return_type','插入返回类型'),
                     # ↓ 边界：抄来那层不能翻（④ 迭代器契约 / ② std 模板名 / 同名两个主人）
                     #   -> 中文名只能用旧方向在这里补（§16.35.5 "方向故意混用"）。
                     @('值类型','value_type'), @('尺寸类型','size_type'),
                     @('反向迭代器','reverse_iterator'),
                     @('常量反向迭代器','const_reverse_iterator') )
    # 中文转发：这些 API 在 <xtree> 里（借用），本文件改名改不到（方案 §3.16）
    deriveExtra = @'
    模板 <类型名... 参数> 声明类型(自动) 插入(参数&&... 值) { 返回 基类::insert(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 擦除(参数&&... 值) { 返回 基类::erase(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 查找(参数&&... 值) { 返回 基类::find(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 计数(参数&&... 值) 常量 { 返回 基类::count(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 尺寸(参数&&... 值) 常量 { 返回 基类::size(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 为空(参数&&... 值) 常量 { 返回 基类::empty(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 清空(参数&&... 值) { 返回 基类::clear(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 包含(参数&&... 值) 常量 { 返回 基类::contains(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 开始(参数&&... 值) { 返回 基类::begin(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 结束(参数&&... 值) { 返回 基类::end(static_cast<参数&&>(值)...); }
'@
    stdHash = $false
    # ⚠ 模板参数名【不能和类名同名】：参数叫 映射 会遮蔽类模板 映射，类型 映射 : ... 报
    #   「使用类模板 '映射' 需要模板实参」。故参数叫 映射值。
    tparam  = @{ decl = '模板 <类型名 键, 类型名 映射值, 类型名 比较 = std::less<键>, 类型名 分配器 = std::allocator<std::pair<常量 键, 映射值>>>'; args = '<键, 映射值, 比较, 分配器>' }
    extra = @'

名域 标准 {

// 多重映射（std::multimap）
模板 <类型名 键, 类型名 映射值, 类型名 比较 = std::less<键>,
      类型名 分配器 = std::allocator<std::pair<常量 键, 映射值>>>
类型 多重映射 : 公开 细节::多重映射实现<键, 映射值, 比较, 分配器> {
公开:
    使用 基类 = 细节::多重映射实现<键, 映射值, 比较, 分配器>;
    使用 基类::基类;
    // §16.47：deriveTypes 只管主类 映射，管不到这里 —— 逐个手写（否则是"翻一半"= 回归）。
    使用 iterator           = 基类::迭代器;
    使用 const_iterator     = 基类::常量迭代器;
    使用 mapped_type        = 基类::映射类型;
    使用 const_reference    = 基类::常量引用;
    使用 key_type           = 基类::键类型;
    使用 key_compare        = 基类::键比较器;
    使用 value_compare      = 基类::值比较;
    使用 node_type          = 基类::结点类型;
    使用 allocator_type     = 基类::分配器类型;
    // ⚠ 边界名（旧方向）：多重映射没有 insert_return_type（不可摘结点）
    使用 值类型             = 基类::value_type;
    使用 尺寸类型           = 基类::size_type;
    使用 反向迭代器         = 基类::reverse_iterator;
    使用 常量反向迭代器     = 基类::const_reverse_iterator;
    模板 <类型名... 参数> 声明类型(自动) 插入(参数&&... 值) { 返回 基类::insert(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 擦除(参数&&... 值) { 返回 基类::erase(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 查找(参数&&... 值) { 返回 基类::find(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 计数(参数&&... 值) 常量 { 返回 基类::count(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 尺寸(参数&&... 值) 常量 { 返回 基类::size(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 为空(参数&&... 值) 常量 { 返回 基类::empty(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 清空(参数&&... 值) { 返回 基类::clear(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 开始(参数&&... 值) { 返回 基类::begin(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 结束(参数&&... 值) { 返回 基类::end(static_cast<参数&&>(值)...); }
};

