                          'value_type' = '值类型'
                          '_SMF_control' = '_特殊成员控制'
                          # §16.34：本文件自己定义的内部件，按 §六第 6 条翻
                          '_Optional_destruct_base'  = '_可选析构基类'
                          '_Optional_construct_base' = '_可选构造基类'
                          '_Nontrivial_dummy_type'   = '_非平凡哑类型'
                          '_Construct_from_invoke_result_tag' = '_由调用结果构造标记'
                          '_Enable_if_bool_convertible' = '_启用若可转布尔'
                          '_Enable_if_comparable_with_equal' = '_启用若可与相等比较'
                          '_Enable_if_comparable_with_not_equal' = '_启用若可与不等比较'
                          '_Enable_if_comparable_with_less' = '_启用若可与小于比较'
                          '_Enable_if_comparable_with_less_equal' = '_启用若可与小于等于比较'
                          '_Enable_if_comparable_with_greater' = '_启用若可与大于比较'
                          '_Enable_if_comparable_with_greater_equal' = '_启用若可与大于等于比较' }
    # 步 0b：把【真 <optional>】也包含进来 —— 为了让 std::bad_optional_access 真的存在。
    # 抄来的那份异常类定义要删掉（dropTypes），否则 _Throw_bad_optional_access()
    # 抛的是我们抄的那个类，用户 catch (std::bad_optional_access&) 永远抓不到。
    # 值类型 optional 可以抄+派生（能有中文成员名），异常类型只能别名 —— 铁律 4。
    realInclude = @('optional')
    dropTypes   = @('bad_optional_access')
    # §15.6 销账：<optional> 正文包含 <xsmf_control.h>，这里指向我们自己的汉语件；
    # 并把 _SMF_control 改成汉语名 _特殊成员控制（细节 里那份是我们自己的）。
    # §17.27.54 阶段(2) 链名接通：原件第 8 行直接 `#include <xutility>`，定义方现在是我们的
    # `通用内部件`（§17.27.52/53）-> 一并指过来，`_Construct_in_place` 才指向我们那份。
    zhIncludes = @{ 'xsmf_control.h' = '特殊成员控制'; 'xutility' = '通用内部件' }
    members = [ordered]@{
      '_Ty' = '_类型';
      '_Elem' = '_元素';
      'has_value' = '有值'; 'value_or' = '取值或'   # ⚠ value 故意【不】登记：
      #   它作为 ::value 出现在借来的 bool_constant<...>::value 里，改名会让约束恒假、
      #   SFINAE 删掉 optional 的转换构造（实测，见方案 §15.5）。中文名改在派生层手写。
      'reset' = '重置'; 'emplace' = '就地构造'
      'and_then' = '且则'; 'transform' = '变换'; 'or_else' = '或则'
      # ⚠ swap 照旧不改名（§3.12）
      # §16.77 本头**自己定义**的 4 个内部助手（实测只有 <optional> 有定义）
      #   -> 翻；不是公开 API，不需要派生层补英文。
      '_Assign' = '_赋值'
      '_Assign_from' = '_由之赋值'
      '_Construct' = '_构造'
      '_Construct_from' = '_由之构造'
      # §17.27.54 链名接通：定义方 <xutility> 现在是我们的 `通用内部件`。
      #   原件 <optional> 第 8 行就直接 `#include <xutility>` -> 本条目补 zhIncludes 指过来。
      '_Construct_in_place' = '_就地构造'
    ;
      '_Do_hash' = '_求散列';
}
    data    = [ordered]@{}
    derive  = @( @('has_value','有值'), @('value_or','取值或'),
                 @('reset','重置'), @('emplace','就地构造'),
                 @('and_then','且则'), @('transform','变换'), @('or_else','或则') )
    # 方向与以前相反：以前是'给派生类加中文名'，现在是'派生层把英文原名补回来'
    deriveTypes = @( @('value_type','值类型') )
    # ⚠ 派生类会【隐式生成】拷贝/移动赋值运算符，从而把基类的 operator= 藏起来
    #   -> `甲 = 5` 报"没有可行的重载 '='"。必须用 using 把基类的运算符拉回来。
    deriveExtra = @'
    // ⚠ 不能写 使用 基类::operator=; —— 那会把基类的拷贝/移动赋值也拉进来，
    //   而 int 能经转换构造变成 可选，于是 `甲 = 5` 有两个候选 -> 歧义（实测）。
    //   手写一个模板赋值即可：对 `可选 = 可选` 隐式拷贝赋值（非模板）优先，不冲突。
    模板 <类型名 实参> 可选& operator=(实参&& 右) { 基类::operator=(static_cast<实参&&>(右)); 返回 *this; }
    使用 基类::operator*;
    使用 基类::operator->;
    // value 的中文名在这里手写（它不能登记进 members 表，见该条目注释与 §15.5）
    模板 <类型名... 参数> 声明类型(自动) 取值(参数&&... 值) { 返回 基类::value(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 取值(参数&&... 值) 常量 { 返回 基类::value(static_cast<参数&&>(值)...); }
'@
    stdHash = $false
    tparam  = @{ decl = '模板 <类型名 值>'; args = '<值>' }
    extra = @'

名域 标准 {

// 坏可选访问异常（std::bad_optional_access）—— 只能是 std 的那个（铁律 4）
使用 坏可选访问 = std::bad_optional_access;

// 顶层 tag 类型也要能在 标准 里写
使用 空值类型 = 细节::空值类型;

// 无值（std::nullopt）—— 全局常量，成员转发管不到，手写
// ⚠ MSVC 的 nullopt_t 取的是嵌套的 _Tag，不是 int（我照 cppreference 写 {42} 是错的）：
//     struct nullopt_t { struct _Tag {}; constexpr explicit nullopt_t(_Tag) {} };
// ⚠⚠ §16.38：这行是【手写层引用拷贝层的名字】—— 拷贝层把 _Tag 翻成了 _标记，
//     手写层必须跟着改（否则 '空值类型' 里没有名为 '_Tag' 的成员）。
//     判据：**手写 extra/deriveExtra 里凡是 `细节::X::Y` 形态的引用，
//     都要在 X/Y 被登记改名时一并核对** —— 编译器会报，但没有守卫会替你记住。
内联 常量表达式 空值类型 无值{细节::空值类型::_标记{}};

}  // 名域 标准
'@
