  'any' = @{
    zh      = '任意'
    types   = [ordered]@{ 'any' = '任意实现'
                          # §16.27：自有内部件也要翻
                          '_Any_representation' = '_任意表示'
                          '_Any_big_RTTI'       = '_任意大对象类型信息'
                          '_Any_small_RTTI'     = '_任意小对象类型信息'
                          # §16.35.7 嵌套名翻转（第 ① 类：只存在于本类，没有第二个主人）：
                          #   这几个都是【我们自己】的私有别名/内部结构（原文 57~77 行与
                          #   338~352 行），既不是 std 模板名、也不在 std 契约里，
                          #   所以可以安全地改在【抄来那层】。
                          '_Destroy_fn'         = '_析构函数指针'
                          '_Copy_fn'            = '_复制函数指针'
                          '_Move_fn'            = '_移动函数指针'
                          '_Small_storage_t'    = '_小存储类型'
                          '_Big_storage_t'      = '_大存储类型'
                          '_Storage_t'          = '_存储类型' }
    # 步 0b：真头 + 丢掉抄来的异常类（铁律 4，见 §3.18）
    realInclude = @('any')
    dropTypes   = @('bad_any_cast')
    members = [ordered]@{
      '_Copy' = '_复制';
      '_Elem' = '_元素';
      '_Ty' = '_类型';
      'reset' = '重置'; 'has_value' = '有值'
      # ⚠ `类型` 是关键词（class），所以 type() 不能叫「类型」
      'type' = '所属类型'; 'emplace' = '就地构造'
      # 自由函数也在这里改名：抄来后它们落在 细节::，靠 extra 里的
      # `使用 细节::中文名;` 引进 标准（using 声明比重写转发保真：
      # 重载全带上、返回引用也不丢 —— 泛型转发用 auto 会把 T& 退化成 T）
      'any_cast' = '任意转换'; 'make_any' = '造任意'
      # ⚠ swap 照旧不改名（§3.12）
      # §16.69 本头**自己定义**的内部助手（实测只有 <any> 有定义）-> 翻：
      #   `_Assign` / `_Copy_impl` / `_Destroy_impl` / `_Emplace` / `_Move_from` /
      #   `_Move_impl` / `_Rep` / `_TypeInfo`。
      #   ⚠ `what` **不翻**：它是 `bad_any_cast` 对**借来的** `std::exception::what()`
      #     的**虚函数覆盖** —— 改名就不再覆盖，`catch (常量 std::exception&) e { e.what(); }`
      #     会拿到基类的实现（静默错误，不是编译错误）。
      #   ⚠ `_Cast` / `_Construct_in_place` / `_Destroy_in_place` 定义在 <xutility>/<xmemory>
      #     -> 本头不翻（调用点留英文名，指到 std 那一份）。
      #     §17.27.53/54 补充：这两个定义方现在**都是我们自己的**
      #     （`_Construct_in_place` -> 通用内部件，`_Destroy_in_place` -> 内存内部件）。
      #     本批已经把 `_Construct_in_place` 接上（见下表），`_Destroy_in_place` 与 `_Cast` 仍是欠账。
      '_Assign'       = '_赋值'
      '_Copy_impl'    = '_复制实现'
      '_Destroy_impl' = '_析构实现'
      # §17.27.54 **译名唯一性**：`_Emplace` 原译 `_就地构造` 与 `_Construct_in_place`
      #   的译名**撞了**。这不是审美问题：`any` 的 `_Emplace` 正文里就调用了
      #   `_STD _Construct_in_place(...)`（原件 any:315/322），两个名字都叫 `_就地构造` 之后，
      #   类作用域查找会**先找到成员 `_Emplace` 自己** -> 静默自我递归（不是编译错误！）。
      #   所以把成员 `_Emplace` 改名为 `_就地安置`，把 `_就地构造` 留给自由函数。
      #   判据：**一个译名只对应一个英文名**（同一 TU 里名域作用域与类作用域会互相遮蔽）。
      '_Emplace'      = '_就地安置'
      '_Construct_in_place' = '_就地构造'
      '_Move_from'    = '_由之移动'
      # §17.27.55 链名接通（第二批）：`_Destroy_in_place` 定义方是 `内存内部件`（本头直接引它）。
      '_Destroy_in_place' = '_就地析构'
      '_Move_impl'    = '_移动实现'
      '_Rep'          = '_表示'
      '_TypeInfo'     = '_类型信息'
    }
    data    = [ordered]@{}
    derive  = @( @('reset','重置'), @('has_value','有值'),
                 @('type','所属类型'), @('emplace','就地构造') )
    deriveExtra = @'
    // 让【抄来那层】的自由函数返回值能直接用：
    // make_any 返回 细节::任意实现，而对外类型是派生出来的 标准::任意。
    // 派生类没有"从基类回来"的路，所以手写一个接管构造。
    任意(细节::任意实现&& 内) noexcept : 基类(static_cast<细节::任意实现&&>(内)) {}
'@
    stdHash = $false
    tparam  = @{ decl = ''; args = '' }
    extra = @'

名域 标准 {

// 坏任意转换异常（std::bad_any_cast）—— 只能是 std 的那个（铁律 4）
使用 坏任意转换 = std::bad_any_cast;

// 自由函数：抄来后落在 细节::，这里用 using 声明引进 标准::
// （比重写转发保真：重载全带上、返回引用也不丢）
使用 细节::任意转换;
使用 细节::造任意;

