    extra = @'

名域 标准 { 名域 细节 {

使用 _Container_base12    = _容器基类12;
使用 _Container_base0     = _容器基类0;
使用 _Container_base      = _容器基类;
使用 _Container_proxy     = _容器代理;
模板 <类型名 分配器参数> 使用 _Container_proxy_ptr = _容器代理指针<分配器参数>;
使用 _Iterator_base12     = _迭代器基类12;
使用 _Iterator_base0      = _迭代器基类0;
使用 _Iterator_base       = _迭代器基类;
使用 _Fake_proxy_ptr_impl = _假代理指针实现;
使用 _Fake_allocator      = _假分配器;

} }  // 名域 标准::细节

'@
    tests = @(
      @('只引中文头','#包含 <双端队列>`n整数 主函数(){ 标准::双端队列<整数> 甲; 甲.尾插(1); 甲.头插(0); 甲.尾部就地构造(2); 返回 甲.取值(0) + (整数)甲.尺寸() - 3; }'),
      @('与微软原头并存','#包含 <双端队列>`n#包含 <deque>`n整数 主函数(){ 标准::双端队列<整数> 甲; 甲.push_back(1); std::deque<int> 乙; 乙.push_back(1); 返回 (整数)甲.尺寸() - (整数)乙.size(); }'),
      @('中英并用 + 中文迭代器名','#包含 <双端队列>`n整数 主函数(){ 标准::双端队列<整数> 甲; 甲.尾插(3); 甲.头插(1); 标准::双端队列<整数>::迭代器 头 = 甲.开始(); 整数 和 = 0; for (; 头 != 甲.结束(); ++头) { 和 += *头; } 返回 和 - 4; }'),
      # §17.27.56 机器守卫：同 <向量>（链名族两边同名，防"静默降级"）。
      @('链名族一致（解包/定位真的作用在我们的迭代器上）','#包含 <双端队列>`n#包含 <type_traits>`n整数 主函数(){ 标准::双端队列<整数> 甲{1,2,3}; 自动 首 = 甲.开始();`n  静态断言(!std::is_same_v<std::remove_cvref_t<decltype(标准::细节::_取解包(首))>, decltype(首)>);`n  标准::细节::_定位包装(首, 标准::细节::_取解包(首));`n  标准::细节::_ADL校验范围(甲.开始(), 甲.结束());`n  返回 (整数)甲.尺寸() - 3; }'),
      @('擦除 / 插入 / 前后','#包含 <双端队列>`n整数 主函数(){ 标准::双端队列<整数> 甲; 甲.尾插(1); 甲.尾插(2); 甲.尾插(3); 甲.擦除(甲.开始()); 甲.插入(甲.开始(), 9); 返回 甲.前() + 甲.后() - 12; }')
    )
  }
