      '_Get_unwrapped' = '_取解包'
      '_Adl_verify_range' = '_ADL校验范围'
      # §17.27.56 链名族（成员名，§17.27.42「接收者定」）：这三个名字在本头是**我们自己
      #   迭代器类**的成员/隐藏友元 -> 改（接收者是我们的实例）。
      #   `通用内部件` 的泛型助手正文里调的就是这些汉语名：`_取解包` -> `._解包()`、
      #   `_定位包装` -> `._定位到(...)`、`_ADL校验范围` -> ADL `_校验范围`。
      #   ⚠ 两边不同改的后果**不是报错而是静默降级**：`_Unwrappable_v` / `_Range_verifiable_v`
      #     是 `if constexpr` 判据，名字对不上就变假 -> 解包直通（不真解包）、范围校验失效。
      '_Unwrapped' = '_解包'
      '_Seek_to' = '_定位到'
      '_Verify_range' = '_校验范围'
      '_Unchecked_erase' = '_非检查擦除'
      'size' = '尺寸'; 'empty' = '为空'
      'begin' = '开始'; 'end' = '结束'
      'cbegin' = '常量开始'; 'cend' = '常量结束'
      'rbegin' = '反向开始'; 'rend' = '反向结束'
      'crbegin' = '常量反向开始'; 'crend' = '常量反向结束'
      'front' = '前'; 'back' = '后'
      'push_back' = '尾插'; 'push_front' = '头插'
      'pop_back' = '尾删'; 'pop_front' = '头删'
      'emplace' = '就地构造'; 'emplace_back' = '尾部就地构造'; 'emplace_front' = '头部就地构造'
      'insert' = '插入'; 'erase' = '擦除'; 'assign' = '赋值'
      'resize' = '调整尺寸'
      'clear' = '清空'; 'get_allocator' = '取分配器'
      'append_range' = '追加范围'; 'prepend_range' = '前置范围'
      'assign_range' = '范围赋值'; 'insert_range' = '范围插入'
      'sort' = '排序'; 'merge' = '归并'; 'splice' = '接合'
      'remove' = '移除'; 'remove_if' = '按条件移除'
      'unique' = '去重'; 'reverse' = '反转'
      # §16.50 与 哈希内部件 同步：这三个名字在 `list` 与 `_Hash` 上【同名两个主人】
      #   （§3.12 那类）。哈希内部件 已按 `_Hash::X` 翻了，而它的正文里有 `_Mylist::X`
      #   —— 所以 list 这一侧也必须翻，否则报
      #   「'标准::细节::链表实现<int>' 中没有名为 '_取分配器' 的成员」。
      '_Getal'            = '_取分配器'
      '_Unchecked_begin'  = '_非检查开始'
      '_Unchecked_end'    = '_非检查结束'
      # ⚠ swap 照旧不改名（§3.12）
    ;
      '_Construct_n' = '_构造n个';

      '_Release' = '_释放';

      '_Proxy' = '_代理';
}
    zhIncludes = @{ 'xmemory' = '内存内部件' }
    data    = [ordered]@{}
    derive  = @( @('size','尺寸'), @('empty','为空'),
                 @('begin','开始'), @('end','结束'),
                 @('front','前'), @('back','后'),
                 @('push_back','尾插'), @('push_front','头插'),
                 @('pop_back','尾删'), @('pop_front','头删'),
                 @('emplace','就地构造'), @('emplace_back','尾部就地构造'),
                 @('emplace_front','头部就地构造'),
                 @('insert','插入'), @('erase','擦除'), @('assign','赋值'),
                 @('resize','调整尺寸'), 
                 @('clear','清空'), @('get_allocator','取分配器'),
                 @('sort','排序'), @('merge','归并'), @('splice','接合'),
                 @('remove','移除'), @('remove_if','按条件移除'),
                 @('unique','去重'), @('reverse','反转') )
    deriveExtra = '    模板 <类型名... 参数> 声明类型(自动) 最大尺寸(参数&&... 值) 常量 { 返回 基类::max_size(static_cast<参数&&>(值)...); }'
    deriveTypes = @( @('迭代器','iterator'), @('常量迭代器','const_iterator'),
                     @('反向迭代器','reverse_iterator'), @('常量反向迭代器','const_reverse_iterator'),
                     @('值类型','value_type'), @('尺寸类型','size_type'),
                     # §16.58 方向翻转：抄来那层的 `allocator_type` 已成本头汉语名，
                     #   公开层必须把【英文原名】补回 —— 否则
                     #   `std::uses_allocator<标准::链表<int>, 分配器>` 会变成 false
                     #   （泛型代码静默换路径，而且照样编得过）。
                     @('allocator_type','分配器类型') )
    stdHash = $false
    tparam  = @{ decl = '模板 <类型名 元素, 类型名 分配器 = std::allocator<元素>>'; args = '<元素, 分配器>' }
    tests = @(
      @('只引中文头','#包含 <链表>`n整数 主函数(){ 标准::链表<整数> 甲; 甲.尾插(1); 甲.头插(0); 甲.尾部就地构造(2); 返回 甲.前() + (整数)甲.尺寸() - 3; }'),
      @('与微软原头并存','#包含 <链表>`n#包含 <list>`n整数 主函数(){ 标准::链表<整数> 甲; 甲.push_back(1); std::list<int> 乙; 乙.push_back(1); 返回 (整数)甲.尺寸() - (整数)乙.size(); }'),
      @('排序 / 去重 / 反转','#包含 <链表>`n整数 主函数(){ 标准::链表<整数> 甲; 甲.尾插(3); 甲.尾插(1); 甲.尾插(1); 甲.尾插(2); 甲.排序(); 甲.去重(); 甲.反转(); 返回 甲.前() + 甲.后() - 4; }'),
      # §17.27.56 机器守卫：同 <向量>（链名族两边同名，防"静默降级"）。
      @('链名族一致（解包/定位真的作用在我们的迭代器上）','#包含 <链表>`n#包含 <type_traits>`n整数 主函数(){ 标准::链表<整数> 甲{1,2,3}; 自动 首 = 甲.开始();`n  静态断言(!std::is_same_v<std::remove_cvref_t<decltype(标准::细节::_取解包(首))>, decltype(首)>);`n  标准::细节::_定位包装(首, 标准::细节::_取解包(首));`n  标准::细节::_ADL校验范围(甲.开始(), 甲.结束());`n  返回 (整数)甲.尺寸() - 3; }'),
      @('中英并用 + 迭代器','#包含 <链表>`n整数 主函数(){ 标准::链表<整数> 甲; 甲.尾插(1); 甲.尾插(2); 标准::链表<整数>::迭代器 头 = 甲.开始(); 整数 和 = 0; for (; 头 != 甲.结束(); ++头) { 和 += *头; } 甲.erase(甲.begin()); 返回 和 + (整数)甲.尺寸() - 4; }')
    )
  }
  'vector' = @{
    zh      = '向量'
    # -----------------------------------------------------------------------
    #  §16.29（用户 2026-09-28 定「乙」）：顺带把【真 <vector>】也引进来。
    #
    #  为什么：实测（6 个探针）—— 光 `#包含 <向量>` 时 `std::vector` 是【找不到】的
    #  （我们的拷贝是另一份实现，不含 std 的那个类型），必须另外 `#包含 <vector>`。
    #  于是"汉语库还能用原来的英语"就成了空话：用户得猜着多引一个头才行。
    #  加 realInclude 之后，只写 `#包含 <向量>` 就有三样东西：
    #     标准::向量<整数>   —— 汉语名 + 我们的实现
    #     std::vector<int>   —— 英文名 + 微软原件（一个字节没动，铁律①）
    #  两种包含顺序都实测过（真头先 / 我们头先）都编得过。
    #
    #  ⚠ 但要如实说清【拿不到什么】：`std::vector` 【不是】我们的实现，
    #  它也【不可能】是 —— 不是版权问题，是类型身份：std::vector 已被微软的头定义，
    #  C++ 不允许重定义；且微软其它头（<format>/<ranges>/<xutility>…）都按它的
    #  布局与 ABI 引用它，换掉等于整个 STL 崩。这就是铁律①的实质。
    #  随之而来的代价：两个类型【不互通】，布局相同也不能直接传参
    #  （`空型 收(std::vector<整数>&)` 不接受 标准::向量<整数>）—— 这正是
    #  §〇「抄来的中文实现和英文名自动免费不可兼得」的另一面。
    # -----------------------------------------------------------------------
    realInclude = @('vector')
    # §17.27.58 copyFixes（**边界**，不是欠账）：`std::initializer_list` 的
    #   `size/begin/end` 永远是英文（铁律③：它只能是 std 那一个）。
    copyFixes = @( @('_Ilist.尺寸()', '_Ilist.size()'),
                   @('_Ilist.开始()', '_Ilist.begin()'),
                   @('_Ilist.结束()', '_Ilist.end()') )
    types   = [ordered]@{ 'vector' = '向量实现'
      '_Container_proxy_ptr' = '_容器代理指针'
      '_Container_base' = '_容器基类'
      '_Iterator_base12' = '_迭代器基类12'
      '_Iterator_base' = '_迭代器基类'
      '_Leave_proxy_unbound' = '_离开代理未绑定'
      '_GET_PROXY_ALLOCATOR' = '_取代理分配器'
                          # ------------------------------------------------------------------
                          # ⚠ 2026-09-28 更正（§2.4 / §16.33）：这里原来写着
                          #   "迭代器类（_Vector_iterator / _Vb_iterator 等）都是本文件内部件，
                          #    故意不改名" —— **那是错的，而且没写理由**。
                          #   §六第 6 条早就定了「内部件也翻成中文，保留前导 _ 以标示内部」，
                          #   而这批名字都是【本文件自己定义】的长名，不存在 §10.2 那种
                          #   "同一个名字另有主人"的歧义 -> 按判据【必须翻】。
                          #   真正"故意不改名"的是另外两个，且都写在文档里：
                          #     bitset::reference（第 346 行注）、thread::id（第 732 行）
                          #     —— 理由是【名字太短、全局 \b..\b 替换有二义】。
                          #   译名见方案 §2.4.1（该节此前被 §六第 6 条引用却根本不存在，
                          #   本轮一并补出）。
                          # ------------------------------------------------------------------
                          '_Vector_val'            = '_向量值'
                          '_Vector_iterator'       = '_向量迭代器'
                          '_Vector_const_iterator' = '_向量常量迭代器'
                          '_Vec_iter_types'        = '_向量迭代类型集'
                          '_Value_init_tag'        = '_值初始化标记'
                          '_Wrap_alloc'            = '_包装分配器'
                          '_Vbase'                 = '_位基'
                          '_Vbase_compare_three_way' = '_位基三路比较'
                          '_Vb_val'                = '_位向量值'
                          '_Vb_iterator'           = '_位向量迭代器'
                          '_Vb_const_iterator'     = '_位向量常量迭代器'
                          '_Vb_iter_base'          = '_位向量迭代基类'
                          '_Vb_reference'          = '_位引用'
                          # §16.36 容器族第 ① 类嵌套名（本头类内私有别名，无第二个主人）
                          '_Alty'                  = '_分配器类型'
                          '_Alty_traits'           = '_分配器特征'
                          '_Alproxy_type'          = '_代理分配器类型'
                          '_Scary_val'             = '_迭代器检查值'
                          '_Size_type'             = '_尺寸类型'
                          '_Difference_type'       = '_差异类型'
                          '_Tptr'                  = '_类型指针'
                          '_Mycont'                = '_我的容器'
                          '_Comp'                  = '_比较器'
                          '_Vectype'               = '_向量类型'
                          '_Reft'                  = '_引用类型'
                          '_Alvbase'               = '_位向量基分配器'
                          '_Alvbase_traits'        = '_位向量基分配器特征'
                          '_Alvbase_wrapped'       = '_位向量基分配器包装'
                          '_Prevent_inheriting_unwrap' = '_阻止继承解包'
                          '_Asan_create_guard'     = '_地址消毒创建守卫'
                          '_Asan_extend_guard'     = '_地址消毒延长守卫'
                          '_Reallocation_guard'    = '_重分配守卫'
                          '_Simple_reallocation_guard' = '_简单重分配守卫'
                          '_Reallocation_policy'   = '_重分配策略'
                          '_Vaporization_guard'    = '_蒸发守卫'
                          # ⚠ 宏名也必须一起汉化（§16.24 判据，本轮由宏泄漏守卫【在组合探针之前】抓到）：
                          #   这两个宏的宏体里含 _Asan_create_guard / _Asan_extend_guard，
                          #   而那两个名字已被翻成汉语 -> 宏体出现汉语 -> 宏名若不改，
                          #   真 <vector> 展开同名宏时会拿到汉语标识符（在 std 里找不到）。
                          '_ASAN_VECTOR_CREATE_GUARD' = '_地址消毒向量创建守卫'
                          '_ASAN_VECTOR_EXTEND_GUARD' = '_地址消毒向量延长守卫'
                          # §16.41 第 ① 类：`using _Alloc = _Alloc0;`（本文件自己声明的）。
                          # ⚠ 它同时被用作多处模板参数名 —— 全局改名是【一致】的（都是同一个名字），
                          #   会一并变成 `_分配器`；`typename _Alvbase_wrapped::_Alloc` 那一侧的
                          #   _Wrap_alloc 也是本文件定义的类，两边一起改不会错位。
                          '_Alloc'                 = '_分配器' }
    # vector<bool> 特化也定义在本文件里，同一个 types 改名会一起覆盖 ——
    # 于是 细节::向量实现<bool, 分配器> 自动指到那个特化，派生层不用特殊处理。
    members = [ordered]@{
      '_Alloc_temporary2' = '_分配器临时对象2';
      '_Compressed_pair' = '_压缩对';
      '_Container_proxy' = '_容器代理';
      '_Dest' = '_目标';
      '_Elem' = '_元素';
