    zhIncludes = @{ 'xmemory' = '内存内部件' }
    data    = [ordered]@{}
    derive  = @( @('size','尺寸'), @('empty','为空'),
                 @('capacity','容量'), @('reserve','预留'), @('data','数据'),
                 @('begin','开始'), @('end','结束'),
                 @('at','取值'), @('front','前'), @('back','后'),
                 @('push_back','尾插'), @('pop_back','尾删'),
                 @('emplace','就地构造'), @('emplace_back','尾部就地构造'),
                 @('insert','插入'), @('erase','擦除'), @('assign','赋值'),
                 @('resize','调整尺寸'), @('shrink_to_fit','收缩至适应'),
                 @('clear','清空'), @('get_allocator','取分配器') )
    deriveExtra = '    模板 <类型名... 参数> 声明类型(自动) 最大尺寸(参数&&... 值) 常量 { 返回 基类::max_size(static_cast<参数&&>(值)...); }'
    deriveTypes = @( @('迭代器','iterator'), @('常量迭代器','const_iterator'),
                     @('反向迭代器','reverse_iterator'), @('常量反向迭代器','const_reverse_iterator'),
                     @('值类型','value_type'), @('尺寸类型','size_type'),
                     @('引用','reference'), @('常量引用','const_reference') )
    stdHash = $false
    tparam  = @{ decl = '模板 <类型名 元素, 类型名 分配器 = std::allocator<元素>>'; args = '<元素, 分配器>' }
    tests = @(
      @('只引中文头 + 强制实例化（预留/扩容会走到 _Alty_traits::max_size 那类只在实例化时检查的位置）','#包含 <向量>`n整数 主函数(){ 标准::向量<整数> 表; 表.预留(64); 表.尾插(1); 表.尾插(2); 表.尾部就地构造(3); (空型)表.最大尺寸(); (空型)表.容量(); 返回 表.前() + (整数)表.尺寸() - 4; }'),
      @('与微软原头并存','#包含 <向量>`n#包含 <vector>`n整数 主函数(){ 标准::向量<整数> 表; 表.push_back(1); std::vector<int> 乙; 乙.push_back(1); 返回 (整数)表.尺寸() - (整数)乙.size(); }'),
      # ⚠ §16.29（乙）：**只写** `#包含 <向量>`，不加 `#include <vector>` ——
      #   英文名必须照样可用。这条测试就是那条要求的守卫；
      #   去掉 realInclude 它立刻会红。
      @('只写 <向量> 就能同时用 std::vector','#包含 <向量>`n整数 主函数(){ 标准::向量<整数> 汉; std::vector<整数> 英; 汉.尾插(1); 英.push_back(1); 返回 (整数)汉.尺寸() - (整数)英.size(); }'),
      @('中英并用 + 容量 / 预留 / 下标','#包含 <向量>`n整数 主函数(){ 标准::向量<整数> 表(3, 7); 表.reserve(10); 表[0] = 1; 整数 和 = 表[0] + 表.at(1); 布尔 够 = 表.容量() >= 10; 返回 和 + (够 ? 0 : 1) - 8; }'),
      # §17.27.56 机器守卫：链名族必须"两边同名" —— `通用内部件` 的 `_取解包` 正文里
      #   走的是 `if constexpr (_Unwrappable_v<_Iter>)` -> `._解包()`。名字对不上时**不报错**，
      #   而是判据变假、解包直通 -> 这条断言就会失败（把"静默降级"变成"看得见的红"）。
      @('链名族一致（解包/定位真的作用在我们的迭代器上）','#包含 <向量>`n#包含 <type_traits>`n整数 主函数(){ 标准::向量<整数> 甲{1,2,3}; 自动 首 = 甲.开始();`n  静态断言(!std::is_same_v<std::remove_cvref_t<decltype(标准::细节::_取解包(首))>, decltype(首)>);`n  标准::细节::_定位包装(首, 标准::细节::_取解包(首));`n  标准::细节::_ADL校验范围(甲.开始(), 甲.结束());`n  返回 (整数)甲.尺寸() - 3; }'),
      @('迭代器 + vector<bool> 特化','#包含 <向量>`n整数 主函数(){ 标准::向量<bool> 位(3, true); 位.尾插(false); 整数 数 = 0; for (标准::向量<bool>::迭代器 头 = 位.开始(); 头 != 位.结束(); ++头) { if (*头) { ++数; } } 返回 数 - 3; }')
    )
  }
