    derive  = @( @('empty','为空'), @('max_size','最大尺寸'),
                 @('before_begin','首前'), @('begin','开始'), @('end','结束'),
                 @('front','前'),
                 @('push_front','头插'), @('pop_front','头删'),
                 @('emplace_front','头部就地构造'),
                 @('insert_after','后插'), @('emplace_after','后就地构造'),
                 @('erase_after','后擦除'),
                 @('assign','赋值'), @('resize','调整尺寸'), @('clear','清空'),
                 @('get_allocator','取分配器'),
                 @('sort','排序'), @('merge','归并'), @('splice_after','后接合'),
                 @('remove','移除'), @('remove_if','按条件移除'),
                 @('unique','去重'), @('reverse','反转') )
    deriveTypes = @( @('迭代器','iterator'), @('常量迭代器','const_iterator'),
                     @('值类型','value_type'), @('尺寸类型','size_type') )
    stdHash = $false
    tparam  = @{ decl = '模板 <类型名 元素, 类型名 分配器 = std::allocator<元素>>'; args = '<元素, 分配器>' }
    tests = @(
      @('只引中文头','#包含 <单向链表>`n整数 主函数(){ 标准::单向链表<整数> 甲; 甲.头插(1); 甲.头插(0); 布尔 空 = 甲.为空(); 返回 甲.前() + (空 ? 1 : 0); }'),
      @('与微软原头并存','#包含 <单向链表>`n#包含 <forward_list>`n整数 主函数(){ 标准::单向链表<整数> 甲; 甲.push_front(1); std::forward_list<int> 乙; 乙.push_front(1); 返回 甲.前() - 乙.front(); }'),
      # §17.27.56 机器守卫：同 <向量>（链名族两边同名，防"静默降级"）。
      @('链名族一致（解包/定位真的作用在我们的迭代器上）','#包含 <单向链表>`n#包含 <type_traits>`n整数 主函数(){ 标准::单向链表<整数> 甲{1,2,3}; 自动 首 = 甲.开始();`n  静态断言(!std::is_same_v<std::remove_cvref_t<decltype(标准::细节::_取解包(首))>, decltype(首)>);`n  标准::细节::_定位包装(首, 标准::细节::_取解包(首));`n  标准::细节::_ADL校验范围(甲.开始(), 甲.结束());`n  返回 0; }'),
      @('后插 / 后擦除 / 迭代器','#包含 <单向链表>`n整数 主函数(){ 标准::单向链表<整数> 甲; 甲.头插(2); 甲.后插(甲.首前(), 1); 甲.后擦除(甲.首前()); 整数 和 = 0; for (标准::单向链表<整数>::迭代器 头 = 甲.开始(); 头 != 甲.结束(); ++头) { 和 += *头; } 返回 和 - 2; }'),
      @('排序 / 去重 / 反转','#包含 <单向链表>`n整数 主函数(){ 标准::单向链表<整数> 甲; 甲.头插(1); 甲.头插(3); 甲.头插(1); 甲.排序(); 甲.去重(); 甲.反转(); 返回 甲.前() - 3; }')
    )
  }
  'queue' = @{
    zh      = '队列'
    realInclude = @('queue')   # §16.29「乙」
    types   = [ordered]@{ 'queue' = '队列实现'
                          'priority_queue' = '优先队列实现'
                          # §16.41 第 ① 类：`container_type` / `value_compare` 只属于本类，
                          #   拷贝层的 `using X = _Container;` / `= _Pr;` 右边是我们的模板参数
                          #   （不是借用类型的成员）-> 可以翻。
                          'container_type' = '容器类型'
                          'value_compare'  = '值比较' }
    # ⚠ 只有【主类】(队列) 的那几个才进 deriveTypes —— `value_compare` 属于 priority_queue，
    #   写进这里会生成 `使用 value_compare = 基类::值比较;` 挂到 队列 上 -> 报没有这个成员
    #   （§10.1 第 2/3 类错误；§16.35.5 配方第 2 步）。
    deriveTypes = @( @('container_type','容器类型') )
    # ⚠ 不翻 uses_allocator / formatter —— 它们是 std 的模板，改名会断（同 <栈>）
    members = [ordered]@{


      '_Get_unwrapped' = '_取解包';
      '_Adaptor_formatter_base' = '_适配器格式化基类'
      '_Alloc' = '_分配器'
      '_Comp' = '_比较器'
      '_First' = '_首个'
      '_Last' = '_最后'
      '_Ty' = '_类型';
      '_Valty' = '_值参数类型'
      'emplace' = '就地构造'; 'pop' = '弹出'
      'push' = '压入'; 'push_range' = '范围压入'
      # §16.74 与 `<栈>` **同批**的协调改名（两个条目同译名，跨头译名守卫强制）：
      #   `_Get_container`（本头定义 1 处）/ `_Make_heap`（本头定义 17 处）都是
      #   本头自己的内部助手 —— 都翻。
      #   ⚠ `back` / `front` **不翻**：它们调的是【借来的容器】的 `c.back()`/`c.front()`
      #     （§15.10 形态②，与 `size`/`empty` 同一类）-> 登记为边界。
      #   ⚠ `make_heap` / `pop_heap` / `push_heap` 是 std 算法（借来的）-> 边界。
      '_Get_container' = '_取容器'
      '_Make_heap' = '_造堆'
      # ⚠ swap 【不登记】（§3.12 + §16.30.3）：正文是
      #     `using _STD swap; swap(c, _Right.c); // intentional ADL`
      #   —— 那是有意的 ADL 自由函数调用。改名 + 步4c 去限定之后，
      #   `交换(c, _Right.c)` 会被解析成我们自己的同名【成员】`交换(队列实现&)`，
      #   报"实参太多 / 调用非静态成员函数时没有对象实参"。
      #   ⚠ 以前这里登记了 `swap -> 交换`，靠"编译器报错后自动回退"兜住 ——
      #   但**依赖回退就是依赖"它恰好在被编译到的位置"**（§16.30.2），不该有这种运气。
      #   正确做法与同条目的 front/size 一致：不登记，中文名在 deriveExtra 手写、调 基类::swap。
      # ⚠ empty/size/front/back 故意【不】登记改名：queue 正文里 c.front()/c.size() 调的是
      #   【借来的容器】std::deque（成员是英文），改名会报 deque 中没有 '前'/'尺寸'（§15.9）。
      #   中文名改在派生层手写。
      'top' = '堆顶'
    ;
      'comp' = '比较器';
}
    data    = [ordered]@{}
    derive  = @( @('emplace','就地构造'), @('pop','弹出'),
                 @('push','压入'), @('push_range','范围压入') )
    deriveExtra = @'
    模板 <类型名... 参数> 声明类型(自动) 交换(参数&&... 值) { 返回 基类::swap(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 尺寸(参数&&... 值) 常量 { 返回 基类::size(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 为空(参数&&... 值) 常量 { 返回 基类::empty(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 前(参数&&... 值) { 返回 基类::front(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 后(参数&&... 值) { 返回 基类::back(static_cast<参数&&>(值)...); }
'@
    stdHash = $false
    tparam  = @{ decl = '模板 <类型名 元素, 类型名 容器 = std::deque<元素>>'; args = '<元素, 容器>' }
    extra = @'

名域 标准 {

// 优先队列（std::priority_queue）—— 默认容器是 vector，还多一个比较器参数
模板 <类型名 元素, 类型名 容器 = std::vector<元素>,
      类型名 比较 = std::less<typename 容器::value_type>>
类型 优先队列 : 公开 细节::优先队列实现<元素, 容器, 比较> {
公开:
    使用 基类 = 细节::优先队列实现<元素, 容器, 比较>;
    使用 基类::基类;
    // ⚠ §16.41：派生层的 deriveTypes 只管【主类 队列】，管不到这里。
    //   抄来那层已经把 container_type / value_compare 翻成汉语，
    //   所以这两个类的英文原名必须【在这里手写补回】——
    //   不写就是"翻一半"：原来能用的 `标准::优先队列<T>::container_type` 会消失（回归）。
    使用 container_type = 基类::容器类型;
    使用 value_compare  = 基类::值比较;
    模板 <类型名... 参数> 声明类型(自动) push(参数&&... 值) { 返回 基类::压入(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) pop(参数&&... 值) { 返回 基类::弹出(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) top(参数&&... 值) 常量 { 返回 基类::堆顶(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 为空(参数&&... 值) 常量 { 返回 基类::empty(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 尺寸(参数&&... 值) 常量 { 返回 基类::size(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) emplace(参数&&... 值) { 返回 基类::就地构造(static_cast<参数&&>(值)...); }
};

}  // 名域 标准
'@
    tests = @(
      @('只引中文头','#包含 <队列>`n整数 主函数(){ 标准::队列<整数> 甲; 甲.压入(1); 甲.压入(2); 整数 前 = 甲.前(); 甲.弹出(); 返回 前 + (整数)甲.尺寸() - 2; }'),
      @('与微软原头并存','#包含 <队列>`n#包含 <queue>`n整数 主函数(){ 标准::队列<整数> 甲; 甲.push(1); std::queue<int> 乙; 乙.push(1); 返回 (整数)甲.尺寸() - (整数)乙.size(); }'),
      @('优先队列（堆顶 / 弹出）','#包含 <队列>`n整数 主函数(){ 标准::优先队列<整数> 甲; 甲.压入(1); 甲.压入(5); 甲.压入(3); 整数 顶 = 甲.堆顶(); 甲.弹出(); 返回 顶 + (整数)甲.尺寸() - 7; }'),
      @('英文名与中文名并用','#包含 <队列>`n整数 主函数(){ 标准::队列<整数> 甲; 甲.压入(1); 甲.push(2); 布尔 空 = 甲.empty(); 返回 甲.前() + (空 ? 1 : 0) - 1; }'),
      # ⚠ §16.41 的守卫：`container_type`/`value_compare` 在抄来那层翻了，
      #   而【手写的 优先队列】不在 deriveTypes 的覆盖范围内 —— 它的英文原名是手写补回的。
      #   这条测试就是"没翻一半"的机器保证：两类名字都得在。
      @('容器类型/值比较：汉英两种名字都在（含手写 extra 的优先队列）','#包含 <队列>`n整数 主函数(){`n  (空型)sizeof(标准::队列<整数>::容器类型);`n  (空型)sizeof(标准::队列<整数>::container_type);`n  (空型)sizeof(标准::优先队列<整数>::容器类型);`n  (空型)sizeof(标准::优先队列<整数>::container_type);`n  (空型)sizeof(标准::优先队列<整数>::值比较);`n  (空型)sizeof(标准::优先队列<整数>::value_compare);`n  返回 0; }')
    )
  }
  'unordered_set' = @{
    zh      = '无序集合'
    realInclude = @('unordered_set')   # §16.29「乙」
    # ===========================================================================
    #  §16.51 【销账】把 <无序集合> 切到我们自己的 哈希内部件（xhash）。
    #  §16.49 修了前置阻塞（友元），§16.50 修了两个内部件的同步改名，
    #  §16.51 补上最后一层（`_Hash` 的公开 API 名 size/clear）—— 于是能照 §16.44 走。
    # ===========================================================================
    zhIncludes = @{ 'xhash' = '哈希内部件' }
    types   = [ordered]@{ 'unordered_set' = '无序集合实现'
                          'unordered_multiset' = '无序多重集合实现'
                          '_Uset_traits' = '_无序集合特征'
                          # §16.37 【实测结论：不能翻】`_Mutable_value_type` / `_In_place_key_extractor`
                          #   都被【借来的 std::_Hash】读取（xhash:335）-> 第 ③ 类；
                          #   消除路径 = 步骤 1 抄 <xhash>。
                          # `_Mytraits` 是【我们自己】用的（std::_Hash 不读它）-> ① 类，可以翻。
                          '_Mytraits' = '_我的特征'
                          # §16.51 切到我们自己的 哈希内部件
                          '_Hash'          = '_哈希'
                          '_Uhash_compare' = '_无序哈希比较'
                          '_Is_hasher'     = '_是哈希器'
                          # ⚠ §16.60 起 _Alnode / _Alnode_traits / _Key_compare **已经翻**了
                          #   （与 链表 + 哈希内部件 同批，§16.45：基类是我们的，两边一起改）。
                          #   这条注释原来写的是"它们在 哈希内部件 里没被改名，照旧可用" ——
                          #   那句话随本批**废止**。
                          '_Alnode'             = '_结点分配器'
                          '_Alnode_traits'      = '_结点分配器特征'
                          '_Key_compare'        = '_键比较器'
                          # §16.60 其余 4 个（traits 里声明、`_哈希` 读）：本头同批翻。
                          'key_compare'         = '键比较器'
                          'value_compare'       = '值比较'
                          '_Mutable_value_type' = '_可变值类型'
                          '_In_place_key_extractor' = '_就地键提取器'
                          # §16.58 跨条目协调改名（与 哈希内部件 同批）：
                          #   `_Uset_traits` 里的这三个名字被 `_哈希` 读
                          #   （`typename _Traits::allocator_type/key_type/node_type`），
                          #   本头还有 `typename _Mybase::allocator_type/node_type`
                          #   -> 必须同批翻；公开层靠 deriveTypes【方向翻转】补回英文。
                          'allocator_type' = '分配器类型'
                          'key_type'       = '键类型'
                          'node_type'      = '结点类型'
                          # §16.59 协调改名第二批（本头独有的 6 个）：
                          #   它们**只在无序容器里声明**（traits 里没有，`_哈希` 也不读）
                          #   -> 不必牵动 哈希内部件，只在本条目 + 公开层补英文。
                          #   实测：每个都 0 处 `X::名字` 限定读取（§16.58 第一步）。
                          'hasher'              = '散列器'
                          'key_equal'           = '键相等器'
                          'insert_return_type'  = '插入返回类型'
                          'const_reference'     = '常量引用'
                          'local_iterator'      = '局部迭代器'
                          'const_local_iterator' = '常量局部迭代器'
                          }
    members = [ordered]@{
      '_Get_first' = '_取第一';
      '_Alloc' = '_分配器';
      '_First' = '_首个';
      '_Getal' = '_取分配器';
      '_Guide_size_type_t' = '_推导尺寸类型';
      '_In_place_key_extract_set' = '_就地键提取集合';
      '_Insert_range_unchecked' = '_插入范围非检查';
      '_Last' = '_最后';
      '_List_node' = '_链表节点';
      '_Traits' = '_特征'; 
      # §17.27.60 台账收尾（阶段(3) 第一批）：这些名字的定义方是 通用内部件（我们的 xutility 拷贝，
      #   §17.27.52 已给定义方解毒）；本头能看到它 -> 调用点跟改，指向我们那份。
      '_Ubegin' = '_解包首'
      '_Uend' = '_解包尾'
      '_Pass_fn' = '_传递函数'
                          # §16.82 本头自己定义的两个公开 API（抄来那层翻 + 派生层补英文）
                          'hash_function'    = '散列函数'
                          'key_eq'           = '取键相等器'
                          # §16.83 与 哈希内部件 同批：正文调 `_Mybase::rehash(...)`
                          'rehash'           = '重哈希'
                          # §17.8 `_Kfn`（traits 定义侧）——与 哈希内部件 同批，见那边的说明。
                          '_Kfn'             = '_取键'
                          # §16.51 同步改名（本头正文调 `_Mybase::X` / `_Hash::X`）
                          '_Hash_equal'      = '_哈希相等'
                          '_Unchecked_begin' = '_非检查开始'
                          '_Unchecked_end'   = '_非检查结束'
                          'clear'            = '清空' ;
      '_Traitsobj' = '_特征对象';

      # '负载因子' = '负载因子';  # §17.19.49 本条目拷贝层 0 命中（登记≠落地守卫点名），撤下

      # '桶数' = '桶数';  # §17.19.49 本条目拷贝层 0 命中（登记≠落地守卫点名），撤下
}
    data    = [ordered]@{}
    # §16.51 公开 API 名的英文补回（§9.1 的新方向：抄来那层已汉语，派生层补英文）。
    #   ⚠ 漏一个就是回归 —— 用户本来能写的 标准::无序集合<T>::size() 会消失。
    derive  = @( @('emplace','就地构造'), @('emplace_hint','按提示就地构造'),
                 @('size','尺寸'), @('clear','清空'),
                 # §16.82 本头【自己定义】的两个公开 API（实测 hash_function/key_eq
                 #   只在两个无序头里有定义）-> 翻 + 派生层补回英文。
                 @('hash_function','散列函数'), @('key_eq','取键相等器'),
                 @('rehash','重哈希'),
                 @('begin','开始'), @('end','结束'), @('empty','为空'),
                 @('get_allocator','取分配器') )
    deriveTypes = @( @('迭代器','iterator'), @('常量迭代器','const_iterator'),
                     @('尺寸类型','size_type'),
                     # §16.58 跨条目协调改名（与 哈希内部件 同批）：
                     #   `key_type`/`allocator_type`/`node_type` 方向**翻转**
                     #   （抄来那层已汉语 -> 公开层补【英文原名】）；
                     #   `allocator_type`/`node_type` 还是借来的 std 契约名
                     #   （uses_allocator 读 X::allocator_type），必须补回，
                     #   否则泛型代码静默换路径（而且照样编得过）。
                     @('key_type','键类型'), @('allocator_type','分配器类型'),
                     @('node_type','结点类型'),
                     # ⚠ 顺手补一个【旧方向】的：`value_type` 是边界（迭代器契约，
                     #   抄来那层不能翻），主类一直缺汉语名 ——
                     #   用户写 标准::无序集合<T>::值类型 本来会失败。
                     @('值类型','value_type'),
                     # §16.59 第二批：同样【方向翻转】补回英文原名。
                     @('hasher','散列器'), @('key_equal','键相等器'),
                     @('insert_return_type','插入返回类型'),
                     @('const_reference','常量引用'),
                     @('local_iterator','局部迭代器'),
                     @('const_local_iterator','常量局部迭代器') )
    deriveExtra = @'
    模板 <类型名... 参数> 声明类型(自动) 插入(参数&&... 值) { 返回 基类::insert(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 擦除(参数&&... 值) { 返回 基类::erase(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 查找(参数&&... 值) { 返回 基类::find(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 计数(参数&&... 值) 常量 { 返回 基类::count(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 尺寸(参数&&... 值) 常量 { 返回 基类::尺寸(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 为空(参数&&... 值) 常量 { 返回 基类::为空(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 清空(参数&&... 值) { 返回 基类::清空(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 包含(参数&&... 值) 常量 { 返回 基类::contains(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 开始(参数&&... 值) { 返回 基类::开始(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 结束(参数&&... 值) { 返回 基类::结束(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 桶数(参数&&... 值) 常量 { 返回 基类::桶数(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 负载因子(参数&&... 值) 常量 { 返回 基类::负载因子(static_cast<参数&&>(值)...); }
'@
    stdHash = $false
    tparam  = @{ decl = '模板 <类型名 键, 类型名 散列 = std::hash<键>, 类型名 相等 = std::equal_to<键>, 类型名 分配器 = std::allocator<键>>'; args = '<键, 散列, 相等, 分配器>' }
    extra = @'

名域 标准 {

// 无序多重集合（std::unordered_multiset）—— 与 <集合>/<多重集合> 的分工一致
模板 <类型名 键, 类型名 散列 = std::hash<键>, 类型名 相等 = std::equal_to<键>,
      类型名 分配器 = std::allocator<键>>
类型 无序多重集合 : 公开 细节::无序多重集合实现<键, 散列, 相等, 分配器> {
公开:
    使用 基类 = 细节::无序多重集合实现<键, 散列, 相等, 分配器>;
    使用 基类::基类;

    // §16.51 嵌套类型名也补中文（主类有 deriveTypes，这个类得手写）
    使用 迭代器 = 基类::iterator;
    使用 常量迭代器 = 基类::const_iterator;
    使用 值类型 = 基类::value_type;
    使用 尺寸类型 = 基类::size_type;
    // §16.58 这三个名字在【抄来那层】已经是汉语了 -> 这里改成补【英文原名】
    //   （方向翻转，与主类 deriveTypes 一致）；中文名从基类继承，不再手写。
    使用 key_type = 基类::键类型;
    使用 node_type = 基类::结点类型;
    使用 allocator_type = 基类::分配器类型;
    // §16.59 第二批的英文回填（这个类得手写）。
    //   ⚠ `local_iterator`/`const_local_iterator` 原头里只有【主类】声明，
    //     这个类是**从 `_哈希` 继承**来的 —— §16.55 把 `_哈希` 的这两个名字翻成汉语后，
    //     继承来的英文名就没了（std 的 unordered_multiset 是有的）-> 这里必须补回。
    使用 hasher = 基类::散列器;
    使用 key_equal = 基类::键相等器;
    使用 const_reference = 基类::常量引用;
    使用 local_iterator = 基类::局部迭代器;
    使用 const_local_iterator = 基类::常量局部迭代器;

    // §16.51 英文原名回填：这 8 个名字（emplace / emplace_hint + 6 个继承自 _哈希 的公开 API）
    //   在【抄来那层】已经是汉语 —— 不回填，用户原本能写的 甲.size() 就没了 = 回归。
    模板 <类型名... 参数> 声明类型(自动) emplace(参数&&... 值) { 返回 基类::就地构造(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) emplace_hint(参数&&... 值) { 返回 基类::按提示就地构造(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) size(参数&&... 值) { 返回 基类::尺寸(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) size(参数&&... 值) 常量 { 返回 基类::尺寸(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) clear(参数&&... 值) { 返回 基类::清空(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) begin(参数&&... 值) { 返回 基类::开始(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) begin(参数&&... 值) 常量 { 返回 基类::开始(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) end(参数&&... 值) { 返回 基类::结束(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) end(参数&&... 值) 常量 { 返回 基类::结束(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) empty(参数&&... 值) 常量 { 返回 基类::为空(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) get_allocator(参数&&... 值) 常量 { 返回 基类::取分配器(static_cast<参数&&>(值)...); }

    // 主类在 deriveExtra 里有 桶数/负载因子，这个类也得有（空测掩盖至今）
    模板 <类型名... 参数> 声明类型(自动) 桶数(参数&&... 值) 常量 { 返回 基类::桶数(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 负载因子(参数&&... 值) 常量 { 返回 基类::负载因子(static_cast<参数&&>(值)...); }
    // ⚠ §16.51 修：下面这几行的基类名以前写成英文 size/empty/clear/begin/end ——
    //   切到我们自己的 哈希内部件 之后，那些名字在基类里【已经是汉语】了。
    //   之所以一直没报错，是因为转发器是模板、没人实例化就不会查基类名字
    //   （"空测掩盖"）—— 现在由下面那条真测试把它钉住。
    模板 <类型名... 参数> 声明类型(自动) 插入(参数&&... 值) { 返回 基类::insert(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 擦除(参数&&... 值) { 返回 基类::erase(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 查找(参数&&... 值) { 返回 基类::find(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 计数(参数&&... 值) 常量 { 返回 基类::count(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 尺寸(参数&&... 值) 常量 { 返回 基类::尺寸(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 为空(参数&&... 值) 常量 { 返回 基类::为空(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 清空(参数&&... 值) { 返回 基类::清空(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 包含(参数&&... 值) 常量 { 返回 基类::contains(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 开始(参数&&... 值) { 返回 基类::开始(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 结束(参数&&... 值) { 返回 基类::结束(static_cast<参数&&>(值)...); }
};

}  // 名域 标准
'@
    tests = @(
      @('只引中文头','#包含 <无序集合>`n整数 主函数(){ 标准::无序集合<整数> 甲; 甲.插入(1); 甲.插入(2); 返回 甲.计数(1) + (整数)甲.尺寸() - 3; }'),
      # §16.82 欠账销账：hash_function / key_eq 是公开 API，翻它们靠 derive 补回英文 ——
      #   这条把【中文名】与【英文原名】各真调用一次（§16.64 判据）。
      @('散列函数 / 取键相等器 都真能调','#包含 <无序集合>`n整数 主函数(){ 标准::无序集合<整数> 甲; (空型)甲.hash_function(); (空型)甲.散列函数(); (空型)甲.key_eq(); (空型)甲.取键相等器(); 返回 0; }'),
      # §16.83 欠账销账：rehash 同批翻了（哈希内部件 + 两个无序头），这里把
      #   【英文原名】与【中文名】各真调用一次（§16.64 判据）。
      @('重哈希 / rehash 都真能调','#包含 <无序集合>`n整数 主函数(){ 标准::无序集合<整数> 甲; 甲.rehash(16); 甲.重哈希(16); 返回 0; }'),
      @('与微软原头并存','#包含 <无序集合>`n#包含 <unordered_set>`n整数 主函数(){ 标准::无序集合<整数> 甲; 甲.insert(1); std::unordered_set<int> 乙; 乙.insert(1); 返回 (整数)甲.尺寸() - (整数)乙.size(); }'),
      @('中英并用 + 中文迭代器','#包含 <无序集合>`n整数 主函数(){ 标准::无序集合<整数> 甲; 甲.插入(3); 标准::无序集合<整数>::迭代器 头 = 甲.开始(); 整数 和 = 0; for (; 头 != 甲.结束(); ++头) { 和 += *头; } 返回 和 - 3; }'),
      @('无序多重集合 + 桶数 / 负载因子','#包含 <无序集合>`n整数 主函数(){ 标准::无序多重集合<整数> 甲; 甲.插入(1); 甲.插入(1); 布尔 有 = 甲.桶数() > 0 && 甲.负载因子() > 0.0f; 返回 (整数)甲.计数(1) + (有 ? 0 : 1) - 2; }'),
      # §16.51 真守卫：这个类【不在 deriveTypes/derive 的作用范围里】——
      #   嵌套中文类型名与中英双语转发全靠手写，只写主类的测试会漏掉它。
      #   ⚠ 以前没有这条测试 -> 那几行 `基类::size/empty/clear/begin/end` 是坏名字
      #     （模板惰性实例化，不调用就不查基类）—— 现在每个名字都必须真被调用到。
      @('无序多重集合：中英双语 + 嵌套类型','#包含 <无序集合>`n整数 主函数(){ 标准::无序多重集合<整数> 甲;`n  (空型)sizeof(标准::无序多重集合<整数>::常量迭代器);`n  标准::无序多重集合<整数>::键类型 钥 = 1; 标准::无序多重集合<整数>::值类型 值 = 2;`n  标准::无序多重集合<整数>::迭代器 头 = 甲.begin(); 头 = 甲.end();`n  甲.emplace(钥); 甲.emplace_hint(头, 值); 甲.插入(值); 头 = 甲.开始(); 头 = 甲.结束();`n  整数 有 = 甲.包含(钥) ? 1 : (甲.查找(钥) == 甲.结束() ? 0 : 1);`n  整数 尺 = (整数)甲.尺寸() - (整数)甲.size(); 整数 空 = 甲.为空() ? 1 : (甲.empty() ? 1 : 0);`n  整数 桶 = 甲.桶数() > 0 ? 0 : 1; 整数 因子 = 甲.负载因子() > 0.0f ? 0 : 1;`n  (空型)甲.get_allocator(); (空型)甲.计数(钥); (空型)甲.擦除(钥); 甲.清空(); 甲.clear();`n  (空型)sizeof(标准::无序多重集合<整数>::尺寸类型);`n  返回 有 + 尺 + 空 + 桶 + 因子 - 1; }'),
      # §16.55 回归守卫：把 `_哈希` 内部的 local_iterator/const_local_iterator/
      #   const_reference 翻成汉语，**不能**把公开层的这三个英文名一起带走
      #   （消费者拷贝自己声明了 `using local_iterator = typename _Mybase::iterator;`）。
      @('桶迭代器名仍在（3 名销账的回归守卫）','#包含 <无序集合>`n整数 主函数(){`n  (空型)sizeof(标准::无序集合<整数>::local_iterator);`n  (空型)sizeof(标准::无序集合<整数>::const_local_iterator);`n  (空型)sizeof(标准::无序集合<整数>::const_reference);`n  返回 0; }'),
      # §16.55.2 / §16.57 泛型契约守卫：借用来的 std 契约名（allocator_type 等）
      #   在【公开层】必须仍是英文 —— 否则 std::uses_allocator 这类泛型代码读不到。
      #   这条探针是"跨条目协调改名"那一轮的验收判据，先立在这里。
      @('泛型契约：uses_allocator 认得出（英文名必须在公开层）','#包含 <无序集合>`n#包含 <memory>`n静态断言(std::uses_allocator<标准::无序集合<整数>, std::allocator<整数>>::value);`n静态断言(std::uses_allocator<标准::无序多重集合<整数>, std::allocator<整数>>::value);`n整数 主函数(){ 返回 0; }'),
      # §16.58 回归守卫：这次把 `_哈希` 的三个名字（allocator_type/key_type/node_type）
      #   翻成汉语 —— 公开层必须【中英两个名字都在、而且指的是同一个类型】。
      #   ⚠ 这就是 §16.41.2 那条："翻一半就是回归"。
      @('三种名字中英一致（§16.58 回归守卫）','#包含 <无序集合>`n#包含 <type_traits>`n静态断言(std::is_same_v<标准::无序集合<整数>::键类型, 标准::无序集合<整数>::key_type>);`n静态断言(std::is_same_v<标准::无序集合<整数>::结点类型, 标准::无序集合<整数>::node_type>);`n静态断言(std::is_same_v<标准::无序集合<整数>::分配器类型, 标准::无序集合<整数>::allocator_type>);`n静态断言(std::is_same_v<标准::无序多重集合<整数>::键类型, 标准::无序多重集合<整数>::key_type>);`n静态断言(std::is_same_v<标准::无序多重集合<整数>::结点类型, 标准::无序多重集合<整数>::node_type>);`n静态断言(std::is_same_v<标准::无序多重集合<整数>::分配器类型, 标准::无序多重集合<整数>::allocator_type>);`n静态断言(std::is_same_v<标准::无序集合<整数>::值类型, 标准::无序集合<整数>::value_type>);`n整数 主函数(){ 返回 0; }'),
      # §16.59 第二批（6 个名字）：同样中英都在且指同一类型。
      #   ⚠ `local_iterator`/`const_local_iterator` 对【多重集合】是继承来的
      #     （原头只有主类声明）—— §16.55 把 `_哈希` 的它们翻了之后，
      #     继承链上的英文名会消失，所以这里必须两边都查。
      @('第二批名字中英一致（§16.59 回归守卫）','#包含 <无序集合>`n#包含 <type_traits>`n静态断言(std::is_same_v<标准::无序集合<整数>::散列器, 标准::无序集合<整数>::hasher>);`n静态断言(std::is_same_v<标准::无序集合<整数>::键相等器, 标准::无序集合<整数>::key_equal>);`n静态断言(std::is_same_v<标准::无序集合<整数>::插入返回类型, 标准::无序集合<整数>::insert_return_type>);`n静态断言(std::is_same_v<标准::无序集合<整数>::常量引用, 标准::无序集合<整数>::const_reference>);`n静态断言(std::is_same_v<标准::无序集合<整数>::局部迭代器, 标准::无序集合<整数>::local_iterator>);`n静态断言(std::is_same_v<标准::无序集合<整数>::常量局部迭代器, 标准::无序集合<整数>::const_local_iterator>);`n静态断言(std::is_same_v<标准::无序多重集合<整数>::散列器, 标准::无序多重集合<整数>::hasher>);`n静态断言(std::is_same_v<标准::无序多重集合<整数>::键相等器, 标准::无序多重集合<整数>::key_equal>);`n静态断言(std::is_same_v<标准::无序多重集合<整数>::常量引用, 标准::无序多重集合<整数>::const_reference>);`n静态断言(std::is_same_v<标准::无序多重集合<整数>::局部迭代器, 标准::无序多重集合<整数>::local_iterator>);`n静态断言(std::is_same_v<标准::无序多重集合<整数>::常量局部迭代器, 标准::无序多重集合<整数>::const_local_iterator>);`n整数 主函数(){ 返回 0; }')
    )
  }
  'unordered_map' = @{
    zh      = '无序映射'
    realInclude = @('unordered_map')   # §16.29「乙」
    # ===========================================================================
    #  §16.52 【销账】把 <无序映射> 也切到我们自己的 哈希内部件（xhash）——
    #  与 §16.51 的 <无序集合> 同一套改动。<映射>（xtree）那套是 §16.44 做的。
    #
    #  ★ 动工前按 §16.51.1 先把【整个引用面】grep 完（不靠编译器一条条报）：
    #    · `_Mybase::` 的**类型**名：_Alnode / _Alnode_traits / _Key_compare
    #        （xhash 没翻 -> 照旧）、_Nodeptr（xhash 翻了 -> 必须跟）
    #    · `_Mybase::` 的**成员**名：rehash / operator= / swap / insert /
    #        _Traitsobj / allocator_type / size_type / difference_type /
    #        pointer / const_pointer / iterator / const_iterator / node_type /
    #        max_size（xhash 都没翻 -> 照旧）
    #    · `this->` 私有助手：_Try_emplace / _Try_emplace_hint / _Find_last /
    #        _Find_hint / _Check_max_size / _Check_rehash_required_1 /
    #        _Rehash_for_1 / _Getal / _Insert_new_node_before /
    #        _Insert_range_unchecked（xhash 全翻了 -> 必须跟）
    #    · `this->_List._Make_iter` -> `_Make_iter` 没翻，照旧
    #    · `_List_node` / `_List_node_emplace_op2` 是 <list> 的名字，
    #        <链表> 已翻成 _链表节点 / _链表节点就地构造操作2 -> 必须跟（§16.45）
    #    · `_Hash_equal`（自由函数）-> xhash 翻了 -> 必须跟
    # ===========================================================================
    zhIncludes = @{ 'xhash' = '哈希内部件' }
    types   = [ordered]@{ 'unordered_map' = '无序映射实现'
                          'unordered_multimap' = '无序多重映射实现'
                          '_Umap_traits' = '_无序映射特征'
                          # §16.37 【实测结论：不能翻】`_Mutable_value_type` / `_In_place_key_extractor`
                          #   都被【借来的 std::_Hash】读取（xhash:335）-> 第 ③ 类；消除路径 = 抄 <xhash>。
                          # `_Mytraits` 是【我们自己】用的 -> ① 类，可以翻。
                          '_Mytraits' = '_我的特征'
                          # §16.52 切到我们自己的 哈希内部件
                          '_Hash'          = '_哈希'
                          '_Uhash_compare' = '_无序哈希比较'
                          '_Is_hasher'     = '_是哈希器'
                          # §16.45：`typename _Mybase::X` —— 基类已经是【我们的】，
                          #   所以 X 从第 ③ 类（不能翻）变成【两边一起改】的欠账。
                          '_Nodeptr'       = '_结点指针'
                          # §16.45：借用 <list> 的名字，<链表> 已翻 -> 必须跟。
                          '_List_node'     = '_链表节点'
                          '_List_node_emplace_op2' = '_链表节点就地构造操作2'
                          # ⚠ §16.60 起 _Alnode / _Alnode_traits / _Key_compare **已经翻**了
                          #   （与 链表 + 哈希内部件 同批，§16.45：基类是我们的，两边一起改）。
                          #   这条注释原来写的是"它们在 哈希内部件 里没被改名，照旧可用" ——
                          #   那句话随本批**废止**。
                          '_Alnode'             = '_结点分配器'
                          '_Alnode_traits'      = '_结点分配器特征'
                          '_Key_compare'        = '_键比较器'
                          # §16.60 其余 4 个（traits 里声明、`_哈希` 读）：本头同批翻。
                          'key_compare'         = '键比较器'
                          'value_compare'       = '值比较'
                          '_Mutable_value_type' = '_可变值类型'
                          '_In_place_key_extractor' = '_就地键提取器'
                          # §16.58 跨条目协调改名（与 哈希内部件 同批）：
                          #   `_Umap_traits` 里的这三个名字被 `_哈希` 读
                          #   （`typename _Traits::allocator_type/key_type/node_type`），
                          #   本头还有 `typename _Mybase::allocator_type/node_type`
                          #   -> 必须同批翻；公开层靠 deriveTypes【方向翻转】补回英文。
                          'allocator_type' = '分配器类型'
                          'key_type'       = '键类型'
                          'node_type'      = '结点类型'
                          # §16.59 协调改名第二批（本头独有的 7 个；`mapped_type` 只有映射有）：
                          #   它们**只在无序容器里声明**（traits 里没有，`_哈希` 也不读）
                          #   -> 不必牵动 哈希内部件，只在本条目 + 公开层补英文。
                          #   实测：每个都 0 处 `X::名字` 限定读取（§16.58 第一步）。
                          'hasher'              = '散列器'
                          'key_equal'           = '键相等器'
                          'mapped_type'         = '映射类型'
                          'insert_return_type'  = '插入返回类型'
                          'const_reference'     = '常量引用'
                          'local_iterator'      = '局部迭代器'
                          'const_local_iterator' = '常量局部迭代器'
                          }
    members = [ordered]@{
      '_Get_first' = '_取第一';
      '_Valty' = '_值参数类型';
      '_Alloc' = '_分配器';
      '_First' = '_首个';
      '_Ty' = '_类型';
      '_Guide_size_type_t' = '_推导尺寸类型';
      '_In_place_key_extract_map' = '_就地键提取映射';
      '_Last' = '_最后';
      '_Newnode' = '_新节点';
      '_Range_key_type' = '_范围键类型';
      '_Range_mapped_type' = '_范围映射类型';
      '_Range_to_alloc_type' = '_范围到分配器类型';
      '_Result' = '_结果';
      '_Traits' = '_特征';
      # §17.27.60 台账收尾（阶段(3) 第一批）：这些名字的定义方是 通用内部件（我们的 xutility 拷贝，
      #   §17.27.52 已给定义方解毒）；本头能看到它 -> 调用点跟改，指向我们那份。
      '_Make_iter' = '_造迭代器'
      '_Ubegin' = '_解包首'
      '_Uend' = '_解包尾'
      '_Pass_fn' = '_传递函数'
      'at' = '取值'   # ⚠ insert 不改名：基类里没翻 insert（§15.10 形态③）
      # §16.82 本头自己定义的两个公开 API（抄来那层翻 + 派生层补英文）
      'hash_function' = '散列函数'
      'key_eq'        = '取键相等器'
      # §16.83 与 哈希内部件 同批：正文调 `_Mybase::rehash(...)`
      'rehash'        = '重哈希'
      # §17.8 `_Kfn`（traits 定义侧）——与 哈希内部件 同批，见那边的说明。
      '_Kfn'          = '_取键'
      'insert_or_assign' = '插入或赋值'; 'try_emplace' = '尝试就地构造'
      'emplace' = '就地构造'
      # §16.52 正文 `this->emplace_hint(...)`（insert(const_iterator,…) 里）—— 同步
      'emplace_hint' = '按提示就地构造'
      # §16.52 同步改名（本头正文调 `_Mybase::X` / `this->X`，而 xhash 已把它们翻了）
      '_Try_emplace'             = '_尝试就地构造'
      '_Try_emplace_hint'        = '_按提示尝试就地构造'
      '_Find_last'               = '_查找最后'
      '_Find_hint'               = '_按提示查找'
      '_Check_max_size'          = '_检查最大尺寸'
      '_Check_rehash_required_1' = '_检查需重哈希1'
      '_Rehash_for_1'            = '_为1重哈希'
      '_Getal'                   = '_取分配器'
      '_Insert_new_node_before'  = '_在之前插入新节点'
      '_Insert_range_unchecked'  = '_插入范围非检查'
      '_Hash_equal'              = '_哈希相等'
      '_Unchecked_begin'         = '_非检查开始'
      '_Unchecked_end'           = '_非检查结束'
      # §16.52 公开 API 名（`_Mybase::clear()` 在正文里；size/begin/end/empty/
      #   get_allocator 是【继承自 _哈希】的名字，xhash 翻了 -> 派生层必须补回英文，
      #   否则用户写 标准::无序映射<T>::size() 会消失 = 回归，见 §16.41.2）
      'clear'                    = '清空'
    ;
      '_Insert_or_assign' = '_插入或赋值';

      '_Release' = '_释放';

      # '桶数' = '桶数';  # §17.19.49 本条目拷贝层 0 命中（登记≠落地守卫点名），撤下

      '_Traitsobj' = '_特征对象';

      # '负载因子' = '负载因子';  # §17.19.49 本条目拷贝层 0 命中（登记≠落地守卫点名），撤下
;
      # 'insert' = '插入';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下
}
    data    = [ordered]@{}
    derive  = @( @('at','取值'), @('insert_or_assign','插入或赋值'),
                 @('try_emplace','尝试就地构造'), @('emplace','就地构造'),
                 @('emplace_hint','按提示就地构造'),
                 # §16.52 英文补回（§16.41.2：漏一个就是回归 —— 这 6 个名字
                 #   都是【继承自 _哈希】的公开 API，xhash 已把它们翻成汉语）
                 # §16.82 本头【自己定义】的两个公开 API（hash_function/key_eq）
                 @('hash_function','散列函数'), @('key_eq','取键相等器'),
                 @('rehash','重哈希'),
                 @('size','尺寸'), @('clear','清空'),
                 @('begin','开始'), @('end','结束'), @('empty','为空'),
                 @('get_allocator','取分配器') )
    deriveTypes = @( @('迭代器','iterator'), @('常量迭代器','const_iterator'),
                     @('值类型','value_type'), @('尺寸类型','size_type'),
                     # §16.58 跨条目协调改名（与 哈希内部件 同批）：这三个方向**翻转**
                     #   （抄来那层已汉语 -> 公开层补【英文原名】）。
                     #   `allocator_type`/`node_type` 是借来的 std 契约名
                     #   （uses_allocator 读 X::allocator_type），必须补回。
                     @('key_type','键类型'), @('allocator_type','分配器类型'),
                     @('node_type','结点类型'),
                     # §16.59 第二批：`mapped_type` 也【方向翻转】补回英文；
                     #   其余 6 个同理（本头独有，不牵动 哈希内部件）。
                     @('mapped_type','映射类型'),
                     @('hasher','散列器'), @('key_equal','键相等器'),
                     @('insert_return_type','插入返回类型'),
                     @('const_reference','常量引用'),
                     @('local_iterator','局部迭代器'),
                     @('const_local_iterator','常量局部迭代器') )
    deriveExtra = @'
    模板 <类型名... 参数> 声明类型(自动) 插入(参数&&... 值) { 返回 基类::insert(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 擦除(参数&&... 值) { 返回 基类::erase(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 查找(参数&&... 值) { 返回 基类::find(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 计数(参数&&... 值) 常量 { 返回 基类::count(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 尺寸(参数&&... 值) 常量 { 返回 基类::尺寸(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 为空(参数&&... 值) 常量 { 返回 基类::为空(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 清空(参数&&... 值) { 返回 基类::清空(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 包含(参数&&... 值) 常量 { 返回 基类::contains(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 开始(参数&&... 值) { 返回 基类::开始(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 结束(参数&&... 值) { 返回 基类::结束(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 桶数(参数&&... 值) 常量 { 返回 基类::桶数(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 负载因子(参数&&... 值) 常量 { 返回 基类::负载因子(static_cast<参数&&>(值)...); }
'@
    stdHash = $false
    tparam  = @{ decl = '模板 <类型名 键, 类型名 映射值, 类型名 散列 = std::hash<键>, 类型名 相等 = std::equal_to<键>, 类型名 分配器 = std::allocator<std::pair<常量 键, 映射值>>>'; args = '<键, 映射值, 散列, 相等, 分配器>' }
    extra = @'

名域 标准 {

// 无序多重映射（std::unordered_multimap）
模板 <类型名 键, 类型名 映射值, 类型名 散列 = std::hash<键>, 类型名 相等 = std::equal_to<键>,
      类型名 分配器 = std::allocator<std::pair<常量 键, 映射值>>>
类型 无序多重映射 : 公开 细节::无序多重映射实现<键, 映射值, 散列, 相等, 分配器> {
公开:
    使用 基类 = 细节::无序多重映射实现<键, 映射值, 散列, 相等, 分配器>;
    使用 基类::基类;

    // §16.52 嵌套类型名也补中文（主类有 deriveTypes，这个类得手写）
    使用 迭代器 = 基类::iterator;
    使用 常量迭代器 = 基类::const_iterator;
    使用 值类型 = 基类::value_type;
    使用 尺寸类型 = 基类::size_type;
    // §16.58 这三个名字在【抄来那层】已经是汉语了 -> 这里改成补【英文原名】
    //   （方向翻转，与主类 deriveTypes 一致）；中文名从基类继承，不再手写。
    使用 key_type = 基类::键类型;
    使用 node_type = 基类::结点类型;
    使用 allocator_type = 基类::分配器类型;
    // §16.59 第二批的英文回填（这个类得手写）。
    //   ⚠ `映射类型` 不在这里写了：抄来那层已经叫这个名字，直接继承；
    //     这里只负责把【英文原名】mapped_type 补回来。
    使用 mapped_type = 基类::映射类型;
    使用 hasher = 基类::散列器;
    使用 key_equal = 基类::键相等器;
    使用 const_reference = 基类::常量引用;
    使用 local_iterator = 基类::局部迭代器;
    使用 const_local_iterator = 基类::常量局部迭代器;

    // §16.52 英文原名回填：这 8 个名字（emplace / emplace_hint + 6 个继承自 _哈希 的公开 API）
    //   在【抄来那层】已经是汉语 —— 不回填，用户原本能写的 甲.size() 就没了 = 回归。
    模板 <类型名... 参数> 声明类型(自动) emplace(参数&&... 值) { 返回 基类::就地构造(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) emplace_hint(参数&&... 值) { 返回 基类::按提示就地构造(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) size(参数&&... 值) { 返回 基类::尺寸(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) size(参数&&... 值) 常量 { 返回 基类::尺寸(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) clear(参数&&... 值) { 返回 基类::清空(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) begin(参数&&... 值) { 返回 基类::开始(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) begin(参数&&... 值) 常量 { 返回 基类::开始(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) end(参数&&... 值) { 返回 基类::结束(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) end(参数&&... 值) 常量 { 返回 基类::结束(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) empty(参数&&... 值) 常量 { 返回 基类::为空(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) get_allocator(参数&&... 值) 常量 { 返回 基类::取分配器(static_cast<参数&&>(值)...); }

    // 中文转发：insert/erase/find/count/contains/桶数/负载因子 在
    //   基类里【仍是英文】（xhash 没翻那些名字）-> 中文名得手写；
    //   尺寸/为空/清空/开始/结束 基类里已是汉语，这里转发只是保持两个类名字一致。
    模板 <类型名... 参数> 声明类型(自动) 插入(参数&&... 值) { 返回 基类::insert(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 擦除(参数&&... 值) { 返回 基类::erase(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 查找(参数&&... 值) { 返回 基类::find(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 计数(参数&&... 值) 常量 { 返回 基类::count(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 尺寸(参数&&... 值) 常量 { 返回 基类::尺寸(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 为空(参数&&... 值) 常量 { 返回 基类::为空(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 清空(参数&&... 值) { 返回 基类::清空(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 包含(参数&&... 值) 常量 { 返回 基类::contains(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 开始(参数&&... 值) { 返回 基类::开始(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 结束(参数&&... 值) { 返回 基类::结束(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 桶数(参数&&... 值) 常量 { 返回 基类::桶数(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 负载因子(参数&&... 值) 常量 { 返回 基类::负载因子(static_cast<参数&&>(值)...); }
};

}  // 名域 标准
'@
    tests = @(
      @('只引中文头','#包含 <无序映射>`n整数 主函数(){ 标准::无序映射<整数, 整数> 甲; 甲.插入(标准::无序映射<整数, 整数>::值类型{1, 2}); 甲[3] = 4; 返回 甲.取值(1) + (整数)甲.尺寸() - 4; }'),
      # §16.82 欠账销账（同 <无序集合>）：中文名与英文原名各真调用一次。
      @('散列函数 / 取键相等器 都真能调','#包含 <无序映射>`n整数 主函数(){ 标准::无序映射<整数, 整数> 甲; (空型)甲.hash_function(); (空型)甲.散列函数(); (空型)甲.key_eq(); (空型)甲.取键相等器(); 返回 0; }'),
      # §16.83 欠账销账（同 <无序集合>）：英文原名与中文名各真调用一次。
      @('重哈希 / rehash 都真能调','#包含 <无序映射>`n整数 主函数(){ 标准::无序映射<整数, 整数> 甲; 甲.rehash(16); 甲.重哈希(16); 返回 0; }'),
      @('与微软原头并存','#包含 <无序映射>`n#包含 <unordered_map>`n整数 主函数(){ 标准::无序映射<整数, 整数> 甲; 甲[1] = 2; std::unordered_map<int, int> 乙; 乙[1] = 2; 返回 (整数)甲.尺寸() - (整数)乙.size(); }'),
      @('中英并用 + 中文迭代器','#包含 <无序映射>`n整数 主函数(){ 标准::无序映射<整数, 整数> 甲; 甲.insert({1, 10}); 标准::无序映射<整数, 整数>::迭代器 头 = 甲.开始(); 整数 和 = 0; for (; 头 != 甲.结束(); ++头) { 和 += 头->second; } 返回 和 - 10; }'),
      @('无序多重映射 + 就地构造','#包含 <无序映射>`n整数 主函数(){ 标准::无序多重映射<整数, 整数> 甲; 甲.插入(标准::无序映射<整数, 整数>::值类型{1, 1}); 甲.插入(标准::无序映射<整数, 整数>::值类型{1, 2}); 标准::无序映射<整数, 整数> 乙; 乙.try_emplace(5, 6); 返回 (整数)甲.计数(1) + (整数)乙.尺寸() - 3; }'),
      # §16.52 真守卫（不能只写空测）：把【继承自 _哈希】的那 6 个公开 API 的英文名
      #   逐个实例化 —— 少补一个，用户原本能写的 甲.size() 就没了 = 回归（§16.41.2）。
      #   ⚠ `甲.at(1) = 6;` 是【引用返回】守卫：派生层转发器若写成 `自动`，
      #     这里必然编不过（实测：这正是发现 §16.52 那个问题的地方）。
      @('英文原名仍在（回归守卫）','#包含 <无序映射>`n整数 主函数(){ 标准::无序映射<整数, 整数> 甲;(空型)sizeof(标准::无序映射<整数, 整数>::迭代器);`n  甲.emplace(1, 2); 甲.insert_or_assign(1, 5); 甲.at(1) = 6;`n  (空型)甲.emplace_hint(甲.begin(), 标准::无序映射<整数, 整数>::值类型{7, 8});`n  (空型)甲.get_allocator(); 甲.begin(); 甲.end(); 整数 空 = 甲.empty() ? 1 : 0; 整数 尺 = (整数)甲.size(); 甲.clear();`n  返回 尺 - 2 + 空 - (整数)甲.size(); }'),
      # §16.52 第二个类的真守卫：它【不在 deriveTypes/derive 的作用范围里】，
      #   嵌套中文类型名与中英双语转发都得手写 —— 只写主类的测试会漏掉它。
      #   ⚠ 这条也是「空测掩盖」的销账：切到我们自己的 哈希内部件 之后，
      #     这个类里的 `基类::size` 之类会变成不存在的名字（模板惰性实例化，
      #     不实例化就【不报错】）—— 所以下面每个名字都必须被真正调用到。
      @('无序多重映射：中英双语 + 嵌套类型','#包含 <无序映射>`n整数 主函数(){ 标准::无序多重映射<整数, 整数> 甲;`n  (空型)sizeof(标准::无序多重映射<整数, 整数>::常量迭代器);`n  标准::无序多重映射<整数, 整数>::迭代器 头 = 甲.begin(); 头 = 甲.end();`n  甲.emplace(1, 2); 甲.插入(标准::无序多重映射<整数, 整数>::值类型{1, 3}); 甲.emplace_hint(头, 标准::无序多重映射<整数, 整数>::值类型{5, 6});`n  标准::无序多重映射<整数, 整数>::键类型 钥 = 1; 标准::无序多重映射<整数, 整数>::映射类型 值 = 2;`n  头 = 甲.开始(); 头 = 甲.结束(); 整数 有 = 甲.包含(钥) ? 1 : (甲.查找(钥) == 甲.结束() ? 0 : 1);`n  整数 尺 = (整数)甲.尺寸() - (整数)甲.size(); 整数 空 = 甲.为空() ? 1 : (甲.empty() ? 1 : 0);`n  整数 桶 = 甲.桶数() > 0 ? 0 : 1; 整数 因子 = 甲.负载因子() > 0.0f ? 0 : 1;`n  (空型)甲.get_allocator(); (空型)甲.计数(钥); (空型)甲.擦除(钥); 甲.清空(); 甲.clear();`n  (空型)值;`n  返回 有 + 尺 + 空 + 桶 + 因子 - 1; }'),
      # §16.55 回归守卫（同 <无序集合>）：销掉 `_哈希` 内部的三个名字，
      #   公开层的 local_iterator / const_local_iterator / const_reference 必须仍在。
      @('桶迭代器名仍在（3 名销账的回归守卫）','#包含 <无序映射>`n整数 主函数(){`n  (空型)sizeof(标准::无序映射<整数, 整数>::local_iterator);`n  (空型)sizeof(标准::无序映射<整数, 整数>::const_local_iterator);`n  (空型)sizeof(标准::无序映射<整数, 整数>::const_reference);`n  返回 0; }'),
      # §16.55.2 / §16.57 泛型契约守卫（同 <无序集合>）：借用来的 std 契约名
      #   （allocator_type 等）在【公开层】必须仍是英文。
      @('泛型契约：uses_allocator 认得出（英文名必须在公开层）','#包含 <无序映射>`n#包含 <memory>`n静态断言(std::uses_allocator<标准::无序映射<整数, 整数>, std::allocator<标准::无序映射<整数, 整数>::值类型>>::value);`n静态断言(std::uses_allocator<标准::无序多重映射<整数, 整数>, std::allocator<标准::无序多重映射<整数, 整数>::值类型>>::value);`n整数 主函数(){ 返回 0; }'),
      # §16.58 回归守卫（同 <无序集合>）：三个名字中英都在，且指同一个类型。
      @('三种名字中英一致（§16.58 回归守卫）','#包含 <无序映射>`n#包含 <type_traits>`n静态断言(std::is_same_v<标准::无序映射<整数, 整数>::键类型, 标准::无序映射<整数, 整数>::key_type>);`n静态断言(std::is_same_v<标准::无序映射<整数, 整数>::结点类型, 标准::无序映射<整数, 整数>::node_type>);`n静态断言(std::is_same_v<标准::无序映射<整数, 整数>::分配器类型, 标准::无序映射<整数, 整数>::allocator_type>);`n静态断言(std::is_same_v<标准::无序多重映射<整数, 整数>::键类型, 标准::无序多重映射<整数, 整数>::key_type>);`n静态断言(std::is_same_v<标准::无序多重映射<整数, 整数>::结点类型, 标准::无序多重映射<整数, 整数>::node_type>);`n静态断言(std::is_same_v<标准::无序多重映射<整数, 整数>::分配器类型, 标准::无序多重映射<整数, 整数>::allocator_type>);`n整数 主函数(){ 返回 0; }'),
      # §16.59 第二批（7 个名字，含只有映射才有的 mapped_type）：中英都在且指同一类型。
      @('第二批名字中英一致（§16.59 回归守卫）','#包含 <无序映射>`n#包含 <type_traits>`n静态断言(std::is_same_v<标准::无序映射<整数, 整数>::散列器, 标准::无序映射<整数, 整数>::hasher>);`n静态断言(std::is_same_v<标准::无序映射<整数, 整数>::键相等器, 标准::无序映射<整数, 整数>::key_equal>);`n静态断言(std::is_same_v<标准::无序映射<整数, 整数>::映射类型, 标准::无序映射<整数, 整数>::mapped_type>);`n静态断言(std::is_same_v<标准::无序映射<整数, 整数>::插入返回类型, 标准::无序映射<整数, 整数>::insert_return_type>);`n静态断言(std::is_same_v<标准::无序映射<整数, 整数>::常量引用, 标准::无序映射<整数, 整数>::const_reference>);`n静态断言(std::is_same_v<标准::无序映射<整数, 整数>::局部迭代器, 标准::无序映射<整数, 整数>::local_iterator>);`n静态断言(std::is_same_v<标准::无序映射<整数, 整数>::常量局部迭代器, 标准::无序映射<整数, 整数>::const_local_iterator>);`n静态断言(std::is_same_v<标准::无序多重映射<整数, 整数>::散列器, 标准::无序多重映射<整数, 整数>::hasher>);`n静态断言(std::is_same_v<标准::无序多重映射<整数, 整数>::键相等器, 标准::无序多重映射<整数, 整数>::key_equal>);`n静态断言(std::is_same_v<标准::无序多重映射<整数, 整数>::映射类型, 标准::无序多重映射<整数, 整数>::mapped_type>);`n静态断言(std::is_same_v<标准::无序多重映射<整数, 整数>::常量引用, 标准::无序多重映射<整数, 整数>::const_reference>);`n静态断言(std::is_same_v<标准::无序多重映射<整数, 整数>::局部迭代器, 标准::无序多重映射<整数, 整数>::local_iterator>);`n静态断言(std::is_same_v<标准::无序多重映射<整数, 整数>::常量局部迭代器, 标准::无序多重映射<整数, 整数>::const_local_iterator>);`n整数 主函数(){ 返回 0; }')
    )
  }
  'span' = @{
    zh      = '跨度'
    realInclude = @('span')   # §16.29「乙」
    types   = [ordered]@{ 'span' = '跨度实现'
      '_Verify_range' = '_校验范围'
      '_Seek_to' = '_定位到'
      '_Adl_verify_range' = '_ADL校验范围'
      '_Unwrapped' = '_解包'
                          # §16.27：自有内部件也要翻
                          '_Span_extent_type' = '_跨度范围类型'
                          '_Span_iterator'    = '_跨度迭代器'
                          # ------------------------------------------------------------------
                          # §16.35.5 第一次嵌套名翻转（按 §9.1 的方向：抄来那层全汉语，
                          # 派生层把英文补回来）。**只翻"没有第二个主人"的那些** ——
                          # 逐名分析见方案 §16.35.5，这里只列结论：
                          #   可翻：iterator / size_type / const_pointer / const_reference /
                          #         const_reverse_iterator / _Prevent_inheriting_unwrap / _ReturnType
                          #   不可翻（三类陷阱）：
                          #     · std 模板名出现在 _STD 位：reverse_iterator、const_iterator
                          #       （`_STD reverse_iterator<iterator>`，改了名就找不到 std 模板）
                          #     · std 模板【特化体内】的契约成员名：
                          #       pointer_traits<_Span_iterator<_Ty>> 里的 pointer / element_type /
                          #       difference_type（`pointer_traits<X>::pointer` 是 std 契约）
                          #     · 迭代器的 iterator_traits 契约名：
                          #       value_type（`_Span_iterator` 里也有一个 value_type）
                          # ------------------------------------------------------------------
                          'iterator'              = '迭代器'
                          'size_type'             = '尺寸类型'
                          'const_pointer'         = '常量指针'
                          'const_reference'       = '常量引用'
                          'const_reverse_iterator' = '常量反向迭代器'
                          '_Prevent_inheriting_unwrap' = '_阻止继承解包'
                          '_ReturnType'           = '_返回类型' }
    # ⚠ dynamic_extent 是【变量】不是类型/成员 —— 登记进 data 表，
    #   这样既改名、又会被步 4c 去限定（4c 遍历 types/members/data）。
    #   实测漏了它：error: namespace 'std' 中没有名为 'dynamic_extent' 的成员；
    #   你是不是想写 '细节::dynamic_extent'？ / 没有变量模板匹配部分特化
    members = [ordered]@{
      '_Unchecked_begin' = '_非检查开始';
      '_Unchecked_end' = '_非检查结束';
      '_First' = '_首个';
      '_Last' = '_最后';
      '_Myptr' = '_我的指针';
      '_Mysize' = '_我的尺寸';
      '_Sentinel' = '_哨兵';
      '_Ty' = '_类型';
      'size' = '尺寸'; 'size_bytes' = '字节尺寸'; 'empty' = '为空'
      'data' = '数据'; 'front' = '前'; 'back' = '后'
      'begin' = '开始'; 'end' = '结束'
      # 'rbegin' = '反向开始';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下 'rend' = '反向结束'
      'first' = '首段'; 'last' = '末段'; 'subspan' = '子跨度'
      # as_bytes / as_writable_bytes 是命名空间作用域的自由函数，
      # 抄来后落在 细节:: —— 用 using 声明引进 标准（§3.19.1）
      'as_bytes' = '转字节'; 'as_writable_bytes' = '转可写字节'
      # ⚠ swap 照旧不改名（§3.12）
    ;
      # 'crbegin' = '常量反向开始';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下

      # 'crend' = '常量反向结束';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下

      '_Verify_offset' = '_校验偏移';
}
    zhIncludes = @{ 'xutility' = '通用内部件' }
    data    = [ordered]@{ 'dynamic_extent' = '动态范围' }
    derive  = @( @('size','尺寸'), @('size_bytes','字节尺寸'), @('empty','为空'),
                 @('data','数据'), @('front','前'), @('back','后'),
                 @('begin','开始'), @('end','结束'),
                 @('rbegin','反向开始'), @('rend','反向结束'),
                 @('first','首段'), @('last','末段'), @('subspan','子跨度') )
    # ⚠ 方向【故意混用】，因为名字分四类（§16.35.5）：
    #   · 已翻的（抄来那层是汉语）-> 新方向 @('英文名','汉语名')：派生层把英文原名补回来
    #   · 边界（抄来那层必须留英文）-> 旧方向 @('汉语名','英文名')：中文名只能在派生层补
    #   两种都合法 —— 因为生成的都只是 `使用 甲 = 基类::乙;` 一行，区别只在甲、乙谁是汉语。
    deriveTypes = @( @('iterator','迭代器'), @('size_type','尺寸类型'),
                     @('const_pointer','常量指针'), @('const_reference','常量引用'),
                     # ⚠ const_reverse_iterator / const_iterator 【不能】登记：
                     #   原文里它们处在 `#if _HAS_CXX23` 里（span 第 292~295 行），
                     #   而我们的编译配置是 -std=c++20 -> 基类里根本没有这两个名字，
                     #   生成 `使用 ... = 基类::常量反向迭代器;` 会立刻报"没有名为…的类型"。
                     #   **判据：派生层补的名字必须确认它在【我们实际编译的配置下】存在。**
                     # ↓ 边界名：中文名在这里补（上面三类陷阱，抄来那层不能改）
                     @('元素类型','element_type'), @('值类型','value_type'),
                     @('指针','pointer'), @('引用','reference'),
                     @('差异类型','difference_type'),
                     @('反向迭代器','reverse_iterator') )
    stdHash = $false
    tparam  = @{ decl = '模板 <类型名 元素, size_t 范围 = 细节::动态范围>'; args = '<元素, 范围>' }
    extra = @'

名域 标准 {

// 自由函数：抄来后落在 细节::，用 using 声明引进 标准::（§3.19.1，
// 比重写转发保真：重载全带上、返回引用也不丢）
使用 细节::转字节;
使用 细节::转可写字节;

// 动态范围常量（std::dynamic_extent）—— 变量，成员转发管不到，手写
内联 常量表达式 size_t 动态范围常量 = 细节::动态范围;

}  // 名域 标准
'@
    tests = @(
      @('只引中文头','#包含 <跨度>`n整数 主函数(){ 整数 原[4] = {1, 2, 3, 4}; 标准::跨度<整数> 甲(原); 返回 (整数)甲.尺寸() + 甲.前() + 甲.后() - 9; }'),
      @('与微软原头并存','#包含 <跨度>`n#包含 <span>`n整数 主函数(){ 整数 原[3] = {1, 2, 3}; 标准::跨度<整数> 甲(原); std::span<int> 乙(原); 返回 (整数)甲.尺寸() - (整数)乙.size(); }'),
      @('中英并用 + 子跨度 / 首段 / 末段','#包含 <跨度>`n整数 主函数(){ 整数 原[5] = {1, 2, 3, 4, 5}; 标准::跨度<整数> 甲(原); 自动 子 = 甲.subspan(1, 3); 自动 首 = 甲.首段(2); 自动 尾 = 甲.末段(1); 返回 (整数)子.尺寸() + 首.前() + 尾.后() - 9; }'),
      @('字节视图 + 动态范围常量','#包含 <跨度>`n整数 主函数(){ 整数 原[2] = {1, 2}; 标准::跨度<整数> 甲(原); 自动 字节 = 标准::转字节(甲); 布尔 全 = 字节.尺寸() == 甲.字节尺寸(); 标准::跨度<整数, 标准::动态范围常量> 乙(甲); 返回 (全 ? 0 : 1) + (整数)乙.尺寸() - 2; }'),
      # ⚠ §16.35.5 的守卫：这是【第一次嵌套名翻转】，必须证明两件事同时成立 ——
      #   ① 汉语嵌套名可用（抄来那层已翻，派生层继承下来）
      #   ② 英文原名仍然可用（派生层 / 继承两路都在）
      #   少任何一条，"翻转"就等于把一种名字弄丢了。
      @('嵌套名翻转的守卫：汉语嵌套名与英文原名【同时】可用','#包含 <跨度>`n整数 主函数(){`n  标准::跨度<整数> 甲;`n  (空型)sizeof(标准::跨度<整数>::尺寸类型);`n  (空型)sizeof(标准::跨度<整数>::指针);`n  (空型)sizeof(标准::跨度<整数>::常量指针);`n  (空型)sizeof(标准::跨度<整数>::引用);`n  (空型)sizeof(标准::跨度<整数>::常量引用);`n  (空型)sizeof(标准::跨度<整数>::差异类型);`n  (空型)sizeof(标准::跨度<整数>::元素类型);`n  (空型)sizeof(标准::跨度<整数>::值类型);`n  (空型)sizeof(标准::跨度<整数>::迭代器);`n  (空型)sizeof(标准::跨度<整数>::反向迭代器);`n  (空型)sizeof(标准::跨度<整数>::size_type);`n  (空型)sizeof(标准::跨度<整数>::iterator);`n  (空型)sizeof(标准::跨度<整数>::pointer);`n  (空型)sizeof(标准::跨度<整数>::reference);`n  (空型)sizeof(标准::跨度<整数>::reverse_iterator);`n  (空型)sizeof(标准::跨度<整数>::element_type);`n  (空型)sizeof(标准::跨度<整数>::value_type);`n  (空型)甲;`n  返回 0; }')
    )
  }
  'xcall_once.h' = @{
    zh      = '调用一次'
    # ⚠ 内部件（步骤 1 的第一个）：它定义 std::once_flag 与 std::call_once ——
    #   正是 §3.7.2 那条欠账的消除路径。
    #   译名必须与 <mutex> 条目一致（跨头译名检查会强制）：一次标志实现 / 一次调用。
    pub     = '一次标志'
    types   = [ordered]@{ 'once_flag' = '一次标志实现'
                          '_Init_once_completer' = '_一次初始化完成器'
                          # §16.34：原文注释是 "constructs _Ty, never destroys" ——
                          #   它构造了 _Ty 却故意不析构，所以取「永不析构」而不是音译。
                          '_Immortalizer_impl' = '_永不析构实现' }
    members = [ordered]@{
      '_Ty' = '_类型';
      '_Op' = '_操作'; 'call_once' = '一次调用' }
    data    = [ordered]@{}
    derive  = @()
    stdHash = $false
    tparam  = @{ decl = ''; args = '' }
    extra = @'

名域 标准 {

// 自由函数：抄来后落在 细节::，用 using 声明引进 标准（§3.19.1）
使用 细节::一次调用;

}  // 名域 标准
'@
    tests = @(
      @('只引中文头','#包含 <调用一次>`n整数 主函数(){ 标准::一次标志 标; 标准::一次调用(标, []{}); 返回 0; }')
    )
  }
  'xsmf_control.h' = @{
    zh      = '特殊成员控制'
    pub     = '_特殊成员控制'
    types   = [ordered]@{ '_SMF_control' = '_特殊成员控制'
                          '_Non_trivial_copy' = '_非平凡复制'
                          '_Deleted_copy' = '_删除复制'
                          '_SMF_control_copy' = '_特殊成员控制复制'
                          '_Non_trivial_move' = '_非平凡移动'
                          '_Deleted_move' = '_删除移动'
                          '_SMF_control_move' = '_特殊成员控制移动'
                          '_Non_trivial_copy_assign' = '_非平凡复制赋值'
                          # §16.34：同一族的 assign 变体原来漏登记了（审计台账照出来的）
                          '_Deleted_copy_assign' = '_删除复制赋值'
                          '_Deleted_move_assign' = '_删除移动赋值'
                          '_Non_trivial_move_assign' = '_非平凡移动赋值'
                          '_SMF_control_copy_assign' = '_特殊成员控制复制赋值'
                          '_SMF_control_move_assign' = '_特殊成员控制移动赋值' }
    members = [ordered]@{
      # §16.66 把本条目自己清零（第三把尺"完全无残留的头"从 3/31 起往上推）：
      #   这两个是本头**自己定义**的内部助手（量过"谁定义它"：只有 xsmf_control.h 有），
      #   不是公开 API -> 不需要派生层补英文。
      '_Assign_from' = '_由之赋值'
      '_Construct_from' = '_由之构造'
    }
    data    = [ordered]@{}
    derive  = @()
    stdHash = $false
    # ⚠ 参数包【不能叫 类型】（那是 class 的关键词）—— 实测报 缺少 identifier /
    #   匿名 class 的声明必须是定义。这条本来是关键词检查的缺口：它没查 tparam。
    tparam  = @{ decl = '模板 <类型名 基类参数, 类型名... 类型集>'; args = '<基类参数, 类型集...>' }
    tests = @(
      @('只引中文头','#包含 <特殊成员控制>`n整数 主函数(){ 返回 0; }'),
      @('本体类型确实可用（模板形状对）','#包含 <特殊成员控制>`n结构 基类 { 整数 值; };`n整数 主函数(){ 标准::_特殊成员控制<基类, 整数> 甲; (空型)甲; 返回 0; }')
    )
  }
  'xmemory' = @{
    zh      = '内存内部件'
    realInclude = @('memory', 'xutility')
    noPub   = $true
    # -----------------------------------------------------------------------
    #  批 A（7 个，§16.19）：上层容器欠账里点名要的那几个。
    #  批 B（61 个，§16.23）：本头【全部】顶层类型名，一次登记完。
    #
    #  ⚠ 为什么要一次登记完，而不是分几批：
    #     §16.22 实测证明"批 A 单独不足以支撑上层切换"—— 上层拷贝的正文里
    #     还写着 _Simple_types / _Compressed_pair / _Container_base …… 只要本头
    #     有一个名字没翻，上层就找不到它（本头 noPub，派生层不补英文），
    #     或者解析到真 std 的那一份 -> 两边不同步 -> 编不过。
    #     所以"能被上层引用"的前提是【本头的名字集合完整】，不是"翻了几个"。
    #
    #  译名依据（§2.2 的查表顺序）：分配器 / 迭代器 / 指针 / 尺寸类型 / 值类型
    #    来自 ChineseDiagnostics.def；消毒器 同上；其余按最贴近的中文新定。
    #  全部带前导 `_` 或非关键词（分配器 / 分配结果），故不会撞语言关键字。
    # -----------------------------------------------------------------------
    types   = [ordered]@{ 'allocator_traits'    = '分配器特征'
                          # §16.39 第 ① 类（本头类内别名；本头目前【无人消费】，
                          #   所以不会被借来的 std 模板读到 —— 按 §16.37.1 那条判据逐个核过）
                          '_Alloc_traits'  = '_分配器特征别名'
                          '_Dest'          = '_目标'
                          '_Elem'          = '_元素'
                          '_From_primary'  = '_源自主分配器'
                          '_Modifiable'    = '_可修改'
                          '_Pair_t'        = '_对类型'
                          '_Pair_first_t'  = '_对首类型'
                          '_Pair_second_t' = '_对次类型'
                          '_Pair_ref_t'    = '_对引用类型'
                          '_Pair_remaker'  = '_对重建器'
                          '_Ptr_traits'    = '_指针特征'
                          '_Ptrty'         = '_指针类型'
                          '_Ptrval'        = '_指针值类型'
                          '_ReturnType'    = '_返回类型'
                          '_Traits'        = '_特征'
                          '_Valty'         = '_值参数类型'
                          '_Ty'            = '_类型'
                          '_Pocma_values'       = '_传播复制移动赋值取值'
                          '_Compressed_pair'    = '_压缩对'
                          '_Container_base0'    = '_容器基类0'
                          '_Iterator_base0'     = '_迭代器基类0'
                          '_Container_base'     = '_容器基类'
                          '_Iterator_base'      = '_迭代器基类'

                          '_Tidy_guard'         = '_清理守卫'
                          '_Tidy_deallocate_guard' = '_清理释放守卫'
                          '_Default_allocate_traits' = '_默认分配特征'
                          '_Rebind_pointer_t'   = '_重绑定指针类型'
                          '_Get_pointer_type'   = '_取指针类型'
                          '_Get_const_pointer_type' = '_取常量指针类型'
                          '_Get_void_pointer_type' = '_取空型指针类型'
                          '_Get_const_void_pointer_type' = '_取常量空型指针类型'
                          '_Get_difference_type' = '_取差异类型'
                          '_Get_size_type'      = '_取尺寸类型'
                          '_Get_propagate_on_container_copy' = '_取容器复制时传播'
                          '_Get_propagate_on_container_move' = '_取容器移动时传播'
                          '_Get_propagate_on_container_swap' = '_取容器交换时传播'
                          '_Get_is_always_equal' = '_取恒等'
                          '_Get_rebind_type'    = '_取重绑定类型'
                          'allocator'           = '分配器'
                          '_Is_default_allocator' = '_是默认分配器'
                          '_Has_no_allocator_construct' = '_无分配器构造'
                          '_Uses_default_construct' = '_用默认构造'
                          '_Has_no_alloc_destroy' = '_无分配器析构'
                          '_Uses_default_destroy' = '_用默认析构'
                          '_Has_allocate_hint'  = '_有分配提示'
                          '_Has_max_size'       = '_有最大尺寸'
                          '_Has_select_on_container_copy_construction' = '_有容器复制构造时选择'
                          'allocation_result'   = '分配结果'
                          '_Normal_allocator_traits' = '_常规分配器特征'
                          '_Default_allocator_traits' = '_默认分配器特征'
                          '_Rebind_alloc_t'     = '_重绑定分配器类型'
                          '_Maybe_rebind_alloc_t' = '_可能重绑定分配器类型'
                          '_Simple_types'       = '_简单类型集'
                          '_Asan_aligned_pointers' = '_地址消毒对齐指针'
                          '_Guide_size_type_t'  = '_推导尺寸类型'
                          '_Alloc_ptr_t'        = '_分配器指针类型'
                          '_Alloc_size_t'       = '_分配器尺寸类型'
                          '_Alloc_construct_ptr' = '_分配器构造指针'
                          '_Fake_allocator'     = '_假分配器'
                          '_Container_base12'   = '_容器基类12'
                          '_Container_proxy'    = '_容器代理'
                          '_Iterator_base12'    = '_迭代器基类12'
                          '_Leave_proxy_unbound' = '_离开代理未绑定'
                          '_Fake_proxy_ptr_impl' = '_假代理指针实现'
                          '_Basic_container_proxy_ptr12' = '_基本容器代理指针12'
                          '_Container_proxy_ptr12' = '_容器代理指针12'
                          '_Container_proxy_ptr' = '_容器代理指针'
                          # ⚠ 宏名也是名字，必须一起汉化（§16.24）。
                          #   宏【不受名域约束】—— 拷贝里改名的 `#define _GET_PROXY_ALLOCATOR`
                          #   会把真头（list/xtree/vector）的同一个宏【劫持】掉，
                          #   它们展开后拿到的是汉语标识符，而汉语标识符在 std 里找不到：
                          #       list:827:27: error: 使用了未声明的标识符（名字）'_假分配器'
                          #   批 A 时没炸，是因为当时宏体里的名字恰好一个都没改（宏体逐字相同，
                          #   重定义无害）—— 这正是"改名越多越晚爆"的隐藏地雷。
                          '_GET_PROXY_ALLOCATOR' = '_取代理分配器'
                          '_Zero_then_variadic_args_t' = '_先零后变参实参'
                          '_One_then_variadic_args_t' = '_先一后变参实参'
                          '_Uninitialized_backout' = '_未初始化回退'
                          '_Uninitialized_backout_al' = '_未初始化回退分配器版'
                          '_Remove_const_ref_t' = '_去常量引用类型'
                          '_In_place_key_extract_set_impl' = '_就地键提取集合实现'
                          '_In_place_key_extract_set' = '_就地键提取集合'
                          '_In_place_key_extract_map_impl' = '_就地键提取映射实现'
                          '_In_place_key_extract_map' = '_就地键提取映射'
                          '_Wrap'               = '_包装'
                          '_Alloc_temporary2'   = '_分配器临时对象2'
                          '_Normally_bound_ref' = '_常规绑定引用'
                          '_Range_key_type'     = '_范围键类型'
                          '_Range_mapped_type'  = '_范围映射类型'
                          '_Range_to_alloc_type' = '_范围到分配器类型'
                          '_Ebco_base'          = '_空基类优化基类'
                          '_Is_transparent'     = '_是透明'
                          # ---------------------------------------------------------------------
                          # §16.61.6 【组合探针抓到的跨产品同名】`_Allocate_at_least_helper`
                          #
                          # 它在 xmemory 里**定义**（L2293），在 xstring / vector / deque 里只是**调用**。
                          # 本条目是它的定义方：搬进 `标准::细节` 之后，同名定义与本头
                          # `使用 名域 std;` 引进来的 std 那一份**同时可见**，
                          # 于是新产品 字符串内部件 的调用点报
                          #     字符串内部件:831:26: error: 对（函数名）'_Allocate_at_least_helper' 的调用有歧义
                          # （单头测试全过 —— 只有"全部头一起引"的组合探针才照得出来）。
                          #
                          # 判据（§16.50 的又一次实例）：**定义方改名，调用方保持英文名** ——
                          # 调用方（向量/双端队列/字符串内部件）都 include 真 xmemory，
                          # 英文名正好指到 std 那一份；本头自己的定义改成汉语，冲突消失。
                          # ⚠ 本头内部【没有】对它的调用（实测只有这一处定义），所以改名是单点的。
                          # ---------------------------------------------------------------------
                          '_Allocate_at_least_helper' = '_分配至少助手'
                          # §16.63 【调试配置探针抓到的同类问题】`_Delete_plain_internal`
                          #   同样是"本条目定义、别人调用"：`_ITERATOR_DEBUG_LEVEL != 0`
                          #   那一支里 `字符串内部件:1390` 会调用它，于是
                          #       字符串内部件:1390:9: error: 对（函数名）'_Delete_plain_internal' 的调用有歧义
                          #   —— 默认配置下那句在 `#if _ITERATOR_DEBUG_LEVEL != 0` 里，
                          #     所以**单头/组合探针（默认配置）一直照不出来**。
                          #   处理同 §16.61.6：定义方改名，调用方保持英文名（指到 std 那份）。
                          '_Delete_plain_internal'    = '_删除原生内部' }
    # -----------------------------------------------------------------------
    #  §16.67 成员名层（第三把尺指向的最大一块）。逐名量过"谁定义它"（§16.64 判据）：
    #    · 本头定义（下面这 48 条，含 §17.27.53 新增的 `_Construct_in_place`）-> 翻；
    #    · **借用的**（不在本表）-> 留英文：`address` / `addressof` / `apply` / `construct_at` /
    #      `destroy_at` / `make_tuple` / `forward_as_tuple` / `memcpy` / `memset` /
    #      `pointer_to` / `elements_of` / `from_range_t` -> 全是 std/C 的名字；
    #      ⚠ §17.27.55 就地更正：原来这条还列着 `_Adl_verify_range` / `_Seek_wrapped`
    #        （理由"定义在借来的 <xutility>"）—— 前提已随 <xutility> 抄成 `通用内部件` 而消失，
    #        那两个已进本表（还有 `_Get_unwrapped`），指向我们那份。
    #    · **allocator 契约名**（`allocate` / `allocate_at_least` / `deallocate` /
    #      `construct` / `destroy` / `max_size` / `select_on_container_copy_construction`）
    #      -> 第 ③ 类：`allocator_traits<我们的分配器>` 会读它们，翻了就认不出。
    #   ⚠ `_Destroy_range` / `_Extract` / `_Release` /
    #      `_Lock` / `_Orphan_all` / `_Swap_proxy_and_iterators` 在【别的头里也有】
    #      （xtree/xhash/xstring）—— 那是"同名两个主人"（§3.12）。
    #      按 §16.61.6 的规则：**本头是定义方之一就翻本头这份**，
    #      别的头保持英文、指向 std 那一份，两边改名后不再同名、互不干扰。
    #      ⚠ `_Construct_in_place` 已从这一串里**移出**：它的定义方 <xutility> 现在是
    #        我们的 `通用内部件`（§17.27.53 废止 §17.17.2），本头按"指向我们那份"处理。
    # -----------------------------------------------------------------------
    members = [ordered]@{
      '_Uty' = '_结果类型';
      '_Tidy' = '_清理';
      '_Size_type' = '_尺寸类型';
      '_Result' = '_结果';
      '_Mycont' = '_我的容器';
      '_Last' = '_最后';
      '_Idl_distance' = '_IDL距离';
      '_First' = '_首个';
      '_Alty' = '_分配器类型';
      '_Alloc' = '_分配器';
      # §17.19.4：通用守卫 _清理释放守卫 的【定义体】在本头（xmemory 拷贝）里，它调
      #   _Target->_Tidy_deallocate()。字符串实现（xstring 拷贝）把这个成员翻成了
      #   _清理释放() -> 两处口径不一致，只有真踩到那条路径才炸：
      #     实测 标准::字符串 回(转.begin(), 转.end());（从 std::string 迭代器构造）报
      #     「基础字符串实现<char> 中没有名为 _Tidy_deallocate 的成员」（内存内部件:104）。
      #   微软那边【只有 xstring 用这个守卫】（已核：xmemory 定义、xstring 两处使用），
      #   所以在这里补登记译名即可，不必把它划成边界。
      '_Tidy_deallocate' = '_清理释放'
      # §17.27.60 台账收尾（阶段(3) 第一批）：这些名字的定义方是 通用内部件（我们的 xutility 拷贝，
      #   §17.27.52 已给定义方解毒）；本头能看到它 -> 调用点跟改，指向我们那份。
      '_Pass_fn' = '_传递函数'
      '_Copy_memmove_n' = '_内存复制移动计数'
      '_Find_unchecked' = '_查找非检查'
      '_Fill_zero_memset' = '_填充零内存'
      '_Is_all_bits_zero' = '_是否全位为零'
      '_Copy_memmove' = '_内存复制移动'
      '_To_address' = '_取地址'
      # §17.27.55 链名接通（第二批）：这三个的定义方**都是我们自己的**了
      #   （`_Adl_verify_range` / `_Get_unwrapped` / `_Seek_wrapped` 定义在 <xutility>
      #    -> 现在是 `通用内部件`；本头第 8 行就引了它 -> 调用点改名指向我们那份）。
      #   ⚠ 更正下面那条"借用的 -> 留英文"的旧注（就地废止，理由写在原处）。
      '_Get_unwrapped' = '_取解包'
      '_Adl_verify_range' = '_ADL校验范围'
      '_Seek_wrapped' = '_定位包装'
      '_Uninitialized_move' = '_未初始化移动'
      '_Uninitialized_fill_n' = '_未初始化填充若干'
      '_Destroy_in_place' = '_就地析构'
      # §17.27.53 **废止 §17.17.2**（就地记下理由，不删旧条目）：
      #   旧判据是"`_Construct_in_place` 定义在**借来的** <xutility> 一侧，故留英文"。
      #   阶段(2) 把 <xutility> 抄成 `通用内部件` 之后，**定义方已经是我们自己**了
      #   —— 前提消失，判据随之失效。按 §17.27.52 的新判据（定义方的英文名是毒），
      #   本头那 5 处调用点（xmemory L1221/1230/1478/1484/1634，全在
      #   `#if _ITERATOR_DEBUG_LEVEL != 0` 里）改为指向**我们那份**：`_就地构造`。
      #   配套：`zhIncludes` 把本头的 `#include <xutility>` 指到 `<通用内部件>`。
      #   ⚠ 这条只有调试配置探针（IDL=1）照得出来，单头/组合探针默认 IDL=0 照不着。
      '_Construct_in_place' = '_就地构造'
      '_Uninitialized_copy' = '_未初始化复制'
      '_Delete_plain_internal' = '_删除原生内部'
      '_Unfancy' = '_去花式'
      '_Unfancy_maybe_null' = '_去花式可空'
      '_Erase_remove' = '_擦除并移除'
      '_Erase_remove_if' = '_按条件擦除并移除'
      '_Allocate_at_least_helper' = '_分配至少助手'
      '_Adopt' = '_收养'
      '_Adopt_locked' = '_收养加锁'
      '_Adopt_unlocked' = '_收养不加锁'
      '_Alloc_proxy' = '_分配代理'
      '_Allocate' = '_分配'
      '_Assign_locked' = '_赋值加锁'
      '_Assign_unlocked' = '_赋值不加锁'
      '_Bind' = '_绑定'
      '_Clamp_to_end' = '_夹取至末尾'
      # ⚠ §17.17.2 `_Construct_in_place` **撤下改名**（保持英文名）。
      #   逐行看过：`<xmemory>` 里它**只有调用、没有定义**（L1221/1230/1478/1484/1634），
      #   定义在**借来的** `<xutility>` 一侧；而那 5 处调用点**全在
      #   `#if _ITERATOR_DEBUG_LEVEL != 0` 里** —— 这就是"改名后只在 IDL=1 报未声明"的根因
      #   （IDL=0 时那些行不参与编译，这个名字从没被查过）。
      #   撤下后调用点保持英文 -> 解析到 `<xutility>` 那份 ✓；
      #   因为**我们那份从来没有定义过它**，不会出现 §16.61.6 那种"同名两份 -> 歧义"。
      #   ⚠ `_Construct_in_place_by_deref` **不撤**：它在 xmemory L1609 **有定义**，是我们那份。
      '_Construct_in_place_by_deref' = '_按解引用就地构造'
      '_Deallocate_plain' = '_释放原生'
      '_Destroy_range' = '_析构范围'
      '_Emplace_back' = '_尾部就地构造'
      '_Emplace_back_deref' = '_按解引用尾部就地构造'
      '_Emplace_back_deref_move' = '_按解引用移动尾部就地构造'
      '_Extract' = '_摘取'
      '_Get_first' = '_取第一'
      '_Get_val' = '_取本值'
      '_Get_value' = '_取值'
      '_Getcont' = '_取容器'
      '_Lock' = '_加锁'
      '_Orphan_all' = '_孤儿化全部'
      '_Orphan_all_locked_v3' = '_孤儿化全部加锁3'
      '_Orphan_all_unlocked_v3' = '_孤儿化全部不加锁3'
      '_Orphan_me_locked_v3' = '_孤儿化本迭代器加锁3'
      '_Orphan_me_unlocked_v3' = '_孤儿化本迭代器不加锁3'
      '_Reload_proxy' = '_重载代理'
      '_Swap_proxy_and_iterators' = '_交换代理与迭代器'
      '_Swap_proxy_and_iterators_locked' = '_交换代理与迭代器加锁'
      '_Swap_proxy_and_iterators_unlocked' = '_交换代理与迭代器不加锁'
      '_Uninitialized_move_unchecked' = '_未初始化移动非检查'
      # §16.70 收尾：这 5 个也只有本头（`_Fill_memset` 另在 xutility 有定义 ->
      #   按"定义方改本头这份"处理）。翻完本头就只剩 `_Allocate_aligned`
      #   与 allocator 契约名那批边界了。
      '_Copy_memcpy_common' = '_内存复制公共'
      '_Copy_memcpy_count' = '_内存复制计数'
      '_Copy_memcpy_distance' = '_内存复制距离'
      '_Fill_memset' = '_填充内存'
      '_Zero_range' = '_清零范围'
      # ⚠ `_Allocate_aligned` 实测【是本头定义的】（xmemory:140
      #   `__declspec(allocator) static _CLANG_CONSTEXPR20 void* _Allocate_aligned(...)`）
      #   —— 第一遍分类的正则被 `__declspec(...)` 前缀骗了，判成了"别处没有定义"。
      #   判据：**"谁定义它"的正则也要覆盖 `__declspec(...)` / `static` 这类前缀**，
      #   否则会把我们自己的定义判成借用（这一条与 §16.65.1b"尺子要维护"同源）。
      '_Allocate_aligned' = '_按对齐分配'
    ;
      '_Release' = '_释放';
}
    data    = [ordered]@{}
    derive  = @()
    stdHash = $false
    tparam  = @{ decl = ''; args = '' }
    # §17.27.53 阶段(2) 接通链名：本头正文里的 `_Construct_in_place` 已经指向
    #   `通用内部件`（我们的 xutility 拷贝）那份 `_就地构造`，所以必须把它引进来。
    #   ⚠ 顺序要紧：`通用内部件` 在**原件同一个位置**（xmemory 第 8 行）被引，
    #     在 5 处调用点之前 -> 非依赖名查找在定义处就能看到它。
    zhIncludes = @{ 'xutility' = '通用内部件' }
    # ⚠ 自己抄【缺的那句前向声明】。原文靠 <xutility>:4187 的 `struct _Iterator_base12;`
    #   撑住 `_Container_proxy::_Myfirstiter`；搬进 细节:: 后必须自己声明，
    #   否则校对的回退会把那一处改回英文（见 §16.23）。
    prologue = 'struct _迭代器基类12;'
    tests = @(
      @('只引中文头','#包含 <内存内部件>`n整数 主函数(){ 返回 0; }'),
      @('批A 的汉语名可用（分配器特征）','#包含 <内存内部件>`n整数 主函数(){ 标准::细节::分配器特征<std::allocator<整数>> 甲; (空型)甲; 返回 0; }'),
      # ⚠ 这条是【批 B 的真守卫】：它把顶层的汉语类型名逐个用起来。
      #   原来的两条测试太弱（一条是空主函数、一条只用 分配器特征），
      #   照不出"改名只在实例化时才检查"的位置 —— 正是 §15.1/§15.3 那件事。
      @('批B 顶层类型名的汉语名整套可用','#包含 <内存内部件>`n整数 主函数(){`n  (空型)sizeof(标准::细节::_简单类型集<整数>);`n  (空型)sizeof(标准::细节::分配器<整数>);`n  (空型)sizeof(标准::细节::_容器基类12);`n  (空型)sizeof(标准::细节::_迭代器基类12);`n  (空型)sizeof(标准::细节::_容器代理);`n  (空型)sizeof(标准::细节::_取尺寸类型<标准::细节::分配器<整数>>);`n  (空型)sizeof(标准::细节::_是默认分配器<标准::细节::分配器<整数>>);`n  (空型)sizeof(标准::细节::_空基类优化基类<整数>);`n  返回 0; }'),
      @('批B 前向声明确实在（_容器代理 能在定义之前用 _迭代器基类12）','#包含 <内存内部件>`n整数 主函数(){ 标准::细节::_容器代理 代; (空型)代; 返回 0; }'),
      # §17.27.53 机器守卫：链名真的从 `通用内部件` 接进来了（§17.17.2 已废止）。
      #   正文那 5 处调用在 `#if _ITERATOR_DEBUG_LEVEL != 0` 里，靠调试配置探针覆盖；
      #   这条则把"名字可见 + 是我们那一份"直接钉住。
      @('链名接通：_就地构造 从 通用内部件 可见','#包含 <内存内部件>`n整数 主函数(){ 整数 甲 = 0; 标准::细节::_就地构造(甲, 7); 返回 甲 - 7; }')
    )
  }
  # ===========================================================================
  #  §16.43 步骤 1 的第四个内部件：xtree（2000 行）
  #
  #  为什么先做它：`<映射>`/`<集合>`/`<无序映射>`/`<无序集合>`/`<链表>`/`<单向链表>`
  #  的一整族"借用"欠账都卡在它上面 ——
  #      `_Alnode` / `_Alnode_traits` / `_Nodeptr` / `_Key_compare`
  #  在那些头的拷贝里都是 `typename _Mybase::X`（_Mybase = **借来的** std::_Tree），
  #  按 §16.37.1 的判据属于第 ③ 类【不能翻】，除非 _Tree 也是我们自己的。
  #  本头做完，这一族才有消除路径（那时把上层的 zhIncludes 指过来即可）。
  #
  #  与 xmemory 的区别（实测）：本头【不需要 realInclude】——
  #  它引用的 _Container_base / _Simple_types / _Alloc_construct_ptr 等由真 <xmemory> 提供
  #  （它还只 #include <xmemory> 与 <xnode_handle.h>，两者都还没抄），
  #  而本头只翻【自己定义的】16 个名字，不碰那些借来的。
  #
  #  本条目先做【类型层】（与 §16.23 对 xmemory 的做法一致）；
  #  `_Tree` 的成员函数层是下一批。
  # ===========================================================================
  'xtree' = @{
    zh      = '树内部件'
    noPub   = $true
    types   = [ordered]@{
      '_Container_proxy_ptr' = '_容器代理指针'
      '_Container_base' = '_容器基类'
      '_Iterator_base12' = '_迭代器基类12'
      '_Iterator_base0' = '_迭代器基类0'
      '_Iterator_base' = '_迭代器基类'
      '_Leave_proxy_unbound' = '_离开代理未绑定'
      '_GET_PROXY_ALLOCATOR' = '_取代理分配器'
      '_Tree'                          = '_树'
      '_Tree_node'                     = '_树节点'
      '_Tree_val'                      = '_树值'
      '_Tree_iterator'                 = '_树迭代器'
      '_Tree_const_iterator'           = '_树常量迭代器'
      '_Tree_unchecked_iterator'       = '_树非检查迭代器'
      '_Tree_unchecked_const_iterator' = '_树非检查常量迭代器'
      '_Tree_iter_types'               = '_树迭代类型集'
      '_Tree_simple_types'             = '_树简单类型集'
      '_Tree_child'                    = '_树子向'
      '_Tree_id'                       = '_树标识'
      '_Tree_find_result'              = '_树查找结果'
      '_Tree_find_hint_result'         = '_树查找提示结果'
      '_Tree_head_scoped_ptr'          = '_树头作用域指针'
      '_Tree_temp_node_alloc'          = '_树临时节点分配器'
      '_Tree_temp_node'                = '_树临时节点'
      # §16.45 【销账】`_Tree` 的内部成员别名 —— 现在两边都是我们的，可以同步翻了。
      #   （它们就是 §16.2 欠账清单里的 _Alnode / _Alnode_traits / _Nodeptr。）
      #   `_In_place_key_extractor` 是【_Tset_traits/_Tmap_traits】里的成员，
      #   被 _Tree 读取（`_Traits::_In_place_key_extractor`）—— 定义在 set/map，
      #   读取点在本头，所以两边必须一起翻（跨头译名检查会强制一致）。
      '_Alnode'                = '_结点分配器'
      '_Alnode_traits'         = '_结点分配器特征'
      '_Nodeptr'               = '_结点指针'
      '_In_place_key_extractor' = '_就地键提取器'
      # §16.46 树内部件 自己还欠的 ① 类名（实测：这些名字【只在 xtree 里】，set/map 不引用）
      #   前 6 个在 <向量>/<链表>/<双端队列> 已有定译名，跨头一致性检查会强制沿用同一个中文名。
      '_Alty'                    = '_分配器类型'
      '_Alty_traits'             = '_分配器特征'
      '_Scary_val'               = '_迭代器检查值'
      '_Prevent_inheriting_unwrap' = '_阻止继承解包'
      '_Unchecked_iterator'      = '_非检查迭代器'
      '_Unchecked_const_iterator' = '_非检查常量迭代器'
      # 这三个是 xtree 特有的
      '_Erase_tree_and_orphan_guard' = '_擦树并孤立守卫'
      '_Redbl'                   = '_红黑'
      '_Strategy'                = '_策略'
      # 枚举量也是名字（§16.2 欠账清单里点过"enum values"）：
      #   _Redbl 的 _Red/_Black、_Strategy 的 _Copy/_Move。
      #   ⚠ `_Copy`/`_Move` 这一批【没做】—— 它们与 _Tree 的同名成员函数撞名
      #     （同一个文件里两个主人），要单独判定；`_Red`/`_Black` 没有这个问题。
      '_Red'                     = '_红'
      '_Black'                   = '_黑'
      # =======================================================================
      # §16.47 `_Tree` 的【契约名】第一批 —— 先按 §16.35.5 第 ④ 类分类再动手。
      # 实测（数迭代器类区间 25..311 vs _Tree 区间 852..2000 的出现次数）：
      #   只在 _Tree 里出现（=> 容器专有 => 可翻）：
      #     size_type(0/15) const_reference(0/1) const_iterator(0/42) iterator(6/73*)
      #     reverse_iterator(0/7) const_reverse_iterator(0/7) key_type(0/18)
      #     key_compare(0/24) value_compare(0/4) node_type(0/14) allocator_type(0/12)
      #     * iterator 那 6 次**全在字符串字面量里**（断言消息），不是标识符 -> 仍可翻
      #   迭代器类里也在用（=> 迭代器契约 => 不能翻）：
      #     value_type / difference_type / pointer / const_pointer / reference / iterator_category
      #   ⚠ 判据：**同一个名字既是容器契约又是迭代器契约时，不能翻** ——
      #     翻了，std::iterator_traits<我们的迭代器> 就认不出它（标准算法直接用不了）。
      # =======================================================================
      'iterator'                 = '迭代器'
      'const_iterator'           = '常量迭代器'
      # ⚠ `reverse_iterator` / `const_reverse_iterator` 【不翻】（§16.35.5 第 ② 类）：
      #   原文是 `using reverse_iterator = _STD reverse_iterator<iterator>;`
      #   —— 右边的 `reverse_iterator` 是 **std 的模板名**。翻了之后步 4c 会把它去限定成
      #   `反向迭代器<迭代器>`，而 `反向迭代器` 正是我们刚声明的别名 -> 自引用 -> 语法错：
      #       树内部件:898:50: error: 在 alias declaration 之后缺少 ';'
      #   （与 <跨度> 那次同一个坑。）中文名只能在派生层补（旧方向）。
      # ⚠ `size_type` 也【不翻】—— 同名两个主人：`_Tree` 自己有一个，
      #   而借来的 `allocator_traits` 也有一个（原文 867 行 `typename _Alty_traits::size_type`）。
      #   翻了就报：'std::allocator_traits<std::allocator<int>>' 中没有名为「尺寸类型」的类型。
      'const_reference'          = '常量引用'
      'key_type'                 = '键类型'
      'key_compare'              = '键比较器'
      'value_compare'            = '值比较'
      'node_type'                = '结点类型'
      'allocator_type'           = '分配器类型'
    }
    members = [ordered]@{
      '_Size_type' = '_尺寸类型';
      '_Swap_proxy_and_iterators' = '_交换代理与迭代器';
      '_Rebind_pointer_t' = '_重绑定指针类型';
      '_Result' = '_结果';
      '_Simple_types' = '_简单类型集';
      '_Valty' = '_值参数类型';
      '_Traits' = '_特征';
      '_Ty' = '_类型';
      '_One_then_variadic_args_t' = '_先一后变参实参';
      '_Zero_then_variadic_args_t' = '_先零后变参实参';
      '_Rebind_alloc_t' = '_重绑定分配器类型';
      '_Pocma_values' = '_传播复制移动赋值取值';
      '_Alloc_construct_ptr' = '_分配器构造指针';
      '_Mycont' = '_我的容器';
      '_Lock' = '_加锁';
      '_Get_first' = '_取第一';
      '_Difference_type' = '_差异类型';
      '_Compressed_pair' = '_压缩对';
      '_Comp' = '_比较器';
      '_Allocate' = '_分配';
      '_Mysize' = '_我的尺寸';
      '_Alloc' = '_分配器';
      '_Extract' = '_摘取';
      '_Ubegin' = '_解包首'
      '_Uend' = '_解包尾'
      '_Delete_plain_internal' = '_删除原生内部'
      '_Orphan_all' = '_孤儿化全部'
      '_Bind' = '_绑定'
      '_Adopt' = '_收养'
      # §17.22 本头**自己定义**的内部助手（逐名量过"谁定义它"）-> 翻。
      #   ⚠ 不登记（借来的）：_Allocate _Extract _Lock _Make _Proxy _Release _Unwrapped _Verify_range
      #   ⚠ 公共 API 名（insert/erase/find/count/emplace/merge/…）属与 <集合>/<映射> 的**一条链**，
      #     必须三处同批（§17.8 的判据），不在本批。
      '_Alloc_sentinel_and_proxy' = '_分配哨兵与代理'
      '_Copy' = '_复制'
      '_Copy_nodes' = '_复制节点'
      '_Copy_or_move' = '_复制或移动'
      '_Reparent_ptr' = '_重挂父指针'
      '_Sentinel' = '_哨兵'
      # §17.9 `_Kfn`（有序那一条链，**调用侧**）：实测本头正文里只有
      #   `_Traits::_Kfn(...)`（§17.6.1 逐行看过），定义在 <集合>/<映射> 的 traits 里
      #   -> 三处同批翻。与 §17.8 的无序链各自闭包、互不相干。
      '_Kfn' = '_取键'
      # §16.43 成员层第一批：**确认属于 `_Tree` 自己**的那一批。
      # ⚠ 不含借用自 <xutility>/<xmemory> 的自由函数与宏
      #   （_Adl_verify_range / _Construct_in_place / _Destroy_in_place /
      #    _Delete_plain_internal / _Xlength_error / _STL_VERIFY / _STL_INTERNAL_CHECK）——
      #   那些改了名会变成"我们自己的同名函数"，调用点直接报未声明（§15.8/§15.9 那一类）。
      '_Buyheadnode'      = '_建头节点'
      '_Buynode'          = '_建节点'
      '_Newnode'          = '_新节点'
      '_Freenode'         = '_释放节点'
      '_Freenode0'        = '_释放节点0'
      '_Erase_head'       = '_擦除头'
      '_Erase_tree'       = '_擦除树'
      '_Erase_tree_and_orphan' = '_擦除树并孤立'
      '_Orphan_ptr'       = '_孤立指针'
      '_Lrotate'          = '_左旋'
      '_Rrotate'          = '_右旋'
      '_Max'              = '_最大'
      '_Min'              = '_最小'
      '_Getal'            = '_取分配器'
      '_Getcomp'          = '_取比较器'
      '_Get_scary'        = '_取检查值'
      '_Find_hint'        = '_按提示查找'
      '_Find_lower_bound' = '_查找下界'
      '_Find_upper_bound' = '_查找上界'
      '_Find'             = '_查找'
      '_Lower_bound_duplicate' = '_下界重复项'
      '_Eqrange'          = '_等值区间'
      '_Insert_node'      = '_插入节点'
      '_Insert_range_unchecked' = '_插入范围非检查'
      '_Erase'            = '_擦除'
      '_Erase_unchecked'  = '_擦除非检查'
      '_Emplace'          = '_就地安置'
      # §17.27.54 同上（与 `any` 同因）：`_Emplace` 与 `_Construct_in_place` 撞译名 -> 改成员名。
      #   本头经 `内存内部件` 已能看到 `通用内部件` 的自由函数 `_就地构造`。
      '_Construct_in_place' = '_就地构造'
      '_Emplace_hint'     = '_按提示就地构造'
      # §17.27.55 链名接通（第二批）：`_Destroy_in_place` 定义方是 `内存内部件`（本头直接引它），
      #   `_Get_unwrapped`/`_Adl_verify_range` 定义方是 `通用内部件`（经 `内存内部件` 传递可见）。
      '_Destroy_in_place' = '_就地析构'
      '_Get_unwrapped' = '_取解包'
      '_Adl_verify_range' = '_ADL校验范围'
      # §17.27.56 链名族（成员名，§17.27.42「接收者定」）：这三个名字在本头是**我们自己
      #   迭代器类**的成员/隐藏友元 -> 改（接收者是我们的实例）。
      #   `通用内部件` 的泛型助手正文里调的就是这些汉语名：`_取解包` -> `._解包()`、
      #   `_定位包装` -> `._定位到(...)`、`_ADL校验范围` -> ADL `_校验范围`。
      #   ⚠ 两边不同改的后果**不是报错而是静默降级**：`_Unwrappable_v` / `_Range_verifiable_v`
      #     是 `if constexpr` 判据，名字对不上就变假 -> 解包直通（不真解包）、范围校验失效。
      '_Unwrapped' = '_解包'
      '_Verify_range' = '_校验范围'
      # §17.27.59 链名族（第二批）：`_Getcont` 的定义方是**基类** `_迭代器基类12`
      #   （在 `内存内部件` 里已改名为 `_取容器`）—— 本头所有 `this->_Getcont()` 都得跟。
      #   实测：改完 `_解包` 后 instantiate 到这一层才炸（`_树迭代器` 里没有 `_Getcont`）。
      '_Getcont' = '_取容器'
      # ⚠ `_Seek_to` 本头**早已登记**（见下面那行）—— 不要在这里重复登记（重复键会让整张表建不起来）。
      # ⚠ `_Extract` 【不登记】（§3.12 判据：同名另有一个主人）——
      #   本头正文里有 `std::_In_place_key_extract_set<...>::_Extract(...)`
      #   （那个类型借自 <xmemory>，它的成员名是 std 契约的一部分）。
      #   改了名，那一处就报「'std::_In_place_key_extract_set_impl<int,int>' 中没有名为 '_摘除' 的成员」。
      #   消除路径：等 树内部件 也切到我们的 内存内部件（那时两边一起翻）。
      '_Check_grow_by_1'  = '_检查增一'
      '_Check_node_allocator' = '_检查节点分配器'
      '_Swap_val_excluding_comp' = '_交换值不含比较器'
      '_Throw_tree_length_error' = '_抛树长度错误'
      '_Seek_to'          = '_定位到'
      '_First'            = '_首个'
      '_Last'             = '_最后'
      '_Unchecked_begin'  = '_非检查开始'
      '_Unchecked_end'    = '_非检查结束'
      '_Unchecked_end_iter' = '_非检查结束迭代器'
    ;
      'emplace' = '就地构造';
      'emplace_hint' = '按提示就地构造';
      'get_allocator' = '取分配器';
      'key_comp' = '键比较函数';
      'value_comp' = '值比较函数';

      '_Release' = '_释放';

      'insert_range' = '范围插入';

      'equal_range' = '相等区间';

      '_Proxy' = '_代理';

      '_Getptr' = '_取指针';

      # 'merge' = '归并';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下

      # 'extract' = '提取';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下

      # 'crend' = '常量反向结束';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下

      # 'clear' = '清空';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下

      # 'insert' = '插入';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下

      # 'count' = '计数';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下

      # 'rbegin' = '反向开始';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下

      # 'rend' = '反向结束';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下

      # 'erase' = '擦除';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下

      # 'crbegin' = '常量反向开始';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下

      '_Make' = '_造';

      'clear' = '清空';
}
    zhIncludes = @{ 'xmemory' = '内存内部件' }
    data    = [ordered]@{}
    derive  = @()
    stdHash = $false
    tparam  = @{ decl = ''; args = '' }
    tests = @(
      @('只引中文头','#包含 <树内部件>`n整数 主函数(){ 返回 0; }'),
      # ⚠ 真守卫（不是空测）：把几个顶层汉语类型名真正用起来。
      # 形参个数照原文：_Tree_child 无参、_Tree_node<_Value_type,_Voidptr>、_Tree_simple_types<_Ty>。
      @('顶层汉语类型名可用（模板形参照原文）','#包含 <树内部件>`n整数 主函数(){`n  (空型)sizeof(标准::细节::_树子向);`n  (空型)sizeof(标准::细节::_树节点<整数, 空型*>);`n  (空型)sizeof(标准::细节::_树简单类型集<整数>);`n  返回 0; }')
    )
  }
  # ===========================================================================
  #  §16.48 步骤 1 的第五个内部件：xhash（2063 行）
  #
  #  为什么做它：`<无序集合>`/`<无序映射>` 的一整族欠账卡在它上面 ——
  #    `_Alnode` / `_Alnode_traits` / `_Mutable_value_type` / `_In_place_key_extractor` /
  #    `_Key_compare` 在那些头的拷贝里都是 `typename _Mybase::X`（_Mybase = 借来的 std::_Hash）
  #    -> 第 ③ 类不能翻（同 §16.37 的 <映射> 族），除非 `_Hash` 也是我们自己的。
  #
  #  ⚠ `hash_compare` 【不翻】：它在 `_STDEXT_BEGIN`/`_STDEXT_END` 里，也就是
  #    **`stdext` 名域**（第 58 行），而第 90 行的 `using stdext::hash_compare;` 才把它引进 std。
  #    搬名域时 `namespace stdext` 原样不动，所以它是【另一个名域的公开名】，
  #    不属于"我们抄进 细节 的东西" —— 翻了反而会让第 90 行那个 using 找不到它。
  #    这是**边界**（不是欠账）：本项目的汉语化只覆盖 `标准`。
  #
  #  与 xtree 同形：noPub，先做类型层；成员层下一批。
  # ===========================================================================
  'xhash' = @{
    zh      = '哈希内部件'
    # §17.27.58 copyFixes（**边界**，不是欠账）：桶表那几处 `_Ilist` 是借来的
    #   `std::initializer_list`，它的 `begin/end` 永远是英文。
    copyFixes = @( @('_Ilist.开始()', '_Ilist.begin()'),
                   @('_Ilist.结束()', '_Ilist.end()') )
    noPub   = $true
    # ===========================================================================
    #  §16.49 【销账前置】让本头用【我们自己的 list】，不用 std::list。
    #
    #  为什么必须这样（实测）：本头 `_Hash` 靠 `typename _Mylist::_Alnode` 拿 list 的
    #  **私有**成员，而 `<list>:770` 只写了 `template <class> friend class _Hash;`
    #  —— 那个友元是开给 `std::_Hash` 的，我们的 `细节::_哈希` 拿不到，报
    #     「'_Alnode' 是 'std::list<int>' 的私有成员」。
    #  而 `<list>` 我们自己已经抄了（zhstdlib\链表），它拷贝里那句 friend 已经指向
    #  `细节::_哈希`（因为 `_Hash` 在 链表 条目里被翻成了 `_哈希`）——
    #  所以只要把 `list` 指到我们自己的 `链表实现`，友元关系**自动成立**。
    # ===========================================================================
    zhIncludes = @{ 'list' = '链表' }
    types   = [ordered]@{
      'list'                          = '链表实现'
      '_Hash'                         = '_哈希'
      '_Hash_vec'                     = '_哈希向量'
      '_Hash_find_last_result'        = '_哈希查找最后结果'
      '_Uhash_compare'                = '_无序哈希比较'
      '_Uhash_choose_transparency'    = '_无序哈希选择透明性'
      '_Reinterpret_move_iter'        = '_重解释移动迭代器'
      '_List_head_construct_ptr'      = '_链表头构造指针'
      '_Is_hasher'                    = '_是哈希器'
      # §16.50 与 <链表> 同步改名：本头正文里有 `typename _Mylist::X`
      #   （_Mylist = 我们自己的 链表实现），而 链表 条目已把下面这些 X 翻成汉语。
      #   不同步就报「'标准::细节::链表实现<int>' 中没有名为 '_Nodeptr' 的类型」。
      '_Nodeptr'                      = '_结点指针'
      '_Unchecked_iterator'           = '_非检查迭代器'
      '_Unchecked_const_iterator'     = '_非检查常量迭代器'
      # §16.50 与 <链表> 同步：链表 条目已把 `_Scary_val` 翻成 `_迭代器检查值`，
      #   而本头正文里有 `typename _Mylist::_Scary_val` -> 必须跟着改。
      '_Scary_val'                    = '_迭代器检查值'
      # -----------------------------------------------------------------------
      # §16.54 嵌套名欠账第二批（8 个）：`_Hash` **自己**的类内别名。
      #
      # 判据（先量再翻，§16.51.1）：这 8 个名字在【全部原头】里只出现在 xhash
      # （xhash 30 行，xutility/xmemory/xstring/unordered_*/xtree/list/vector 各 0 行）
      # —— 既没有别的内部件读它，也没有借来的 std 模板读它 -> 纯第 ① 类，
      # 翻了不需要任何别处同步。实测命令：见 §16.54 记录。
      #   ⚠ 对照：同在这张残留清单里的 allocator_type/iterator/size_type/… 那 15 个
      #     是【消费者读】的（<无序集合>/<无序映射> 正文里 `typename _Mybase::X`）
      #     -> 属第 ③/④ 类边界，本轮【不翻】（原因写进 §16.54.2）。
      # -----------------------------------------------------------------------
      '_Aliter'                       = '_分配器迭代器'
      '_Aliter_traits'                = '_分配器迭代器特征'

      '_Adapter'                      = '_适配器'
      '_Value_compare'                = '_值比较器'
      '_Equal_range_result'           = '_等值区间结果'
      '_Multi_equal_check_result'     = '_多重相等检查结果'
      '_Min_buckets_construct_ptr'    = '_最小桶数构造指针'
      # -----------------------------------------------------------------------
      # §16.55 嵌套名欠账第三批（3 个）：`_Hash` 里【既没有限定读取、也没有消费者读取】
      # 的那 3 个。判据（两条都要满足，缺一不可）：
      #   ① `X::名字` 在 xhash 里 0 处 —— 即没有任何**借用类型**读它
      #      （对照：`allocator_type` 有 `typename _Mylist::allocator_type`、
      #        `node_type`/`key_type` 有 `typename _Traits::X` -> 见 §16.55.2）；
      #   ② `<无序集合>`/`<无序映射>` 里 `_Mybase::名字` 0 处 —— 即消费者不读它。
      # 实测：这三个都是 0/0。翻掉只影响本头，公开层的英文名不受影响
      #   （消费者自己声明了 `using local_iterator = typename _Mybase::iterator;`，
      #    读的是 `iterator`，不是这三个）。
      # ⚠ `local_iterator`/`const_local_iterator` 是【桶迭代器】的公开名 ——
      #   公开层 `标准::无序集合::local_iterator` 仍在（消费者拷贝自己声明的那个），
      #   变汉语的只是 `细节::_哈希` 内部这一份。
      # -----------------------------------------------------------------------
      'const_reference'               = '常量引用'
      'local_iterator'                = '局部迭代器'
      'const_local_iterator'          = '常量局部迭代器'
      # -----------------------------------------------------------------------
      # §16.58 跨条目协调改名（第一批 3 个）——这三个名字**同时是借来的 std 契约**：
      #   `std::allocator_traits<A>::allocator_type`、`std::uses_allocator<X,A>`
      #   （读 `X::allocator_type`）。所以公开层必须把英文补回，
      #   4 个公开类的 `deriveTypes` 与手写别名【同批翻转】（见 §16.58 的清单）。
      #
      # 跨条目读取（实测）：
      #   · `typename _Traits::allocator_type` / `::key_type` / `::node_type`
      #     —— `_Uset_traits`/`_Umap_traits` 在【无序两头】的拷贝里 -> 同批翻；
      #   · `typename _Mylist::allocator_type` —— 【链表】-> 同批翻；
      #   · `_Hash<_Other_traits>::allocator_type`（两处 static_assert）—— 本头自己的。
      # 译名与 <映射>/<集合>/树内部件 既有的一致（跨头译名守卫会强制）：
      #   allocator_type -> 分配器类型、key_type -> 键类型、node_type -> **结点类型**。
      # -----------------------------------------------------------------------
      'allocator_type'                = '分配器类型'
      'key_type'                      = '键类型'
      'node_type'                     = '结点类型'
      # -----------------------------------------------------------------------
      # §16.60 协调改名第三批（7 个）：`哈希内部件` + `链表` + 两个无序头【同批】改。
      #   全是**内部名**（`key_compare`/`value_compare` 只在 traits 里，
      #   不是公开 API）-> 公开层【不需要】补英文。
      #
      # 跨条目读取（实测）：
      #   · `_Alnode` / `_Alnode_traits`：`链表`（`_List_val` 里 53/23 处，0 处限定读取）
      #     -> 本头读 `typename _Mylist::X`，两个无序头读 `typename _Mybase::X`；
      #   · `_Key_compare`：本头 L337 自己的别名（`typename _Traits::key_compare`），
      #     两个无序头读 `typename _Mybase::_Key_compare`（各 66 处用法）；
      #   · `key_compare` / `value_compare`：两个无序头的 traits 各 1 处声明，
      #     本头 L337/L338 各读 1 处（`typename _Traits::X`）；
      #   · `_Mutable_value_type`：traits 各 1 处声明，本头 6 处（1 处限定读）；
      #   · `_In_place_key_extractor`：traits 各 1 处声明，本头 6 处
      #     （`typename _Traits::template X<...>` —— 注意那个 `template` 关键字，
      #      所以"限定读取"正则会数成 0，实际是**我们在读**）。
      #
      # ⚠ §16.37 当年把 `_Mutable_value_type` / `_In_place_key_extractor` 判成
      #   "第 ③ 类不能翻"，理由是"读它的是**借来的** `std::_Hash`"。
      #   现在 `_Hash` 是我们自己的了 -> 那条理由失效，它变成**欠账**（§16.45）。
      # -----------------------------------------------------------------------
      '_Alnode'                       = '_结点分配器'
      '_Alnode_traits'                = '_结点分配器特征'
      '_Key_compare'                  = '_键比较器'
      'key_compare'                   = '键比较器'
      'value_compare'                 = '值比较'
      '_Mutable_value_type'           = '_可变值类型'
      '_In_place_key_extractor'       = '_就地键提取器'
    }
