  #  §16.61 步骤 1 的第六个内部件：xstring（3515 行）-> 字符串内部件
  #
  #  为什么先做它：`<字符串>`/`<字符串视图>`（步骤 3 的丁类薄壳）整族都卡在它上面，
  #  而它是"借用面最大"的一个 —— §16.53.3 已经量过：
  #    · 【甲】真借用 17 个，全部来自 `内存内部件`（xmemory）；
  #    · 【乙】本头自己声明、还没进表的内部名 24 个。
  #
  #  ★ 本轮的**边界决定**（写清楚，免得后来人以为漏了）：
  #    与 `<链表>` 现状一致 —— **暂时仍旧借用真 `<xmemory>`**，
  #    所以那 17 个 xmemory 名字在本条目里【保持英文】（欠账，消除路径 =
  #    把本条的 zhIncludes 指到 内存内部件 并同批翻那 17 个，见 §16.61.2）。
  #    这样本轮的改动面只有"本头自己的名字"，可以一次做完、一次验完。
  #
  #  ★ 逐名量过（§16.58 第一步：`X::名字` 限定读取）：
  #    下面要翻的每一个，限定读取都是 **0** —— 除了 `_Ctype`：
  #      L3398 `using _Ctype = typename _Myis::_Ctype;` 而
  #      L3397 `using _Myis = basic_istream<_Elem, _Traits>;` —— `_Myis` 是**借来的**
  #      `std::basic_istream`，所以 `_Ctype` 属第 ③ 类【不能翻】（翻了就读不到）。
  #      （对照：位集 条目里能翻 `_Ctype`，因为那里的 `_Ctype` 是 bitset 自己的类内别名。）
  # ===========================================================================
  'xstring' = @{
    zh      = '字符串内部件'
    realInclude = @('string')   # §16.29「乙」
    # §17.19.14 友元契约（前半）：friend 要指向我们的 sstream 类，就得先有它的【前置声明】，
    #   否则改名会被「编译器校对」撤回（实测警告：改回英文 basic_stringbuf）。
    prologue = '模板 <类型名 元素, 类型名 特征, 类型名 分配器> 类型 基础字符串缓冲;'
    # §17.27.58 copyFixes（**边界**，不是欠账）：`std::initializer_list` 的
    copyFixes = @( @('_Ilist.尺寸()', '_Ilist.size()'),
                   @('_Ilist.开始()', '_Ilist.begin()') )
    noPub   = $true
    # §17.12 接起来：本头原来 include 真 `<__msvc_string_view.hpp>`，现在指向我们自己的
    #   `字符串视图内部件`（§17.10 已把它的成员层做好、§17.11 已把 `char_traits` 变别名）。
    #   接上之后，`basic_string_view<...>` 才解析到**我们的** `基础字符串视图`，
    #   于是 `starts_with`/`ends_with`/`contains` 这三条"同一个词两个主人"的边界**销账**
    #   （两边现在都是我们的东西，可以同批翻）。
    zhIncludes = @{ '__msvc_string_view.hpp' = '字符串视图内部件'
                    # §17.15 借用面切换（与类型表/成员表**同批**，§17.14 的判据）
                    'xmemory' = '内存内部件' }
    types   = [ordered]@{
      # ---- §17.12：本头正文里的 `basic_string_view<...>` 指到我们自己的视图 ----
      'basic_string_view'             = '基础字符串视图'
      # §17.19.14 友元契约：friend 必须指向【我们的】sstream 类（否则我们的 <字符串流> 不是我们字符串的友元）。
      'basic_stringbuf' = '基础字符串缓冲'
      # §17.15 借用面切换：15 个 MSVC 内部件**类型**名（译名与 内存内部件 一致，守卫强制）
      # ⚠ allocator/allocator_traits 不在里面：内存内部件 把这两个改了名，本头照旧解析到 std（铁律③）
      '_Compressed_pair'              = '_压缩对'
      '_Container_base'               = '_容器基类'
      '_Iterator_base'                = '_迭代器基类'
      '_Simple_types'                 = '_简单类型集'
      '_Container_proxy_ptr'          = '_容器代理指针'
      '_Rebind_alloc_t'               = '_重绑定分配器类型'
      '_Pocma_values'                 = '_传播复制移动赋值取值'
      '_Guide_size_type_t'            = '_推导尺寸类型'
      '_Tidy_deallocate_guard'        = '_清理释放守卫'
      '_Leave_proxy_unbound'          = '_离开代理未绑定'
      '_Asan_aligned_pointers'        = '_地址消毒对齐指针'
      '_Dest'                         = '_目标'
      '_One_then_variadic_args_t'     = '_先一后变参实参'
      '_Zero_then_variadic_args_t'    = '_先零后变参实参'
      '_GET_PROXY_ALLOCATOR'          = '_取代理分配器'
      # -----------------------------------------------------------------------
      #  §17.13 【实测：切换要**类型 + 成员**一起同步 —— 本轮已回退，留作记录】
      #
      #  只登记了 15 个**类型**名、加了 `zhIncludes = @{ xmemory = 内存内部件 }`，
      #  生成时真头探针当场报：
      #      字符串内部件:44:15: error:
      #        '标准::细节::_字符串常量迭代器<_我的字符串>' 中没有名为 '_Adopt' 的成员
      #  —— `_Adopt` 是 `_Iterator_base12` 的成员，而 内存内部件 里它已经叫 **`_收养`**
      #     （§16.67/§16.70 那两批改的名）。
      #  这就是 §16.50/§16.51 那条老教训：**切换内部件时，类型名与成员名必须一起同步**；
      #  只做一半，报错会落在"上层正文调不到下层成员"上。
      #
      #  **下一轮该做的**：在 `zhIncludes` 加 `xmemory` 的同时，把 内存内部件 的
      #  **成员改名表**（`_Adopt`->`_收养`、`_Alloc_proxy`->`_分配代理`、`_Orphan_all`->`_孤儿化全部`、
      #  `_Swap_proxy_and_iterators`->`_交换代理与迭代器`、`_Get_first`->`_取第一`、
      #  `_Get_value`->`_取值`、`_Get_val`->`_取本值`、`_Reload_proxy`->`_重载代理`、
      #  `_Lock`->`_加锁`、`_Assign_locked/_Assign_unlocked`、`_Bind`、`_Clamp_to_end`、
      #  `_Deallocate_plain`、`_Destroy_range`、`_Extract`、`_Release`、`_Emplace_back` 家族、
      #  `_Construct_in_place(_by_deref)`、`_Uninitialized_move_unchecked`、
      #  `_Copy_memcpy_*`/`_Fill_memset`/`_Zero_range`/`_Allocate_aligned`、
      #  `_Allocate_at_least_helper`、`_Delete_plain_internal` …）
      #  **整表**一并登记到本头的 members，再重新试切换。
      #  判据：**切换的"一条链"= 类型表 + 成员表**，不是只看类型表。
      # -----------------------------------------------------------------------
      'basic_string'                  = '基础字符串实现'
      '_String_val'                   = '_字符串值'
      '_String_iterator'              = '_字符串迭代器'
      '_String_const_iterator'        = '_字符串常量迭代器'
      '_String_iter_types'            = '_字符串迭代类型集'
      '_String_constructor_concat_tag' = '_字符串构造连接标号'
      '_Bxty'                         = '_缓冲联合'
      '_Released_buffer'              = '_已释放缓冲'
      # ---- 本头自己的类内/函数内别名 ----
      #   ⚠ `_Mystr` / `_Mysizt` 是 `operator>>` 里的局部别名（指向 `basic_string` 本身）：
      #     名字是我们的，翻；而 `_Myis` 指向**借来的** `basic_istream` ——
      #     名字本身也是我们的（只是个 using 名），翻它不会碰到 std 里的东西
      #     （被翻掉的是 `typename _Myis::X` 里的 `::` **左边**，右边 `_Ctype` 不动）。
      '_Mystr'                        = '_我的字符串'
      '_Myis'                         = '_我的输入流'
      '_Mysizt'                       = '_我的尺寸类型'
      '_Is_string_view_ish'           = '_是字符串视图类'
      '_Is_elem_cptr'                 = '_是元素字符指针'
      # ---- 与既有的跨头译名**必须一致**（跨头译名守卫会强制）----
      '_Alty'                         = '_分配器类型'
      '_Alty_traits'                  = '_分配器特征'
      '_Scary_val'                    = '_迭代器检查值'
      '_Prevent_inheriting_unwrap'    = '_阻止继承解包'
      'allocator_type'                = '分配器类型'
      'const_reverse_iterator'        = '常量反向迭代器'
      # ---------------------------------------------------------------------
      #  ⚠ 【边界】下面这些**不翻**（都属 §16.35.5 第 ②③④ 类），逐条记理由：
      #    · size_type / iterator / const_iterator / value_type / const_pointer /
      #      const_reference / difference_type / pointer / reference ——
      #      同一个词同时出现在 `basic_string` 与 `_String_iterator` /
      #      `_String_const_iterator` 里（"一个词两个主人"，§16.54.3），
      #      按词替换会把**迭代器契约名**一起改掉；
      #      而且 `typename allocator_traits<_Alloc>::size_type` 这类**借用读取**
      #      也在同一文件里（改了就读不到）。
      #    · _Ctype —— L3398 `typename _Myis::_Ctype`，`_Myis` 是借来的 basic_istream。
      #    · reverse_iterator / iterator_category / iterator_concept / element_type /
      #      traits_type / pointer_traits / hash —— std 契约名或 std 模板名在 _STD 位。
      # ---------------------------------------------------------------------
    }
    # ⚠ 成员函数名（§16.61.9）：与 <链表>/<向量> 同一套译名，跨头译名守卫会强制一致。
    #   ⚠⚠ 这里有个**已知的硬冲突**：`basic_string_view` 是**借来的**
    #      （`<__msvc_string_view.hpp>`，我们还没抄），而它的成员名与 basic_string 完全同名
    #      （size/data/begin/end/substr/compare/find*/starts_with/…）。
    #      按词替换会把这些**借用对象上的调用**一起改掉 —— 那是必然的。
    #      处理办法**不是**逐个手工排查，而是**让编译器的"改回英文"机制兜**（§3.2 坑②：
    #      报行列号 -> 按字节偏移改回 -> 进 `⚠ 生成器告警台账`）。
    #      每一条改回都是**欠账**，消除路径 = 把 `<字符串视图>` 也抄成我们自己的内部件。
    members = [ordered]@{
      '_Alloc' = '_分配器';
      '_Construct' = '_构造';
      '_Ctype' = '_字符类型';
      '_Difference_type' = '_差异类型';
      '_Elem' = '_元素';
      '_First' = '_首个';
      '_Get_comparison_category_t' = '_取比较类别类型';
      '_Last' = '_最后';
      '_Max' = '_最大';
      '_Mycont' = '_我的容器';
      '_Mysize' = '_我的尺寸';
      '_Op' = '_操作';
      '_Result' = '_结果';
      '_Size_type' = '_尺寸类型';
      '_Traits' = '_特征';
      '_Ty' = '_类型';
      '_Uty' = '_结果类型';
      # §17.27.73 A 桶批量（§17.27.62 工作表）：A 桶 = 唯一定义方归我们 -> 可直接登记；
      #   译名取自已登记条目（跨头译名守卫据此保证一致）。
      '_Ubegin' = '_解包首'
      '_Uend' = '_解包尾'
      '_Unfancy' = '_去花式'
      '_Unfancy_maybe_null' = '_去花式可空'
      # §17.27.60 台账收尾（阶段(3) 第一批）：这些名字的定义方是 通用内部件（我们的 xutility 拷贝，
      #   §17.27.52 已给定义方解毒）；本头能看到它 -> 调用点跟改，指向我们那份。
      '_Pass_fn' = '_传递函数'
      '_Copy_n_unchecked4' = '_复制N个非检查4'
      '_To_unsigned_like' = '_转为无符号同型'
      '_Allocate_for_capacity' = '_按容量分配'
      # §17.27.54 链名接通：本头经 `内存内部件` 已能看到 `通用内部件` 的 `_就地构造`。
      '_Construct_in_place' = '_就地构造'
      # §17.27.55 链名接通（第二批）：`_Destroy_in_place` 定义方 `内存内部件`；
      #   `_Get_unwrapped`/`_Adl_verify_range` 定义方 `通用内部件`（同一条传递链）。
      '_Destroy_in_place' = '_就地析构'
      '_Get_unwrapped' = '_取解包'
      '_Adl_verify_range' = '_ADL校验范围'
      # §17.27.56 链名族（成员名，§17.27.42「接收者定」）：这三个名字在本头是**我们自己
      #   迭代器类**的成员/隐藏友元 -> 改（接收者是我们的实例）。
      #   `通用内部件` 的泛型助手正文里调的就是这些汉语名：`_取解包` -> `._解包()`、
      #   `_定位包装` -> `._定位到(...)`、`_ADL校验范围` -> ADL `_校验范围`。
      #   ⚠ 两边不同改的后果**不是报错而是静默降级**：`_Unwrappable_v` / `_Range_verifiable_v`
      #     是 `if constexpr` 判据，名字对不上就变假 -> 解包直通（不真解包）、范围校验失效。
      '_Unwrapped' = '_解包'
      '_Seek_to' = '_定位到'
      '_Verify_range' = '_校验范围'
      '_Deallocate_for_capacity' = '_按容量释放'
      # ---- 容量与尺寸 ----
      'size' = '尺寸'; 'capacity' = '容量'
      'empty' = '为空'; 'clear' = '清空'
      # ⚠ `max_size` 【不翻】：与 <链表>/<哈希内部件> 一致 —— 它也是借来的
      #   `allocator_traits` 的契约成员（实测那两处都因它报过错）。
      # ⚠ `length` / `assign` / `copy` / `compare` / `find` 【不翻】——
      #   实测（§16.61.9）：它们是**借来的 `char_traits`** 的成员名，
      #   `basic_string<char>` 的默认 `_Traits` 就是 `std::char_traits<char>`，
      #   所以 `_Traits::length(...)` 这类调用点改了就报
      #     「'std::char_traits<char>' 中没有名为 '长度' 的成员」。
      #   （生成器的"改回英文"机制只兜住了它**编译到**的那两处 assign/copy，
      #     length/compare/find 是在单头测试里才炸的 —— §16.37.2 那条老教训。）
      #   消除路径 = 把 `<字符串视图>` / `char_traits` 也抄成我们自己的内部件。
      # ---- 迭代器 ----
      'begin' = '开始'; 'end' = '结束'
      'cbegin' = '常量开始'; 'cend' = '常量结束'
      'rbegin' = '反向开始'; 'rend' = '反向结束'
      'crbegin' = '常量反向开始'; 'crend' = '常量反向结束'
      # ---- 元素访问 ----
      'front' = '前'; 'back' = '后'; 'at' = '取值'
      'data' = '数据'; 'c_str' = 'C字符串'
      # ---- 修改 ----
      'push_back' = '尾插'; 'pop_back' = '尾删'
      'append' = '追加'
      'insert' = '插入'; 'erase' = '擦除'; 'replace' = '替换'
      'resize' = '调整尺寸'; 'reserve' = '预留'
      'shrink_to_fit' = '收缩至适应'
      'append_range' = '追加范围'; 'assign_range' = '范围赋值'
      'insert_range' = '范围插入'; 'replace_with_range' = '按范围替换'
      # ---- 操作 ----
      'substr' = '子串'
      'rfind' = '反向查找'
      'find_first_of' = '查找首次属于'; 'find_last_of' = '查找末次属于'
      'find_first_not_of' = '查找首次不属于'; 'find_last_not_of' = '查找末次不属于'
      # ⚠ `starts_with` / `ends_with` / `contains` 【不翻】—— 实测（§16.61.9）：
      #   它们的实现是**造一个 `basic_string_view` 再调用它的同名成员**：
      #       return basic_string_view<...>{...}.starts_with(_Right);
      #   而 `basic_string_view` 是**借来的**（`<__msvc_string_view.hpp>`，还没抄）
      #   -> 同一个词两个主人（§16.54.3）：只翻左边，右边那句就报
      #      「'std::basic_string_view<char>' 中没有名为（成员名）'开头为' 的成员」。
      #   ⚠ 而且这句在**模板体里**，生成器的"改回英文"机制【看不见】（它只编译到
      #     校对探针实例化到的位置，§16.37.2）—— 是新加的那条"汉语成员真测试"抓出来的。
      #   消除路径 = 把 `<字符串视图>` 也抄成我们自己的内部件，两边一起翻。
      'get_allocator' = '取分配器'
      # §17.12 三条边界销账：`starts_with`/`ends_with`/`contains` 的实现是
      #   「造一个 view 再调用它的同名成员」。原来 view 是**借来的** -> 同一个词两个主人，
      #   按词替换必然误伤（§16.61.9）。现在 view 是我们的 `基础字符串视图`、且我们那份
      #   已经叫 `开头为`/`结尾为`/`包含` -> 两边同批翻，边界消失。
      'starts_with' = '开头为'; 'ends_with' = '结尾为'; 'contains' = '包含'
      # §17.15 借用面切换的**成员表**（§17.14：类型表 + 成员表必须同批）。
      #   ⚠ 不登记 _Construct_in_place(_by_deref)/_Destroy_range/_Extract/_Release：
      #     它们属于**借来的 std**（allocator_traits 那一侧），改名会报"未使用声明的标识符"。
      '_Adopt' = '_收养'
      '_Alloc_proxy' = '_分配代理'
      '_Bind' = '_绑定'
      '_Clamp_to_end' = '_夹取至末尾'
      '_Get_first' = '_取第一'
      '_Getcont' = '_取容器'
      '_Orphan_all' = '_孤儿化全部'
      '_Reload_proxy' = '_重载代理'
      '_Swap_proxy_and_iterators' = '_交换代理与迭代器'
      '_Allocate_at_least_helper' = '_分配至少助手'
      '_Delete_plain_internal' = '_删除原生内部'
      # ⚠ `swap` 照旧不改名（§3.12）。
      # -----------------------------------------------------------------------
      # §16.64 本头**自己定义**的内部助手（逐个量过"谁定义它"）：
      #   判据 = 这 31 个里，只有 `_Erase_remove`/`_Erase_remove_if` 在 xmemory 里
      #   也有同名定义，`_Getal`/`_Unchecked_begin`/`_Unchecked_end` 在 xtree/xhash 里
      #   也有 —— 后三个**必须用既有译名**（跨头译名守卫会强制），其余是本头独有。
      #   ⚠ 这批不是公开 API（内部助手），所以**不需要**在公开层补英文；
      #     它们只被本头自己的成员调用（`字符串内部件` 目前还没有消费者）。
      # -----------------------------------------------------------------------
      '_Activate_SSO_buffer' = '_激活小串缓冲'
      '_Become_small' = '_转为小串'
      '_Calculate_growth' = '_计算增长'
      '_Check_offset' = '_检查偏移'
      '_Check_offset_exclusive' = '_检查偏移排他'
      '_Clamp_suffix_size' = '_夹取后缀尺寸'
      '_Construct_empty' = '_构造为空串'
      '_Construct_from_iter' = '_由迭代器构造'
      '_Eos' = '_串尾'
      '_Erase_noexcept' = '_擦除不抛出'
      '_Erase_remove' = '_擦除并移除'
      '_Erase_remove_if' = '_按条件擦除并移除'
      '_Insert_string' = '_插入字符串'
      '_Large_mode_engaged' = '_已启用大串模式'
      '_Move_assign_from_buffer' = '_由缓冲移动赋值'
      '_Move_construct_from_substr' = '_由子串移动构造'
      '_Myptr' = '_我的指针';
      '_Reallocate_for' = '_为重分配'
      '_Reallocate_grow_by' = '_按增量重分配'
      '_Release_to_buffer' = '_释放至缓冲'
      '_Resize_and_overwrite' = '_调整尺寸并覆写'
      '_Starts_with' = '_开头为'
      '_Swap_bx_large_with_small' = '_交换大串小串缓冲'
      '_Swap_data' = '_交换数据'
      '_Switch_to_buf' = '_切换到缓冲'
      '_Take_contents' = '_接管内容'
      '_Tidy_deallocate' = '_清理释放'
      '_Xran' = '_抛范围错'
      '_Getal' = '_取分配器'
      '_Unchecked_begin' = '_非检查开始'
      '_Unchecked_end' = '_非检查结束'
    ;
      '_Ok' = '_成功';

      '_Equal' = '_相等';

      '_Copy_s' = '_复制s';

      '_Do_hash' = '_求散列';

      '_Hash_array_representation' = '_散列数组表示';

      '_Compat' = '_兼容';

      '_Release' = '_释放';

      '_Modify_annotation' = '_修改标注';

      '_Apply_annotation' = '_应用标注';

      '_Verify_offset' = '_校验偏移';

      '_Proxy' = '_代理';

      '_Create_annotation' = '_创建标注';

      '_Remove_annotation' = '_移除标注';

      '_ASAN_STRING_CREATE' = '_ASAN_串创建';

