}
    data    = [ordered]@{}
    derive  = @()
    stdHash = $false
    tparam  = @{ decl = ''; args = '' }
    tests = @(
      @('只引中文头','#包含 <字符串内部件>`n整数 主函数(){ 返回 0; }'),
      @('顶层汉语类型名可用（真用法，不是空测）','#包含 <字符串内部件>`n整数 主函数(){ 标准::细节::基础字符串实现<字符> 甲 = "abc"; 甲.尾插(字符(100)); 返回 (整数)甲.尺寸() - 4; }'),
      # ⚠ 这条的写法吃过一次亏：`基础字符串实现<字符>::_迭代器检查值` 是**私有**成员
      #   （实测报「是 私有 成员」），基类名也不能这样点出来 ——
      #   所以从**名域作用域**直接命名这几个内部类型（它们本来就在 `标准::细节`）。
      @('内部类型名可用（名域作用域直呼）','#包含 <字符串内部件>`n整数 主函数(){`n  (空型)sizeof(标准::细节::_字符串值<std::_Simple_types<字符>>);`n  (空型)sizeof(标准::细节::_字符串迭代器<标准::细节::_字符串值<std::_Simple_types<字符>>>);`n  (空型)sizeof(标准::细节::_字符串常量迭代器<标准::细节::_字符串值<std::_Simple_types<字符>>>);`n  返回 0; }'),
      # §16.61.9 成员层真守卫：把**改过名的成员**逐个调一遍（空测照不出"名字不存在"）。
      @('汉语成员可用（真用法）','#包含 <字符串内部件>`n整数 主函数(){ 标准::细节::基础字符串实现<字符> 甲 = "abc";`n  甲.追加("de"); 甲.插入(0, 1, 字符(122)); 甲.替换(0, 1, "Z"); 甲.调整尺寸(6, 字符(121)); 甲.预留(32); 甲.收缩至适应();`n  整数 和 = (整数)甲.尺寸() + (整数)甲.容量() + (甲.为空() ? 1 : 0);`n  字符 首 = 甲.前(); 字符 末 = 甲.后();`n  (空型)甲.数据(); (空型)甲.C字符串(); (空型)甲.取分配器(); (空型)甲.子串(0, 1);`n  (空型)甲.反向查找("y"); (空型)甲.查找首次属于("y"); (空型)甲.查找末次不属于("q");`n  (空型)甲.开头为("Z"); (空型)甲.结尾为("y");`n  标准::细节::基础字符串实现<字符>::iterator 头 = 甲.开始(); 头 = 甲.结束();`n  甲.assign("xyz"); 甲.擦除(0, 1); 甲.清空();`n  (空型)(和 + (整数)首 + (整数)末); 返回 (甲.为空() ? 0 : 1); }'),
      # §17.27.56 机器守卫：同 <向量>；这条覆盖 `字符串内部件` 的迭代器。
      @('链名族一致（解包/定位真的作用在我们的迭代器上）','#包含 <字符串内部件>`n#包含 <type_traits>`n整数 主函数(){ 标准::细节::基础字符串实现<字符> 甲 = "abc"; 自动 首 = 甲.开始();`n  静态断言(!std::is_same_v<std::remove_cvref_t<decltype(标准::细节::_取解包(首))>, decltype(首)>);`n  标准::细节::_定位包装(首, 标准::细节::_取解包(首));`n  标准::细节::_ADL校验范围(甲.开始(), 甲.结束());`n  返回 (整数)甲.尺寸() - 3; }'),
      @('与微软原头并存（std::string 照旧）','#包含 <字符串内部件>`n#包含 <string>`n整数 主函数(){ 标准::细节::基础字符串实现<字符> 甲 = "abc"; std::string 乙 = "abc"; 返回 (整数)甲.尺寸() - (整数)乙.size(); }')
    )
  }
  # ===========================================================================
  #  §16.62 步骤 1 的第七个内部件：__msvc_string_view.hpp（2016 行）
  #
  #  为什么做它：§16.61.9 把 `字符串内部件` 成员层的**全部边界**都归结到它身上 ——
  #  `starts_with` / `ends_with` / `contains` 之所以不能翻，就是因为它们的实现是
  #  「造一个 `basic_string_view` 再调用它的同名成员」，而 view 是**借来的**。
  #  这个头里同时定义着 `char_traits`（`_Narrow_char_traits` / `_WChar_traits` 的公开壳）
  #  与 `basic_string_view` / `_String_view_iterator`。
  #
  #  ★ 铁律③ 的判定（本轮最重要的一个决定）：
  #    `char_traits` **不翻**（保持英文名）—— 它是**用户可特化**的 std 模板
  #    （`std::char_traits<自定义字符>`），**类型身份参与语义**：
  #    翻了就等于换了一个类型，用户的特化再也匹配不上。属铁律③ 的"只能用别名"那一类。
  #    它下面的实现基类（`_Char_traits`/`_WChar_traits`/`_Narrow_char_traits`）是我们自己的
  #    内部件 -> 照翻（用户不会特化它们）。
  #  ★ 与 <字符串内部件> 的关系：本轮**不**把两者的 zhIncludes 接起来
  #    （那是一次跨条目协调改名，同 §16.58/§16.60 的做法，留作下一步）。
  # ===========================================================================
  '__msvc_string_view.hpp' = @{
    zh      = '字符串视图内部件'
    realInclude = @('string_view')   # §16.29「乙」
    noPub   = $true
    # -----------------------------------------------------------------------
    #  §17.11.3（铁律③）`char_traits` **必须是别名，不能是拷贝** —— 机制已补好，本轮启用。
    #
    #  `char_traits` 是用户可特化的 std 模板（`std::char_traits<自定义字符>`），
    #  身份参与语义。我们抄的那一份（主模板 + 6 个特化）**永远收不到用户的特化**。
    #  做法：`dropTypes` 把抄来的 7 处定义全部删掉（`Remove-ClassDef` 现在会连
    #  【前面的多行模板头】一起删 —— §17.11.1 就是栽在这里），
    #  于是本文件里的 `char_traits` 由 `使用 名域 std;` + 真头包含解析到 **std 那一份**
    #  = "伸手用 std"的别名语义，身份不变。
    #  ⚠ 实现基类 `_Char_traits`/`_WChar_traits`/`_Narrow_char_traits` 保留
    #    （用户不会特化它们）；std 的 `char_traits<char>` 派生自 std 自己的基类，
    #    我们那份拷贝因此**不被用到**，但留着无害。
    # -----------------------------------------------------------------------
    dropTypes = @('char_traits')
    types   = [ordered]@{
      '_Verify_range' = '_校验范围'
      '_Seek_to' = '_定位到'
      '_Unwrapped' = '_解包'
      # ---- 本头自己的顶层类型 ----
      'basic_string_view'             = '基础字符串视图'
      '_String_view_iterator'         = '_字符串视图迭代器'
      '_String_bitmap'                = '_字符串位图'
      '_Ostr_t'                       = '_输出流类型'
      '_Traits_ch_t'                  = '_特征字符类型'
      '_Get_comparison_category'      = '_取比较类别'
      '_Get_comparison_category_t'    = '_取比较类别类型'
      # ---- char_traits 的实现基类（我们自己的内部件；公开壳 char_traits 见下）----
      '_Char_traits'                  = '_字符特征基类'
      '_WChar_traits'                 = '_宽字符特征'
      # ---------------------------------------------------------------------
      #  ⚠ 【不翻】逐条记理由：
      #    · `char_traits` —— 铁律③：用户可特化的 std 模板，身份参与语义（见上）。
      #    · `char_type` / `int_type`? / `off_type` / `pos_type` / `state_type` /
      #      `difference_type` / `reference` / `comparison_category` / `element_type` /
      #      `traits_type` —— traits / 迭代器的**契约名**（第 ③④ 类），
      #      借来的 std 模板与 traits 契约都读它们。
      #    · `hash` / `pointer_traits` —— std 模板名，本头里是它们的**特化**（`_STD` 位）。
      #    · `reverse_iterator` / `iterator_category` / `iterator_concept` —— 同上。
      # ---------------------------------------------------------------------
    }
    # §17.10 成员层（**只翻本头自己定义、且不同时是借用契约的那些**）：
    #   本头目前【还没有消费者】（`字符串内部件` 仍 include 真 `<string_view>`），
    #   所以这一批是**自洽的、零跨条目风险** —— 正好按 §17.8 的"一条链"判据先做一半。
    #   ⚠ 不翻的（边界，逐条有理由）：
    #     · `length` / `assign` / `copy` / `compare` / `find` / `rfind` / `find_first_of` /
    #       `find_last_of` / `find_first_not_of` / `find_last_not_of` —— 借来的 `char_traits`
    #       成员名（§16.61.9 实测过同族错误）；
    #     · `max_size` —— 借来的 `allocator_traits` 契约名。
    #   ⚠ `starts_with` / `ends_with` / `contains` 本头**可以**翻（view 里是直接定义），
    #     它们之所以在 `字符串内部件` 那边是边界，是因为**那边调的是本头的同名成员** ——
    #     等两个头接起来、两边同批翻之后，那三条边界才销账（下一轮）。
    members = [ordered]@{
      '_Dest' = '_目标';
      '_Elem' = '_元素';
      '_First' = '_首个';
      '_Last' = '_最后';
      '_Mysize' = '_我的尺寸';
      '_Prevent_inheriting_unwrap' = '_阻止继承解包';
      '_Traits' = '_特征';
      '_Ty' = '_类型';
      # §17.27.60 台账收尾（阶段(3) 第一批）：这些名字的定义方是 通用内部件（我们的 xutility 拷贝，
      #   §17.27.52 已给定义方解毒）；本头能看到它 -> 调用点跟改，指向我们那份。
      '_Myptr' = '_我的指针';
      '_Find_vectorized' = '_查找向量化'
      '_Find_last_vectorized' = '_查找末个向量化'
      '_Find_end_vectorized' = '_查找末段向量化'
      '_Search_vectorized' = '_搜索向量化'
      '_Mark' = '_标记'
      '_Match' = '_匹配'
      'size' = '尺寸'; 'empty' = '为空'
      'begin' = '开始'; 'end' = '结束'
      'cbegin' = '常量开始'; 'cend' = '常量结束'
      'rbegin' = '反向开始'; 'rend' = '反向结束'
      'crbegin' = '常量反向开始'; 'crend' = '常量反向结束'
      'front' = '前'; 'back' = '后'; 'at' = '取值'
      'data' = '数据'
      'substr' = '子串'
      'remove_prefix' = '去前缀'; 'remove_suffix' = '去后缀'
      # §17.24 与 字符串内部件【同名助手】口径统一（译名早已在那边定下，跨头守卫强制）：
      '_Check_offset' = '_检查偏移'
      '_Check_offset_exclusive' = '_检查偏移排他'
      '_Clamp_suffix_size' = '_夹取后缀尺寸'
      '_Insert_string' = '_插入字符串'
      '_Starts_with' = '_开头为'
      '_Unchecked_begin' = '_非检查开始'
      '_Unchecked_end' = '_非检查结束'
      '_Xran' = '_抛范围错'
      'starts_with' = '开头为'; 'ends_with' = '结尾为'; 'contains' = '包含'
      # ⚠ swap 照旧不改名（§3.12）
    ;
      '_Ok' = '_成功';

      '_Equal' = '_相等';

      '_Copy_s' = '_复制s';

      '_Do_hash' = '_求散列';

      '_Hash_array_representation' = '_散列数组表示';

      '_Traits_ptr_t' = '_特征指针类型';

      '_Primary_char_traits' = '_主字符特征';

      '_Verify_offset' = '_校验偏移';
}
    zhIncludes = @{ 'xutility' = '通用内部件' }
    data    = [ordered]@{}
    derive  = @()
    stdHash = $false
    tparam  = @{ decl = ''; args = '' }
    tests = @(
      @('只引中文头','#包含 <字符串视图内部件>`n整数 主函数(){ 返回 0; }'),
      @('顶层汉语类型名可用（真用法）','#包含 <字符串视图内部件>`n整数 主函数(){ 标准::细节::基础字符串视图<字符> 甲("abc"); 甲.去前缀(1); 返回 (整数)甲.尺寸() - 2; }'),
      # ⚠ `包含`（contains）是 C++23 才有的成员（我们编 -std=c++20）-> 测试里不调；
      #   但它在表里照登记（C++23 下那个成员照样会翻成汉语）。
      @('迭代器与位图内部名可用','#包含 <字符串视图内部件>`n整数 主函数(){ 标准::细节::基础字符串视图<字符> 甲("abc");`n  标准::细节::基础字符串视图<字符>::iterator 头 = 甲.开始(); 头 = 甲.结束();`n  (空型)sizeof(标准::细节::基础字符串视图<字符>::const_iterator);`n  整数 和 = 甲.开头为("a") ? 1 : 0; 整数 尾 = 甲.结尾为("c") ? 1 : 0;`n  (空型)甲.数据(); (空型)甲.子串(0, 1); 甲.去后缀(0);`n  返回 (整数)甲.尺寸() + 和 + 尾 - 5; }'),
      @('与微软原头并存（std::string_view 照旧）','#包含 <字符串视图内部件>`n#包含 <string_view>`n整数 主函数(){ 标准::细节::基础字符串视图<字符> 甲("abc"); std::string_view 乙 = "abc"; 返回 (整数)甲.尺寸() - (整数)乙.size(); }'),
      # §17.11.3 铁律③ 的机器守卫：`char_traits` 必须是**别名**（= std 那一个），
      #   不是我们抄的一份 —— 用户对 `std::char_traits<自定义字符>` 的特化才会适用。
      #   只断言"我们那边有个 char_traits"是不够的：**必须是同一个类型**。
      @('char_traits 就是 std 那一个（铁律③ 机器守卫）','#包含 <字符串视图内部件>`n#包含 <type_traits>`n静态断言(std::is_same_v<标准::细节::char_traits<字符>, std::char_traits<字符>>);`n静态断言(std::is_same_v<标准::细节::基础字符串视图<字符>::traits_type, std::char_traits<字符>>);`n整数 主函数(){ 返回 0; }')
    )
  }
  'xutility' = @{
    zh      = '通用内部件'
    # 目标阶段(2)：Step 1 的最后一块（7630 行）。noPub -> 派生层不补英文，名字要逐批补全。
    #   prologue：subrange 的【带默认值前置声明】在另一个头（__msvc_iter_core.hpp）里，
    #   而定义在 <xutility>（三参无默认）—— 拷贝落在 标准::细节::ranges 后，推导指引找不到默认值，
    #   会报『太少个模板实参』。这里按原件原样补一份前置声明。
    noPub   = $true
    realInclude = @('xutility')
    prologue = "#ifndef ZH_SUBRANGE_FWD`n#define ZH_SUBRANGE_FWD`n名域 ranges { 模板 <input_or_output_iterator _It, sentinel_for<_It> _Se = _It, std::ranges::subrange_kind _Ki = sized_sentinel_for<_Se, _It> ? std::ranges::subrange_kind::sized : std::ranges::subrange_kind::unsized> requires (_Ki == std::ranges::subrange_kind::sized || !sized_sentinel_for<_Se, _It>) 类型 subrange; }`n#endif"
    types   = [ordered]@{
      '_Container_proxy' = '_容器代理'
      '_Iterator_base12' = '_迭代器基类12'
                          '_Construct_in_place' = '_就地构造'
                          '_Adl_verify_range' = '_ADL校验范围'
                          '_Unwrapped' = '_解包'
