                          # §17.19.17：`monostate` 的**定义**在这里（实测微软把它放在 xutility，
                          #   <variant> 只用不定义）。定义侧不改名，<变体> 那边的调用侧就永远改不动
                          #   —— 编译器校对会把它撤回英文，而且**死分支里的残留不会被撤回**
                          #   （实测 `#else` 支留下未定义的 `单态`）。判据：借来的类型名也要在定义侧落地。
                          'monostate' = '单态'
                          ;
                          '_Adjacent_find_fn' = '_相邻查找函数对象';
