    # 目标阶段(2)：本头是【定义方】，它的名字一旦留在英文，就会把同名两份摆进同一个
    #   `标准::细节`（我们那份 + `使用 名域 std;` 拉进来的原件），别的拷贝一调用就
    #   『对 X 的调用有歧义』（§17.27.52 实测：链表:1794 `_Pass_fn`）。
    #   判据：**凡本头在名域作用域有定义、且其它产品无限定调用的自由函数，一律改名**
    #   （下表即按此判据从原件正则扫出，见 §17.27.52；成员名不受影响：成员查找只看类作用域）。
    copyFixes = @( @('extern "C++" [[noreturn]] _CRTIMP2_PURE void __CLRCALL_PURE_OR_CDECL _Xlength_error(_In_z_ const char*);', ''), @('extern "C++" [[noreturn]] _CRTIMP2_PURE void __CLRCALL_PURE_OR_CDECL _Xout_of_range(_In_z_ const char*);', '') )
    members = [ordered]@{
      '_Strategy' = '_策略';
      '_Result' = '_结果';
      '_Sentinel' = '_哨兵';
      '_Size_type' = '_尺寸类型';
      '_Min' = '_最小';
      '_Traits' = '_特征';
      '_Ty' = '_类型';
      '_Unchecked_begin' = '_非检查开始';
      '_Prevent_inheriting_unwrap' = '_阻止继承解包';
      '_Unchecked_end' = '_非检查结束';
      '_Max' = '_最大';
      '_Last' = '_最后';
      '_First' = '_首个';
      '_Elem' = '_元素';
      '_Dest' = '_目标';
      '_Copy_fn' = '_复制函数指针';
      '_Comp' = '_比较器';
      '_Alloc' = '_分配器';
      '_Uty' = '_结果类型';
      '_As_const_pointer' = '_作为常量指针'
      '_Equal_rev_pred' = '_相等反转谓词'
      '_Find_if_unchecked' = '_查找若非检查'
      '_Find_last_iterator' = '_查找最后迭代器'
      '_Idl_distance' = '_IDL距离'
      '_Max_element_unchecked' = '_最大元素非检查'
      '_Min_element_unchecked' = '_最小元素非检查'
      '_Mismatch_4' = '_不匹配4'
      '_Mismatch_n' = '_不匹配计数'
      '_Possibly_const_range' = '_可能常量范围'
      '_Rewrap_iterator' = '_重包装迭代器'
      '_Ubegin' = '_解包首'
      '_Uend' = '_解包尾'
      '_Pass_fn'                     = '_传递函数'
      '_Copy_memmove_n'              = '_内存复制移动计数'
      '_Copy_n_unchecked4'           = '_复制N个非检查4'
      '_Copy_unchecked'              = '_复制非检查'
      '_To_unsigned_like'            = '_转为无符号同型'
      '_Next_iter'                   = '_下一迭代器'
      '_Prev_iter'                   = '_上一迭代器'
      '_Move_backward_unchecked'     = '_向后移动非检查'
      '_Get_final_iterator_unwrapped'= '_取末尾迭代器解包'
      '_Find_unchecked'              = '_查找非检查'
      '_Find_vectorized'             = '_查找向量化'
      '_Find_last_vectorized'        = '_查找末个向量化'
      '_Find_end_vectorized'         = '_查找末段向量化'
      '_Search_vectorized'           = '_搜索向量化'
      '_Check_match_counts'          = '_检查匹配计数'
      '_Fill_zero_memset'            = '_填充零内存'
      '_Seek_wrapped'                = '_定位包装'
      '_Is_all_bits_zero'            = '_是否全位为零'
    ;
      '_DEBUG_ORDER_UNWRAPPED' = '_DEBUG_ORDER_解包';   # §16.24 宏名必须一起汉化（宏不受名域约束）
;
      '_Base' = '_基';

      '_CDiff' = '_常量差类型';

      '_Common' = '_公共';

      '_Ref' = '_引用标记';

      '_Type' = '_类型参数';

      'rbegin' = '反向开始';

      '_Verify_offset' = '_校验偏移';

      'rend' = '反向结束';
}
    data    = [ordered]@{}
    derive  = @()
    stdHash = $false
    tparam  = @{ decl = ''; args = '' }
    tests = @(
      @('只引中文头','#包含 <通用内部件>`n整数 主函数(){ 返回 0; }'),
      @('内部自由函数真实可用','#包含 <通用内部件>`n整数 主函数(){ 整数 甲 = 0; 标准::细节::_取解包(甲); 返回 0; }'),
      # §17.27.52 机器守卫：定义方改名后，`_传递函数` 必须真的可用（原件那份是同名英文，
      #   若表里没改名，这里会因『两份同名』而编不过）。取 `_Pass_fn` 作代表。
      @('定义方改名真的落地（代表：_Pass_fn）','#包含 <通用内部件>`n#包含 <functional>`n整数 主函数(){ std::less<整数> 丙; 常量 自动& 丁 = 标准::细节::_传递函数(丙); (空型)丁; 返回 0; }')
    )
  }
  'scoped_allocator' = @{
    zh      = '作用域分配器'
    realInclude = @('scoped_allocator')   # §16.29「乙」
    types   = [ordered]@{ 'scoped_allocator_adaptor' = '作用域分配器适配器实现'
                          # §16.38 第 ① 类（本头类内别名）
                          '_Myadaptor'     = '_我的适配器'
                          '_Outer_alloc'   = '_外层分配器'
                          '_Outer_traits'  = '_外层特征'
                          '_Other_alloc'   = '_另一分配器'
                          '_Scoped_base' = '_作用域基类'
                          '_Scoped_outermost' = '_作用域最外层'
                          '_Scoped_outermost_helper' = '_作用域最外层助手'
                          # §16.27：自有内部件也要翻（长名，二义风险为零）
                          '_Scoped_outermost_t'       = '_作用域最外层类型'
                          '_Scoped_outermost_traits'  = '_作用域最外层特征'
                          '_Secret_scoped_allocator_construct_tag' = '_作用域构造内部标号' ;
                          'inner_allocator_type' = '内层分配器类型';
                          'outer_allocator_type' = '外层分配器类型';
}
    # ⚠ 不翻 allocator_traits / rebind / enable_if_t 等 std 的名字
    members = [ordered]@{ 'inner_allocator' = '内层分配器'
      '_Get_rebind_type' = '_取重绑定类型';
      '_Alloc' = '_分配器';

      '_Ty' = '_类型';
                          'outer_allocator' = '外层分配器'
                          'select_on_container_copy_construction' = '复制时选择'
                          'construct' = '构造'; 'destroy' = '析构'
                          'max_size' = '最大尺寸'
                          'allocate' = '分配'; 'deallocate' = '释放'
                          # §16.75 本头**自己定义**的内部助手（`_Get_inner_object`）
                          #   —— 不是公开 API，翻它不需要派生层补英文。
                          '_Get_inner_object' = '_取内层对象' }
    data    = [ordered]@{}
    derive  = @(@('inner_allocator','内层分配器'), @('outer_allocator','外层分配器'),
                 @('select_on_container_copy_construction','复制时选择'),
                 @('construct','构造'), @('destroy','析构'),
                 @('max_size','最大尺寸'), @('allocate','分配'), @('deallocate','释放') )
    stdHash = $false
    tparam  = @{ decl = '模板 <类型名 外层, 类型名... 内层>'; args = '<外层, 内层...>' }
    tests = @(
      @('只引中文头','#包含 <作用域分配器>`n整数 主函数(){ 标准::作用域分配器<std::allocator<int>> 甲; 常量 自动& 内 = 甲.内层分配器(); (空型)内; 返回 0; }'),
      @('与微软原头并存','#包含 <作用域分配器>`n#包含 <scoped_allocator>`n整数 主函数(){ 标准::作用域分配器<std::allocator<int>> 甲; std::scoped_allocator_adaptor<std::allocator<int>> 乙; 返回 (整数)(甲.外层分配器() == 乙.outer_allocator()) - 1; }'),
      @('英文名与中文名并用','#包含 <作用域分配器>`n整数 主函数(){ 标准::作用域分配器<std::allocator<int>> 甲; 常量 自动& 内 = 甲.内层分配器(); 常量 自动& 内2 = 甲.inner_allocator(); (空型)内; (空型)内2; 返回 0; }')
    )
  }
  'stack' = @{
    zh      = '栈'
    realInclude = @('stack')   # §16.29「乙」
    types   = [ordered]@{ 'stack' = '栈实现'
                          '_Adaptor_formatter_base' = '_适配器格式化基类'
                          # §16.41 第 ① 类：拷贝层 `using container_type = _Container;`
                          'container_type' = '容器类型' }
    deriveTypes = @( @('container_type','容器类型') )
    # ⚠ 不翻 uses_allocator / formatter —— 它们是 std 的模板，改名会断
    members = [ordered]@{ 'emplace' = '就地构造'; 'empty' = '为空'; 'pop' = '弹出'
      '_Alloc' = '_分配器';
      '_First' = '_首个';
      '_Last' = '_最后';
      '_Ty' = '_类型';
      '_Valty' = '_值参数类型';
                          'push' = '压入'; 'push_range' = '范围压入'
                          'top' = '栈顶'
                          # §16.73 本头**自己定义**的内部助手（`stack::_Get_container`）-> 翻。
                          #   ⚠ `<队列>` 里也有同名的一个，但它那一条【本轮不动】——
                          #     跨条目协调改名要两个条目同批，留到下一轮一起做。
                          '_Get_container' = '_取容器' }
                          # ⚠ swap 也不改名的理由同 <队列>（§3.12 + §16.30.3）
    data    = [ordered]@{}
    derive  = @( @('emplace','就地构造'), @('empty','为空'), @('pop','弹出'),
                 @('push','压入'), @('push_range','范围压入'),
                 @('top','栈顶') )
    deriveExtra = '    模板 <类型名... 参数> 声明类型(自动) 交换(参数&&... 值) { 返回 基类::swap(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 尺寸(参数&&... 值) 常量 { 返回 基类::size(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 为空(参数&&... 值) 常量 { 返回 基类::empty(static_cast<参数&&>(值)...); }'
    stdHash = $false
    tparam  = @{ decl = '模板 <类型名 元素, 类型名 容器 = std::deque<元素>>'; args = '<元素, 容器>' }
    # stack 的 uses_allocator 特化必须挂在【对外那个类型】上，
    # 所以要在 std 里为重发一份（抄来的那份挂在内层实现类型上，对外类型用不上）
    stdExtra = '模板 <类型名 元素, 类型名 容器, 类型名 分配器>
    结构 uses_allocator<标准::栈<元素, 容器>, 分配器> : std::uses_allocator<容器, 分配器>::type {};'
    tests = @(
      @('只引中文头','#包含 <栈>`n整数 主函数(){ 标准::栈<整数> 甲; 甲.压入(1); 返回 (整数)甲.尺寸() - 1; }'),
      @('与微软原头并存','#包含 <栈>`n#包含 <stack>`n整数 主函数(){ 标准::栈<整数> 甲; 甲.压入(1); std::stack<int> 乙; 乙.push(1); 返回 (整数)甲.尺寸() + (整数)乙.size() - 2; }'),
      @('英文名与中文名并用 + 栈顶','#包含 <栈>`n整数 主函数(){ 标准::栈<整数> 甲; 甲.压入(2); 甲.push(3); 返回 甲.栈顶() + 甲.top() - 6; }'),
      # ⚠ §16.41 的守卫：`container_type` 翻了之后，派生层要把英文原名补回来。
      @('容器类型：汉英两种名字都在','#包含 <栈>`n整数 主函数(){ (空型)sizeof(标准::栈<整数>::容器类型); (空型)sizeof(标准::栈<整数>::container_type); 返回 0; }')
    )
  }
  'typeindex' = @{
    zh      = '类型索引'
    realInclude = @('typeindex')   # §16.29「乙」
    types   = [ordered]@{ 'type_index' = '类型索引实现' }
    # ⚠ hash_code / name 【不登记】（§16.30.3）：正文里 `_Target->hash_code()` /
    #   `_Target->name()` 调的是【借来的】std::type_info 的成员，改名会报
    #   "type_info 中没有名为 '哈希值' 的成员"。中文名在 deriveExtra 手写、调 基类::hash_code/name。
    members = [ordered]@{}
    data    = [ordered]@{ '_Tptr' = '_类型指针' }
    # 派生层要补回的英文名（英文 = 中文），用一模板转发，不需要签名
    derive  = @()
    deriveExtra = '    模板 <类型名... 参数> 声明类型(自动) 哈希值(参数&&... 值) 常量 { 返回 基类::hash_code(static_cast<参数&&>(值)...); }
    模板 <类型名... 参数> 声明类型(自动) 名称(参数&&... 值) 常量 { 返回 基类::name(static_cast<参数&&>(值)...); }'
    # 额外要在 std 里补的特化（派生类型也需要 std::hash）
    stdHash = $true
    tparam  = @{ decl = ''; args = '' }
    tests = @(
      @('只引中文头','#包含 <类型索引>`n整数 主函数(){ 标准::类型索引 甲(类型标识(整数)); 返回 0; }'),
      @('与微软原头并存','#包含 <类型索引>`n#包含 <typeindex>`n整数 主函数(){ 标准::类型索引 甲(类型标识(整数)); std::type_index 乙(类型标识(整数)); 返回 0; }'),
      @('英文名与中文名并用','#包含 <类型索引>`n整数 主函数(){ 标准::类型索引 甲(类型标识(整数)); 返回 (整数)甲.hash_code() * 0 + (整数)甲.哈希值() * 0 + (整数)甲.name()[0] * 0; }'),
      # ⚠ 守卫：哈希值 / 名称 现在是从 members 表里【移出】、改由 deriveExtra 手写的
      #   （因为正文里的 hash_code/name 是借来的 type_info 成员）。这条证明中文名没丢。
      @('哈希值 / 名称 的汉语名在（派生层手写）','#包含 <类型索引>`n整数 主函数(){ 标准::类型索引 甲(类型标识(整数)); 返回 (整数)(甲.哈希值() * 0 + 甲.名称()[0] * 0); }')
    )
  }
