      '_One_then_variadic_args_t' = '_先一后变参实参';
      '_Get_first' = '_取第一';
      '_Compressed_pair' = '_压缩对'; 'arrive' = '到达'; 'arrive_and_drop' = '到达并退出'
                          'arrive_and_wait' = '到达并等待'; 'wait' = '等待' }
    zhIncludes = @{ 'xmemory' = '内存内部件' }
