  'semaphore' = @{
    zh      = '信号量'
    realInclude = @('semaphore')   # §16.29「乙」
    types   = [ordered]@{ 'counting_semaphore' = '计数信号量实现'
                          '_Semaphore_max' = '_信号量最大值'
                          }
    members = [ordered]@{
      '_Rep' = '_表示'; 'acquire' = '获取'; 'try_acquire' = '尝试获取'
                          'try_acquire_for' = '尝试限时获取'
                          'try_acquire_until' = '尝试获取至时刻'
                          'release' = '释放'; 'max' = '最大' }
    data    = [ordered]@{}
    derive  = @( @('acquire','获取'), @('try_acquire','尝试获取'),
                 @('try_acquire_for','尝试限时获取'),
                 @('try_acquire_until','尝试获取至时刻'),
                 @('release','释放'), @('max','最大') )
    stdHash = $false
    # 非类型模板形参（ptrdiff_t）—— 形参名也要中文
    tparam  = @{ decl = '模板 <ptrdiff_t 最小最大值 = 细节::_信号量最大值>'; args = '<最小最大值>' }
    tests = @(
      @('只引中文头','#包含 <信号量>`n整数 主函数(){ 标准::信号量<2> 甲(0); 甲.释放(); 返回 0; }'),
      @('与微软原头并存','#包含 <信号量>`n#包含 <semaphore>`n整数 主函数(){ 标准::信号量<2> 甲(0); 甲.释放(); std::counting_semaphore<2> 乙(0); 乙.release(); 返回 0; }'),
      @('英文名与中文名并用','#包含 <信号量>`n整数 主函数(){ 标准::信号量<2> 甲(0); 甲.释放(); 甲.release(); 返回 0; }')
    )
  }
  'condition_variable' = @{
    zh      = '条件变量'
    realInclude = @('condition_variable')   # §16.29「乙」
    # §16.35.7 嵌套名翻转（第 ① 类）：`_Common_duration` 是
    # `decltype(_Abs_time - _Now)` 的私有别名（原文第 97 行），只在本类用 -> 已并入下面的 types 表。
    # ⚠ std::condition_variable（非 _any）其实定义在 <mutex> 里；这个头只有 _any
    pub     = '条件变量任意'
    types   = [ordered]@{ 'condition_variable_any' = '条件变量任意实现'
                          # 这个头里 `shared_ptr<mutex>` / `_Ptr->_Mymtx()` 必须落到
                          # 【我们自己那份 <互斥量>】的家族里，否则碰到 std 的私有成员
                          # （微软只对真实的 std::condition_variable_any 开友元，见步 0）
                          'mutex'                = '互斥量实现'
                          'condition_variable'   = '条件变量实现'
                          # lock_guard / unique_lock 也定义在 <mutex> 里（就是现在我们包含的那份）
                          'lock_guard'           = '锁守卫实现'
                          'unique_lock'          = '独占锁实现'
                          '_Unlock_guard' = '_解锁卫兵'
                          '_Cv_any_notify_all' = '_条件变量任意通知全部'
                          '_Common_duration' = '_公共时长' }
    # 已经抄完的头才开这个开关（见步 0 的长注释）
    zhIncludes = @{ 'mutex' = '互斥量' }
    members = [ordered]@{
      '_Rep' = '_表示';
      '_Myptr' = '_我的指针'; 'notify_all' = '通知全部'; 'notify_one' = '通知一个'
      '_Mymtx' = '_我的互斥量'; '_Register' = '_注册'; '_Lock' = '_加锁'
                          'wait' = '等待'; 'wait_for' = '限时等待'
                          'wait_until' = '等待至时刻'
                          # 跨头成员名：这两个是 <互斥量> 里定下的译名，
                          # 本文件对 独占锁实现 调 .unlock() 必须跟着叫「解锁」，
                          # 否则 error: '独占锁实现<互斥量实现>' 中没有名为 'unlock' 的成员。
                          # ⚠ 这就是方案 §3.6.1 说的"译名必须全库共享"——
                          #   现在还是按头抄一遍，最终要提成一张全局表。
                          'lock' = '加锁'; 'unlock' = '解锁'; }
    data    = [ordered]@{}
    derive  = @( @('notify_all','通知全部'), @('notify_one','通知一个'),
                 @('wait','等待'), @('wait_for','限时等待'),
                 @('wait_until','等待至时刻') )
    stdHash = $false
    tparam  = @{ decl = ''; args = '' }
    tests = @(
      @('只引中文头','#包含 <条件变量>`n整数 主函数(){ 标准::条件变量任意 甲; 甲.通知全部(); 返回 0; }'),
      @('与微软原头并存','#包含 <条件变量>`n#包含 <condition_variable>`n整数 主函数(){ 标准::条件变量任意 甲; 甲.通知全部(); std::condition_variable_any 乙; 乙.notify_all(); 返回 0; }'),
      @('英文名与中文名并用','#包含 <条件变量>`n整数 主函数(){ 标准::条件变量任意 甲; 甲.通知一个(); 甲.notify_one(); 返回 0; }'),
      # 方案 §3.6：<mutex> 里 `friend condition_variable_any;` 与本头的类必须成对改名。
      # 两个头一起引，才能证明友元真的对上了（<互斥量> 里的 条件变量任意实现 是同一个类）。
      @('与互斥量并存（friend 成对）','#包含 <互斥量>`n#包含 <条件变量>`n整数 主函数(){ 标准::互斥量 甲; 标准::条件变量任意 乙; 标准::独占锁<标准::互斥量> 锁(甲); 乙.通知全部(); 布尔 有 = 锁.持有锁(); 返回 有 ? 0 : 1; }')
    )
  }
  'latch' = @{
    zh      = '门闩'
    realInclude = @('latch')   # §16.29「乙」
    types   = [ordered]@{ 'latch' = '门闩实现' }
    members = [ordered]@{ 'count_down' = '递减'; 'try_wait' = '尝试等待'
                          'arrive_and_wait' = '到达并等待' }
                          # ⚠ wait 【不登记】（§16.30.3 的样板）：正文里 `_My_cond.wait(...)`
                          #   调的是【借来的】std::condition_variable 的成员，改名会报
                          #   "condition_variable 中没有名为 '等待' 的成员"。
                          #   中文名 等待 在 deriveExtra 里手写、调 基类::wait ——
                          #   与 <队列>/<栈> 的 swap 同一手法（不依赖"改了再回退"）。
    data    = [ordered]@{}
    derive  = @( @('count_down','递减'), @('try_wait','尝试等待'),
                 @('arrive_and_wait','到达并等待') )
    deriveExtra = '    模板 <类型名... 参数> 声明类型(自动) 等待(参数&&... 值) 常量 { 返回 基类::wait(static_cast<参数&&>(值)...); }'
    stdHash = $false
    tparam  = @{ decl = ''; args = '' }
    tests = @(
      @('只引中文头','#包含 <门闩>`n整数 主函数(){ 标准::门闩 甲(1); 甲.递减(); 返回 0; }'),
      @('与微软原头并存','#包含 <门闩>`n#包含 <latch>`n整数 主函数(){ 标准::门闩 甲(1); 甲.递减(); std::latch 乙(1); 乙.count_down(); 返回 0; }'),
      @('英文名与中文名并用','#包含 <门闩>`n整数 主函数(){ 标准::门闩 甲(2); 甲.递减(); 甲.count_down(); 返回 0; }'),
      # ⚠ 守卫：`等待` 的中文名是【deriveExtra 手写】的（因为正文里的 `wait` 是借来的
      #   condition_variable 成员，不能登记改名）。这条测试证明手写的那条真的存在 ——
      #   否则"改成不登记"就等于把中文名弄丢了。
      @('等待 / 尝试等待 的汉语名在（派生层手写，不靠回退）','#包含 <门闩>`n整数 主函数(){ 标准::门闩 甲(1); 甲.递减(); 甲.等待(); 布尔 好 = 甲.尝试等待(); 标准::门闩 乙(1); 乙.到达并等待(); 返回 好 ? 0 : 1; }')
    )
  }
  # ==========================================================================
  #  §17.19 丁类薄壳：<字符串>（shell = $true）
  #
  #  为什么需要这个形态：<string> 的全部内容已经在【字符串内部件】里了（步骤 1 抄好并验证过），
  #  本头【没有微软原头可抄】—— 它要做的只是"包含内部件 + 派生层"。
  #  所以 shell 条目跳过"读取/抄写/改名/校对"整条流水线，其余机制（守卫/派生层/测试）照用。
  #
  #  ⚠ 三条配套约定（§17.19 第 4 条「原头 = 内部件」）：
  #    shellHost     产物名 —— 宏扫描、三把尺、乙探针都拿【内部件产物】当"原头"；
  #    shellIncludes 要包含的内部件（有序，直接写进产物）；
  #    zhIncludes    同一批内部件（Get-ZhNameScope 靠它把内部件的改名表拉进译名域，
  #                  这样派生层"目标中文名必须存在"的守卫才真的守得住）。
  # ==========================================================================
  '字符串' = @{
    zh      = '字符串'
    shell   = $true
    shellHost     = '字符串内部件'
    shellGuard    = '_ZH_STRING_'
    shellIncludes = @('字符串视图', '字符串内部件')   # 镜像微软：xstring 包含 __msvc_string_view.hpp
    zhIncludes = [ordered]@{ 'xstring' = '字符串内部件'
                             '__msvc_string_view.hpp' = '字符串视图内部件'
                             'string_view' = '字符串视图' }
    realInclude = @('string')   # §16.29「乙」：与真 <string> 并存
    pub     = '基础字符串'
    # ⚠ 薄壳里 types 表的作用与普通条目【不同】：普通条目是"原类型名 -> 抄来那层的中文名"，
    #   薄壳只有一行 —— 值 = 内部件里的实现类名（派生层的 公开 基类），键 = 微软原名。
    types   = [ordered]@{ 'basic_string' = '基础字符串实现'
                          # ⚠ 公开别名也必须【登记】：译名唯一性守卫（§17.27.54）只看表，
                          #   不登记 = `标准::字符串` 这个公开名不受任何守卫约束。
                          'string'      = '字符串'
                          'wstring'     = '宽字符串' }
    # ⚠ members 【故意为空】：薄壳成员的中文名全部在内部件里，已由 xstring 条目逐条验证过
    #   （§17.19）；在这里重复登记等于抄两份表，必然漂移。
    members = [ordered]@{}
    tparam  = @{ decl = '模板 <类型名 元素, 类型名 特征 = std::char_traits<元素>, 类型名 分配器 = std::allocator<元素>>'
                 args = '<元素, 特征, 分配器>' }
    # §17.19.3：实现层里【按值返回实现类型】的成员（substr / operator+ / operator"" 家族）
    #   返回的是 细节::基础字符串实现<...>，派生类型没有"从实现类型转回来"的路 ->
    #   实测 标准::字符串 乙 = 甲.substr(0, 2); 报「没有可行的转换」= 英文用法回归。
    #   解法与视图同一条（§17.19.2）：转发构造模板，实参恒等绑定、转换发生在构造体内。
    deriveExtra = ( @(
      '    // §17.19.3 转发构造模板 —— 让 substr / operator+ 这类"按值返回实现类型"的结果能转回来。',
      '    模板 <类型名 源> 基础字符串(常量 源& 值) : 基类(值) {}'
    ) -join "`
`
" )
    # 英文原名 -> 内部件里已经翻好的中文名（守卫逐个核对"这个中文名真的存在"）
    derive  = @( @('size','尺寸'), @('capacity','容量'), @('empty','为空'), @('clear','清空'), @('begin','开始'),
                 @('end','结束'), @('cbegin','常量开始'), @('cend','常量结束'), @('rbegin','反向开始'), @('rend','反向结束'),
                 @('crbegin','常量反向开始'), @('crend','常量反向结束'), @('front','前'), @('back','后'), @('at','取值'),
                 @('data','数据'), @('c_str','C字符串'), @('push_back','尾插'), @('pop_back','尾删'),
                 @('append','追加'), @('insert','插入'), @('erase','擦除'), @('replace','替换'),
                 @('resize','调整尺寸'), @('reserve','预留'), @('shrink_to_fit','收缩至适应'),
                 @('append_range','追加范围'), @('assign_range','范围赋值'), @('insert_range','范围插入'),
                 @('replace_with_range','按范围替换'), @('substr','子串'), @('rfind','反向查找'),
                 @('find_first_of','查找首次属于'), @('find_last_of','查找末次属于'), @('find_first_not_of','查找首次不属于'),
                 @('find_last_not_of','查找末次不属于'), @('get_allocator','取分配器'), @('starts_with','开头为'),
                 @('ends_with','结尾为'), @('contains','包含') )
    extra   = ( @(
      '名域 标准 {',
      '',
      '使用 字符串   = 基础字符串<字符>;',
      '使用 宽字符串 = 基础字符串<宽字符>;',
      '',
      '// ⚠ 字符串视图/宽字符串视图 的别名【不在这里】—— 它们归 <字符串视图>（镜像微软：',
      '//   string_view 定义在 __msvc_string_view.hpp 里），本头包含 <字符串视图> 就拿到了。',
      '//   在这里再声明一次会撞：#别名声明 被重定义，类型不同（实现类型 vs 派生类型）。',
      '',
      '}  // 名域 标准'
    ) -join "`r`n" )
    tests = @(
      @('只引中文头','#包含 <字符串>`n整数 主函数(){ 标准::字符串 甲 = "你好"; 甲.追加("，世界"); 返回 (整数)甲.尺寸() > 0 ? 0 : 1; }'),
      @('与微软原头并存','#包含 <字符串>`n#包含 <string>`n整数 主函数(){ 标准::字符串 甲 = "甲"; std::string 乙 = "乙"; 返回 甲.size() == 乙.size() ? 0 : 1; }'),
      @('英文名与中文名并用','#包含 <字符串>`n整数 主函数(){ 标准::字符串 甲 = "ab"; 甲.append("c"); 甲.尾插(''d''); 返回 (整数)甲.size() == 4 ? 0 : 1; }'),
      @('宽字符串 / 字符串视图 别名都在','#包含 <字符串>`n整数 主函数(){ 标准::宽字符串 甲 = L"宽"; 标准::字符串视图 视 = "视图"; 返回 (整数)甲.尺寸() == 1 ? 0 : 1; }'),
      @('英文原名整批可用（40 条转发实测）','#包含 <字符串>`n整数 主函数(){ 标准::字符串 甲 = "abc"; 甲.reserve(64); 甲.push_back(''d'');`n  甲.resize(6, ''e''); 甲.insert(1, "XY"); 甲.replace(0, 1, "Z"); 甲.erase(0, 1);`n  标准::字符串 乙 = 甲.substr(0, 2); 整数 找 = (整数)甲.rfind("c");`n  (空型)甲.capacity(); (空型)甲.get_allocator(); (空型)甲.c_str(); (空型)甲.find_first_of("abc");`n  标准::字符串 丙 = 乙; 丙.pop_back();`n  返回 找 >= 0 && (整数)丙.尺寸() < (整数)乙.尺寸() ? 0 : 1; }'),
      @('与 std::string 互转（宗旨：派生层要与 std 原类型互转）','#包含 <字符串>`n#包含 <string>`n整数 主函数(){ 标准::字符串 甲 = "甲乙";`n  std::string 转(甲.开始(), 甲.结束()); 标准::字符串 回(转.begin(), 转.end());`n  返回 (整数)回.尺寸() == (整数)甲.尺寸() ? 0 : 1; }')
    )
  }
  # ==========================================================================
  #  §17.19 丁类薄壳：<字符串视图>（shell = $true）
  #
  #  ⚠ 归属镜像（照微软，不是照我们方便）：微软把 string_view/wstring_view 定义在
  #    <__msvc_string_view.hpp>，而 <xstring> 又包含它 —— 所以是
  #    <字符串> 包含 <字符串视图>，不是反过来。两个头同时引也不会重定义。
  #
  #  ⚠ 为什么必须有「转发构造模板」（实测，§17.19.2）：
  #    `标准::字符串视图 视 = 甲;`（甲 是 标准::字符串）在派生薄壳上会撞
  #    【两次用户定义转换】：① 基类的 operator 基础字符串视图() ② 派生类的转换构造。
  #    解法：把转换挪进构造函数【体内】——
  #        模板 <类型名 源> 基础字符串视图(常量 源& 值) : 基类(值) {}
  #    这样实参是恒等绑定（源 直接推导成 标准::字符串），只算一次转换。
  #    实测三种写法都成立：视 = 甲 / 视 = "abc" / 视(甲)。
  #
  #  ⚠ 视图实现的模板形参【特征没有默认值】（`template <class _Elem, class _Traits>`），
  #    所以公开薄壳必须自己补默认值，否则 `基础字符串视图<字符>` 这个名字都写不出来。
  # ==========================================================================
  '字符串视图' = @{
    zh      = '字符串视图'
    shell   = $true
    shellHost     = '字符串视图内部件'
    shellGuard    = '_ZH_STRING_VIEW_'
    shellIncludes = @('字符串视图内部件')
    zhIncludes = [ordered]@{ '__msvc_string_view.hpp' = '字符串视图内部件' }
    realInclude = @('string_view')   # §16.29「乙」
    pub     = '基础字符串视图'
    types   = [ordered]@{ 'basic_string_view' = '基础字符串视图'
                          'string_view'  = '字符串视图'
                          'wstring_view' = '宽字符串视图' }
    members = [ordered]@{}
    tparam  = @{ decl = '模板 <类型名 元素, 类型名 特征 = std::char_traits<元素>>'
                 args = '<元素, 特征>' }
    derive  = @( @('size','尺寸'), @('empty','为空'), @('begin','开始'), @('end','结束'), @('cbegin','常量开始'),
                 @('cend','常量结束'), @('rbegin','反向开始'), @('rend','反向结束'), @('crbegin','常量反向开始'),
                 @('crend','常量反向结束'), @('front','前'), @('back','后'), @('at','取值'), @('data','数据'),
                 @('substr','子串'), @('remove_prefix','去前缀'), @('remove_suffix','去后缀'),
                 @('starts_with','开头为'), @('ends_with','结尾为'), @('contains','包含') )
    deriveExtra = ( @(
      '    // §17.19.2：把「用户定义转换」挪进构造体内 —— 否则 `视 = 甲` 要两次转换，编不过。',
      '    模板 <类型名 源> 基础字符串视图(常量 源& 值) : 基类(值) {}'
    ) -join "`r`n" )
    extra   = ( @(
      '名域 标准 {',
      '',
      '使用 字符串视图   = 基础字符串视图<字符>;',
      '使用 宽字符串视图 = 基础字符串视图<宽字符>;',
      '',
      '}  // 名域 标准'
    ) -join "`r`n" )
    tests = @(
      @('只引中文头','#包含 <字符串视图>`n整数 主函数(){ 标准::字符串视图 视 = "你好"; 返回 (整数)视.尺寸() > 0 ? 0 : 1; }'),
      @('与微软原头并存','#包含 <字符串视图>`n#包含 <string_view>`n整数 主函数(){ 标准::字符串视图 甲 = "甲"; std::string_view 乙 = "乙"; 返回 甲.size() == 乙.size() ? 0 : 1; }'),
      @('英文原名与中文名并用','#包含 <字符串视图>`n整数 主函数(){ 标准::字符串视图 视 = "abc"; 返回 (整数)视.size() == 3 && (整数)视.尺寸() == 3 ? 0 : 1; }'),
      @('从 标准::字符串 隐式转换（§17.19.2）','#包含 <字符串>`n整数 主函数(){ 标准::字符串 甲 = "甲乙"; 标准::字符串视图 视 = 甲; 标准::字符串视图 视2(甲); 返回 (整数)视.尺寸() == 6 && (整数)视2.尺寸() == 6 ? 0 : 1; }'),
      @('英文原名整批可用（20 条转发实测）','#包含 <字符串视图>`n整数 主函数(){ 标准::字符串视图 视 = "abcde"; 视.remove_prefix(1); 视.remove_suffix(1);`n  布尔 头 = 视.starts_with("bc"); 布尔 尾 = 视.ends_with("cd");`n  字符 前 = 视.front(); 字符 后 = 视.back(); 字符 取 = 视.at(0);`n  (空型)视.crbegin(); (空型)视.rend(); 标准::字符串视图 子 = 视.substr(0, 1);`n  返回 头 && 尾 && 前 == ''b'' && 后 == ''d'' && 取 == ''b'' && (整数)子.尺寸() == 1 ? 0 : 1; }'),
      @('与 std::string_view 互转','#包含 <字符串视图>`n#包含 <string_view>`n整数 主函数(){ 标准::字符串视图 视 = "甲乙";`n  std::string_view 转(视.数据(), 视.尺寸()); 标准::字符串视图 回(转.data(), 转.size());`n  返回 (整数)回.尺寸() == (整数)视.尺寸() ? 0 : 1; }')
    )
  }
  # ==========================================================================
  #  阶段(4) 第一个「真汉语实现」的公开头：<源码位置>（std::source_location）
  #
  #  为什么挑它先做（Step 3 起步，证据来自"借用链"统计）：
  #    它是候选公开头里唯一【零未汉化依赖】的小头（74 行，只 include <yvals_core.h> 与 <cstdint>，
  #    两个都已在甲类别名轨道做完），所以不欠任何借用链，能做干净。
  #
  #  ⚠ §17.19.5 【默认实参的调用点语义不能被转发吞掉】
  #    `current()` 的默认实参是 __builtin_LINE()/__builtin_COLUMN()/__builtin_FILE()/__builtin_FUNCSIG()。
  #    若用派生层的通用模板转发（`模板 <类型名... 参数> current(参数&&...)`），默认实参就在【本头】里
  #    求值 -> 报出来的是头文件的位置，语义直接错。所以这一条在 deriveExtra 里手写，
  #    并把默认实参原样带上（#if 也照抄，否则 _USE_DETAILED_FUNCTION_NAME_IN_SOURCE_LOCATION=0
  #    时中文名与英文名两边不一致）。守卫 = tests 里那条"行号必须等于 3"的锐利测试。
  # ==========================================================================
  'source_location' = @{
    zh      = '源码位置'
    realInclude = @('source_location')   # §16.29「乙」：与真 <source_location> 并存
    types   = [ordered]@{ 'source_location' = '源码位置' }
    members = [ordered]@{ 'current' = '当前'; 'line' = '行号'; 'column' = '列号'
                          'file_name' = '文件名'; 'function_name' = '函数名' }
    data    = [ordered]@{ '_Line' = '_行号'; '_Column' = '_列号'
                          '_File' = '_文件'; '_Function' = '_函数'
                          # 形参与局部量也一并汉化（本头很小，能一次做干净）
                          '_Line_' = '_行号_'; '_Column_' = '_列号_'
                          '_File_' = '_文件_'; '_Function_' = '_函数_'
                          '_Result' = '_结果' }
    derive  = @( @('line','行号'), @('column','列号'),
                 @('file_name','文件名'), @('function_name','函数名') )
    deriveExtra = ( @(
      '    // §17.19.3 通用规则（本条目也踩到了）：实现层按值返回【实现类型】，派生类型必须有一条',
      '    //   转发构造 —— 否则 返回 基类::当前(...) 报"没有可行的转换"。',
      '    模板 <类型名 源> constexpr 源码位置(常量 源& 值) : 基类(值) {}',
      '',
      '    // §17.19.5：默认实参必须在【调用点】求值 —— 通用模板转发会把它们在本头里求值。',
      '    静态 立即求值 源码位置 current(const uint_least32_t _行号_ = __builtin_LINE(),',
      '        const uint_least32_t _列号_ = __builtin_COLUMN(), const char* const _文件_ = __builtin_FILE(),',
      '#if _USE_DETAILED_FUNCTION_NAME_IN_SOURCE_LOCATION',
      '        const char* const _函数_ = __builtin_FUNCSIG()) 不抛出 {',
      '#else // ^^^ detailed / basic vvv',
      '        const char* const _函数_ = __builtin_FUNCTION()) 不抛出 {',
      '#endif // ^^^ basic ^^^',
      '        返回 基类::当前(_行号_, _列号_, _文件_, _函数_);',
      '    }'
    ) -join "`r`n" )
    stdHash = $false
    tparam  = @{ decl = ''; args = '' }
    tests = @(
      @('只引中文头','#包含 <源码位置>`n整数 主函数(){ 标准::源码位置 甲 = 标准::源码位置::当前(); 返回 甲.行号() > 0 ? 0 : 1; }'),
      @('与微软原头并存','#包含 <源码位置>`n#包含 <source_location>`n整数 主函数(){ 标准::源码位置 甲 = 标准::源码位置::当前(); std::source_location 乙 = std::source_location::current(); 返回 甲.行号() == 乙.line() ? 0 : 1; }'),
      @('英文原名与中文名并用','#包含 <源码位置>`n整数 主函数(){ 标准::源码位置 甲 = 标准::源码位置::current(); 返回 (整数)甲.line() > 0 && (整数)甲.行号() > 0 ? 0 : 1; }'),
      @('★守卫 §17.19.5：current() 必须报【调用点】的行号，不能被转发吞成头里的行号','#包含 <源码位置>`n整数 主函数(){`n    标准::源码位置 甲 = 标准::源码位置::当前();`n    返回 甲.行号() == 3 ? 0 : 1;`n}')
    )
  }
  # ==========================================================================
  #  阶段(4) 第二个真汉语公开头：<数值算法>（std::numeric）
  #
  #  形状是【纯自由函数头】—— 没有对外类，所以派生层那套（`类型 X : 公开 细节::Y`）不适用。
  #  这里的做法：`noPub = $true`（不生成类派生层），公开层在 extra 里手写，
  #  而且是【双名转发】：中文名与英文原名各一份（同一份 细节:: 实现）——
  #    中文在前：`标准::累加(...)`；英文在后（在中文基础上派生）：`标准::accumulate(...)`。
  #  ⚠ 这只是 14 个名字 x 2 = 28 行，因为转发器是【变参模板】（一个名字一行，不必逐个重载）。
  #  ⚠ 转发器一律带 constexpr：`gcd/lcm/midpoint/iota` 等在 std 里是常量表达式可用的，
  #    去掉 constexpr 就是英文用法回归（tests 里有 static_assert 守卫）。
  #
  #  借用链：只 include <xutility>（-> 我们的 通用内部件）与 <__msvc_bit_utils.hpp>
  #    （后者是宏/内联助手，别的产品也照原样引真头，见 <向量>）。
  # ==========================================================================
  'numeric' = @{
    zh      = '数值算法'
    realInclude = @('numeric')   # §16.29「乙」：与真 <numeric> 并存
    noPub   = $true
    zhIncludes = @{ 'xutility' = '通用内部件' }
    types   = [ordered]@{}
    members = [ordered]@{
      '_Adl_verify_range' = '_ADL校验范围'
      '_Dest' = '_目标'
      '_First' = '_首个'
      '_Get_unwrapped' = '_取解包'
      '_Idl_distance' = '_IDL距离'
      '_Last' = '_最后'
      '_Pass_fn' = '_传递函数'
      '_Result' = '_结果'
      '_Seek_wrapped' = '_定位包装'
      '_To_address' = '_取地址'
      '_Ty' = '_类型';
      '_Uend' = '_解包尾'
      'accumulate' = '累加'; 'reduce' = '归约'
      'inner_product' = '内积'; 'transform_reduce' = '变换归约'
      'partial_sum' = '部分和'
      'exclusive_scan' = '排他扫描'; 'inclusive_scan' = '包含扫描'
      'transform_exclusive_scan' = '变换排他扫描'
      'transform_inclusive_scan' = '变换包含扫描'
      'adjacent_difference' = '相邻差'
      'iota' = '递增填充'
      'gcd' = '最大公约数'; 'lcm' = '最小公倍数'
      'midpoint' = '中点'
      # 内部件（C++23 那段 ranges::iota 也在表里，-std=c++20 下不生效，照登记）
      '_Iota_fn' = '_递增填充函数'; '_Iota_impl' = '_递增填充实现'
      'iota_result' = '递增填充结果'
    ;
      '_Common' = '_公共';

      '_Unsigned' = '_无符号类型';
}
    data    = [ordered]@{}
    # 纯自由函数头：没有类派生层，derive 显式为【空】（公开层在 extra 里手写双名转发）
    derive  = @()
    tparam  = @{ decl = ''; args = '' }
    extra   = ( @(
      '// ============================================================================',
      '//  公开层：中文名 + 英文原名，双名转发到同一份 细节:: 实现',
      '// ============================================================================',
      '名域 标准 {',
      '',
      '// ---- 中文名（汉语优先）----',
      '模板 <类型名... 参数> constexpr 声明类型(自动) 累加(参数&&... 值) { 返回 细节::累加(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) 归约(参数&&... 值) { 返回 细节::归约(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) 内积(参数&&... 值) { 返回 细节::内积(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) 变换归约(参数&&... 值) { 返回 细节::变换归约(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) 部分和(参数&&... 值) { 返回 细节::部分和(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) 排他扫描(参数&&... 值) { 返回 细节::排他扫描(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) 包含扫描(参数&&... 值) { 返回 细节::包含扫描(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) 变换排他扫描(参数&&... 值) { 返回 细节::变换排他扫描(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) 变换包含扫描(参数&&... 值) { 返回 细节::变换包含扫描(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) 相邻差(参数&&... 值) { 返回 细节::相邻差(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) 递增填充(参数&&... 值) { 返回 细节::递增填充(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) 最大公约数(参数&&... 值) { 返回 细节::最大公约数(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) 最小公倍数(参数&&... 值) { 返回 细节::最小公倍数(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) 中点(参数&&... 值) { 返回 细节::中点(static_cast<参数&&>(值)...); }',
      '',
      '// ---- 英文原名（在【中文的基础上】派生：同一份实现，两个名字）----',
      '模板 <类型名... 参数> constexpr 声明类型(自动) accumulate(参数&&... 值) { 返回 细节::累加(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) reduce(参数&&... 值) { 返回 细节::归约(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) inner_product(参数&&... 值) { 返回 细节::内积(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) transform_reduce(参数&&... 值) { 返回 细节::变换归约(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) partial_sum(参数&&... 值) { 返回 细节::部分和(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) exclusive_scan(参数&&... 值) { 返回 细节::排他扫描(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) inclusive_scan(参数&&... 值) { 返回 细节::包含扫描(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) transform_exclusive_scan(参数&&... 值) { 返回 细节::变换排他扫描(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) transform_inclusive_scan(参数&&... 值) { 返回 细节::变换包含扫描(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) adjacent_difference(参数&&... 值) { 返回 细节::相邻差(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) iota(参数&&... 值) { 返回 细节::递增填充(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) gcd(参数&&... 值) { 返回 细节::最大公约数(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) lcm(参数&&... 值) { 返回 细节::最小公倍数(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> constexpr 声明类型(自动) midpoint(参数&&... 值) { 返回 细节::中点(static_cast<参数&&>(值)...); }',
      '',
      '}  // 名域 标准'
    ) -join "`r`n" )
    tests = @(
      @('只引中文头','#包含 <数值算法>`n整数 主函数(){ 整数 甲[3] = {1, 2, 3}; 返回 标准::累加(甲, 甲 + 3, 0) == 6 ? 0 : 1; }'),
      @('与微软原头并存','#包含 <数值算法>`n#包含 <numeric>`n整数 主函数(){ 整数 甲[3] = {1, 2, 3};`n  返回 标准::累加(甲, 甲 + 3, 0) == std::accumulate(甲, 甲 + 3, 0) ? 0 : 1; }'),
      @('英文原名与中文名并用','#包含 <数值算法>`n整数 主函数(){ 整数 甲[3] = {1, 2, 3};`n  返回 标准::accumulate(甲, 甲 + 3, 0) == 标准::累加(甲, 甲 + 3, 0) ? 0 : 1; }'),
      @('★守卫：常量表达式可用（constexpr 不能被转发吞掉）','#包含 <数值算法>`nstatic_assert(标准::最大公约数(12, 18) == 6);`nstatic_assert(标准::最小公倍数(4, 6) == 12);`nstatic_assert(标准::中点(1, 3) == 2);`nstatic_assert(标准::gcd(12, 18) == 6);`n整数 主函数(){ 整数 甲[4] = {0, 0, 0, 0}; 标准::递增填充(甲, 甲 + 4, 10); 返回 甲[0] == 10 && 甲[3] == 13 ? 0 : 1; }'),
      @('★守卫：部分和 / 排他扫描 / 内积 的值正确','#包含 <数值算法>`n整数 主函数(){ 整数 甲[4] = {1, 2, 3, 4}; 整数 乙[4] = {0, 0, 0, 0};`n  标准::部分和(甲, 甲 + 4, 乙);`n  如果 (乙[0] != 1 || 乙[3] != 10) { 返回 1; }`n  标准::排他扫描(甲, 甲 + 4, 乙, 0);`n  如果 (乙[3] != 6) { 返回 2; }`n  返回 标准::内积(甲, 甲 + 4, 乙, 0) == 35 ? 0 : 3; }')
    )
  }
  # ==========================================================================
  #  阶段(4) 第三个真汉语公开头：<数值数组>（std::valarray）
  #
  #  挑它的判据（沿用 §17.19.5 的"借用链"统计）：2128 行、只欠 <xmemory>（已是我们自己的
  #    `内存内部件`），<cmath> 在甲类 C 包装轨道上已完成 -> 借用链可接通。
  #
  #  形状：**多对外类**。主类由机制生成派生层（`数值数组` -> `细节::数值数组实现`），
  #    其余 6 个辅助类（切片/通用切片/切片数组/通用切片数组/掩码数组/间接数组）在 extra 里
  #    以**别名**公开（它们只是描述符/代理，身份不参与语义；英文用法照旧走 std —— 与 <互斥量>
  #    的多类写法同一手法，但这里不需要补英文转发，故用别名更省且不会引入半成品）。
  #
  #  ⚠ §17.19.3：`shift` / `cshift` / `apply` / `operator+` 等都**按值返回实现类型**，
  #    所以派生类必须带转发构造，否则 `标准::数值数组<整数> 乙 = 甲.shift(1);` 报"没有可行的转换"。
  # ==========================================================================
  'valarray' = @{
    zh      = '数值数组'
    realInclude = @('valarray')   # §16.29「乙」：与真 <valarray> 并存
    zhIncludes = @{ 'xmemory' = '内存内部件' }
    pub     = '数值数组'
    types   = [ordered]@{ 'valarray' = '数值数组实现'
                          'slice' = '切片'; 'gslice' = '通用切片'
                          'slice_array' = '切片数组'; 'gslice_array' = '通用切片数组'
                          'mask_array' = '掩码数组'; 'indirect_array' = '间接数组'
                          '_Sizarray' = '_尺寸数组' }
    # §17.27.58 边界（铁律③）：std::initializer_list 永远是 std 那一个，它的成员保持英文。
    #   这个名字潜伏到链名族测试写 甲{1,2,3} 才炸（与 <字符串> / <内存内部件> 同型）。
    copyFixes = @( @('_Ilist.尺寸()', '_Ilist.size()'), @('_Ilist.开始()', '_Ilist.begin()') )
    members = [ordered]@{ 'size' = '尺寸'; 'sum' = '求和'; 'min' = '最小'; 'max' = '最大'
      '_Construct_in_place' = '_就地构造'
      '_Destroy_range' = '_析构范围'
      '_Inc' = '_递增'
      '_Max' = '_最大'
      '_Min' = '_最小'
      '_Tidy_deallocate_guard' = '_清理释放守卫'
      '_Ty' = '_类型';
                          'shift' = '移位'; 'cshift' = '循环移位'; 'apply' = '应用'
                          'resize' = '调整尺寸'; 'begin' = '开始'; 'end' = '结束'
                          'start' = '起始'; 'stride' = '步长'
                          '_Tidy_deallocate' = '_清理释放'
                          '_Assign' = '_赋值'; '_Grow' = '_增长' ;
      '_Mask' = '_掩码';
}
    data    = [ordered]@{ '_Myptr' = '_我的指针'; '_Mysize' = '_我的尺寸' }
    derive  = @( @('size','尺寸'), @('sum','求和'), @('min','最小'), @('max','最大'),
                 @('shift','移位'), @('cshift','循环移位'), @('apply','应用'),
                 @('resize','调整尺寸'), @('begin','开始'), @('end','结束') )
    deriveExtra = ( @(
      '    // §17.19.3：shift / cshift / apply / operator+ 按值返回【实现类型】，必须有转发构造。',
      '    模板 <类型名 源> 数值数组(常量 源& 值) : 基类(值) {}'
    ) -join "`r`n" )
    extra   = ( @(
      '名域 标准 {',
      '',
      '// 辅助类：描述符 / 代理，身份不参与语义 -> 用别名公开（英文用法照旧走 std）。',
      '使用 切片         = 细节::切片;',
      '使用 通用切片     = 细节::通用切片;',
      '模板 <类型名 元素> 使用 切片数组     = 细节::切片数组<元素>;',
      '模板 <类型名 元素> 使用 通用切片数组 = 细节::通用切片数组<元素>;',
      '模板 <类型名 元素> 使用 掩码数组     = 细节::掩码数组<元素>;',
      '模板 <类型名 元素> 使用 间接数组     = 细节::间接数组<元素>;',
      '',
      '}  // 名域 标准'
    ) -join "`r`n" )
    tparam  = @{ decl = '模板 <类型名 元素>'; args = '<元素>' }
    tests = @(
      @('只引中文头','#包含 <数值数组>`n整数 主函数(){ 标准::数值数组<整数> 甲 = {1, 2, 3}; 返回 甲.求和() == 6 ? 0 : 1; }'),
      @('与微软原头并存','#包含 <数值数组>`n#包含 <valarray>`n整数 主函数(){ 标准::数值数组<整数> 甲 = {1, 2, 3}; std::valarray<整数> 乙 = {1, 2, 3}; 返回 甲.求和() == 乙.sum() ? 0 : 1; }'),
      @('英文原名与中文名并用','#包含 <数值数组>`n整数 主函数(){ 标准::数值数组<整数> 甲 = {1, 2, 3}; 返回 甲.size() == 甲.尺寸() && 甲.sum() == 甲.求和() ? 0 : 1; }'),
      @('★守卫 §17.19.3：按值返回实现类型的成员（shift / apply）要能转回派生类型','#包含 <数值数组>`n整数 主函数(){ 标准::数值数组<整数> 甲 = {1, 2, 3};`n  标准::数值数组<整数> 乙 = 甲.shift(1);`n  标准::数值数组<整数> 丙 = 甲.apply([](整数 值) { 返回 值 * 2; });`n  返回 (整数)乙.尺寸() == 3 && (整数)丙.尺寸() == 3 && 丙.求和() == 12 ? 0 : 1; }'),
      @('切片 / 掩码数组 的汉语名可用（辅助类别名）','#包含 <数值数组>`n整数 主函数(){ 标准::数值数组<整数> 甲 = {1, 2, 3, 4}; 标准::切片 切(0, 2, 2);`n  标准::数值数组<整数> 乙 = 甲[切];`n  返回 乙.求和() == 4 ? 0 : 1; }')
    )
  }
  # ==========================================================================
  #  阶段(4) 第四个真汉语公开头：<数值极限>（std::numeric_limits）
  #
  #  挑它的判据（沿用 §17.19.5 借用链统计，且**这次把 .h 内部件也算进去**）：
  #    1007 行、零未汉化【公开头】依赖（只引 cfloat/climits/cwchar 这些 C 包装头 +
  #    内部件 xtr1common / _STL_INTRIN_HEADER，照别的产品做法引真头即可），且是 C++11 就活跃的头。
  #  ⚠ 与 <数值数组> 不同：这里没有自由函数，所以**不需要** extra 的双名转发。
  #
  #  ⚠ 变量成员与函数成员要分开处理（本轮设计判据）：
  #    · `min()` / `max()` 这类是**静态 constexpr 函数** -> 走 derive 的通用转发（带括号，语义一致）；
  #    · `is_specialized` / `is_signed` 这类是**静态 constexpr 变量** -> 通用转发会把它变成函数 ✗，
  #      所以用 deriveExtra 手写 `static constexpr auto 英文名 = 基类::中文名;`
  #      （用 auto 避免写被改名的枚举类型名）。
  # ==========================================================================
  'limits' = @{
    zh      = '数值极限'
    realInclude = @('limits')   # §16.29「乙」：与真 <limits> 并存
    pub     = '数值极限'
    types   = [ordered]@{ 'numeric_limits' = '数值极限实现'
                          'float_denorm_style' = '浮点非规格方式'
                          'float_round_style'  = '浮点舍入方式'
                          '_Num_base' = '_数值基类'; '_Num_int_base' = '_整数数值基类'
                          '_Num_float_base' = '_浮点数值基类' }
    members = [ordered]@{
      '_Ty' = '_类型';
      # 枚举值（名域作用域的名字，靠 members 表改名）
      'denorm_indeterminate' = '非规格不确定'; 'denorm_absent' = '非规格不存在'; 'denorm_present' = '非规格存在'
      'round_indeterminate' = '舍入不确定'; 'round_toward_zero' = '向零舍入'
      'round_to_nearest' = '就近舍入'; 'round_toward_infinity' = '向正无穷舍入'
      'round_toward_neg_infinity' = '向负无穷舍入'
      # 静态函数成员
      'min' = '最小'; 'max' = '最大'; 'lowest' = '最低'; 'epsilon' = '机器精度'
      'round_error' = '舍入误差'; 'infinity' = '无穷'; 'quiet_NaN' = '静默非数'
      'signaling_NaN' = '信号非数'; 'denorm_min' = '非规格最小'
      'digits' = '位数'; 'digits10' = '十进制位数'; 'max_digits10' = '最大十进制位数'
      'radix' = '基数'; 'min_exponent' = '最小指数'; 'min_exponent10' = '最小十进制指数'
      'max_exponent' = '最大指数'; 'max_exponent10' = '最大十进制指数'
      # 静态变量成员
      'is_specialized' = '已特化'; 'is_signed' = '带符号'; 'is_integer' = '整数类型'
      'is_exact' = '精确'; 'is_iec559' = '符合IEC559'; 'is_bounded' = '有界'
      'is_modulo' = '取模'; 'has_infinity' = '有无穷'; 'has_quiet_NaN' = '有静默非数'
      'has_signaling_NaN' = '有信号非数'; 'has_denorm' = '有非规格'
      'has_denorm_loss' = '非规格损失'; 'traps' = '陷阱'; 'tinyness_before' = '先测微小'
      'round_style' = '舍入方式'
    }
    data    = [ordered]@{}
    # ⚠ numeric_limits 的成员大多是【静态】——通用转发器是非静态成员函数，
    #   套上去会报"调用非静态成员函数时没有对象实参"，所以这里 derive 留空、全部手写。
    derive  = @()
    deriveExtra = ( @(
      '    // 变量成员的英文名（通用转发会把变量变成函数，所以逐个手写；auto 免去写被改名的枚举类型名）。',
      '    static constexpr auto is_specialized    = 基类::已特化;',
      '    static constexpr auto is_signed         = 基类::带符号;',
      '    static constexpr auto is_integer        = 基类::整数类型;',
      '    static constexpr auto is_exact          = 基类::精确;',
      '    static constexpr auto is_iec559         = 基类::符合IEC559;',
      '    static constexpr auto is_bounded        = 基类::有界;',
      '    static constexpr auto is_modulo         = 基类::取模;',
      '    static constexpr auto has_infinity      = 基类::有无穷;',
      '    static constexpr auto has_quiet_NaN     = 基类::有静默非数;',
      '    static constexpr auto has_signaling_NaN = 基类::有信号非数;',
      '    static constexpr auto has_denorm        = 基类::有非规格;',
      '    static constexpr auto has_denorm_loss   = 基类::非规格损失;',
      '    static constexpr auto traps             = 基类::陷阱;',
      '    static constexpr auto tinyness_before   = 基类::先测微小;',
      '    static constexpr auto round_style       = 基类::舍入方式;',
      '',
      '    // 静态【函数】成员：同样手写（带括号，语义与 std 一致）。',
      '    static constexpr auto min() { 返回 基类::最小(); }',
      '    static constexpr auto max() { 返回 基类::最大(); }',
      '    static constexpr auto lowest() { 返回 基类::最低(); }',
      '    static constexpr auto epsilon() { 返回 基类::机器精度(); }',
      '    static constexpr auto round_error() { 返回 基类::舍入误差(); }',
      '    static constexpr auto infinity() { 返回 基类::无穷(); }',
      '    static constexpr auto quiet_NaN() { 返回 基类::静默非数(); }',
      '    static constexpr auto signaling_NaN() { 返回 基类::信号非数(); }',
      '    static constexpr auto denorm_min() { 返回 基类::非规格最小(); }',
      '    static constexpr auto digits() { 返回 基类::位数(); }',
      '    static constexpr auto digits10() { 返回 基类::十进制位数(); }',
      '    static constexpr auto max_digits10() { 返回 基类::最大十进制位数(); }',
      '    static constexpr auto radix() { 返回 基类::基数(); }',
      '    static constexpr auto min_exponent() { 返回 基类::最小指数(); }',
      '    static constexpr auto min_exponent10() { 返回 基类::最小十进制指数(); }',
      '    static constexpr auto max_exponent() { 返回 基类::最大指数(); }',
      '    static constexpr auto max_exponent10() { 返回 基类::最大十进制指数(); }'
    ) -join "`r`n" )
    extra   = ( @(
      '名域 标准 {',
      '',
      '// 两个枚举与它们的枚举值：抄来层在 细节::，公开层补别名/引入（枚举值用 using 引入名域作用域）。',
      '使用 浮点舍入方式   = 细节::浮点舍入方式;',
      '使用 浮点非规格方式 = 细节::浮点非规格方式;',
      '// 英文原名也要能用（否则"标准::float_round_style"这种写法就没了）。',
      '使用 float_round_style  = 细节::浮点舍入方式;',
      '使用 float_denorm_style = 细节::浮点非规格方式;'
      '使用 细节::舍入不确定; 使用 细节::向零舍入; 使用 细节::就近舍入;',
      '使用 细节::向正无穷舍入; 使用 细节::向负无穷舍入;',
      '使用 细节::非规格不确定; 使用 细节::非规格不存在; 使用 细节::非规格存在;',
      '',
      '}  // 名域 标准'
    ) -join "`r`n" )
    tparam  = @{ decl = '模板 <类型名 元素>'; args = '<元素>' }
    tests = @(
      @('只引中文头','#包含 <数值极限>`n整数 主函数(){ 返回 标准::数值极限<整数>::最大() > 0 ? 0 : 1; }'),
      @('与微软原头并存','#包含 <数值极限>`n#包含 <limits>`n整数 主函数(){ 返回 标准::数值极限<整数>::最大() == std::numeric_limits<整数>::max() ? 0 : 1; }'),
      @('英文原名与中文名并用','#包含 <数值极限>`n整数 主函数(){ 返回 标准::数值极限<整数>::max() == 标准::数值极限<整数>::最大() ? 0 : 1; }'),
      @('★守卫：常量表达式 + 变量成员的两条路都要通','#包含 <数值极限>`n静态断言(标准::数值极限<双精度>::已特化);`n静态断言(标准::数值极限<双精度>::is_specialized);`n静态断言(标准::数值极限<双精度>::符合IEC559);`n静态断言(标准::数值极限<整数>::带符号);`n整数 主函数(){ 返回 标准::数值极限<双精度>::无穷() > 标准::数值极限<双精度>::最大() ? 0 : 1; }'),
      @('枚举（含英文原名）','#包含 <数值极限>`n整数 主函数(){ 标准::浮点舍入方式 方式 = 标准::就近舍入;`n  标准::float_round_style 原名 = 标准::就近舍入;`n  返回 方式 == 原名 ? 0 : 1; }')
    )
  }
  # ==========================================================================
  #  阶段(4) 第五个真汉语公开头：<变体>（std::variant）
  #
  #  挑它的判据（真实 include 口径）：1729 行，依赖几乎全是【已完成的头】
  #    （compare/exception/initializer_list/type_traits/utility/xsmf_control/xutility）
  #    -> 用 zhIncludes 直接接通，借用链为零；C++17 活跃。
  #
  #  ⚠ 铁律④：`bad_variant_access` 是【异常类型】——捕获按类型匹配，抄一份就抓不到别人抛的。
  #    做法与 <可选> 同：realInclude 保证 std 那份在 + dropTypes 丢掉抄来的定义 + extra 里做别名。
  #
  #  ⚠ `get` / `get_if` 是**带显式模板实参**的自由函数（`标准::取<0>(甲)`），
  #    变参通用转发器接不住，必须手写（按位与按类型各一条）。
  # ==========================================================================
  'variant' = @{
    zh      = '变体'
    realInclude = @('variant')
    zhIncludes = @{ 'compare' = '比较'; 'exception' = '异常'; 'initializer_list' = '初始化列表'
                    'type_traits' = '类型特征'; 'utility' = '工具'
                    'xsmf_control.h' = '特殊成员控制'; 'xutility' = '通用内部件' }
    # 注：bad_variant_access 并不在 <variant> 里定义（实测 0 命中），所以不需要 dropTypes；
    #     它的中文名在 extra 里直接别名到 std 那一个（铁律④）。
    pub     = '变体'
    types   = [ordered]@{ 'variant' = '变体实现'; 'monostate' = '单态'
                          'variant_size' = '变体尺寸'; 'variant_alternative' = '变体替体' ;
                          '_As_variant' = '_作变体';
                          '_Tagged' = '_带标记';
                          '_Visit_strategy' = '_访问策略';
                          '_Meta_apply' = '_元_应用';
                          '_Meta_apply_' = '_元_应用_';
                          '_Meta_as_integer_sequence' = '_元_作整数序列';
                          '_Meta_as_integer_sequence_' = '_元_作整数序列_';
                          '_Meta_as_list' = '_元_作列表';
                          '_Meta_as_list_' = '_元_作列表_';
                          '_Meta_at_' = '_元_取位_';
                          '_Meta_at_c' = '_元_取位常量';
                          '_Meta_at_impl' = '_元_取位实现';
                          '_Meta_bind_back' = '_元_后绑定';
                          '_Meta_cartesian_product' = '_元_笛卡尔积';
                          '_Meta_cartesian_product_' = '_元_笛卡尔积_';
                          '_Meta_concat' = '_元_拼接';
                          '_Meta_concat_' = '_元_拼接_';
                          '_Meta_front' = '_元_取首';
                          '_Meta_front_' = '_元_取首_';
                          '_Meta_invoke' = '_元_调用';
                          '_Meta_join' = '_元_连接';
                          '_Meta_list' = '_元_列表';
                          '_Meta_pop_front' = '_元_弹首';
                          '_Meta_pop_front_' = '_元_弹首_';
                          '_Meta_push_front' = '_元_压首';
                          '_Meta_push_front_' = '_元_压首_';
                          '_Meta_quote' = '_元_引用';
                          '_Meta_quote_helper_' = '_元_引用助手_';
                          '_Meta_repeat_first_helper' = '_元_重复首助手';
                          '_Meta_repeat_n_c' = '_元_重复n常量';
                          '_Meta_repeat_n_c_' = '_元_重复n常量_';
                          '_Meta_transform' = '_元_变换';
                          '_Meta_transform_' = '_元_变换_';
                          '_Variant_assign_visitor' = '_变体_赋值访问器';
                          '_Variant_base' = '_变体_基';
                          '_Variant_construct_visitor' = '_变体_构造访问器';
                          '_Variant_destroy_layer' = '_变体_析构层';
                          '_Variant_destroy_layer_' = '_变体_析构层_';
                          '_Variant_dispatch_table' = '_变体_分派表';
                          '_Variant_dispatcher' = '_变体_分派器';
                          '_Variant_hash_visitor' = '_变体_散列访问器';
                          '_Variant_index_t' = '_变体_索引类型';
                          '_Variant_init_helper' = '_变体_初始化助手';
                          '_Variant_init_index' = '_变体_初始化索引';
                          '_Variant_init_overload_set' = '_变体_初始化重载集';
                          '_Variant_init_overload_set_' = '_变体_初始化重载集_';
                          '_Variant_init_single_overload' = '_变体_初始化单重载';
                          '_Variant_init_type' = '_变体_初始化类型';
                          '_Variant_item' = '_变体_项';
                          '_Variant_raw_dispatch_table1' = '_变体_裸分派表1';
                          '_Variant_raw_visit_t' = '_变体_裸访问类型';
                          '_Variant_raw_visit1' = '_变体_裸访问1';
                          '_Variant_relop_visitor2' = '_变体_关系访问器2';
                          '_Variant_storage' = '_变体_存储';
                          '_Variant_storage_' = '_变体_存储_';
                          '_Variant_tagged_ref_t' = '_变体_带标记引用类型';
                          '_Variant_type_resolver' = '_变体_类型解析器';
                          '_Variant_visit_result_t' = '_变体_访问结果类型';
                          '_BaseTy' = '_基类型';
                          '_Dispatch_t' = '_分派类型';
                          '_Index_t' = '_索引类型';
                          '_Indexed_value_type' = '_带索引值类型';
                          '_ListOfIndexLists' = '_索引列表之列表';
                          '_ListOfIndexVectors' = '_索引向量之列表';
                          '_Ret' = '_返回';
                          '_TargetTy' = '_目标类型';
                          '_Visitor' = '_访问器';
}
    # §17.27.58 copyFixes：std::hash 的特化必须写在 名域 std 里，而我们的类型在 细节:: —— 单态 在那里
    #   不可见（实测：'使用了未声明的标识符 单态'），所以把特化里的名字【限定】成 细节::单态。
    copyFixes = @( @('hash<单态>', 'hash<细节::单态>') )
    members = [ordered]@{
      '_STL_CASE' = '_STL_情形';
      '_Ty' = '_类型';
      '_Tag' = '_标记';
      '_Strategy' = '_策略';
      '_Storage_t' = '_存储类型';
      '_SMF_control' = '_特殊成员控制';
      '_Result' = '_结果';
      '_Op' = '_操作';
      '_Invoke' = '_调用';
      '_Indices' = '_下标集';
      '_First' = '_首个';
      '_Elem' = '_元素';
      '_Construct_in_place' = '_就地构造';
      '_Construct_from' = '_由之构造';
      '_Assign_from' = '_由之赋值'; 'index' = '索引'; 'valueless_by_exception' = '因异常无值'
                          'emplace' = '就地构造'; 'visit' = '访问'
                          'get' = '取'; 'get_if' = '条件取'
                          'holds_alternative' = '持有替体'
                          'variant_npos' = '变体无位置'
                          # 宏名也要汉化（§16.24）：宏不受名域约束，宏体改了名而宏名不改会劫持真头同名宏。
                          '_STL_VISIT_STAMP' = '_访问戳' ;
      '_Destroy' = '_析构';
      '_Dispatch2' = '_分派2';
      '_Do_hash' = '_求散列';
      '_Emplace_from' = '_由之就地构造';
      '_Emplace_valueless' = '_无值就地构造';
      '_Eval' = '_求值';
      '_Get' = '_取';
      '_Reset' = '_重置';
      '_Set_index' = '_置索引';
      '_Storage' = '_存储';
      '_Variant_raw_visit' = '_变体_裸访问';
      '_Variant_visit_index1' = '_变体_访问索引1';
      '_Visit' = '_访问';
      '_Visit2' = '_访问2';
}
    data    = [ordered]@{}
    # ⚠ emplace 在 std 里就要求【显式类型实参】（甲.emplace<整数>(7)），通用转发器是纯变参、接不住 -> 改手写。
    deriveExtra = ( @(
      '    // emplace 要显式类型实参（std 亦然），所以手写一个带显式首参的转发。',
      '    模板 <类型名 替体, 类型名... 参数> 声明类型(自动) emplace(参数&&... 值) { 返回 基类::就地构造<替体>(static_cast<参数&&>(值)...); }'
    ) -join "`r`n" )
    derive  = @( @('index','索引'), @('valueless_by_exception','因异常无值') )
    extra   = ( @(
      '名域 标准 {',
      '',
      '// 铁律④：异常类型只能用 std 那一个（realInclude 保证它在），这里只补中文名。',
      '使用 变体访问错误 = std::bad_variant_access;',
      '',
      '// §17.19.17 类型名也要有中文名：单态 的【定义】在 通用内部件（我们的 xutility 拷贝）的',
      '//   标准::细节 里；定义侧已改名，本头那些引用会自动跟成 单态。这里给公开层一个别名。',
      '使用 单态 = 细节::单态;',
      '',
      '// ---- 自由函数的中文名 ----',
      '模板 <类型名... 参数> 声明类型(自动) 访问(参数&&... 值) { 返回 细节::访问(static_cast<参数&&>(值)...); }',
      '模板 <size_t 位, 类型名 变体类型> 声明类型(自动) 取(变体类型&& 值) { 返回 细节::取<位>(static_cast<变体类型&&>(值)); }',
      '模板 <类型名 替体, 类型名 变体类型> 声明类型(自动) 取(变体类型&& 值) { 返回 细节::取<替体>(static_cast<变体类型&&>(值)); }',
      '模板 <size_t 位, 类型名 变体类型> 声明类型(自动) 条件取(变体类型* 值) 不抛出 { 返回 细节::条件取<位>(值); }',
      '模板 <类型名 替体, 类型名 变体类型> 声明类型(自动) 条件取(变体类型* 值) 不抛出 { 返回 细节::条件取<替体>(值); }',
      '模板 <类型名 替体, 类型名... 参数> 声明类型(自动) 持有替体(参数&&... 值) { 返回 细节::持有替体<替体>(static_cast<参数&&>(值)...); }',
      '内联 常量表达式 自动 变体无位置 = 细节::变体无位置;',
      '',
      '// ---- 英文原名（在【中文的基础上】派生：同一份实现，两个名字）----',
      '模板 <类型名... 参数> 声明类型(自动) visit(参数&&... 值) { 返回 细节::访问(static_cast<参数&&>(值)...); }',
      '模板 <size_t 位, 类型名 变体类型> 声明类型(自动) get(变体类型&& 值) { 返回 细节::取<位>(static_cast<变体类型&&>(值)); }',
      '模板 <类型名 替体, 类型名 变体类型> 声明类型(自动) get(变体类型&& 值) { 返回 细节::取<替体>(static_cast<变体类型&&>(值)); }',
      '模板 <size_t 位, 类型名 变体类型> 声明类型(自动) get_if(变体类型* 值) 不抛出 { 返回 细节::条件取<位>(值); }',
      '模板 <类型名 替体, 类型名 变体类型> 声明类型(自动) get_if(变体类型* 值) 不抛出 { 返回 细节::条件取<替体>(值); }',
      '模板 <类型名 替体, 类型名... 参数> 声明类型(自动) holds_alternative(参数&&... 值) { 返回 细节::持有替体<替体>(static_cast<参数&&>(值)...); }',
      '内联 常量表达式 自动 variant_npos = 细节::变体无位置;',
      '',
      '}  // 名域 标准'
    ) -join "`r`n" )
    tparam  = @{ decl = '模板 <类型名... 类型们>'; args = '<类型们...>' }
    tests = @(
      @('只引中文头','#包含 <变体>`n整数 主函数(){ 标准::变体<整数, 双精度> 甲 = 5; 返回 标准::取<0>(甲) == 5 ? 0 : 1; }'),
      @('与微软原头并存','#包含 <变体>`n#包含 <variant>`n整数 主函数(){ 标准::变体<整数, 双精度> 甲 = 5; std::variant<整数, 双精度> 乙 = 5; 返回 标准::取<0>(甲) == std::get<0>(乙) ? 0 : 1; }'),
      @('英文原名与中文名并用','#包含 <变体>`n整数 主函数(){ 标准::变体<整数> 甲; 甲.emplace<整数>(7);`n  返回 甲.index() == 甲.索引() && 甲.索引() == 0 ? 0 : 1; }'),
      @('★守卫：访问 / 持有替体 / 条件取 三条路都要通','#包含 <变体>`n整数 主函数(){ 标准::变体<整数, 双精度> 甲 = 3;`n  整数 和 = 标准::访问([](自动 值) { 返回 (整数)值; }, 甲);`n  整数* 针 = 标准::条件取<整数>(&甲);`n  布尔 持有 = 标准::持有替体<整数>(甲);`n  返回 持有 && 针 != 空指针 && 和 == 3 ? 0 : 1; }'),
      @('异常类型身份（铁律④ 机器守卫）','#包含 <变体>`n静态断言(std::is_same<标准::变体访问错误, std::bad_variant_access>::value, "");`n整数 主函数(){ 返回 0; }'),
      @('★守卫 §17.19.17：借来的类型也要有中文名（单态）','#包含 <变体>`n整数 主函数(){ 标准::变体<标准::单态> 甲; 返回 甲.索引() == 0 && 标准::持有替体<标准::单态>(甲) ? 0 : 1; }')
    )
  }
  'charconv' = @{
    zh      = '字符转换'
    realInclude = @('charconv')
    zhIncludes = @{ 'xutility' = '通用内部件' }
    # §17.19.12/12.1：同名助手族按【编译器信号】定类（prologue = 形态一的 using-声明；
    #   members 里的中文名 = 形态二/三的改名）。不用文本启发式去猜"我们有没有定义"。
    prologue = '使用 std::_Bit_scan_reverse; 使用 std::_Floating_to_chars_ryu; 使用 std::_Floating_to_chars_scientific_precision; 使用 std::_Floating_to_chars_fixed_precision;'
    noPub   = $true
    pub     = '字符转换'
    types   = [ordered]@{}
    members = [ordered]@{ 'to_chars' = '数值转字符'; 'from_chars' = '字符转数值'
      '_Adl_verify_range' = '_ADL校验范围';
      '_Copy_n_unchecked4' = '_复制N个非检查4';
      '_Elem' = '_元素';
      '_First' = '_首个';
      '_Last' = '_最后';
      '_Result' = '_结果';
      '_Traits' = '_特征';
                          '_Floating_from_chars' = '_浮点转数值'
                          '_Floating_to_chars' = '_浮点转字符'
                          '_Floating_to_chars_hex_shortest' = '_浮点转字符十六进制最短'
                          '_Floating_to_chars_hex_precision' = '_浮点转字符十六进制精度'
                          '_Floating_to_chars_general_precision' = '_浮点转字符通用精度'
                          '_Convert_decimal_string_to_floating_type' = '_十进制串转浮点类型'
                          '_Convert_hexadecimal_string_to_floating_type' = '_十六进制串转浮点类型'
                          '_Ordinary_floating_from_chars' = '_常规浮点转数值' ;
      '_Unsigned' = '_无符号类型';
}
    data    = [ordered]@{}
    derive  = @()
    extra   = ( @(
      '名域 标准 {',
      '',
      '使用 数值转字符结果 = std::to_chars_result;',
      '使用 字符转数值结果 = std::from_chars_result;',
      '使用 字符格式       = std::chars_format;',
      '内联 常量表达式 自动 科学     = std::chars_format::scientific;',
      '内联 常量表达式 自动 定点     = std::chars_format::fixed;',
      '内联 常量表达式 自动 十六进制 = std::chars_format::hex;',
      '内联 常量表达式 自动 通用     = std::chars_format::general;',
      '',
      '模板 <类型名... 参数> 声明类型(自动) 数值转字符(参数&&... 值) { 返回 细节::数值转字符(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> 声明类型(自动) 字符转数值(参数&&... 值) { 返回 细节::字符转数值(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> 声明类型(自动) to_chars(参数&&... 值) { 返回 细节::数值转字符(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> 声明类型(自动) from_chars(参数&&... 值) { 返回 细节::字符转数值(static_cast<参数&&>(值)...); }',
      '',
      '}  // 名域 标准'
    ) -join "`r`n" )
    tparam  = @{ decl = ''; args = '' }
    tests = @(
      @('只引中文头','#包含 <字符转换>`n整数 主函数(){ 字符 缓[16]; 自动 果 = 标准::数值转字符(缓, 缓 + 16, 42); 返回 果.ptr != 缓 ? 0 : 1; }'),
      @('与微软原头并存','#包含 <字符转换>`n#包含 <charconv>`n整数 主函数(){ 字符 甲[16]; 字符 乙[16];`n  标准::数值转字符(甲, 甲 + 16, 42); std::to_chars(乙, 乙 + 16, 42);`n  返回 甲[0] == 乙[0] ? 0 : 1; }'),
      @('英文原名与中文名并用','#包含 <字符转换>`n整数 主函数(){ 字符 甲[16]; 字符 乙[16];`n  标准::数值转字符(甲, 甲 + 16, 42); 标准::to_chars(乙, 乙 + 16, 42);`n  返回 甲[0] == 乙[0] ? 0 : 1; }'),
      @('★守卫 §17.19.12：格式枚举可用（隐藏 / 歧义的现场）','#包含 <字符转换>`n整数 主函数(){ 返回 标准::通用 == std::chars_format::general && 标准::十六进制 == std::chars_format::hex ? 0 : 1; }'),
      @('结果类型身份（铁律④ 机器守卫）','#包含 <字符转换>`n静态断言(std::is_same<标准::数值转字符结果, std::to_chars_result>::value, "");`n静态断言(std::is_same<标准::字符转数值结果, std::from_chars_result>::value, "");`n整数 主函数(){ 返回 0; }')
    )
  }
  'sstream' = @{
    zh      = '字符串流'
    realInclude = @('sstream')
    # §17.14 借用面切换：本头要调 basic_string 的【私有】_Getal（sstream 是它的友元）——
    #   用真头那份会撞 §3.6 的反向形态（我们不是 std::basic_string 的友元）；
    #   接到我们自己的字符串后，xstring 里那条 friend 已改成我们的 基础字符串缓冲，对得上。
    zhIncludes = @{ 'string' = '字符串' }
    pub     = '基础字符串缓冲'
    types   = [ordered]@{ 'basic_string'      = '基础字符串实现'
                          'basic_string_view' = '基础字符串视图'
                          'basic_stringbuf' = '基础字符串缓冲'
                          'basic_istringstream' = '基础输入字符串流'
                          'basic_ostringstream' = '基础输出字符串流'
                          'basic_stringstream'  = '基础字符串流' }
    members = [ordered]@{ 'str' = '字符串'; 'view' = '视图'; 'rdbuf' = '缓冲'
                          '_Alloc' = '_分配器'
                          '_Allocate_at_least_helper' = '_分配至少助手'
                          '_Elem' = '_元素'
                          '_Getal' = '_取分配器'
                          '_Move_assign_from_buffer' = '_由缓冲移动赋值'
                          '_Mystr' = '_我的字符串'
                          '_Pocma_values' = '_传播复制移动赋值取值'
                          '_Ptr_traits' = '_指针特征'
                          '_Release_to_buffer' = '_释放至缓冲'
                          '_Result' = '_结果'
                          '_Take_contents' = '_接管内容'
                          '_Tidy' = '_清理'
                          '_Traits' = '_特征'
                          '_Unfancy' = '_去花式'
                          'get_allocator' = '取分配器'
                          '_Get_buffer_view' = '_取缓冲视图' ;
      '_Assign_rv_no_alias' = '_无别名移动赋值';

      '_Mysize_type' = '_我的大小类型';

      '_Mysb' = '_我的流缓冲';

      '_Init_string_inplace' = '_就地初始化串';

      '_Init' = '_初始化';

      '_Getstate' = '_取状态';

      '_Copy_into_self_and_tidy' = '_自拷贝并整理';

      '_Buffer_view' = '_缓冲视图';

      '_Mystr_view' = '_我的串视图';
}
    data    = [ordered]@{}
    # ⚠ 本轮先只转 str（其余 view/rdbuf/get_allocator 的中文名要在【每个实现类】里逐个核实存在性，
    #   否则派生层转发器会指向不存在的成员 —— 这正是登记≠落地守卫要防的）。
    derive  = @( @('str','字符串') )
    extra   = ( @(
      '名域 标准 {',
      '',
      '// 另外三个流类：手写派生层（与 <互斥量>/<数值数组> 的多类写法同）——派生层只负责补回英文原名。',
      '模板 <类型名 元素, 类型名 特征 = std::char_traits<元素>, 类型名 分配器 = std::allocator<元素>>',
      '类型 基础输入字符串流 : 公开 细节::基础输入字符串流<元素, 特征, 分配器> {',
      '公开:',
      '    使用 基类 = 细节::基础输入字符串流<元素, 特征, 分配器>;',
      '    使用 基类::基类;',
      '    模板 <类型名... 参数> 声明类型(自动) str(参数&&... 值) { 返回 基类::字符串(static_cast<参数&&>(值)...); }',
      '    模板 <类型名... 参数> 声明类型(自动) rdbuf(参数&&... 值) { 返回 基类::缓冲(static_cast<参数&&>(值)...); }',
      '    模板 <类型名... 参数> 声明类型(自动) view(参数&&... 值) { 返回 基类::视图(static_cast<参数&&>(值)...); }',
      '};',
      '',
      '模板 <类型名 元素, 类型名 特征 = std::char_traits<元素>, 类型名 分配器 = std::allocator<元素>>',
      '类型 基础输出字符串流 : 公开 细节::基础输出字符串流<元素, 特征, 分配器> {',
      '公开:',
      '    使用 基类 = 细节::基础输出字符串流<元素, 特征, 分配器>;',
      '    使用 基类::基类;',
      '    模板 <类型名... 参数> 声明类型(自动) str(参数&&... 值) { 返回 基类::字符串(static_cast<参数&&>(值)...); }',
      '    模板 <类型名... 参数> 声明类型(自动) rdbuf(参数&&... 值) { 返回 基类::缓冲(static_cast<参数&&>(值)...); }',
      '    模板 <类型名... 参数> 声明类型(自动) view(参数&&... 值) { 返回 基类::视图(static_cast<参数&&>(值)...); }',
      '};',
      '',
      '模板 <类型名 元素, 类型名 特征 = std::char_traits<元素>, 类型名 分配器 = std::allocator<元素>>',
      '类型 基础字符串流 : 公开 细节::基础字符串流<元素, 特征, 分配器> {',
      '公开:',
      '    使用 基类 = 细节::基础字符串流<元素, 特征, 分配器>;',
      '    使用 基类::基类;',
      '    模板 <类型名... 参数> 声明类型(自动) str(参数&&... 值) { 返回 基类::字符串(static_cast<参数&&>(值)...); }',
      '    模板 <类型名... 参数> 声明类型(自动) rdbuf(参数&&... 值) { 返回 基类::缓冲(static_cast<参数&&>(值)...); }',
      '    模板 <类型名... 参数> 声明类型(自动) view(参数&&... 值) { 返回 基类::视图(static_cast<参数&&>(值)...); }',
      '};',
      '',
      '// 常用别名（对应 std::stringbuf / istringstream / ostringstream / stringstream）',
      '使用 字符串缓冲     = 基础字符串缓冲<字符>;',
      '使用 输入字符串流   = 基础输入字符串流<字符>;',
      '使用 输出字符串流   = 基础输出字符串流<字符>;',
      '使用 字符串流       = 基础字符串流<字符>;',
      '使用 宽字符串缓冲   = 基础字符串缓冲<宽字符>;',
      '使用 宽输入字符串流 = 基础输入字符串流<宽字符>;',
      '使用 宽输出字符串流 = 基础输出字符串流<宽字符>;',
      '使用 宽字符串流     = 基础字符串流<宽字符>;',
      '',
      '}  // 名域 标准'
    ) -join "`r`n" )
    tparam  = @{ decl = '模板 <类型名 元素, 类型名 特征 = std::char_traits<元素>, 类型名 分配器 = std::allocator<元素>>'
                 args = '<元素, 特征, 分配器>' }
    tests = @(
      @('只引中文头','#包含 <字符串流>`n整数 主函数(){ 标准::输出字符串流 甲; 甲 << 42; 返回 甲.字符串() == "42" ? 0 : 1; }'),
      @('与微软原头并存','#包含 <字符串流>`n#包含 <sstream>`n整数 主函数(){ 标准::输出字符串流 甲; 甲 << 42; std::ostringstream 乙; 乙 << 42; 返回 甲.字符串().尺寸() == 乙.str().size() ? 0 : 1; }'),
      @('英文原名与中文名并用','#包含 <字符串流>`n整数 主函数(){ 标准::输出字符串流 甲; 甲 << 7; 返回 甲.str() == 甲.字符串() ? 0 : 1; }'),
      @('★守卫：输入流 / 双向流 的中文名都在','#包含 <字符串流>`n整数 主函数(){ 标准::输入字符串流 甲("41"); 整数 值 = 0; 甲 >> 值; 标准::字符串流 乙; 乙 << 1; 返回 值 == 41 && 乙.字符串() == "1" ? 0 : 1; }')
    )
  }
  'complex' = @{
                              # §17.19.43 还有 3 条（_Float_abs_bits/_Tyreal/_Zv）与其余 10 条同理：本头【没有它们的定义】，
    #   是借来的 std/C 名（守卫的『借用名告警』点出来的），不登记改名。
    # §17.19.43 另外 10 条（_Cosh/_Exp/_FCosh/_FExp/_FSinh/_LCosh/_LDtest/_LExp/_LSinh/_Sinh）
    #   在原文里是 _CSTD _X(...) —— _CSTD = ::，那是 CRT 的函数，不是我们拷贝层的：不登记改名。
    # §10.2 两个主人 + 宏限定：#define _FMP _STD _Float_multi_prec:: —— 跟在 _FMP 后面的 _Fmp_t/_Sqr_x2/_Add_small_x2
    #   是【std 结构的成员】，还有 _Math_algorithms::_Log_hypot 同样是 std 的：这四条不登记改名（真边界）。
    # dropTypes 里的三个 C 复数类型（_C_double_complex 等）身份必须留给 std（铁律③），不登记改名
    zh      = '复数'
    realInclude = @('complex')
    # §17.19.15：C 复数结构在真头与副本各一份 -> 丢掉副本（⚠ 实名是 _C_ldouble_complex）。
    dropTypes = @('_C_double_complex', '_C_float_complex', '_C_ldouble_complex')
    # 本轮判定：**不切借用面**（本头不与我们的容器/串/极限做类型混用，也没有友元/私有访问问题）。
    pub     = '复数'
    types   = [ordered]@{ 'complex' = '复数实现' ;
                          '_Complex_base' = '_复数基';
                          '_Complex_value' = '_复数值';
                          '_Ctraits' = '_复数特征';
                          '_Myctraits' = '_我的复数特征';
                          '_Dcomplex_value' = '_双精度复数值';
                          '_Fcomplex_value' = '_单精度复数值';
                          '_Lcomplex_value' = '_长双精度复数值';
                          '_Flt_eps' = '_浮点最小增量';
                          '_Flt_max' = '_浮点最大值';
                          '_Flt_norm_min' = '_浮点规格化最小值';
                          '_High_half' = '_高半部';
                          '_Infv' = '_无穷值';
                          '_Nanv' = '_非数值';
                          '_Promoted' = '_提升后类型';
                          '_Upgraded' = '_升级后类型';
}
    members = [ordered]@{
      '_Ty' = '_类型';
      '_Traits' = '_特征';
      '_Result' = '_结果';
      '_Elem' = '_元素'; 'real' = '实部'; 'imag' = '虚部'
                          'abs' = '模'; 'arg' = '幅角'; 'norm' = '模方'; 'conj' = '共轭'
                          'proj' = '投影'; 'polar' = '极坐标'
                          'log10' = '常用对数'
                          'asin' = '反正弦'; 'acos' = '反余弦'; 'atan' = '反正切'
                          'sinh' = '双曲正弦'; 'cosh' = '双曲余弦'; 'tanh' = '双曲正切'
                          'asinh' = '反双曲正弦'; 'acosh' = '反双曲余弦'; 'atanh' = '反双曲正切'
                          # §17.19.15：与 <cmath> 同名的这 7 个【不能改名】——本头也用它们做标量调用，
                          #   改名会被编译器校对撤回（信号：改回英文: X）。它们的中文名在 extra 里给。
                          # §16.24：宏名也要汉化（宏体改了名而宏名不改会劫持真头同名宏）。
                          '_C_COMPLEX_T' = '_C_复数_T'
                          '_COMPLEX_' = '_复数_'
                          '_FMP' = '_FMP_汉'
                          '_FMP_USING_STD_FMA' = '_FMP_USING_STD_FMA_汉'
                          '_FMP_USING_X86_X64_INTRINSICS' = '_FMP_USING_X86_X64_INTRINSICS_汉'
                          '_RE' = '_RE_汉'
                          '_IM' = '_IM_汉' ;
      '_Abs' = '_取模';
      '_Add' = '_加';
      '_Add_x1' = '_加一倍';
      '_Add_x2' = '_加双倍';
      '_Copysign' = '_复制符号';
      '_Div' = '_除';
      '_Hypot_leg_huge_helper' = '_直角边巨大助手';
      '_Hypot_leg_tiny_helper' = '_直角边极小助手';
      '_Isinf' = '_是无穷';
      '_Isnan' = '_是非数值';
      '_Logp1' = '_对数加一';
      '_Mul' = '_乘';
      '_Norm_minus_one' = '_模减一';
      '_Polar_positive_nan_inf_zero_rho' = '_极坐标正非数值无穷零半径';
      '_Pow' = '_幂';
      '_Signbit' = '_符号位';
      '_Sqr_error_fallback' = '_平方误差回退';
      '_Sqr_error_std_fma' = '_平方误差标准融合乘加';
      '_Sqr_error_x86_x64_fma' = '_平方误差x86x64融合乘加';
      '_Sub' = '_减';
      '_Upgrade_to_double' = '_升级到双精度';

      '_Tmp' = '_临时';

      '_Type' = '_类型参数';
}
    data    = [ordered]@{}
    derive  = @( @('real','实部'), @('imag','虚部') )
    extra   = ( @(
      '名域 标准 {',
      '',
      '// ---- 公开层：中文名 + 英文原名，一律【只吃复数】的受限重载 ----',
      '//   §17.19.16 判定（全量组合探针逼出来的）：<C数学> 的中文名（正弦/平方根/常用对数/幂/…）本身',
      '//   就是可变参模板 模板<类型名... 参数> 名(参数&&...)。**同签名的可变参模板在同一名字空间里是',
      '//   重定义，不是重载** —— 单引 <复数> 时看不见，全量组合必炸。',
      '//   受限重载参数表不同 -> 与 C数学 共存；复数实参按函数模板偏序优选本份，标量实参仍走 C数学。',
      '//   exp 的中文名与 C数学 统一为 自然指数（原先这里叫 指数，属一名两物）。',
      '//   极坐标/polar 例外：它本来就吃标量，C数学 也没有同名 -> 保留可变参转发。',
      '模板 <类型名 元素> 声明类型(自动) 实部(const 细节::复数实现<元素>& 值) { 返回 细节::实部(值); }',
      '模板 <类型名 元素> 声明类型(自动) 虚部(const 细节::复数实现<元素>& 值) { 返回 细节::虚部(值); }',
      '模板 <类型名 元素> 声明类型(自动) 模(const 细节::复数实现<元素>& 值) { 返回 细节::模(值); }',
      '模板 <类型名 元素> 声明类型(自动) 幅角(const 细节::复数实现<元素>& 值) { 返回 细节::幅角(值); }',
      '模板 <类型名 元素> 声明类型(自动) 模方(const 细节::复数实现<元素>& 值) { 返回 细节::模方(值); }',
      '模板 <类型名 元素> 声明类型(自动) 共轭(const 细节::复数实现<元素>& 值) { 返回 细节::共轭(值); }',
      '模板 <类型名 元素> 声明类型(自动) 投影(const 细节::复数实现<元素>& 值) { 返回 细节::投影(值); }',
      '模板 <类型名... 参数> 声明类型(自动) 极坐标(参数&&... 值) { 返回 细节::极坐标(static_cast<参数&&>(值)...); }',
      '模板 <类型名 元素> 声明类型(自动) 常用对数(const 细节::复数实现<元素>& 值) { 返回 细节::常用对数(值); }',
      '模板 <类型名 元素> 声明类型(自动) 反正弦(const 细节::复数实现<元素>& 值) { 返回 细节::反正弦(值); }',
      '模板 <类型名 元素> 声明类型(自动) 反余弦(const 细节::复数实现<元素>& 值) { 返回 细节::反余弦(值); }',
      '模板 <类型名 元素> 声明类型(自动) 反正切(const 细节::复数实现<元素>& 值) { 返回 细节::反正切(值); }',
      '模板 <类型名 元素> 声明类型(自动) 双曲正弦(const 细节::复数实现<元素>& 值) { 返回 细节::双曲正弦(值); }',
      '模板 <类型名 元素> 声明类型(自动) 双曲余弦(const 细节::复数实现<元素>& 值) { 返回 细节::双曲余弦(值); }',
      '模板 <类型名 元素> 声明类型(自动) 双曲正切(const 细节::复数实现<元素>& 值) { 返回 细节::双曲正切(值); }',
      '模板 <类型名 元素> 声明类型(自动) 反双曲正弦(const 细节::复数实现<元素>& 值) { 返回 细节::反双曲正弦(值); }',
      '模板 <类型名 元素> 声明类型(自动) 反双曲余弦(const 细节::复数实现<元素>& 值) { 返回 细节::反双曲余弦(值); }',
      '模板 <类型名 元素> 声明类型(自动) 反双曲正切(const 细节::复数实现<元素>& 值) { 返回 细节::反双曲正切(值); }',
      '模板 <类型名 元素> 声明类型(自动) 自然指数(const 细节::复数实现<元素>& 值) { 返回 细节::exp(值); }',
      '模板 <类型名 元素> 声明类型(自动) 自然对数(const 细节::复数实现<元素>& 值) { 返回 细节::log(值); }',
      '模板 <类型名 元素> 声明类型(自动) 正弦(const 细节::复数实现<元素>& 值) { 返回 细节::sin(值); }',
      '模板 <类型名 元素> 声明类型(自动) 余弦(const 细节::复数实现<元素>& 值) { 返回 细节::cos(值); }',
      '模板 <类型名 元素> 声明类型(自动) 平方根(const 细节::复数实现<元素>& 值) { 返回 细节::sqrt(值); }',
      '模板 <类型名 元素> 声明类型(自动) 正切(const 细节::复数实现<元素>& 值) { 返回 细节::tan(值); }',
      '模板 <类型名 元素> 声明类型(自动) 幂(const 细节::复数实现<元素>& 甲, const 细节::复数实现<元素>& 乙) { 返回 细节::pow(甲, 乙); }',
      '模板 <类型名 元素> 声明类型(自动) real(const 细节::复数实现<元素>& 值) { 返回 细节::实部(值); }',
      '模板 <类型名 元素> 声明类型(自动) imag(const 细节::复数实现<元素>& 值) { 返回 细节::虚部(值); }',
      '模板 <类型名 元素> 声明类型(自动) abs(const 细节::复数实现<元素>& 值) { 返回 细节::模(值); }',
      '模板 <类型名 元素> 声明类型(自动) arg(const 细节::复数实现<元素>& 值) { 返回 细节::幅角(值); }',
      '模板 <类型名 元素> 声明类型(自动) norm(const 细节::复数实现<元素>& 值) { 返回 细节::模方(值); }',
      '模板 <类型名 元素> 声明类型(自动) conj(const 细节::复数实现<元素>& 值) { 返回 细节::共轭(值); }',
      '模板 <类型名 元素> 声明类型(自动) proj(const 细节::复数实现<元素>& 值) { 返回 细节::投影(值); }',
      '模板 <类型名... 参数> 声明类型(自动) polar(参数&&... 值) { 返回 细节::极坐标(static_cast<参数&&>(值)...); }',
      '模板 <类型名 元素> 声明类型(自动) log10(const 细节::复数实现<元素>& 值) { 返回 细节::常用对数(值); }',
      '模板 <类型名 元素> 声明类型(自动) asin(const 细节::复数实现<元素>& 值) { 返回 细节::反正弦(值); }',
      '模板 <类型名 元素> 声明类型(自动) acos(const 细节::复数实现<元素>& 值) { 返回 细节::反余弦(值); }',
      '模板 <类型名 元素> 声明类型(自动) atan(const 细节::复数实现<元素>& 值) { 返回 细节::反正切(值); }',
      '模板 <类型名 元素> 声明类型(自动) sinh(const 细节::复数实现<元素>& 值) { 返回 细节::双曲正弦(值); }',
      '模板 <类型名 元素> 声明类型(自动) cosh(const 细节::复数实现<元素>& 值) { 返回 细节::双曲余弦(值); }',
      '模板 <类型名 元素> 声明类型(自动) tanh(const 细节::复数实现<元素>& 值) { 返回 细节::双曲正切(值); }',
      '模板 <类型名 元素> 声明类型(自动) asinh(const 细节::复数实现<元素>& 值) { 返回 细节::反双曲正弦(值); }',
      '模板 <类型名 元素> 声明类型(自动) acosh(const 细节::复数实现<元素>& 值) { 返回 细节::反双曲余弦(值); }',
      '模板 <类型名 元素> 声明类型(自动) atanh(const 细节::复数实现<元素>& 值) { 返回 细节::反双曲正切(值); }',
      '模板 <类型名 元素> 声明类型(自动) exp(const 细节::复数实现<元素>& 值) { 返回 细节::exp(值); }',
      '模板 <类型名 元素> 声明类型(自动) log(const 细节::复数实现<元素>& 值) { 返回 细节::log(值); }',
      '模板 <类型名 元素> 声明类型(自动) sin(const 细节::复数实现<元素>& 值) { 返回 细节::sin(值); }',
      '模板 <类型名 元素> 声明类型(自动) cos(const 细节::复数实现<元素>& 值) { 返回 细节::cos(值); }',
      '模板 <类型名 元素> 声明类型(自动) sqrt(const 细节::复数实现<元素>& 值) { 返回 细节::sqrt(值); }',
      '模板 <类型名 元素> 声明类型(自动) tan(const 细节::复数实现<元素>& 值) { 返回 细节::tan(值); }',
      '模板 <类型名 元素> 声明类型(自动) pow(const 细节::复数实现<元素>& 甲, const 细节::复数实现<元素>& 乙) { 返回 细节::pow(甲, 乙); }',
      '',
      '}  // 名域 标准'
    ) -join "`r`n" )
    tparam  = @{ decl = '模板 <类型名 元素>'; args = '<元素>' }
    tests = @(
      @('只引中文头','#包含 <复数>`n整数 主函数(){ 标准::复数<双精度> 甲(3.0, 4.0); 返回 标准::模(甲) == 5.0 ? 0 : 1; }'),
      @('与微软原头并存','#包含 <复数>`n#包含 <complex>`n整数 主函数(){ 标准::复数<双精度> 甲(3.0, 4.0); std::complex<双精度> 乙(3.0, 4.0); 返回 标准::模(甲) == std::abs(乙) ? 0 : 1; }'),
      @('英文原名与中文名并用','#包含 <复数>`n整数 主函数(){ 标准::复数<双精度> 甲(1.0, 2.0); 返回 甲.real() == 甲.实部() && 标准::abs(甲) == 标准::模(甲) ? 0 : 1; }'),
      @('★守卫：极坐标 / 共轭 / 虚部 的中文名都在','#包含 <复数>`n整数 主函数(){ 自动 乙 = 标准::极坐标(2.0, 0.0); 自动 丙 = 标准::共轭(标准::复数<双精度>(1.0, 1.0)); 返回 标准::实部(乙) == 2.0 && 标准::虚部(丙) == -1.0 ? 0 : 1; }'),
      @('★守卫 §17.19.15：与 <cmath> 同名的那 7 个，中文名照样可用','#包含 <复数>`n整数 主函数(){ 标准::复数<双精度> 甲(0.0, 0.0); 返回 标准::正弦(甲) == 标准::sin(甲) && 标准::平方根(标准::复数<双精度>(4.0, 0.0)) == 标准::复数<双精度>(2.0, 0.0) ? 0 : 1; }')
    )
  }
  # ==========================================================================
  #  §17.19.18 <atomic>（原子）：第 9 个真汉语公开头（阶段(4)）
  #  · 借用面：realInclude 让真头在场；`xatomic.h` / `xatomic_wait.h` / `xthreads.h`
  #    仍借 std 的 —— 消除路径 = 以后把这三个内部头也抄成我们的内部件（欠账，见方案 §17.19.18）。
  #  · 命名（只按已有译名，不另造）：atomic → 原子实现（公开层 标准::原子）、
  #    memory_order → 内存序、fetch_add → 取加、notify_one → 通知一个、wait → 等待。
  # ==========================================================================
  'atomic' = @{
    zh      = '原子'
    realInclude = @('atomic')
    # §17.19.20：xatomic.h 已是我们的内部件 -> 借用面切过来，原子相关名字就能在拷贝层落地
    zhIncludes = @{ 'xatomic.h' = '原子内部件' }
    types   = [ordered]@{
      'atomic'                 = '原子实现'
      'atomic_flag'            = '原子标志实现'
      'atomic_ref'             = '原子引用实现'
      'memory_order'           = '内存序'

      '_Atomic_storage'        = '_原子存储'
      '_Atomic_padded'         = '_原子填充'
      '_Atomic_storage_traits' = '_原子存储特征'
      '_Atomic_storage_types'  = '_原子存储类型'
      '_Atomic_lock_guard'     = '_原子锁守卫'
      '_Storage_for'           = '_存储用于'
      '_Form_mask_t'           = '_形式掩码类型'
      '_Atomic_integral'          = '_原子整数'
      '_Atomic_integral_facade'   = '_原子整数门面'
      '_Atomic_pointer'           = '_原子指针'
      '_Atomic_nonobject_pointer' = '_原子非对象指针'
      '_Atomic_floating'          = '_原子浮点'
    }
    members = [ordered]@{
      '_Dest' = '_目标';
      '_Lock' = '_加锁';
      '_Rep' = '_表示';
      '_Result' = '_结果';
      '_Ty' = '_类型';
      '_Uty' = '_结果类型';
      'load' = '载入'; 'store' = '存储'; 'exchange' = '置换'
      'compare_exchange_weak' = '比较交换弱'
      'compare_exchange_strong' = '比较交换强'
      'fetch_add' = '取加'; 'fetch_sub' = '取减'; 'fetch_and' = '取与'
      'fetch_or' = '取或'; 'fetch_xor' = '取异或'
      'is_lock_free' = '无锁'
      'wait' = '等待'; 'notify_one' = '通知一个'; 'notify_all' = '通知全部'
      'test' = '测试'; 'test_and_set' = '测试并置位'; 'clear' = '清空'
      'atomic_store' = '原子存储'; 'atomic_load' = '原子载入'; 'atomic_exchange' = '原子置换'
      'atomic_compare_exchange_weak' = '原子比较交换弱'
      'atomic_compare_exchange_strong' = '原子比较交换强'
      'atomic_fetch_add' = '原子取加'; 'atomic_fetch_sub' = '原子取减'
      'atomic_fetch_and' = '原子取与'; 'atomic_fetch_or' = '原子取或'; 'atomic_fetch_xor' = '原子取异或'
      'atomic_is_lock_free' = '原子无锁'
      'atomic_wait' = '原子等待'; 'atomic_notify_one' = '原子通知一个'; 'atomic_notify_all' = '原子通知全部'
      'atomic_thread_fence' = '线程栅栏'; 'atomic_signal_fence' = '信号栅栏'
      'kill_dependency' = '消除依赖'
      'memory_order_relaxed' = '内存序松弛'; 'memory_order_consume' = '内存序消费'
      'memory_order_acquire' = '内存序获取'; 'memory_order_release' = '内存序释放'
      'memory_order_acq_rel' = '内存序获取释放'; 'memory_order_seq_cst' = '内存序顺序一致'
      '_Atomic_address_as' = '_原子取地址为'
      '_Atomic_reinterpret_as' = '_原子重解释为'
      '_Atomic_wait_compare_16_bytes' = '_原子等待比较16字节'
      '_Atomic_wait_compare_non_lock_free' = '_原子等待比较非无锁'
      # 全局作用域 extern C 匿名枚举（与 vcruntime 共享）：真头在场会重定义 -> 改成汉语名（§17.19.18）
      # 同段里的全局函数（真头也定义 -> 重定义）与宏（宏体已含汉语 -> 宏名必须一起改，§16.24）
      '_Check_memory_order' = '_检查内存序'
      '_Atomic_thread_fence' = '_原子线程栅栏'
      '_INVALID_MEMORY_ORDER' = '_非法内存序'
      # 同名两份（我们抄的 + xatomic.h 借来的）造成的【歧义】-> 按 §17.19.12.1：把我们那份改中文名
      '_Check_load_memory_order' = '_检查载入内存序'
      '_Check_store_memory_order' = '_检查存储内存序'
      '_Init_spinlock_for_ref' = '_为引用初始化自旋锁'
      '_Store_and_unlock' = '_存储并解锁'
      '_Combine_cas_memory_orders' = '_合并CAS内存序'
      # 全局作用域 extern C 匿名枚举（与 vcruntime 共享）：真头在场会重定义 -> 枚举成员改成汉语名
      '_Atomic_memory_order_relaxed' = '_原子内存序松弛'
      '_Atomic_memory_order_consume' = '_原子内存序消费'
      '_Atomic_memory_order_acquire' = '_原子内存序获取'
      '_Atomic_memory_order_release' = '_原子内存序释放'
      '_Atomic_memory_order_acq_rel' = '_原子内存序获取释放'
      '_Atomic_memory_order_seq_cst' = '_原子内存序顺序一致'
      # §16.24 x 守卫步：这些宏的名字被守卫步加了 _ZH_ 前缀，而宏体里已有汉语 -> 两种写法成对登记
      '_ATOMIC_CHOOSE_INTRINSIC' = '_原子选择内建'
      '_ZH_ATOMIC_CHOOSE_INTRINSIC' = '_原子选择内建'
      '_ATOMIC_LOAD_ARM64' = '_原子载入ARM64'
      '_ZH_ATOMIC_LOAD_ARM64' = '_原子载入ARM64'
      '_ATOMIC_POST_LOAD_BARRIER_AS_NEEDED' = '_原子载入后栅栏按需'
      '_ZH_ATOMIC_POST_LOAD_BARRIER_AS_NEEDED' = '_原子载入后栅栏按需'
      '_ATOMIC_STORE_SEQ_CST_ARM' = '_原子存储顺序一致ARM'
      '_ZH_ATOMIC_STORE_SEQ_CST_ARM' = '_原子存储顺序一致ARM'
      '_ATOMIC_STORE_SEQ_CST_ARM64' = '_原子存储顺序一致ARM64'
      '_ZH_ATOMIC_STORE_SEQ_CST_ARM64' = '_原子存储顺序一致ARM64'
      '_ATOMIC_STORE_SEQ_CST_X86_X64' = '_原子存储顺序一致X86X64'
      '_ZH_ATOMIC_STORE_SEQ_CST_X86_X64' = '_原子存储顺序一致X86X64'
      '_ATOMIC_STORE_32_SEQ_CST_X86_X64' = '_原子存储32顺序一致X86X64'
      '_ZH_ATOMIC_STORE_32_SEQ_CST_X86_X64' = '_原子存储32顺序一致X86X64'
      '_ATOMIC_STORE_64_SEQ_CST_IX86' = '_原子存储64顺序一致IX86'
      '_ZH_ATOMIC_STORE_64_SEQ_CST_IX86' = '_原子存储64顺序一致IX86'
      '_ATOMIC_STORE_SEQ_CST' = '_原子存储顺序一致'
      '_ZH_ATOMIC_STORE_SEQ_CST' = '_原子存储顺序一致'
      '_ATOMIC_STORE_32_SEQ_CST' = '_原子存储32顺序一致'
      '_ZH_ATOMIC_STORE_32_SEQ_CST' = '_原子存储32顺序一致'
      '_ATOMIC_STORE_64_SEQ_CST' = '_原子存储64顺序一致'
      '_ZH_ATOMIC_STORE_64_SEQ_CST' = '_原子存储64顺序一致'
      '__LOAD_ACQUIRE_ARM64' = '__载入获取ARM64'
      '__STORE_RELEASE' = '__存储释放'
    ;
      '_Base' = '_基';

      '_Ref' = '_引用标记';

      '_Ptr' = '_指针';

      '_Locked_pointer' = '_已加锁指针';

      '_Lock_and_load' = '_加锁并载入';

      '_Unsafe_load_relaxed' = '_不安全松散载入';

      '_TVal' = '_值类型参数';

      '_TStorage' = '_存储类型参数';

      '_Spinlock' = '_自旋锁';

      '_Negate' = '_取负';

      '_Int128' = '_整数128';

      '_Atomic_wait_direct' = '_原子等待直达';

      '_Choose_atomic_base_t' = '_选原子基类型';

      '_Choose_atomic_base2_t' = '_选原子基类型2';

      '_Guard' = '_守卫';

      '_Local' = '_局部';
}
    data    = [ordered]@{}
    derive  = @( @('load','载入'), @('store','存储'), @('exchange','置换'),
                 @('compare_exchange_weak','比较交换弱'), @('compare_exchange_strong','比较交换强'),
                 @('fetch_add','取加'), @('fetch_sub','取减'), @('fetch_and','取与'),
                 @('fetch_or','取或'), @('fetch_xor','取异或'),
                 @('is_lock_free','无锁'), @('wait','等待'),
                 @('notify_one','通知一个'), @('notify_all','通知全部'),
                 @('test','测试'), @('test_and_set','测试并置位'), @('clear','清空') )
    extra   = ( @(
      '名域 标准 {',
      '',
      '// ---- 其余公开类型/常量的中文名（主类 原子 由派生层给出；英文原名一并保留）----',
      '使用 原子标志 = 细节::原子标志实现;',
      '使用 内存序 = 细节::内存序;',
      '模板 <类型名 元素> 使用 原子引用 = 细节::原子引用实现<元素>;',
      '内联 常量表达式 自动 内存序松弛 = 细节::内存序松弛;',
      '内联 常量表达式 自动 内存序消费 = 细节::内存序消费;',
      '内联 常量表达式 自动 内存序获取 = 细节::内存序获取;',
      '内联 常量表达式 自动 内存序释放 = 细节::内存序释放;',
      '内联 常量表达式 自动 内存序获取释放 = 细节::内存序获取释放;',
      '内联 常量表达式 自动 内存序顺序一致 = 细节::内存序顺序一致;',
      '',
      '',
      '// ---- 自由函数的中文名（英文原名仍可由 标准:: 的英文转发或 std:: 使用）----',
      '内联 空型 线程栅栏(内存序 序) 不抛出 { 细节::线程栅栏(序); }',
      '内联 空型 信号栅栏(内存序 序) 不抛出 { 细节::信号栅栏(序); }',
      '}  // 名域 标准'
    ) -join "`r`n" )
    tparam  = @{ decl = '模板 <类型名 元素>'; args = '<元素>' }
    tests = @(
      @('只引中文头','#包含 <原子>`n整数 主函数(){ 标准::原子<整数> 甲{0}; 甲.存储(3); 返回 甲.载入() == 3 ? 0 : 1; }'),
      @('与微软原头并存','#包含 <原子>`n#包含 <atomic>`n整数 主函数(){ 标准::原子<整数> 甲{0}; std::atomic<整数> 乙{0}; 甲.存储(1); 乙.store(1); 返回 甲.载入() == 乙.load() ? 0 : 1; }'),
      @('英文原名与中文名并用','#包含 <原子>`n整数 主函数(){ 标准::原子<整数> 甲{0}; 甲.store(5); 返回 甲.load() == 甲.载入() ? 0 : 1; }'),
      @('★守卫：内存序 / 原子标志 / 线程栅栏 的中文名都在','#包含 <原子>`n整数 主函数(){ 标准::原子标志 标; 标.清空(); 标准::线程栅栏(标准::内存序顺序一致); 返回 标.测试() ? 1 : 0; }')
    )
  }

  # ==========================================================================
  #  §17.19.20 抄 xatomic.h 成内部件（原子内部件）：销掉 <原子> 的借用面欠账
  #  · `memory_order` / `memory_order_*` / `_Atomic_address_as` / `_Atomic_counter_t`
  #    的**定义**就在 xatomic.h 里 —— 抄下来之后它们能在拷贝层落地（汉语名），
  #    不再只能"在公开层别名到 std"（§17.19.18 第 5 条的欠账就此销掉）。
  #  · 消费者侧（<原子> 等）的借用面切换按 §17.27.60.1 的批处理链同步（下一步做）。
  # ==========================================================================
  'xatomic.h' = @{
    zh      = '原子内部件'
    realInclude = @('atomic')
    noPub   = $true
    types   = [ordered]@{ 'memory_order'      = '内存序'
                          '_Atomic_counter_t' = '_原子计数器类型' }
    members = [ordered]@{ 'memory_order_relaxed' = '内存序松弛'
                          'memory_order_consume' = '内存序消费'
                          'memory_order_acquire' = '内存序获取'
                          'memory_order_release' = '内存序释放'
                          'memory_order_acq_rel' = '内存序获取释放'
                          'memory_order_seq_cst' = '内存序顺序一致'
                          '_Atomic_address_as' = '_原子取地址为' }
    data    = [ordered]@{}
    tests = @(
      @('只引中文头','#包含 <原子内部件>`n整数 主函数(){ 标准::细节::内存序 序 = 标准::细节::内存序松弛; 返回 序 == 标准::细节::内存序松弛 ? 0 : 1; }'),
      @('与微软原头并存','#包含 <原子内部件>`n#包含 <atomic>`n整数 主函数(){ std::memory_order 甲 = std::memory_order_relaxed; 标准::细节::内存序 乙 = 标准::细节::内存序松弛; 返回 (甲 == std::memory_order_relaxed && 乙 == 标准::细节::内存序松弛) ? 0 : 1; }'),
      @('★守卫：_原子取地址为 能用（借来的定义侧也要跟着改）','#包含 <原子内部件>`n整数 主函数(){ 整数 甲 = 7; 自动 针 = 标准::细节::_原子取地址为<整数>(甲); 返回 (*针 == 7) ? 0 : 1; }')
    )
  }

  # ==========================================================================
  #  §17.19.22 <iterator> 落地（第 10 个真汉语公开头）：核心头，实测此前完全缺失
  #  · 依赖：只 include <yvals_core.h> / <iosfwd> / <xutility>（xutility 已是我们的 通用内部件）
  #  · 多类型头 -> noPub + 手写 extra 公开层（同 <互斥量> / <原子> 的做法）
  #  · 第一批只收【本头自己定义的】12 个类型 + 7 个自由函数；成员名与助手类型留给后续批次
  # ==========================================================================
  'iterator' = @{
    zh      = '迭代器'
    realInclude = @('iterator')
    # MSVC 扩展 checked_array_iterator / unchecked_array_iterator 在【全局 stdext】里，
    #   真头也定义一份 -> 副本这份丢掉（否则重定义）。它们的中文名以后按 stdext 单独处理。
    # 正解不是丢定义：把副本里的【全局】 stdext 改名，别与真头撞（丢定义会让函数体失去类型）。
    copyFixes = @( @('_STDEXT_BEGIN', '名域 细节stdext {'),
                   @('_STDEXT_END', '}'),
                   @('_STDEXT ', '细节stdext::') )
    noPub   = $true
    types   = [ordered]@{
      'back_insert_iterator'     = '后插迭代器实现'
      'front_insert_iterator'    = '前插迭代器实现'
      'insert_iterator'          = '插入迭代器实现'
      'move_sentinel'            = '移动哨兵实现'
      'istream_iterator'         = '输入流迭代器实现'
      'ostream_iterator'         = '输出流迭代器实现'
      'istreambuf_iterator'      = '输入流缓冲迭代器实现'
      'ostreambuf_iterator'      = '输出流缓冲迭代器实现'
      'common_iterator'          = '公共迭代器实现'
      'counted_iterator'         = '计数迭代器实现'
    ;
                          '_Arrow_proxy' = '_箭头代理';
                          '_CIter' = '_常量迭代器';
                          '_Common_iterator_category_base' = '_公共迭代器类别基';
                          '_Common_iterator_pointer_type' = '_公共迭代器指针类型';
                          '_Counted_iterator_category_base' = '_计数迭代器类别基';
                          '_Counted_iterator_concept_base' = '_计数迭代器概念基';
                          '_Counted_iterator_value_type_base' = '_计数迭代器值类型基';
                          '_Istreambuf_proxy' = '_输入流缓冲代理';
                          '_Pointee_type' = '_所指类型';
                          '_Postfix_proxy' = '_后缀代理';
                          '_Proxy_base' = '_代理基';
                          '_Variantish' = '_类变体';
                          '_Variantish_empty_tag' = '_类变体空标记';
                          '_Variantish_state' = '_类变体状态';
                          '_Wrapped_iter' = '_包装迭代器';
                          '_Unwrapped' = '_解包';
                          'checked_array_iterator' = '检查数组迭代器';
                          'unchecked_array_iterator' = '未检查数组迭代器';
                          'container_type' = '容器类型';
                          'istream_type' = '输入流类型';
                          'ostream_type' = '输出流类型';
                          'streambuf_type' = '流缓冲类型';
}
    members = [ordered]@{
      'back_inserter'  = '后插器'; 'front_inserter' = '前插器'; 'inserter' = '插入器'
      # iter_move / iter_swap 是【隐藏友元】（只靠 ADL 找到）-> 本批不登记（限定调用会自我递归）
    ;
      '_Clear' = '_清空';
      '_Emplace_first' = '_就地构造首';
      '_Emplace_second' = '_就地构造次';
      '_Get_first' = '_取第一';
      '_Get_last' = '_取末';
      '_Get_second' = '_取次';
      '_Get_val' = '_取本值';
      '_Getval' = '_取原值';
      '_Inc' = '_递增';
      '_Peek' = '_窥视';
      '_Prevent_inheriting_unwrap' = '_阻止继承解包';
      '_Raw_clear' = '_裸清空';
      '_Same_sequence' = '_同序列';
      '_Seek_to' = '_定位到';
      '_Verify_range' = '_校验范围';
      'failed' = '失败';

      '_CDiff' = '_常量差类型';

      '_Equal' = '_相等';

      '_Verify_offset' = '_校验偏移';

      # 'count' = '计数';  # §17.19.52 公共成员名销账必须同时补 derive 英文转发，本轮先撤下
}
    data    = [ordered]@{}
    extra   = ( @(
      '名域 标准 {',
      '',
      '// ---- 公开类型的中文名（模板类按 <元素...> 转发；英文原名由 forwarder 补回）----',
      '模板 <类型名 容器> 使用 后插迭代器 = 细节::后插迭代器实现<容器>;',
      '模板 <类型名 容器> 使用 前插迭代器 = 细节::前插迭代器实现<容器>;',
      '模板 <类型名 容器> 使用 插入迭代器 = 细节::插入迭代器实现<容器>;',
      '模板 <类型名 哨兵> 使用 移动哨兵 = 细节::移动哨兵实现<哨兵>;',
      '模板 <类型名 元素, 类型名 特征 = std::char_traits<元素>> 使用 输入流迭代器 = 细节::输入流迭代器实现<元素, 特征>;',
      '模板 <类型名 元素, 类型名 特征 = std::char_traits<元素>> 使用 输出流迭代器 = 细节::输出流迭代器实现<元素, 特征>;',
      '模板 <类型名 元素, 类型名 特征 = std::char_traits<元素>> 使用 输入流缓冲迭代器 = 细节::输入流缓冲迭代器实现<元素, 特征>;',
      '模板 <类型名 元素, 类型名 特征 = std::char_traits<元素>> 使用 输出流缓冲迭代器 = 细节::输出流缓冲迭代器实现<元素, 特征>;',
      '模板 <类型名 迭代器类型, 类型名 哨兵类型> 使用 公共迭代器 = 细节::公共迭代器实现<迭代器类型, 哨兵类型>;',
      '模板 <类型名 迭代器类型> 使用 计数迭代器 = 细节::计数迭代器实现<迭代器类型>;',
      '',
      '// ---- 自由函数：中文名 + 英文原名，都指向同一份 细节:: 实现 ----',
      '模板 <类型名 容器> 声明类型(自动) 后插器(容器& 甲) { 返回 细节::后插器(甲); }',
      '模板 <类型名 容器> 声明类型(自动) back_inserter(容器& 甲) { 返回 细节::后插器(甲); }',
      '模板 <类型名 容器> 声明类型(自动) 前插器(容器& 甲) { 返回 细节::前插器(甲); }',
      '模板 <类型名 容器> 声明类型(自动) front_inserter(容器& 甲) { 返回 细节::前插器(甲); }',
      '模板 <类型名 容器, 类型名 位置类型> 声明类型(自动) 插入器(容器& 甲, 位置类型 位置) { 返回 细节::插入器(甲, 位置); }',
      '模板 <类型名 容器, 类型名 位置类型> 声明类型(自动) inserter(容器& 甲, 位置类型 位置) { 返回 细节::插入器(甲, 位置); }',
      '',
      '}  // 名域 标准'
    ) -join "`r`n" )
    tests = @(
      @('只引中文头','#包含 <迭代器>
#包含 <向量>
整数 主函数(){ 标准::向量<整数> 甲; 自动 针 = 标准::后插器(甲); *针 = 5; 返回 甲[0] == 5 ? 0 : 1; }'),
      @('与微软原头并存','#包含 <迭代器>
#包含 <iterator>
#包含 <向量>
整数 主函数(){ 标准::向量<整数> 甲; std::vector<整数> 乙; 自动 针甲 = 标准::后插器(甲); 自动 针乙 = std::back_inserter(乙); *针甲 = 1; *针乙 = 1; 返回 (甲[0] == 乙[0]) ? 0 : 1; }'),
      @('英文原名与中文名并用','#包含 <迭代器>
#包含 <向量>
整数 主函数(){ 标准::向量<整数> 甲; 自动 针 = 标准::back_inserter(甲); *针 = 7; 返回 甲[0] == 7 ? 0 : 1; }')
    )
  }

  # ==========================================================================
  #  §17.19.23 <version>（版本）：宏为主的标准头 —— 副本是"把真头引进来"的壳
  #  判据：特性测试宏（__cpp_lib_*）是【标准契约名】，用户按名字查特性 -> 不许改；
  #    所以这个头没有可改名的名字，"汉语化"体现为【中文头名可用】。
  #    台账里它与"深抄"分开计数（§17.19.21 的判据）。
  # ==========================================================================
  'version' = @{
    zh      = '版本'
    realInclude = @('version')
    noPub   = $true
    types   = [ordered]@{}
    members = [ordered]@{}
    data    = [ordered]@{}
    tests = @(
      @('只引中文头','#包含 <版本>`n静态断言(__cpp_lib_bit_cast >= 201806L, "");`n整数 主函数(){ 返回 0; }'),
      @('与微软原头并存','#包含 <版本>`n#包含 <version>`n整数 主函数(){ 返回 0; }')
    )
  }
  # ==========================================================================
  #  §17.19.23 <cerrno>（错误号）：同理（`errno` 是 C 宏，改了就断了 C 互操作）
  # ==========================================================================
  'cerrno' = @{
    zh      = '错误号'
    realInclude = @('cerrno')
    noPub   = $true
    types   = [ordered]@{}
    members = [ordered]@{}
    data    = [ordered]@{}
    tests = @(
      @('只引中文头','#包含 <错误号>`n整数 主函数(){ errno = 0; 返回 errno == 0 ? 0 : 1; }'),
      @('与微软原头并存','#包含 <错误号>`n#包含 <cerrno>`n整数 主函数(){ errno = 0; 返回 errno == 0 ? 0 : 1; }')
    )
  }

  # ==========================================================================
  #  §17.19.24 <iomanip>（格式化）：CRT 提供的操纵器【不能改名】—— 改名能编过、链不上
  #  · 实测：setw / setbase / setprecision / setiosflags / resetiosflags / get_money /
  #    put_money / get_time / put_time 在 <iomanip> 里都是 `_MRTIMP2` **声明**（定义在 CRT 导入库）
  #    -> 改名后编译通过、**链接失败**（LNK2019 未解析的外部符号 标准::细节::设宽度）。
  #    这是 §17.19.12.1 信号表里【第一类只有链接才现形】的：编译器校对看不见它，只有会链接的用例能抓。
  #  · 所以本头【零改名】：6 个助手类 dropTypes（用真头的，保证与 std 流互操作），
  #    11 个操纵器只在公开层给中文名，转发到 `std::`（真头在场，链接无忧）。
  # ==========================================================================
  'iomanip' = @{
    zh      = '格式化'
    realInclude = @('iomanip')
    noPub   = $true
    dropTypes = @('_Fillobj', '_Monobj', '_Timeobj', '_Quote_out', '_Quote_in', '_Smanip')
    types   = [ordered]@{}
    members = [ordered]@{}
    data    = [ordered]@{}
    extra   = ( @(
      '名域 标准 {',
      '',
      '// ---- 11 个操纵器的中文名：转发到 std::（它们是 CRT 契约名，改了就链不上）----',
      '模板 <类型名... 参数> 声明类型(自动) 设宽度(参数&&... 值) { 返回 std::setw(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> 声明类型(自动) 设填充(参数&&... 值) { 返回 std::setfill(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> 声明类型(自动) 设进制(参数&&... 值) { 返回 std::setbase(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> 声明类型(自动) 设精度(参数&&... 值) { 返回 std::setprecision(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> 声明类型(自动) 设标志(参数&&... 值) { 返回 std::setiosflags(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> 声明类型(自动) 重置标志(参数&&... 值) { 返回 std::resetiosflags(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> 声明类型(自动) 取货币(参数&&... 值) { 返回 std::get_money(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> 声明类型(自动) 放货币(参数&&... 值) { 返回 std::put_money(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> 声明类型(自动) 取时间格式(参数&&... 值) { 返回 std::get_time(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> 声明类型(自动) 放时间格式(参数&&... 值) { 返回 std::put_time(static_cast<参数&&>(值)...); }',
      '模板 <类型名... 参数> 声明类型(自动) 带引号(参数&&... 值) { 返回 std::quoted(static_cast<参数&&>(值)...); }',
      '',
      '}  // 名域 标准'
    ) -join "`r`n" )
    tests = @(
      @('只引中文头','#包含 <格式化>`n#包含 <字符串流>`n整数 主函数(){ 标准::输出字符串流 甲; 甲 << 标准::设宽度(5) << 42; 返回 甲.字符串() == "   42" ? 0 : 1; }'),
      @('与微软原头并存','#包含 <格式化>`n#包含 <iomanip>`n#包含 <字符串流>`n整数 主函数(){ 标准::输出字符串流 甲; std::ostringstream 乙; 甲 << 标准::设填充(字符(48)) << 7; 乙 << std::setfill(字符(48)) << 7; 返回 甲.字符串().尺寸() == 乙.str().size() ? 0 : 1; }'),
      @('英文原名与中文名并用','#包含 <格式化>`n#包含 <字符串流>`n整数 主函数(){ 标准::输出字符串流 甲; 甲 << 标准::设进制(16) << 255; 返回 甲.字符串() == "ff" ? 0 : 1; }')
    )
  }

}

# ---------------------------------------------------------------------------
#  跨头译名一致性检查（方案 §3.6.1 / §3.8.2，为什么要有它）
#
#  现实：译名目前按头各抄一遍（"共享表"还是过渡形态）。同一个英文名出现在多个条目里时，
#  只要有人在一处改了译名、别处忘了改，就会在【很后面】才以"某某里没有名为某某的成员"
#  的形式报出来 —— 实测已经连续踩了三例（<mutex> -> <condition_variable> -> <shared_mutex>）。
#
#  与其靠人记得同步，不如让机器开口：同一个英文名（同一类：types / members）
#  在任意两个条目里的中文译名必须【一模一样】。
#
#  ⚠ 确实有"同名不同义"的合法情形，允许在 $ZH_NAME_EXCEPTIONS 里登记豁免，
#     但豁免要写理由 —— 默认是"必须一致"。
# ---------------------------------------------------------------------------
# ---------------------------------------------------------------------------
#  -ExportJson：把整张表以 JSON 输出后直接退出（供 tools\make_zh_usage.ps1
#  生成【用法对照表】用）。
#
#  为什么用这个开关，而不是让文档生成器去"正则扫表"：
#    扫描正则会漂移 —— 本项目已经栽过好几次（§16.31 的键名漏 `.`、§16.36 的假残留）。
#    这里导出的是 PowerShell **自己解析出来的同一张表** —— 单一事实来源，天然不漂移。
# ---------------------------------------------------------------------------
if ($ExportJson) { $H | ConvertTo-Json -Depth 8; exit 0 }

$ZH_NAME_EXCEPTIONS = @{
    # 登记必须写理由 —— 默认是"同一个英文名必须同一个译名"。
    'members/reset' = 'bitset::reset 是"把某一位清零"（复位）；optional::reset 是"销毁所存的值"（重置）。同名不同义，允许两个译名。'
    'members/top'   = 'stack::top 是"栈顶"，priority_queue::top 是"堆顶" —— 两种数据结构不同，允许两个译名。'
}
$zhSeen  = @{}
$zhClash = @()
foreach ($en in ($H.Keys | Sort-Object)) {
    foreach ($kind in @('types', 'members', 'data')) {
        if (-not $H[$en].ContainsKey($kind)) { continue }
        foreach ($k in $H[$en][$kind].Keys) {
            $zh = $H[$en][$kind][$k]
            $id = "$kind/$k"
            if ($ZH_NAME_EXCEPTIONS.ContainsKey($id)) { continue }
            if (-not $zhSeen.ContainsKey($id)) {
                $zhSeen[$id] = @{ zh = $zh; owners = @($en) }
            } elseif ($zhSeen[$id].zh -ne $zh) {
                $zhClash += ("  [$kind] '{0}': {1} 译作 '{2}'，但 {3} 译作 '{4}'" -f `
                    $k, ($zhSeen[$id].owners -join '/'), $zhSeen[$id].zh, $en, $zh)
            } else {
                if ($zhSeen[$id].owners -notcontains $en) { $zhSeen[$id].owners += $en }
            }
        }
    }
}
$shared = @($zhSeen.Values | Where-Object { $_.owners.Count -gt 1 })
Write-Host ("跨头译名检查: 共 {0} 个英文名，其中 {1} 个跨了多个头" -f $zhSeen.Count, $shared.Count)
if ($zhClash.Count) {
    Write-Host "❌ 跨头译名不一致（同一个英文名、两个译名）:" -ForegroundColor Red
    $zhClash | ForEach-Object { Write-Host $_ -ForegroundColor Red }
    Write-Host '  修法：统一成同一个译名；若确实同名不同义，到 $ZH_NAME_EXCEPTIONS 登记并写理由。' -ForegroundColor Yellow
    throw "跨头译名不一致，先修表再生成"
}

# ---------------------------------------------------------------------------
#  §17.27.54 反向守卫：**一个译名只对应一个英文名**。
#
#  为什么需要（实测，而且是最阴的一种）：`<any>` 的成员 `_Emplace` 与自由函数
#  `_Construct_in_place` 都译作 `_就地构造`，而 `_Emplace` 的**正文里**恰好调用了
#  `_STD _Construct_in_place(...)`（原件 any:315/322）。两个名字一样之后，
#  类作用域查找**先命中成员自己** -> 变成自我递归模板：
#  **既不是编译错误，产品测试也照不出来**（返回类型/副作用都"对得上"）。
#  所以必须机器拦住，不能靠记性（判据来自 §17.27.54）。
#
#  判据：同一 kind（types / members / data）下，一个译名只能对应一个英文名。
#  ⚠ 跨 kind 不拦：类型名在名域作用域、成员名在类作用域，互不遮蔽。
#  ⚠ 允许清单按【译名】登记，并逐个列出允许的英文名：
#     连"又多了第三个英文名"也要报 —— 否则白名单会变成永久缺口。
# ---------------------------------------------------------------------------
$ZH_REVERSE_EXCEPTIONS = @{
    '_非法内存序' = @{ names = @('_INVALID_MEMORY_ORDER')
                 why   = '_ATOMIC_* 族宏的两种写法（守卫步加 _ZH_ 前缀），同一个宏（§17.19.18 第 7 条）。' }
    '_原子选择内建' = @{ names = @('_ATOMIC_CHOOSE_INTRINSIC', '_ZH_ATOMIC_CHOOSE_INTRINSIC')
                 why   = '_ATOMIC_* 族宏的两种写法（守卫步加 _ZH_ 前缀），同一个宏（§17.19.18 第 7 条）。' }
    '_原子载入ARM64' = @{ names = @('_ATOMIC_LOAD_ARM64', '_ZH_ATOMIC_LOAD_ARM64')
                 why   = '_ATOMIC_* 族宏的两种写法（守卫步加 _ZH_ 前缀），同一个宏（§17.19.18 第 7 条）。' }
    '_原子载入后栅栏按需' = @{ names = @('_ATOMIC_POST_LOAD_BARRIER_AS_NEEDED', '_ZH_ATOMIC_POST_LOAD_BARRIER_AS_NEEDED')
                 why   = '_ATOMIC_* 族宏的两种写法（守卫步加 _ZH_ 前缀），同一个宏（§17.19.18 第 7 条）。' }
    '_原子存储顺序一致ARM' = @{ names = @('_ATOMIC_STORE_SEQ_CST_ARM', '_ZH_ATOMIC_STORE_SEQ_CST_ARM')
                 why   = '_ATOMIC_* 族宏的两种写法（守卫步加 _ZH_ 前缀），同一个宏（§17.19.18 第 7 条）。' }
    '_原子存储顺序一致ARM64' = @{ names = @('_ATOMIC_STORE_SEQ_CST_ARM64', '_ZH_ATOMIC_STORE_SEQ_CST_ARM64')
                 why   = '_ATOMIC_* 族宏的两种写法（守卫步加 _ZH_ 前缀），同一个宏（§17.19.18 第 7 条）。' }
    '_原子存储顺序一致X86X64' = @{ names = @('_ATOMIC_STORE_SEQ_CST_X86_X64', '_ZH_ATOMIC_STORE_SEQ_CST_X86_X64')
                 why   = '_ATOMIC_* 族宏的两种写法（守卫步加 _ZH_ 前缀），同一个宏（§17.19.18 第 7 条）。' }
    '_原子存储32顺序一致X86X64' = @{ names = @('_ATOMIC_STORE_32_SEQ_CST_X86_X64', '_ZH_ATOMIC_STORE_32_SEQ_CST_X86_X64')
                 why   = '_ATOMIC_* 族宏的两种写法（守卫步加 _ZH_ 前缀），同一个宏（§17.19.18 第 7 条）。' }
    '_原子存储64顺序一致IX86' = @{ names = @('_ATOMIC_STORE_64_SEQ_CST_IX86', '_ZH_ATOMIC_STORE_64_SEQ_CST_IX86')
                 why   = '_ATOMIC_* 族宏的两种写法（守卫步加 _ZH_ 前缀），同一个宏（§17.19.18 第 7 条）。' }
    '_原子存储顺序一致' = @{ names = @('_ATOMIC_STORE_SEQ_CST', '_ZH_ATOMIC_STORE_SEQ_CST')
                 why   = '_ATOMIC_* 族宏的两种写法（守卫步加 _ZH_ 前缀），同一个宏（§17.19.18 第 7 条）。' }
    '_原子存储32顺序一致' = @{ names = @('_ATOMIC_STORE_32_SEQ_CST', '_ZH_ATOMIC_STORE_32_SEQ_CST')
                 why   = '_ATOMIC_* 族宏的两种写法（守卫步加 _ZH_ 前缀），同一个宏（§17.19.18 第 7 条）。' }
    '_原子存储64顺序一致' = @{ names = @('_ATOMIC_STORE_64_SEQ_CST', '_ZH_ATOMIC_STORE_64_SEQ_CST')
                 why   = '_ATOMIC_* 族宏的两种写法（守卫步加 _ZH_ 前缀），同一个宏（§17.19.18 第 7 条）。' }
    '_标记' = @{ names = @('_Tag', '_Mark')
                 why   = '两处都是不可见的实现细节名（nullopt 的 _Tag / 另一处的 _Mark），组合探针 73 头同引实测无碍。' }
    '_代理分配器类型' = @{ names = @('_Alproxy_ty', '_Alproxy_type')
                 why   = '同一别名的两种 MSVC 拼写（deque 与 list 各写各的），同一个实体。' }
    '_等值区间' = @{ names = @('_Eqrange', '_Equal_range')
                 why   = '同一查表助手两种拼写（xtree 与 xhash 各写各的），同一个概念。' }
    '_取容器' = @{ names = @('_Getcont', '_Get_container')
                 why   = '同一概念两种写法（成员版 _Getcont 与自由版 _Get_container），组合探针 73 头同引实测无碍。' }
    '_造迭代器' = @{ names = @('_Make_iterator', '_Make_iter')
                 why   = '同一助手两种拼写（vector 与 forward_list 各写各的）。' }
    '释放' = @{ names = @('deallocate', 'release')
                 why   = '两个都是 std 契约名（allocator::deallocate / unique_lock、shared_lock、semaphore 的 release），
                          各自是**不同类**的成员 -> 类作用域互不可见；组合探针 73 头同引实测无碍。
                          ⚠ 判据：白名单只收"类作用域不共现"的情形；凡【同一类】里两个名字撞译名，一律照报（那才是静默遮蔽）。' }
}
$zhReverse = @{}
foreach ($en in ($H.Keys | Sort-Object)) {
    foreach ($kind in @('types', 'members', 'data')) {
        if (-not $H[$en].ContainsKey($kind)) { continue }
        foreach ($k in $H[$en][$kind].Keys) {
            $key = "$kind|" + $H[$en][$kind][$k]
            if (-not $zhReverse.ContainsKey($key)) { $zhReverse[$key] = @() }
            if ($zhReverse[$key] -notcontains $k) { $zhReverse[$key] += $k }
        }
    }
}
$zhReverseClash = @()
foreach ($key in ($zhReverse.Keys | Sort-Object)) {
    $names = @($zhReverse[$key] | Sort-Object)
    if ($names.Count -le 1) { continue }
    $parts = $key -split '\|', 2
    $zh    = $parts[1]
    if ($ZH_REVERSE_EXCEPTIONS.ContainsKey($zh)) {
        $allowed = @($ZH_REVERSE_EXCEPTIONS[$zh].names)
        $extra   = @($names | Where-Object { $allowed -notcontains $_ })
        if ($extra.Count -eq 0) { continue }
        $zhReverseClash += ("  [{0}] '{1}'：白名单外又多出 {2}（§17.27.54 白名单只认 {3}）" -f `
            $parts[0], $zh, ($extra -join ' / '), ($allowed -join ' / '))
        continue
    }
    $zhReverseClash += ("  [{0}] '{1}' 同时是 {2} 的译名" -f $parts[0], $zh, ($names -join ' / '))
}
Write-Host ("译名唯一性检查（§17.27.54）: 共 {0} 个译名，撞车 {1} 条" -f $zhReverse.Count, $zhReverseClash.Count)
if ($zhReverseClash.Count) {
    Write-Host "❌ 译名撞车（同一个译名、两个英文名）:" -ForegroundColor Red
    $zhReverseClash | ForEach-Object { Write-Host $_ -ForegroundColor Red }
    Write-Host '  危害：类作用域会遮蔽名域作用域 -> 可能是「静默自我递归」（不是编译错误，测试也照不出）。' -ForegroundColor Yellow
    Write-Host '  修法：改掉其中一个译名；确属同一实体，到 $ZH_REVERSE_EXCEPTIONS 登记译名 + 允许的英文名 + 理由。' -ForegroundColor Yellow
    throw "译名撞车，先修表再生成"
}

# ---------------------------------------------------------------------------
#  §16.52.3 守卫：derive 的**中文目标**必须在"基类所在的抄来那层"里真的存在。
#
#  为什么需要（实测栽过）：`derive @('emplace','就地构造')` 发的是
#      `声明类型(自动) emplace(参数&&... 值) { 返回 基类::就地构造(...); }`
#  它【遮住了】基类继承来的英文 `emplace`，然后去调一个**不存在的中文名** ——
#  于是 `甲.emplace(1)` 编不过 = 英文用法回归；而且转发器是模板，
#  没人实例化就不查基类名 -> 一条测试不写就【完全静默】（§16.52.3）。
#
#  判据：中文名要么出现在**本条目抄来那层**的正文里，
#        要么由**基类那一侧的改名表**产生（`zhIncludes` 传递闭包里的
#        types/members/data + $INTERNAL_NAMES）。
#        只看表、不看别的产品的生成结果 —— 这样它就【不依赖生成顺序】，
#        不会因为"兄弟产品还是上一轮的"而误报。
# ---------------------------------------------------------------------------
$ZH_ENTRY_OF = @{}                       # 产品名 -> 条目键（zhIncludes 的值是产品名）
foreach ($k in $H.Keys) { if ($H[$k].ContainsKey('zh')) { $ZH_ENTRY_OF[$H[$k].zh] = $k } }
$ZH_SCOPE_CACHE = @{}
function Get-ZhNameScope([string] $entryKey) {
    if ($ZH_SCOPE_CACHE.ContainsKey($entryKey)) { return $ZH_SCOPE_CACHE[$entryKey] }
    $scope = New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($v in $INTERNAL_NAMES.Values) { [void]$scope.Add($v) }
    $seen = @{}
    $queue = New-Object System.Collections.Queue
    $queue.Enqueue($entryKey)
    while ($queue.Count) {
        $e = [string]$queue.Dequeue()
        if (-not $e -or $seen.ContainsKey($e)) { continue }
        $seen[$e] = $true
        if (-not $H.ContainsKey($e)) { continue }
        foreach ($kind in @('types', 'members', 'data')) {
            if (-not $H[$e].ContainsKey($kind)) { continue }
            foreach ($v in $H[$e][$kind].Values) { [void]$scope.Add([string]$v) }
        }
        if ($H[$e].ContainsKey('zhIncludes')) {
            foreach ($prod in $H[$e]['zhIncludes'].Values) {
                if ($ZH_ENTRY_OF.ContainsKey($prod)) { $queue.Enqueue([string]$ZH_ENTRY_OF[$prod]) }
            }
        }
    }
    $ZH_SCOPE_CACHE[$entryKey] = $scope
    return $scope
}
$derMissing = @()

# ---------------------------------------------------------------------------
#  关键词表检查：中文名绝不能是关键词（实测踩到，且极难从报错看出是命名问题）
#
#  <bitset> 里我把 flip 译作「取反」，而关键词表里：
#      ZH_OPERATOR_KEYWORD(取反, tilde)   // 取反 = compl = ~
#  于是 `取反()` 被词法成 `~()`，编译器报的是
#      error: '~' 之后需要给出类名来指明析构函数
#  —— 报的是"析构函数"，跟命名八竿子打不着，看半天看不出来。
#
#  判据：ChineseKeywords.def 里的中文词一律不能当标识符（方案 §2.2 第一步就是查它，
#        但"我记得查"不算数 —— 这里改成机器查）。
# ---------------------------------------------------------------------------
$kwFile = Join-Path $root 'LLVM-main\clang\include\clang\Basic\ChineseKeywords.def'
$kwList = @{}
if (Test-Path $kwFile) {
    foreach ($line in [System.IO.File]::ReadAllLines($kwFile)) {
        if ($line -notmatch 'KEYWORD') { continue }
        # ZH_KEYWORD(英文, 中文, FLAGS)     —— 中文是第 2 个参数
        foreach ($m in [regex]::Matches($line, 'ZH_KEYWORD\s*\(\s*[^,]+,\s*([^,]+),')) {
            $kwList[$m.Groups[1].Value.Trim()] = $line.Trim()
        }
        # ZH_OPERATOR_KEYWORD(中文, 英文)   —— 中文是第 1 个参数
        foreach ($m in [regex]::Matches($line, 'ZH_OPERATOR_KEYWORD\s*\(\s*([^,]+),')) {
            $kwList[$m.Groups[1].Value.Trim()] = $line.Trim()
        }
    }
}
$kwBad = @(); $kwChecked = 0

# ---------------------------------------------------------------------------
#  关键词检查【扩展】：模板参数名（§16.9 的实证缺口）
#  xsmf_control.h 的 tparam 里我把参数包命名为「类型」—— 那是 class 的关键词，
#  生成的派生层直接语法错（缺少 identifier）。而当初的关键词检查只扫
#  zh/pub/types/members/data，没扫 tparam。
#
#  ⚠ 只查【模板参数名】，不查 tparam.decl 全文、也不查 extra/deriveExtra：
#     那些地方本来就该出现中文关键词（模板/类型名/返回/公开…），拿关键词扫它们是纯噪音。
#     参数名的取法：decl 里 <...> 内按 ',' 切开，每段最后一个词就是参数名
#     （先去掉 '...' 与 '= 默认值'）。
# ---------------------------------------------------------------------------
foreach ($en in ($H.Keys | Sort-Object)) {
    $sp = $H[$en]
    if (-not $sp.ContainsKey('tparam')) { continue }
    $decl = [string]$sp.tparam.decl
    $lt = $decl.IndexOf('<'); $gt = $decl.LastIndexOf('>')
    if ($lt -lt 0 -or $gt -le $lt) { continue }
    $inner = $decl.Substring($lt + 1, $gt - $lt - 1)
    foreach ($piece in ($inner -split ',')) {
        $p = $piece.Trim()
        if ($p -match '=') { $p = ($p -split '=')[0].Trim() }
        $p = $p.Replace('...', ' ').Trim()
        $toks = @($p -split '\s+' | Where-Object { $_ -ne '' })
        if ($toks.Count -eq 0) { continue }
        $pname = $toks[$toks.Count - 1]
        if ($kwList.ContainsKey($pname)) {
            Write-Host ("  ❌ 关键词检查[模板参数名] {0} 的参数名 '{1}' 是关键词（{2}）" -f $en, $pname, $kwList[$pname]) -ForegroundColor Red
            $kwBad += ("  [tparam] {0} 的参数名 '{1}' 是关键词：{2}" -f $en, $pname, $kwList[$pname])
        }
    }
}
foreach ($en in ($H.Keys | Sort-Object)) {
    $names = @($H[$en].zh)
    if ($H[$en].ContainsKey('pub')) { $names += $H[$en].pub }
    foreach ($kind in @('types', 'members', 'data')) {
        if ($H[$en].ContainsKey($kind)) { $names += @($H[$en][$kind].Values) }
    }
    foreach ($n in $names) {
        $kwChecked++
        if ($kwList.ContainsKey($n)) { $kwBad += ("  [{0}] '{1}' 是关键词：{2}" -f $en, $n, $kwList[$n]) }
        # -----------------------------------------------------------------------
        #  铁律④：**中文标识符不得以数字开头**（§16.42）。
        #
        #  以前这条只被"编译器会报错"隐含守住 —— 但那要等到单头测试才炸，
        #  而且报的是语法错，看不出是命名规则问题。这里显式挡住，理由一眼可见。
        #  （实测来源：`字符16位` 不能写 `16位字符`；`_容器基类0` 合法，因为数字不在开头。）
        # -----------------------------------------------------------------------
        if ($n -match '^[0-9]') {
            $kwBad += ("  [{0}] '{1}' 以数字开头 —— 铁律④：中文标识符不得以数字开头" -f $en, $n)
        }
    }
}
# ---------------------------------------------------------------------------
#  §17.19.22 关键词检查【补】手写块（extra / prologue）——
#  实测（第 99 轮）：`extra` 里写了 `模板 <类型名 类型>`（`类型` 是 class 的关键词），
#  上面那圈【只扫表里的名字】，一直到编译才报「缺少 identifier」。
#  判据：手写块也要过同一套关键词检查。这里只看两种"名字位置"的形态：
#      · 类型名 <关键词>      （模板形参名；上一轮就是这里踩的）
#      · 使用 <关键词> =      （别名左端）
# ---------------------------------------------------------------------------
foreach ($en2 in ($H.Keys | Sort-Object)) {
    foreach ($field in @('extra', 'prologue')) {
        if (-not $H[$en2].ContainsKey($field)) { continue }
        $txt = [string]$H[$en2][$field]
        foreach ($kw in $kwList.Keys) {
            if ($txt -match ('类型名\s*(?:\.\.\.)?\s*' + [regex]::Escape($kw) + '(?![\w\u4e00-\u9fff])')) {
                $kwBad += ("  [{0}] {1} 里 '{2}' 在【模板形参名】位置 —— 它是关键词（{3}）" -f $en2, $field, $kw, $kwList[$kw])
            }
            if ($txt -match ('使用\s+' + [regex]::Escape($kw) + '\s*=')) {
                $kwBad += ("  [{0}] {1} 里 '{2}' 在【别名左端】位置 —— 它是关键词（{3}）" -f $en2, $field, $kw, $kwList[$kw])
            }
        }
    }
}
Write-Host ("关键词表检查: 表里 {0} 个关键词，查了本表 {1} 个中文名" -f $kwList.Count, $kwChecked)
if ($kwBad.Count) {
    Write-Host "❌ 有中文名撞上关键词（会词法成运算符/语句，报错完全不像命名问题）:" -ForegroundColor Red
    $kwBad | ForEach-Object { Write-Host $_ -ForegroundColor Red }
    throw "中文名撞关键词，先改名再生成"
}

# ---------------------------------------------------------------------------
#  守卫（§16.1②）：extra 里【手写的对外类】必须覆盖条目的 members 表。
#  实测 5 次栽在这：shared_mutex 编造了不存在的成员、unordered_set 漏了 桶数/负载因子、
#  set 根本没写转发、thread 名域没再出口中文名、span 名字不一致。
#  extra 是手写层，不受任何机制约束 —— 所以在这里把它和 members 表对一遍。
#  ⚠ 只警告不 throw：有些类（如 多重集合）语义上不需要全部成员，要人看一眼。
# ---------------------------------------------------------------------------
foreach ($h2 in $H.Keys) {
    $sp = $H[$h2]
    if (-not $sp.ContainsKey('extra')) { continue }
    $ex = [string]$sp.extra
    # extra 里每个"类型 X : 公开 细节::..."的类，检查它是否覆盖 members 的中文名
    foreach ($cm in [regex]::Matches($ex, '(?m)^\s*类型\s+(\S+)\s*:\s*公开')) {
        $cls = $cm.Groups[1].Value
        $start = $cm.Index
        $end = $ex.IndexOf("`n};", $start); if ($end -lt 0) { $end = $ex.Length }
        $body = $ex.Substring($start, $end - $start)
        $missing = @()
        foreach ($k in $sp.members.Keys) {
            $zhN = $sp.members[$k]
            if ($body -notmatch [regex]::Escape($zhN)) { $missing += $zhN }
        }
        if ($missing.Count) {
            Write-Host ("  · 差异清单[手写层] {0} 的 extra 类 {1} 缺: {2}" -f $h2, $cls, ($missing -join ' '))
        }
    }
}
$spec = $H[$Header]
if (-not $spec) { throw "表里没有 $Header —— 先在 make_zhstdlib2.ps1 的表里加一条" }

$srcPath = Join-Path $vsInc $Header
$isShell = [bool]$spec.shell
$shellText = ''
if ($isShell) {
    # ------------------------------------------------------------------------
    #  §17.19 丁类薄壳：本头【没有微软原头可抄】。
    #    `<string>` 的全部内容已经在【字符串内部件】里了（步骤 1 抄好并验证过），
    #    所以薄壳只做两件事：① 包含内部件；② 派生层把英文原名补回来。
    #  「原头 = 内部件」（§17.19 第 4 条）：下面的宏扫描 / 三把尺 / 乙探针
    #    都拿【内部件产物】当对照物，所以 $srcPath 改指内部件产物。
    # ------------------------------------------------------------------------
    if (-not $spec.shellHost)     { throw "薄壳条目必须写 shellHost（内部件产物名）" }
    if (-not $spec.shellGuard)    { throw "薄壳条目必须写 shellGuard（包含守卫宏名）" }
    if (-not $spec.shellIncludes) { throw "薄壳条目必须写 shellIncludes（要包含的内部件，有序）" }
    $srcPath = Join-Path $out ([string]$spec.shellHost)
    if (-not (Test-Path $srcPath)) { throw "薄壳的内部件产物不存在：$srcPath（先做内部件）" }
    $incl = (@($spec.shellIncludes) | ForEach-Object { "#include <$_>" }) -join "`r`n"
    $shellText = @"
// <$($spec.zh)>（§17.19 丁类薄壳）—— 本头【没有微软原头可抄】：对应英文头的全部内容
//   已经在 <$($spec.shellHost)> 里（步骤 1 抄好并验证过）。本文件只做两件事：
//     ① 把内部件包含进来；② 在【中文的基础上】派生，把英文原名补回来（本文件后半段）。
//   ⚠ 派生层由生成器插在下面这个守卫 #endif 之前，所以本文件必须有且只有一个 #endif。
#ifndef $($spec.shellGuard)
#define $($spec.shellGuard)
$incl

#endif // $($spec.shellGuard)
"@
}
$text = if ($isShell) { $shellText } else { [System.IO.File]::ReadAllText($srcPath) }
$origLines = ([System.IO.File]::ReadAllLines($srcPath)).Count
Write-Host $(if ($isShell) { "=== 步骤 2：<$($spec.zh)>（§17.19 薄壳：无原头，站在 <$($spec.shellHost)> 上，$origLines 行）===" } else { "=== 步骤 2：<$($spec.zh)>（源 <$Header>, $origLines 行）===" }) -ForegroundColor Cyan

# ---------------------------------------------------------------------------
if (-not $isShell) {
# ---------------------------------------------------------------------------
#  ⚠ §17.19：下面这一整段（步 0 ~ 步 5）是【抄原头】的流水线：读到的原头 -> 改名 -> 校对。
#    薄壳条目没有原头可抄，整段跳过（它的 $text 已在上面合成好）。
#    注意这一段里定义的 4 个辅助函数（Remove-OperatorDefs / Remove-ClassDef /
#    Get-RenamePattern / Remove-StdQualifier）都【只在本段内使用】—— 已核对，包起来安全。
# ---------------------------------------------------------------------------
#  步 0：把 `#include <英文头>` 换成我们【已经抄好】的 `#include <汉语头>`
#
#  为什么必须这么做（实测，<condition_variable>）：MSVC 的 <condition_variable> 里
#  `_Ptr->_Mymtx()` 的 `_Ptr` 是 `shared_ptr<mutex>`，而 `mutex::_Mymtx()` 是【私有】的，
#  微软只对【真实的 std::condition_variable_any】开友元。我们那个头第 17 行
#  `#include <mutex>` 拉进来的是微软的真 <mutex>，于是我们的类碰到了人家的私有成员：
#      error: '_Mymtx' 是 'std::_Mutex_base' 的私有成员
#  这是方案 §3.6 那个 friend 问题的【反向形态】：不是"我的 friend 指不到对方"，
#  而是"我引用了别人家的类型，人家的 friend 不认识我"。
#  修法：让它包含【我们自己的】<互斥量> —— 那一份里的 friend 已经跟着改成了
#  `friend 条件变量任意实现;`，两边同处 标准::细节，友元自然对上。
#
#  ⚠ 只对【已经抄完并通过验证】的头开这个开关（否则会 include 到不存在的文件）。
#     所以这是按条目选择的 `zhIncludes` 表，不是全局替换。
# ---------------------------------------------------------------------------
if ($spec.zhIncludes) {
    foreach ($en in @($spec.zhIncludes.Keys)) {
        $zhInc = $spec.zhIncludes[$en]
        $before0 = $text
        $text = $text.Replace("#include <$en>", "#include <$zhInc>")
        if ($text -ne $before0) {
            Write-Host "  步0 包含改名 <$en> -> <$zhInc>"
        } else {
            Write-Host "  步0 ⚠ 未找到 #include <$en>" -ForegroundColor Yellow
        }
    }
}
# ---------------------------------------------------------------------------
#  步 0b：真头包含（realInclude）+ 丢掉抄来的异常类（dropTypes）
#
#  为什么需要（<optional> 是第一个用户）：
#    一个头里常常【混着两类东西】：
#      · 值类型（std::optional）                 -> 可以抄+派生，能有中文成员名
#      · 异常类型（std::bad_optional_access）    -> 身份参与语义，铁律 4 要求必须是 std 的那个
#    整个头都抄的话，_Throw_bad_optional_access() 抛的是【我们抄来那个类】，
#    用户写 catch (std::bad_optional_access&) 永远抓不到。
#
#  办法两步：
#    realInclude  把【微软原头】也包含进来 -> 真的 std::bad_optional_access 存在了
#    dropTypes    把抄来那份【异常类的定义删掉】-> 本文件里的 bad_optional_access
#                 就靠 `使用 名域 std;` 解析到真的那个，异常自然就是同一个类型
#
#  ⚠ dropTypes 只适合"简单异常类"。删除用花括号配对实现，
#     不处理字符串/注释里的花括号 —— 对异常类足够，别拿它删大东西。
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
#  §16.16：dropTypes 只丢类定义不够 —— 为这个类写的【自由运算符/函数】也要一起丢。
#  实测（xpolymorphic_allocator.h）：丢掉 memory_resource 之后，
#    多态分配器:299:36: error: 重载运算符 '==' 的使用有歧义（memory_resource 和 memory_resource）
#  因为拷贝里还留着 operator==(const memory_resource&, const memory_resource&)，
#  而 realInclude 带来的真头里也有一份 -> 两份同时可见（细节::pmr 有 使用 名域 std::pmr;）-> 歧义。
#
#  做法：对每个被丢的类名，凡是以 operator 开头且签名里出现该类名的行，
#  从该处起用【花括号配对】删掉整个定义块。
# ---------------------------------------------------------------------------
function Remove-OperatorDefs {
    param([string]$Text, [string]$Name, [ref]$Count)
    $rx = [regex]('(?m)^[^\r\n]*\boperator\b[^\r\n]*\b' + [regex]::Escape($Name) + '\b')
    $removed = 0
    while ($true) {
        $m = $rx.Match($Text)
        if (-not $m.Success) { break }
        $i = $Text.IndexOf('{', $m.Index)
        if ($i -lt 0) { break }
        $depth = 0; $j = $i
        while ($j -lt $Text.Length) {
            $ch = $Text[$j]
            if ($ch -eq '{') { $depth++ }
            elseif ($ch -eq '}') { $depth--; if ($depth -eq 0) { break } }
            $j++
        }
        if ($j -ge $Text.Length) { break }
        $end = $j + 1
        while ($end -lt $Text.Length -and ($Text[$end] -eq ';' -or $Text[$end] -eq "`r" -or $Text[$end] -eq "`n" -or $Text[$end] -eq ' ')) { $end++ }
        $start = $m.Index
        while ($start -gt 0 -and $Text[$start - 1] -ne "`n") { $start-- }
        $Text = $Text.Substring(0, $start) + $Text.Substring($end)
        $removed++
    }
    if ($removed -gt 0) { $Count.Value += $removed }
    return $Text
}

function Remove-ClassDef {
    param([string]$Text, [string]$Name, [ref]$Count)
    # ⚠ 类名和 class 之间常夹着宏/说明符：原文是 `class _NODISCARD bad_optional_access`。
    #   原来写成 `class\s+NAME` 会【匹配不到】-> dropTypes 静默什么都没删（实测踩到），
    #   于是异常类还在，_Throw_xxx() 抛的是抄来那个类 -> catch(std::xxx&) 永远抓不到。
    $rx = [regex]('(?m)^[^\r\n]*\b(?:class|struct)\s+[^;{\r\n]*?' + [regex]::Escape($Name) + '\b[^\r\n]*\{')
    # §17.11.3 续：**同名可能有多个定义**（主模板 + 若干特化）。
    #   实测 `char_traits` 有 7 处（主模板 + char16_t/char32_t/wchar_t/unsigned short/char/char8_t 特化）；
    #   原来这里只 `Match` 一次 -> 只删掉第一个，剩下的特化与真头重定义：
    #       error: 重定义（名字） 'char_traits<char16_t>'
    #   所以像 `Remove-OperatorDefs` 那样**循环删到没有为止**。
    while ($true) {
    $m = $rx.Match($Text)
    if (-not $m.Success) { break }
    $i = $Text.IndexOf('{', $m.Index)
    $depth = 0; $j = $i
    while ($j -lt $Text.Length) {
        $ch = $Text[$j]
        if ($ch -eq '{') { $depth++ }
        elseif ($ch -eq '}') { $depth--; if ($depth -eq 0) { break } }
        $j++
    }
    if ($j -ge $Text.Length) { return $Text }
    $end = $j + 1
    while ($end -lt $Text.Length -and ($Text[$end] -eq ';' -or $Text[$end] -eq ' ' -or $Text[$end] -eq "`r" -or $Text[$end] -eq "`n")) { $end++ }
    $Count.Value++
    # -----------------------------------------------------------------------
    #  §17.11.3 多行模板头：定义可能写成
    #      _EXPORT_STD template <class _Elem>
    #      struct char_traits : _字符特征基类<_Elem, long> {};
    #  只删第二行会留下【悬空的模板前缀】-> 紧随其后的特化报
    #      "模板特化或类外模板定义中多余的模板形参列表"（§17.11.1 实测）。
    #  所以从 $m.Index 往前吃掉所有"只由 template <...>（可带宏）构成"的行。
    #  ⚠ 只吃"整行就是模板头"的行：`(_EXPORT_STD )?template <...>`；别的行一律不吃，
    #     避免误删上一段的结尾（那会造成更隐蔽的破坏）。
    # -----------------------------------------------------------------------
    $start = $m.Index
    while ($start -gt 0 -and $Text[$start - 1] -eq "`n") {
        $prevEnd = $start - 1
        $prevStart = $Text.LastIndexOf("`n", [Math]::Max($prevEnd - 1, 0))
        if ($prevStart -lt 0) { break }
        $prevLine = $Text.Substring($prevStart + 1, $prevEnd - $prevStart - 1).Trim()
        if ($prevLine -match '^(?:_EXPORT_STD\s+)?template\s*<.*>\s*$') { $start = $prevStart + 1 } else { break }
    }
    $note = "// [dropTypes] 这里删掉了抄来的 " + $Name + " 定义。`n" +
            "// 它的身份必须是 std 的那个（铁律 4：捕获按类型匹配），所以改用真头的 std::" + $Name + "。`n"
    $Text = $Text.Substring(0, $start) + $note + $Text.Substring($end)
    }  # while（删到没有同名定义为止）
    return $Text
}


if ($spec.dropTypes) {
    foreach ($dn in @($spec.dropTypes)) {
        if ($spec.types -and $spec.types.Contains($dn)) {
            throw "dropTypes 与 types 冲突：'$dn' 既被删又被改名 —— 删掉就不该再登记改名"
        }
        $nDrop = 0
        $text = Remove-ClassDef -Text $text -Name $dn -Count ([ref]$nDrop)
        if ($nDrop -eq 0) {
            Write-Host "  步0b ⚠ dropTypes 没找到类定义 '$dn'" -ForegroundColor Yellow
        } else {
            Write-Host "  步0b 丢掉抄来的类定义 '$dn'（改用真头的 std::$dn）"
$text = Remove-OperatorDefs -Text $text -Name $dn -Count ([ref]$nDrop)
        }
    }
}


# 步 1：换守卫
$gm = [regex]::Match($text, '(?m)^#ifndef\s+([A-Za-z_][A-Za-z0-9_]*)\s*\r?\n#define\s+\1\b')
if ($gm.Success) {
    $g = $gm.Groups[1].Value
    $ng = '_ZH_' + ($spec.zh)
    $ng = '_ZH_' + ($Header.ToUpper() -replace '[^A-Z0-9]', '_') + '_'
    $text = $text.Replace("#ifndef $g", "#ifndef $ng").Replace("#define $g", "#define $ng")
    Write-Host "  步1 守卫 $g -> $ng"
}

# 步 2：搬名域
# ---------------------------------------------------------------------------
#  prologue：本层【自己的前向声明】，插在名域开头（`使用 名域 std;` 之后）。
#
#  为什么需要它（xmemory 实测，§16.23）：
#    微软的 xmemory 在 `_Container_proxy` 里用了 `_Iterator_base12*`，
#    而 `_Iterator_base12` 的定义在本文件【更后面】。原文能编过，是因为
#    `<xutility>` 第 4187 行有一句 `struct _Iterator_base12;` —— 它是【借来的】前向声明。
#    我们把正文搬进 细节:: 之后，`_迭代器基类12` 在那一行还没有任何声明，
#    于是编译器报「没有名为（名字）'迭代器基类12'」，校对的回退机制就把那一处
#    【改回了英文】—— 表面通过了，实际留下一个英文标识符（静默欠账）。
#    正确做法不是"保留英文"，而是把缺的那句前向声明【抄成自己的】。
# ---------------------------------------------------------------------------
$nsOpen = "名域 标准 { 名域 细节 {`n使用 名域 std;"
if ($spec.prologue) { $nsOpen += "`n" + $spec.prologue }
$text = $text.Replace('_STD_BEGIN', $nsOpen)
$text = $text.Replace('_STD_END', '} }')
Write-Host "  步2 名域 -> 标准::细节 + 使用 名域 std;$(if ($spec.prologue) { ' + prologue 前向声明' })"

# ---------------------------------------------------------------------------
#  步 2b：pmr 嵌套名域（实测踩到，<set> 是第一个带它的头）
#
#  MSVC 很多容器头末尾有一段：
#      namespace pmr {
#          using set = _STD set<_Kty, _Pr, polymorphic_allocator<_Kty>>;
#      }
#  搬进 细节 之后，`polymorphic_allocator` 就找不到了一一 它本来靠
#  "在 std::pmr 里面" 这个位置找到同名的 std::pmr::polymorphic_allocator：
#      error: 使用了未声明的标识符 'polymorphic_allocator'；
#             你是不是想写 'std::pmr::polymorphic_allocator'？
#  而 `使用 名域 std;` 只把 std 的名字引进 细节，引不进 std::pmr 的【嵌套】名字。
#
#  修法：在 `namespace pmr {` 后面补一句 `使用 名域 std::pmr;`。
#  pmr 名域本身暂不翻（方案 §六第 9 条），但里面的名字必须能找到。
# ---------------------------------------------------------------------------
# ⚠ 不止 pmr：std 里还有 ranges / chrono / filesystem / execution 等【嵌套名域】，
#   原头行里写 namespace X { ... }，里面的名字靠"在 std::X 里"这个位置找。
#   搬进 细节 之后同样找不到 —— 一律补一句 使用 名域 std::X;
$nested# ⚠ 绝不能放进 this_thread：<thread> 里它是【我们自己翻译】的（本线程），
#   注入 使用 名域 std::this_thread; 会被改名成 std::本线程 -> 名域不存在。
$nested = @('pmr', 'ranges', 'chrono', 'filesystem', 'execution')
foreach ($ns in $nested) {
    if ($text -match "(?m)^namespace $ns \{") {
        $text = [regex]::Replace($text, "(?m)^(namespace $ns \{)",
            "`$1`n    使用 名域 std::$ns;   // 嵌套名域暂不翻，但里面的名字要靠它找到（步 2b）")
        Write-Host "  步2b 嵌套名域 $ns：补 使用 名域 std::$ns;"
    }
}

# 步 3/4：类型名、成员名、数据成员名（按 \b 边界，逐条替换）
# ---------------------------------------------------------------------------
#  §17.19.43 限定引用守卫：被 _STD / _CSTD / _RANGES / 宏（= _STD 某结构::）限定引用的名字
#  【不是我们拷贝层的】，不能登记改名。
#  为什么加它（第 110 轮实测）：把 <复数> 的 _Exp/_Sinh/_Cosh… 登记改名后，编译逐个报
#    「the global namespace 中没有名为 '_长双精度指数' 的成员」——原文写的是 `_CSTD _LExp(...)`
#    （_CSTD 展开成 ::），那是 CRT 的函数。/  _Fmp_t/_Sqr_x2 则是 `#define _FMP _STD _Float_multi_prec::`
#    后面的 std 成员。逐轮试错一次只能揪出一个名字，太贵 —— 这条守卫一次把全部点出来。
#  判据：在【改名之前】的拷贝层正文里，凡出现 `_STD/_CSTD/_RANGES/_STDEXT/std::` 或
#        `#define M _STD 某结构::` 里那个 M 紧跟该名字 —— 一律拦。
# ---------------------------------------------------------------------------
#  校准（第 110 轮，第二次）：第一版把 `_STD real(...)` 也拦了 —— **假报**。
#  实测：生成器对 `_STD <我们登记的名>` 会**顺手去掉限定**（产品里是 `实部(_Left)`，
#  不是 `_STD 实部(_Left)`），所以 real/imag/asinh/atanh 这些登记本来是对的。
#  真正不能碰的只有两类：
#    ① `_CSTD NAME`（_CSTD 展开成 ::）—— C 库的函数，永远不是我们拷贝层的；
#    ② `#define M _STD 某结构::` 之后 `M NAME` —— std 结构的成员（如 _Float_multi_prec）。
#  这两类【硬拦】；`_STD NAME` / `std::NAME` 只【告警】（人工判断，避免假报逼人绕守卫）。
# ---------------------------------------------------------------------------
$qualHard = @(); $qualSoft = @(); $undef = @()
$macroQuals = @()
foreach ($qm in [regex]::Matches($text, '(?m)^#define\s+(\w+)\s+_STD\s+\w+::')) { $macroQuals += $qm.Groups[1].Value }
foreach ($qk in @('types', 'members', 'data')) {
    if (-not $spec.ContainsKey($qk)) { continue }
    foreach ($qn in @($spec[$qk].Keys)) {
        $esc = [regex]::Escape($qn)
        # 判据：拷贝层里【有没有它的定义】—— 有定义 = 我们的；只有引用 = 借来的（std/C 的）。
        $defined =
            ($text -match ('(?m)^\s*(?:template\s*<[^>]*>\s*)?(?:struct|class|enum(?:\s+class)?|union)\s+' + $esc + '\b')) -or
            ($text -match ('(?m)^\s*using\s+' + $esc + '\s*=')) -or
            ($text -match ('(?m)^\s*typedef\b[^;]*\b' + $esc + '\s*;')) -or
            ($text -match ('(?m)^\s*#define\s+' + $esc + '\b')) -or
            ($text -match ('(?m)^[^\r\n]*\b' + $esc + '\s*\([^;{]*\)[^;{]*\{'))
        if (-not $defined) { $undef += ("[{0}] '{1}'" -f $qk, $qn); continue }
        if ($text -match ('(?<![\w])_CSTD\s+' + $esc + '(?![\w])')) { $qualHard += ("[{0}] '{1}' 被 _CSTD 限定引用（C 库的函数）" -f $qk, $qn); continue }
        foreach ($mq in $macroQuals) {
            if ($text -match ('(?<![\w])' + [regex]::Escape($mq) + '\s+' + $esc + '(?![\w])')) { $qualHard += ("[{0}] '{1}' 被宏 {2} 限定引用" -f $qk, $qn, $mq); break }
        }
    }
}
if ($qualSoft.Count) { Write-Host ("  ⚠ 限定引用告警：" + (($qualSoft | Sort-Object -Unique) -join '、')) -ForegroundColor DarkYellow }
#  §17.19.43 校准（第 110 轮第三次）：判据只能【告警】，不能硬拦。
#  为什么：定义形态判据有无法根除的假报 —— 头文件守卫宏（`#ifndef _COMPLEX_` 已被步1改名）、
#    模板形参名（`template <class _Elem>`）、局部别名、跨内部件的定义。
#    硬拦会逼人给这些无关登记改名或绕开守卫；**假报和漏报一样坏**（§17.19.37）。
#  价值仍在：真正的借用名（_CSTD / 宏限定 / 拷贝层无定义）会在生成日志里【当场点名】，
#    不必等编译报「未声明的标识符」再一个个试（本轮 4 轮试错就是这么省下来的）。
if ($undef.Count) {
    Write-Host ("  ⚠ 借用名告警（§17.19.43，拷贝层里没有定义、可能是借来的 std/C 名）：" + (($undef | Sort-Object -Unique) -join '、')) -ForegroundColor DarkYellow
}
if ($qualHard.Count) {
    Write-Host ("  ⚠ 限定引用告警（§17.19.43）：" + (($qualHard | Sort-Object -Unique) -join '、')) -ForegroundColor DarkYellow
}
$nT = 0; $nM = 0; $nD = 0
# ---------------------------------------------------------------------------
#  全库共享：【我们自己引入的】内部名一键替换（方案 §十三 第①类）
#
#  为什么这类可以"一键替换"而没有二义：
#    它们在【抄来那层的正文里是有定义的】（`using _Mybase = ...` / 模板参数），
#    所以全文出现的 `_Mybase` 都是我们自己那个，不存在"我们的 vs std 的"歧义。
#    （反例是 reverse_iterator：`std::reverse_iterator` 与我们的别名同名 —— 那种不能盲替。）
#
#  ⚠ 第②类（真正借来的 std 内部件：_Alty_traits/_Alnode_traits/_Pocma_values…）
#     不能只靠替换：它们【在 std 里有定义】，替换后需要我们自己也有那份定义
#     —— 那要先抄（步骤 1）。所以这里只放第①类。
# ---------------------------------------------------------------------------
$INTERNAL_NAMES = [ordered]@{
    '_Mybase'    = '_我的基类'
    '_Mylist'    = '_我的链表'
    '_Myvec'     = '_我的向量'
    '_Mydeque'   = '_我的双端队列'
    '_Val_types' = '_值类型集'
    '_Node'      = '_节点'
}
$nI = 0
# ---------------------------------------------------------------------------
#  ⚠ `_RANGES X` 里的 X 是【借来的】std::ranges 名字，**绝不能被改名**（§16.27）。
#
#  `_RANGES` 展开成 `::std::ranges::`（Microsoft yvals_core.h:1930），
#  所以 `_RANGES size(...)` 永远是 std::ranges::size，不是我们的成员 ——
#  这就是 §10.2 第 1 条「同一个英文名在同一个文件里属于不同的类」的又一面，
#  只不过这次的另一个主人根本不在本文件里。
#
#  实测（<跨度>）：members 表里的 `data -> 数据` / `size -> 尺寸` 把
#  `_RANGES data(_Range)` / `_RANGES size(_Range)` 一起改了。
#     · `_RANGES data(_Range)` 被编译到 -> 编译器回退救回来了（并且因为回退现在
#       【会响亮报出来】，才发现这里有问题）；
#     · `_RANGES 尺寸(_Range)` 落在 `#if _MSVC_STL_HARDENING_SPAN || _ITERATOR_DEBUG_LEVEL != 0`
#       分支里 -> **那一支没被编译** -> 回退机制看不见 -> 静默留在产品里，
#       一旦有人开调试迭代器/强化检查就炸。
#  **不能靠"改了再等编译器回退"**：回退只对【被编译到】的位置有效。
#  所以从源头用负向后顾挡住（.NET 支持变长后顾，`\s+` 可跨行缩进）。
# ---------------------------------------------------------------------------
$RANGES_RENAMABLE = @('_Ubegin','_Uend','_Copy_memcpy_common','_Copy_memcpy_distance','_Copy_unchecked','_Find_unchecked','_Get_final_iterator_unwrapped','_As_const_pointer','_Equal_rev_pred','_Find_if_unchecked','_Find_last_iterator','_Idl_distance','_Max_element_unchecked','_Min_element_unchecked','_Mismatch_4','_Mismatch_n','_Possibly_const_range','_Rewrap_iterator')
function Get-RenamePattern([string] $name) {
    if ($RANGES_RENAMABLE -contains $name) { return '\b' + [regex]::Escape($name) + '\b' }
    return '(?<!_RANGES\s+)\b' + [regex]::Escape($name) + '\b'
}
$origText = $text          # §17.27.3 守卫用：改名【之前】的正文（登记有没有落地必须在原文上量）
foreach ($k in $INTERNAL_NAMES.Keys) {
    if ($spec.types.Contains($k)) { continue }
    $c = ([regex]::Matches($text, (Get-RenamePattern $k))).Count
    if ($c) {
        $text = [regex]::Replace($text, (Get-RenamePattern $k), $INTERNAL_NAMES[$k])
        $nI += $c
    }
}
if ($nI) { Write-Host "  步3/4b 内部名一键替换 $nI 处" }
# ---------------------------------------------------------------------------
#  §17.27.3 守卫：「登记了」必须等于「落地了」—— 登记≠落地。
#
#  实测换来的（提交 4ba775e 那次虚报）：<互斥量> 的 members 表里登记了 8 个
#  `_Lock`/`_Validate`/`_Mymtx`/... -> 产品正文里**改到 0 处**，因为那些名字
#  根本不在本条目拷贝的正文里（它们在 <xthreads.h> 的 C 包装层与 <shared_mutex>
#  的拷贝层，该登记在那边）。登记表是【意图】，产品正文才是【事实】。
#
#  旧代码 `if ($c) { ...改名... }` —— **0 命中就静默跳过**，于是"多写几行登记"
#  就能在审计表上凭空涨进度。这里把 0 命中一律报到 regen 的告警台账上。
#  ⚠ 必须在 `$origText`（改名前的正文）上量：改名会吃掉英文名，改完再量都是 0。
# ---------------------------------------------------------------------------
$zeroHit = @()
$landedPairs = @()   # §17.27.13 第三层守卫：登记了、且在抄来那层命中，还要在【产品正文】里出现
foreach ($k in $spec.types.Keys) {
    $c = ([regex]::Matches($text, (Get-RenamePattern $k))).Count
    if ($c) { $text = [regex]::Replace($text, (Get-RenamePattern $k), $spec.types[$k]); $nT += $c; $landedPairs += [pscustomobject]@{ Kind = 'types'; En = $k; Zh = $spec.types[$k] } }
    elseif (([regex]::Matches($origText, (Get-RenamePattern $k))).Count -eq 0) {
        $zeroHit += ("⚠ {0} : types 表 {1} -> {2} —— 本条目拷贝层 0 命中" -f $Header, $k, $spec.types[$k])
    }
}
foreach ($k in $spec.members.Keys) {
    $c = ([regex]::Matches($text, (Get-RenamePattern $k))).Count
    if ($c) { $text = ([regex]::Replace($text, (Get-RenamePattern $k), $spec.members[$k])); $nM += $c; $landedPairs += [pscustomobject]@{ Kind = 'members'; En = $k; Zh = $spec.members[$k] } }
    elseif (-not $spec.types.Contains($k) -and -not $INTERNAL_NAMES.Contains($k) -and
            ([regex]::Matches($origText, (Get-RenamePattern $k))).Count -eq 0) {
        $zeroHit += ("⚠ {0} : members 表 {1} -> {2} —— 本条目拷贝层 0 命中" -f $Header, $k, $spec.members[$k])
    }
}
foreach ($k in $spec.data.Keys) {
    $c = ([regex]::Matches($text, (Get-RenamePattern $k))).Count
    if ($c) { $text = ([regex]::Replace($text, (Get-RenamePattern $k), $spec.data[$k])); $nD += $c; $landedPairs += [pscustomobject]@{ Kind = 'data'; En = $k; Zh = $spec.data[$k] } }
    elseif (-not $spec.types.Contains($k) -and -not $spec.members.Contains($k) -and -not $INTERNAL_NAMES.Contains($k) -and
            ([regex]::Matches($origText, (Get-RenamePattern $k))).Count -eq 0) {
        $zeroHit += ("⚠ {0} : data 表 {1} -> {2} —— 本条目拷贝层 0 命中" -f $Header, $k, $spec.data[$k])
    }
}
if ($zeroHit.Count) {
    Write-Host ("❌ 登记≠落地（§17.27.3/§17.27.4）：{0} 有 {1} 条改名登记在本条目拷贝层 0 命中" -f $Header, $zeroHit.Count) -ForegroundColor Red
    $zeroHit | ForEach-Object { Write-Host $_ -ForegroundColor Red }
    Write-Host '  含义：这些名字要么根本不属这个头（例：_Lock 属 <xthreads.h>/<shared_mutex> -> 该登记在那边），' -ForegroundColor Yellow
    Write-Host '        要么是过时/拼错的登记。危害不止"白写"：它会让 §16.52.3 那类【查表】守卫假通过 ——' -ForegroundColor Yellow
    Write-Host '        §17.27.4 的幽灵 API（链表 shrink_to_fit -> 基类::收缩至适应）就是这样被掩盖的。' -ForegroundColor Yellow
    throw "登记≠落地（§17.27.3）：先把这些登记删掉或搬到真正定义它的条目上，再生成"
}
Write-Host "  步3/4 类型 $nT 处 / 成员 $nM 处 / 数据 $nD 处"
# ⚠ realInclude 必须插在【改名之后】：否则 `#include <optional>` 里的 optional
#   会被类型改名改成 `#include <可选实现>` -> fatal error: 找不到文件 '可选实现'。
#   （dropTypes 相反，必须在改名【之前】，因为要匹配英文类名。）
if ($spec.realInclude) {
    $pos = $text.IndexOf('_STD_BEGIN')
    if ($pos -lt 0) { $pos = 0 }
    $inc = (@($spec.realInclude) | ForEach-Object { "#include <$_>" }) -join "`n"
    $text = $text.Substring(0, $pos) + $inc + "`n" + $text.Substring($pos)
    Write-Host ("  步0b 真头包含（改名后插）: {0}" -f (@($spec.realInclude) -join ', '))

    # -----------------------------------------------------------------------
    #  机器检查（§3.26 第 3 条）：realInclude 与"抄来的 std 模板特化"天生冲突。
    #
    #  实测（<variant>）：抄来的文本里有 `结构 hash<monostate>`；一旦 monostate
    #  解析到 std::monostate，我们那份就成了"在 细节 里特化 std::hash<...>"，
    #  而 realInclude 带进来的真头里【已经有一份】-> 重定义。
    #
    #  这里只【警告】不 throw：有些特化确实无害（比如特化的是我们自己的类型），
    #  要人看一眼。但至少不再是"没人知道"。
    #
    #  ⚠ 2026-09-28 精确化（§16.32）：笼统地警告会【淹没】真问题。
    #    铺开 realInclude 之后，13 条告警里有 8 条是这个 —— 而它们全是**误报**：
    #       结构 hash<位集实现<位数>> : ...
    #    它在特化 std::hash，但特化的是**我们自己的类型**（模板实参里有汉语标识符）
    #    —— 真头里不可能有同一个特化，所以永远撞不上。
    #    判据改成可机器判定的一条：
    #      **特化行里出现汉语标识符（或 细节::）-> 特化的目标是我们的类型 -> 无害**
    #      否则 -> 是拿 std 的类型去特化 std 的模板 -> 真会和真头撞车 -> 必须警告
    # -----------------------------------------------------------------------
    #  ⚠ 2026-09-28 第二次修正：判据必须看【整个声明块】，不能只看那一行。
    #    实测 <向量> 的 formatter：
    #        template <class _Ty, _Format_supported_charT _CharT>
    #            requires _Is_specialization_v<_Ty, _位引用>      ← 汉语标识符在【上一行】
    #        struct formatter<_Ty, _CharT> {                      ← 匹配到的是这一行
    #    只看匹配行 -> 看不到 _位引用 -> 误判成"拿 std 类型特化"。
    #    所以取"从上一个空行到本行"的整块（声明通常以空行分隔）。
    # -----------------------------------------------------------------------
    $specOurs = @(); $specStd = @()
    $specRx = '(?m)^\s*(?:结构|struct|类型|class)\s+(hash|formatter|uses_allocator|tuple_size|tuple_element|pointer_traits|numeric_limits|iterator_traits|char_traits|is_error_code_enum|is_error_condition_enum|default_delete|allocator_traits)\s*<[^\r\n]*'
    foreach ($m in [regex]::Matches($text, $specRx)) {
        $prefix = $text.Substring(0, $m.Index)
        $sep = [regex]::Matches($prefix, '\r?\n\r?\n')
        $start = if ($sep.Count) { $sep[$sep.Count - 1].Index + $sep[$sep.Count - 1].Length } else { 0 }
        $block = $text.Substring($start, $m.Index - $start + $m.Length)
        $nm = $m.Groups[1].Value
        # ⚠ 2026-09-29 第三次精确化（§17.19.17）：**本头自己定义了主模板**时，那些 `名<...>`
        #    是本模板的【特化】，不是"拿 std 类型特化 std 模板"。实测 <xutility> 的 pointer_traits：
        #        struct pointer_traits : _Ptr_traits_sfinae_layer<_Ty> {};   ← 主模板（我们那份，在 细节）
        #        struct pointer_traits<_Ty*> { ... };                        ← 它的偏特化
        #    上一版只看"上一个空行到本行"的声明块，块里既没有汉语标识符也没有 细节:: -> 误报。
        #    判据：同名主模板的定义/声明就在同一份文本里 -> 这些特化是【我们的】-> 无害。
        $hasPrimary = [regex]::IsMatch($text, "(?m)^\s*(?:模板[^\r\n]*[\r\n]\s*)?(?:结构|struct|类型|class)\s+$nm\s*(?![<])")
        if ($hasPrimary -or $block -match '[\u4e00-\u9fff]' -or $block -match '细节\s*::') { $specOurs += $nm }
        else { $specStd += $nm }
    }
    if ($specOurs.Count) {
        Write-Host ("  步0b 抄来文本里有 {0} 处 std 模板特化，但特化的是【我们自己的类型】（含汉语标识符）或【我们自己主模板的特化】-> 无害：{1}" -f `
            $specOurs.Count, (($specOurs | Sort-Object -Unique) -join ', '))
    }
    if ($specStd.Count) {
        Write-Host ("  ⚠ 步0b【§3.26 第3条】开了 realInclude，抄来文本里有 {0} 处【拿 std 类型特化 std 模板】：{1}" -f `
            $specStd.Count, (($specStd | Sort-Object -Unique) -join ', ')) -ForegroundColor Yellow
        Write-Host '     这一种真会与真头里的同一特化撞车（重定义）。要么 dropTypes 丢掉，要么逐条确认。' -ForegroundColor Yellow
        # ⚠ 这三行是**解释**，故意不用 ⚠ 前缀 —— regen 的告警台账是"凡 ⚠/❌ 行"，
        #   我第一版把提示也写成 ⚠ 开头，结果它自己变成第 7 条告警（噪声）。
        Write-Host '     · 诊断提示：也可能是"特化其实是针对我们自己的内部件、只是那个名字还没汉化"' -ForegroundColor Yellow
        Write-Host '       （实测 <向量> 的 formatter：约束里的 _Vb_reference 是我们自己的类）。' -ForegroundColor Yellow
        Write-Host '       那种情况【翻掉那个名字这条告警就会自动消失】—— 告警本身即该名字的欠账标记。' -ForegroundColor Yellow
    }
}

# ---------------------------------------------------------------------------
#  步 4c：把 `_STD <本文件自己定义的东西>` 的限定去掉
#
#  `_STD` 展开成 `std::`。文件里有地方写 `_STD X` 来引用【它自己】定义的 X
#  （例：scoped_allocator 里的 `_STD _Scoped_outermost`）。本文件的内容已经搬进
#  `标准::细节`，X 就不在 `std` 里了 —— 于是报「namespace 'std' 中没有名为 X 的成员」。
#  这与 §3.3 记的 `cstddef` 的 `using _STD max_align_t` 那条"桥"是同一类问题。
#  修法：改名完成后，把 `_STD <改后的名字>` 还原成不带限定的 `<改后的名字>`。
# ---------------------------------------------------------------------------
$nq = 0
# ⚠ 只对【类型】【数据成员】【自由函数】去限定，绝不能对【成员函数名】去限定。
#   反例（实测踩到）：<stack> 里 `using _STD swap;` 是**故意**把 std::swap 拉进来供 ADL 用，
#   它不是"引用自己"。而我那张 members 表里也有 swap->交换，于是步 4c 把
#   `using _STD 交换;` 去限定成 `using 交换;` -> error: 使用 声明要求限定名。
#   判据：`_STD X` 只有在本文件【定义】了 X 时才该去限定。
#   细化（本轮实测）：`using` 开头的 `_STD X` 一律不动；其余位置 types/data/members 都去限定。
function Remove-StdQualifier {
    param([string]$Text, [string]$Name, [ref]$Count)
    $rx = '(?<!using )_STD ' + [regex]::Escape($Name) + '\b'
    $new = [regex]::Replace($Text, $rx, $Name)
    if ($new -ne $Text) { $Count.Value++ }
    return $new
}
foreach ($m in @($spec.types, $spec.data, $spec.members)) {
    foreach ($k in $m.Keys) {
        $text = Remove-StdQualifier -Text $text -Name $m[$k] -Count ([ref]$nq)
    }
}
# 本文件在名域作用域定义的 `_` 开头自由函数：改名后同样要被去限定。
# 不靠人肉登记（漏一个就报一次），直接从生成文本里扫出来。
$scanned = 0
foreach ($mm in [regex]::Matches($text, '(?m)^[^\r\n#]*?\b(_\w+)\s*\(')) {
    $nm = $mm.Groups[1].Value
    $before3 = $text
    $text = Remove-StdQualifier -Text $text -Name $nm -Count ([ref]$scanned)
    if ($text -eq $before3) { continue }
}
Write-Host "  步4c 去限定 `_STD <本文件的实体>`: $nq 个（另扫出内部函数 $scanned 个）"

$rngN = 0
foreach ($m in @($spec.types, $spec.data, $spec.members)) {
    foreach ($k in $m.Keys) {
        $rx = [regex]::Escape("_RANGES " + $m[$k]) + '\b'
        $new = [regex]::Replace($text, $rx, $m[$k])
        if ($new -ne $text) { $rngN++; $text = $new }
    }
}
if ($rngN) { Write-Host ("  步4d _RANGES 去限定: {0} 处" -f $rngN) }

}   # end if (-not $isShell) —— 抄原头流水线到此结束（薄壳跳过整段）
# ---------------------------------------------------------------------------
# 步 6：派生层（在中文的基础上派生，补回英文原名）
$cls = ($spec.types.Values | Select-Object -First 1)   # 实现类名（⚠ types 表的【第一个值】—— 新条目一律追加到表尾，插表头会静默改这里，§17.19.41）
Write-Host ("  派生层基类 {0} / 原类型名 {1}" -f $cls, ($spec.types.Keys | Select-Object -First 1)) -ForegroundColor DarkGray
$origType = ($spec.types.Keys | Select-Object -First 1) # 原本的类型名（供测试用）
# 头名与对外类名不一定相同（例：<条件变量> 里只有 condition_variable_any）
$pub = if ($spec.ContainsKey('pub')) { $spec.pub } else { $spec.zh }

# ---------------------------------------------------------------------------
#  ⚠⚠ 成对列表的"恰好一对"陷阱（实测：<可选> 派生层生成出 `使用 值 = 基类::类;`）
#
#  PowerShell 的数组子表达式 @() 会【枚举】内容：
#      @( @('值类型','value_type') ).Count  ==  2     # 被展平！元素是 String
#      @( @('a','b'), @('c','d') ).Count    ==  2     # 不展平，元素是 Object[]
#  于是 foreach ($p in $spec.deriveTypes) 里的 $p 成了【字符串】，
#  $p[0]/$p[1] 取到的是【单个字符】：'值类型'[0]='值' [1]='类'；'value_type'[0]='v' [1]='a'。
#  生成物就是 `使用 值 = 基类::类;` 与 `使用 v = 基类::a;` —— 而且它【编译得过】，
#  所以"4/4 语法通过"照不出来（见方案第八节）。
#
#  ⚠ 不要把它写成函数：PowerShell 的函数返回值【也会被管道展开】，
#    `return $out`（只含一对时）会被摊回两个字符串 —— 第一版修复就栽在这里。
#    必须【内联 + 纯赋值】（赋值不走管道，不展开）。
# ---------------------------------------------------------------------------
function Repair-Pairs([object]$list) {
    # 注意：调用方必须用 = 赋值接收（不能用 foreach 直接吃函数输出）
    # ⚠ 条目可以【完全合法地】没有 derive/deriveTypes（例：纯自由函数头 <数值算法>，
    #   它的公开层是 extra 里手写的）。@($null) 的 Count 是 1、元素是 $null，
    #   于是旧写成 `return , $arr` 会返回"含一个 $null 的数组"，
    #   调用方 `$p[1]` 立刻炸「不能为空数组建立索引」——所以 $null 必须显式挡在这里。
    if ($null -eq $list) { return , @() }
    $arr = @($list)
    if ($arr.Count -eq 0 -or $arr[0] -isnot [string]) { return , $arr }
    $tmp = @()
    for ($i = 0; $i + 1 -lt $arr.Count; $i += 2) { $tmp += , @($arr[$i], $arr[$i + 1]) }
    return , $tmp
}
$derPairs = Repair-Pairs $spec.derive
$fwd = @()
$zhScope = Get-ZhNameScope $Header
foreach ($p in $derPairs) {
    # §16.52.3 守卫：中文目标必须真的存在（本条目抄来那层 / 基类那侧的改名表）
    #   —— 否则这个英文转发器会遮住继承来的英文名，还指向一个不存在的中文名。
    if (-not $text.Contains([string]$p[1]) -and -not $zhScope.Contains([string]$p[1])) {
        $derMissing += ("  $Header : derive @('{0}','{1}') —— 中文名「{1}」在本条目抄来那层和基类改名表里都找不到" -f $p[0], $p[1])
    }
    # 发两个转发：非 const 一个、const 一个。
    # 为什么两个都要：只发非 const 的话，const 对象上调用不到（实测
    # std::hash 特化里 _键.hash_code() 就是 const 引用，直接报"没有匹配的成员函数"）。
    # 两个并存不会歧义：非 const 对象上非 const 版更匹配；const 对象上只有 const 版可用。
    # 转发是模板，惰性实例化 —— 所以给非 const 成员也发一个 const 版是安全的。
    # -----------------------------------------------------------------------
    # §16.52 返回类型用【声明类型(自动)】(= decltype(auto))，不用 `自动`：
    #   基类里 `at` / `front` / `back` / `operator[]` / `data` 这类成员是**引用返回**，
    #   而 `自动` 会把返回值按值推导掉 -> `甲.at(键) = 值;` 直接编不过。
    #   那是「英文用法在 标准:: 层退化」= 回归（用户要的就是"原本的英语用法还能用"）。
    #   `声明类型(自动)` 按【基类声明的返回类型】原样推导：引用还是引用、
    #   常量引用还是常量引用、void 还是 void、按值还是按值 —— 严格更忠实。
    #   实测（tools\zh_decltype_auto_probe.cpp）：`声明类型(自动)` 能当左值用。
    # ⚠ 绝不写成 `自动`：那等于悄悄把英文 API 的引用语义砍掉。
    $fwd += ("    模板 <类型名... 参数> 声明类型(自动) {0}(参数&&... 值) {{ 返回 基类::{1}(static_cast<参数&&>(值)...); }}" -f $p[0], $p[1])
    $fwd += ("    模板 <类型名... 参数> 声明类型(自动) {0}(参数&&... 值) 常量 {{ 返回 基类::{1}(static_cast<参数&&>(值)...); }}" -f $p[0], $p[1])
}
if ($derMissing.Count) {
    Write-Host "❌ 派生层英文转发器指向【不存在的中文名】（它会遮住基类继承来的英文名 = 回归，§16.52.3）:" -ForegroundColor Red
    $derMissing | ForEach-Object { Write-Host $_ -ForegroundColor Red }
    Write-Host '  修法二选一：① 基类那侧（如 哈希内部件/链表）确实有这个成员 -> 把它的中文名登记进本表；' -ForegroundColor Yellow
    Write-Host '              ② 该成员只继承自借用类型（没被翻）-> 从 derive 里拿掉，改在 deriveExtra 里手写中文转发。' -ForegroundColor Yellow
    throw "派生层目标名不存在，先修表再生成"
}
$fwdT = @()
if ($spec.ContainsKey('deriveTypes')) {
    foreach ($p in (Repair-Pairs $spec.deriveTypes)) { $fwdT += ("    使用 {0} = 基类::{1};" -f $p[0], $p[1]) }
}
$hashSpec = if ($spec.stdHash) { @"

// std::hash 的特化必须挂在【对外那个类型】上（派生层之后），所以放在这里
名域 std {
    模板 <>
    结构 hash<标准::$pub> {
        _NODISCARD size_t operator()(常量 标准::$pub& _键) 常量 noexcept {
            返回 _键.hash_code();
        }
    };
}
"@ } else { '' }

# 额外要在 std 里补的特化（除 std::hash 之外的，按头给原始文本）
# 例：<stack> 的 std::uses_allocator / std::formatter 都要认识我们的类型。
if ($spec.ContainsKey('stdExtra')) {
    $hashSpec += "`n`n// 表里给的额外 std 特化 —— 这些 std 模板也必须认识我们的类型`n名域 std {`n$($spec.stdExtra)`n}"
}

$layer = @"


// ============================================================================
//  第二层：在【中文的基础上】派生，把英文原名补回来
//  · 第一层 标准::细节::$cls 是抄自微软的中文实现，成员名全中文
//  · 本层加回英文原名，所以两种名字在【同一个对象】上都能用
//  · 与微软的原类型并存：它是【另一个类型】，不碰 std 里的定义
// ============================================================================
名域 标准 {
$($spec.tparam.decl)
类型 $pub : 公开 细节::$cls$($spec.tparam.args) {
公开:
    使用 基类 = 细节::$cls$($spec.tparam.args);
    使用 基类::基类;

    // 嵌套类型名也要补回英文（数据成员不行 —— 那会改布局）
$($fwdT -join "`n")

    // 英文原名，一模板转发回中文名（不需要写签名，重载也自动跟过去）
$($fwd -join "`n")

    // 表里给的额外成员（deriveExtra）—— 【中文】转发，用来给"继承自借用基类"的
    // API 补中文名（那些名字不在本文件里，members 表改不到，见方案 §3.16）
$($spec.deriveExtra)
};
}$hashSpec
"@
#$text = $text + $layer    # ← 派生层改到"编译器校对之后"再追加，见下
New-Item -ItemType Directory -Force $out | Out-Null
$outPath = Join-Path $out $spec.zh

# ---------------------------------------------------------------------------
#  守卫：宏泄漏检查（§16.24，由组合探针抓到的一次真实失败逼出来）
#
#  宏【不受名域约束】。我们改写名之后，拷贝里那些 `#define` 的【宏体】可能含汉语标识符；
#  只要【宏名与原头相同】，真头（list / xtree / vector …）展开同一个宏时
#  拿到的就是汉语标识符 —— 而汉语标识符在 std 里不存在：
#      list:827:27: error: 使用了未声明的标识符（名字）'_假分配器'
#  这不是"组合探针运气好"，而是一类必然问题：拷贝头只要改一个名字，
#  就可能污染所有【共用同一个宏】的真头。
#
#  判据（可机器判定，不靠记性）：
#      宏名与原头相同  &&  宏体里出现 CJK 字符   ->  泄漏，拦住
#  正解是把【宏名也汉化】（宏名也是名字）：宏名一改，就不再与真头重名，各用各的。
# ---------------------------------------------------------------------------
$origText = [System.IO.File]::ReadAllText($srcPath)
$origMacros = @{}
foreach ($m in [regex]::Matches($origText, '(?m)^[ \t]*#\s*define\s+([A-Za-z_]\w*)')) {
    $origMacros[$m.Groups[1].Value] = $true
}
$macroLeaks = @()
# 宏体可能折行（行尾反斜杠续行）：一直吃到"不以反斜杠结尾的那一行"
foreach ($m in [regex]::Matches($text, '(?m)^[ \t]*#\s*define\s+([A-Za-z_]\w*)((?:.*\\\r?\n)*.*)$')) {
    $mn = $m.Groups[1].Value
    if ($mn -like '_ZH_*') { continue }                     # 包含守卫是我们自己的，不算
    if ($m.Groups[2].Value -notmatch '[\u4e00-\u9fff]') { continue }
    if ($origMacros.ContainsKey($mn)) { $macroLeaks += $mn }
}
if ($macroLeaks.Count) {
    Write-Host ("  ❌ 宏泄漏: {0} 个宏【宏名没改】但宏体里已有汉语标识符 —— 会劫持真头的同名宏:" -f $macroLeaks.Count) -ForegroundColor Red
    foreach ($mn in ($macroLeaks | Sort-Object -Unique)) { Write-Host ("      {0}" -f $mn) -ForegroundColor Red }
    throw "宏名必须一起汉化（宏不受名域约束，见 §16.24）：$($macroLeaks -join ', ')"
}

# ---------------------------------------------------------------------------
#  §17.27.58 copyFixes：抄来层的【定点修复】（显式例外 + "未命中即报错"）
#
#  为什么需要：改名的粒度是"名字"，但**同一个名字在不同接收者上的归属不同**
#  （§17.27.42「接收者定」）。典型：`std::initializer_list` 是铁律③ 的别名类型
#  （永远是借来的），它的成员名 `size/begin/end` 在我们这边被改成了 `尺寸/开始/结束`，
#  于是**每个**含有 initializer_list 构造的条目都在抄来层留下编不过的位置
#  （实测 向量/链表/双端队列/单向链表/哈希内部件/字符串内部件 都有；
#   而 <向量> 那条一直潜伏，因为校对探针原来只编译第一条测试，见 §17.27.57）。
#  判据：这类"接收者是借来的"位置必须**定点改回英文**，而且必须**显式登记**
#  —— 不能只靠编译器兜（它只兜住实例化到的地方）。这是**边界**，不是欠账：
#  `std::initializer_list` 只能是 std 那一个（铁律③），所以这些位置永远是英文。
#  ⚠ 守卫：登记的旧文本**必须真的命中**；找不到说明表已过期 -> 直接报错。
# ---------------------------------------------------------------------------
if ($spec.ContainsKey('copyFixes')) {
    $cfPairs = Repair-Pairs $spec.copyFixes
    $cfMiss  = @()
    foreach ($p in $cfPairs) {
        $old = [string]$p[0]; $new = [string]$p[1]
        if ($text.Contains($old)) { $text = $text.Replace($old, $new) }
        else { $cfMiss += ("  {0} : copyFixes 未命中 『{1}』（表已过期：产品里没有这段文本）" -f $Header, $old) }
    }
    Write-Host ("  步5 copyFixes 定点修复: {0} 条" -f @($cfPairs).Count)
    if ($cfMiss.Count) {
        Write-Host "❌ copyFixes 登记的旧文本在产品里找不到 —— 必须删掉或改对:" -ForegroundColor Red
        $cfMiss | ForEach-Object { Write-Host $_ -ForegroundColor Red }
        throw "copyFixes 未命中，先修表再生成"
    }
}

[System.IO.File]::WriteAllText($outPath, $text, $utf8)
Write-Host ("  输出: {0}  ({1} 行)" -f $outPath, ([System.IO.File]::ReadAllLines($outPath)).Count)

# --- 编译器当改名校对 ---
$probe = Join-Path $env:TEMP ('zh2_' + [guid]::NewGuid().ToString('N').Substring(0,8) + '.cpp')
# ⚠ 探针必须用【真实用法】，不能用 主函数(){返回 0;}：
#   后者从不实例化任何成员，于是"只有完整实例化才检查"的错误
#   （典型：借来模板成员的调用，如 _Alty_traits::max_size）永远照不出来。
#   实测：examples\汉语库示例.cpp 一编译就报
#     'std::allocator_traits<...>' 中没有名为 '最大尺寸' 的成员   （见方案 §十二）
#   这里直接用该条目的第一条测试 —— 它本来就是会真正使用这些类的程序。
$tp = Repair-Pairs $spec.tests
# ---------------------------------------------------------------------------
#  §17.27.57 校对探针原来**只编译第 1 条测试** —— 于是"只有别的测试才会实例化到的位置"
#  永远照不出来（实测：<向量> 第 1 条测试不用 initializer_list 构造，产品 L723 的
#  `_Ilist.尺寸()` 一直潜伏，直到新加的"链名族"测试写 `甲{1,2,3}` 才炸 —— 而那时
#  它已经是【测试失败】，不是"自动改回英文"）。这正是 §16.37.2 记过的
#  "只编译到校对探针实例化到的位置"。
#  改法：**逐轮换一条测试**（轮次 -> 测试序号，循环跑），并且**每条测试都干净**才收工。
# ---------------------------------------------------------------------------
$probeBodies = @(@($tp) | ForEach-Object { [string]$_[1] } | ForEach-Object { $_.Replace([char]96 + 'n', "`n") })
if ($probeBodies.Count -eq 0) { $probeBodies = @("整数 主函数(){ 返回 0; }") }
$rev = @{}
foreach ($k in $spec.members.Keys) { $rev[$spec.members[$k]] = $k }
foreach ($k in $spec.data.Keys)    { $rev[$spec.data[$k]] = $k }
# ⚠ 类型名也要能回退：现在要让【抄来那层】的嵌套类型名（value_type 等）也汉化，
#   而这类名字会用在【借用类型】的路径上（allocator_traits<_Alloc>::value_type 之类），
#   一旦改错必须能自动救回。
foreach ($k in $spec.types.Keys)     { $rev[$spec.types[$k]] = $k }
$maxRounds = [Math]::Max(12, $probeBodies.Count * 3)
$cleanStreak = 0
for ($round = 1; $round -le $maxRounds; $round++) {
    $ti = ($round - 1) % $probeBodies.Count
    [System.IO.File]::WriteAllText($probe, $probeBodies[$ti] + "`n", $utf8)
    $raw = & cmd /c "`"$cxx`" -std=c++20 -isystem`"$out`" -ferror-limit=0 -fsyntax-only `"$probe`" 2>&1"
    $hits = @()
    foreach ($l in @($raw)) {
        if ([string]$l -match "$($spec.zh)`:(\d+):(\d+): error: .*?(?:没有名为（成员名）|没有名为（名字）|未知的类型名（类型名）) '([^']+)'") {
            $hits += [pscustomobject]@{ Line=[int]$Matches[1]; Col=[int]$Matches[2]; Name=$Matches[3] }
        }
    }
    if ($hits.Count -eq 0) {
        $cleanStreak++
        Write-Host ("  校对第 {0} 轮（测试#{1}）: 无同名冲突" -f $round, ($ti + 1)) -ForegroundColor Green
        if ($cleanStreak -ge $probeBodies.Count) { break }
        continue
    }
    $cleanStreak = 0
    $lines = [System.IO.File]::ReadAllLines($outPath); $fixed = 0
    # -----------------------------------------------------------------------
    #  「改回英文」必须【响亮】（§16.23 的教训）。
    #
    #  xmemory 那次：`_Iterator_base12` 被静默改回英文，测试 2/2 照样通过，
    #  只有一行 "改回英文 1 处" 混在输出里 —— 一个英文标识符就这样留在了产品里。
    #  **一个"通过"如果盖住了一次回退，它就不是守卫。**
    #  所以这里把【具体哪个名字】改回英文逐个打出来，让人看得见、能去销账。
    # -----------------------------------------------------------------------
    $revNames = @{}; $revWhere = @{}; $revZhOf = @{}
    $doneLines = @{}
    foreach ($h in ($hits | Sort-Object Line,Col -Descending)) {
        if (-not $rev.ContainsKey($h.Name)) { continue }
        # 同一行一轮只改一处：坐标是按【改之前】那一行算的，改完长度就变了，
        # 同一行再改第二处会用错坐标（这也是坏掉派生层那个 bug 的成因之一）。
        # 剩下的下一轮再来，循环会兜住。
        if ($doneLines.ContainsKey($h.Line)) { continue }
        $idx = $h.Line - 1; $line = $lines[$idx]
        $lb = [System.Text.Encoding]::UTF8.GetBytes($line); $nb = [System.Text.Encoding]::UTF8.GetBytes($h.Name)
        $off = $h.Col - 1
        if ($off -lt 0 -or ($off + $nb.Length) -gt $lb.Length) { continue }
        $ok = $true; for ($i=0; $i -lt $nb.Length; $i++) { if ($lb[$off+$i] -ne $nb[$i]) { $ok=$false; break } }
        if (-not $ok) { continue }
        $ci = [System.Text.Encoding]::UTF8.GetString($lb,0,$off).Length
        $lines[$idx] = $line.Remove($ci,$h.Name.Length).Insert($ci,$rev[$h.Name]); $fixed++
        $revNames[$rev[$h.Name]] = $true
        $revWhere[$rev[$h.Name]] = ("第 {0} 行" -f $h.Line)
        $revZhOf[$rev[$h.Name]] = $h.Name          # 英文 -> 中文（§17.19.17.1 要拿它扫干净）
        $doneLines[$h.Line] = $true
    }
    # -----------------------------------------------------------------------
    #  §17.19.17.1 撤回必须【文件级一致】—— 编译器只看得见它**编到**的那几处。
    #
    #  实测（第 83 轮，monostate）：活代码里的 `单态` 被撤回英文，而 `#else`（非 C++20）
    #  分支编译不到、也就没人撤回，于是产品里【两种写法并存】：活代码 `monostate`、
    #  死代码 `单态`（一个全库没有定义的标识符）。全库照样编过 —— 因为那条分支永不编译；
    #  而 `<变体>` 的中文 API 其实是缺的（没有 `标准::单态`）。
    #  判据：**一次撤回 = 这个文件的一次改名撤销**，不是"改掉编译器报的那几处"。
    #  所以这里把该名字在本文件里的中文写法一次扫干净，并把"编译器看不见的处数"响亮打出来。
    # -----------------------------------------------------------------------
    $revExtra = @{}
    if ($revNames.Count) {
        $txt = ($lines -join "`n")
        foreach ($en in @($revNames.Keys)) {
            $zh = $revZhOf[$en]
            if (-not $zh) { continue }
            $rx = '(?<![\w])' + [regex]::Escape($zh) + '(?![\w])'
            $n  = [regex]::Matches($txt, $rx).Count
            if ($n -gt 0) { $txt = [regex]::Replace($txt, $rx, $en); $revExtra[$en] = $n }
        }
        if ($revExtra.Count) { $lines = $txt -split "`n" }
    }
    [System.IO.File]::WriteAllLines($outPath, $lines, $utf8)
    Write-Host ("  校对第 {0} 轮（测试#{1}）: 指出 {2} 处，改回英文 {3} 处" -f $round,($ti+1),$hits.Count,$fixed)
    if ($revNames.Count) {
        foreach ($rn in ($revNames.Keys | Sort-Object)) {
            $extra = ''
            if ($revExtra.ContainsKey($rn)) {
                $extra = ("；另有 {0} 处在【编译器看不见的分支】里残留，已一并改回（§17.19.17.1）" -f $revExtra[$rn])
            }
            Write-Host ("    ⚠ 改回英文: {0}（{1}）{2} —— 这是【欠账】，要么补前向声明/别名，要么登记进方案文档" -f `
                $rn, $revWhere[$rn], $extra) -ForegroundColor Yellow
        }
    }
    if ($fixed -eq 0) { break }
}
Remove-Item $probe -Force -ErrorAction SilentlyContinue

# ---------------------------------------------------------------------------
#  派生层必须在【编译器校对之后】才追加。
#  为什么：校对是按编译器给的【字节坐标】直接改文件，如果派生层已经在那儿，
#  它的中文标识符会被误当冲突位置改坏 —— 实测把「到达令牌」改成了「到」「达」碎片。
# ---------------------------------------------------------------------------
# extra：原样追加在文件最末的代码。用途：一个头里有【多个对外类】时，
# 主类由上面的机制生成，其余类与自由函数在这里手写（如 <mutex> 有 8 个公开类）。
# 这样不必为多类重构整张表，现有条目一行都不用改。
if ($spec.ContainsKey('noPub')) { $layer = '' }
$layerText = $layer
if ($spec.ContainsKey('extra')) { $layerText += "`n" + $spec.extra }
# ---------------------------------------------------------------------------
#  ⚠ 派生层必须插在【包含守卫的 #endif 之前】，不能追加到文件最末。
#
#  为什么（<shared_mutex> 实测踩到，一个【潜伏了很久】的 bug）：
#  MSVC 公开头的最末一行就是守卫的 `#endif // _XXX_`。原先把派生层 Append 在它之后，
#  于是「守卫守得住正文，守不住派生层」—— 同一个汉语头被包含两次时，
#  正文被守卫跳过，派生层却被编译第二遍：
#      error: 重定义（名字） '互斥量' / '独占锁' / '锁守卫'
#  单头测试永远照不出来；<共享互斥量> 同时包含 <互斥量> 与 <条件变量>，
#  而 <条件变量> 自己又包含 <互斥量> —— 同一头进两次，才把这个坑炸出来。
#  规则：**凡是我们往头文件里加东西，都要问一句"它在守卫里面吗"。**
# ---------------------------------------------------------------------------
$cur = [System.IO.File]::ReadAllText($outPath)
# ---------------------------------------------------------------------------
#  ⚠ 给【派生层】打一个显式标记（§16.26）。
#
#  为什么需要：产品里有两层，性质完全相反 ——
#    · 抄来那层（细节::）出现英文标识符 = **欠账**，必须消灭；
#    · 派生层（标准::）的英文标识符 = **有意的英文兼容层**（铁律 3），必须存在。
#  没有标记时，机器（和我）都分不清一个残留英文名属于哪一层：
#  例如 <互斥量> 里的 `lock_guard` 是派生层有意补回的英文名（不是欠账），
#  而 `_Unlock_one_guard` 是抄来那层没翻的内部件（是欠账）—— 只看名字看不出来。
#  所以边界必须由生成器【自己声明】，而不是靠人猜或靠"它在文件后半段"这类位置特征。
#  审计脚本 tools\audit_hanhua.ps1 就按这一行切分两层。
# ---------------------------------------------------------------------------
$layerMark = '// [ZH-DERIVE-LAYER] 汉语派生层（英文兼容层）从这一行开始 —— 本行【以上】属抄来那层，有英文名就是欠账'
if ($layerText.Trim().Length -gt 0 -and $layerText -notmatch 'ZH-DERIVE-LAYER') {
    $layerText = $layerMark + "`r`n" + $layerText.TrimStart("`r", "`n")
}
$endifs = [regex]::Matches($cur, '(?m)^[ \t]*#endif\b')
if ($endifs.Count -gt 0) {
    $pos = $endifs[$endifs.Count - 1].Index      # 最后一个 #endif = 包含守卫那一个
    # 插到它前面（保留原文一切字节不变，只做插入）
    $cur = $cur.Substring(0, $pos) + $layerText.TrimStart("`r", "`n") + "`r`n`r`n" + $cur.Substring($pos)
    [System.IO.File]::WriteAllText($outPath, $cur, $utf8)
} else {
    Write-Host "  ⚠ 没找到守卫 #endif，派生层只能追加在文件末" -ForegroundColor Yellow
    [System.IO.File]::AppendAllText($outPath, $layerText, $utf8)
}
Write-Host "  步6 派生层 + 英文转发 $($spec.derive.Count) 条$(if ($spec.deriveTypes) { " + 嵌套类型 $($spec.deriveTypes.Count) 条" })$(if ($spec.stdHash) { ' + std::hash 特化' })"
# ---------------------------------------------------------------------------
#  §17.27.13 守卫（第三层）："登记≠落地"要看【产品正文】，不是抄来那层
#
#  实测动机（§17.27.12）：`内存内部件` 的 `_Copy_memcpy_common` 在抄来那层**命中并替换了**，
#  但产品里**仍有一处英文**、中文只有一处 —— 第一层守卫（0 命中即 throw）看不见这种"部分落地"。
#  本守卫按 §17.27.5 的两阶段规矩先做【可见】：逐条登记检查"中文名到底进没进产品正文"。
#  清单清零后再升级为 ❌（否则会拿"守卫替人做决定"）。
# ---------------------------------------------------------------------------
if ($landedPairs.Count) {
    $prodText = [System.IO.File]::ReadAllText($outPath)
    $notLanded = @()
    foreach ($pr in $landedPairs) {
        if ($prodText.IndexOf($pr.Zh) -lt 0) {
            $notLanded += ("  {0} : {1} 表 {2} -> {3} —— 抄来那层命中过，但【产品正文】里没有这个中文名" -f $Header, $pr.Kind, $pr.En, $pr.Zh)
        }
    }
    if ($notLanded.Count) {
        Write-Host ("⚠ 登记≠落地·第三层（§17.27.13）：{0} 有 {1} 条中文名没进产品" -f $Header, $notLanded.Count) -ForegroundColor Yellow
        $notLanded | ForEach-Object { Write-Host $_ -ForegroundColor Yellow }
    } else {
        Write-Host ("  第三层守卫: 通过（{0} 条登记的中文名都在产品正文里）" -f $landedPairs.Count) -ForegroundColor Green
    }
}

# ---------------------------------------------------------------------------
#  守卫：「乙」的机器判据（§16.29）—— 只写【中文头】，真英文头必须已经进来。
#
#  为什么必须【自动派生】而不是手写一张表：
#    条目的 `realInclude` 是数据，而真英文头的包含守卫宏可以**从真头读出来**
#    （与步 1 换守卫用的是同一套判据）。手写"中文头 -> 宏名"的映射一定会漂移
#    —— 本项目已经因为手写清单栽过多次（§3.11 / §16.31）。
#
#  做法：对 realInclude 里的每个英文头 X，读出它的包含守卫宏 G，
#  然后编一个【只 `#包含 <中文头>`】的探针，用 `#ifndef G -> #error` 断言 G 已定义。
#  （`#ifndef` / `#error` 用英文写即可 —— 中文关键字是叠加的，英文照样有效。）
#
#  ⚠ 这条守卫是 §16.29 那件事的**唯一**机器保证：
#    只给 <向量> 写一条专门测试是不够的，其余 20 个头的「乙」就成了"我记得"。
# ---------------------------------------------------------------------------
if ($spec.realInclude) {
    $probe2 = Join-Path $env:TEMP ('zh2ri_' + [guid]::NewGuid().ToString('N').Substring(0, 8) + '.cpp')
    $lines2 = @("#包含 <$($spec.zh)>")
    $riChecked = 0
    $riSkipped = @()
    foreach ($ri in @($spec.realInclude)) {
        $riPath = Join-Path $vsInc $ri
        if (-not (Test-Path $riPath)) { $riSkipped += $ri; continue }
        $riText = [System.IO.File]::ReadAllText($riPath)
        $gm2 = [regex]::Match($riText, '(?m)^#ifndef\s+([A-Za-z_][A-Za-z0-9_]*)\s*\r?\n#define\s+\1\b')
        if (-not $gm2.Success) { $riSkipped += "$ri(无守卫宏)"; continue }
        $g2 = $gm2.Groups[1].Value
        $lines2 += "#ifndef $g2"
        $lines2 += "#error 只写 <$($spec.zh)> 没能把真 <$ri> 引进来（方案 §16.29「乙」）"
        $lines2 += "#endif"
        $riChecked++
    }
    if ($riSkipped.Count) {
        Write-Host ("  ⚠ 顺带引真头探针: 跳过 {0}（读不出包含守卫宏，无法断言）" -f ($riSkipped -join ', ')) -ForegroundColor Yellow
    }
    if ($riChecked -gt 0) {
        $lines2 += "整数 主函数(){ 返回 0; }"
        [System.IO.File]::WriteAllText($probe2, ($lines2 -join "`n") + "`n", $utf8)
        $raw2 = & cmd /c "`"$cxx`" -std=c++20 -isystem`"$out`" -fsyntax-only `"$probe2`" 2>&1"
        if ($LASTEXITCODE -ne 0) {
            Remove-Item $probe2 -Force -ErrorAction SilentlyContinue
            Write-Host ("  ❌ 顺带引真头探针 FAIL（只写 <{0}> 时真头没进来）:" -f $spec.zh) -ForegroundColor Red
            foreach ($l in @($raw2 | Select-Object -First 4)) { Write-Host ("      " + ([string]$l).Trim()) -ForegroundColor Red }
            throw "「乙」探针失败：realInclude 没生效（去掉 realInclude 这条测试必须会红）"
        }
        Remove-Item $probe2 -Force -ErrorAction SilentlyContinue
        Write-Host ("  顺带引真头探针: 通过（只写中文头时 {0} 个真头已在）" -f $riChecked) -ForegroundColor Green
    }
}

# --- 最终验证：中文名 / 英文名 / 与 std 并存 ---
Write-Host ""
Write-Host "=== 验证 ===" -ForegroundColor Cyan
$t = Join-Path $root 'build\_zh2'
if ($t -and (Test-Path $t)) { Remove-Item -Recurse -Force $t -ErrorAction SilentlyContinue; if (Test-Path $t) { Remove-Item -Force (Join-Path $t 't.exe') -ErrorAction SilentlyContinue } }
New-Item -ItemType Directory -Force $t | Out-Null
$cases = Repair-Pairs $spec.tests
Write-Host ("  测试用例数: {0}" -f @($cases).Count)
if (@($cases).Count -le 0) { throw "用例数为 0 —— 测试没跑起来（§15.3：跑 0 条的通过不是通过）" }
if ($env:ZH_NO_TEST -eq '1') { Write-Host '  （预热第一遍：跳过测试，只落盘）' } else {
$pass = 0
foreach ($c in $cases) {
    $src = Join-Path $t 't.cpp'
    # ⚠⚠ 测试正文里的反引号-n 是【字面两个字符】（条目用单引号写的），必须先转成真换行！
    #   否则整条测试会写成一行，clang 把 `#include` 之后的全当"多余记号"（只警告）
    #   -> 函数体被吞掉 -> 测试文件只剩一个 include -> 【所有 4/4 都是空测】。
    #   实测：这正是本条修复的原因。用 [char]96 + 'n' 拼出那两个字面字符。
    [System.IO.File]::WriteAllText($src, $c[1].Replace([char]96 + 'n', "`n") + "`n", $utf8)
    $exeRun = Join-Path $env:TEMP ('zh2run_' + [guid]::NewGuid().ToString('N') + '.exe')
    & cmd /c "`"$cxx`" -std=c++20 -isystem`"$out`" `"$src`" -o `"$exeRun`" > `"$t\o.txt`" 2>&1"
    $ccRc  = $LASTEXITCODE
    $runRc = -1
    if ($ccRc -eq 0) {
        # ⚠ 不要用 `Start-Process -PassThru` + `WaitForExit()` 取 `.ExitCode`：
        #   在 Windows PowerShell 5.1 下该属性会是 $null，于是判据 `$null -ne 0` 成立
        #   -> 5/5 全报「运行返回 （空）」，全部是【假 FAIL】。
        #   2026 实测踩到：用 cmd /c powershell -File 调本脚本时白查了一轮（见方案 §17.19.16.1）。
        #   `& $exeRun` + `$LASTEXITCODE` 在 5.1 与 7.x 下都准（代价：不再有 20 秒超时）。
        & $exeRun
        $runRc = $LASTEXITCODE
    }
    Remove-Item -Force $exeRun -ErrorAction SilentlyContinue
    if ($ccRc -eq 0 -and $runRc -eq 0) { Write-Host ("  [ok]   {0}" -f $c[0]); $pass++ }
    else {
        if ($ccRc -eq 0 -and $runRc -ne 0) { Write-Host ("  [FAIL] {0} —— 运行返回 {1}（能编过/能链上，但跑不对）" -f $c[0], $runRc) -ForegroundColor Yellow }
        else { Write-Host ("  [FAIL] {0}" -f $c[0]) -ForegroundColor Yellow }
        Get-Content "$t\o.txt" -ErrorAction SilentlyContinue | Where-Object { $_ -match 'error:' } |
            Select-Object -First 3 | ForEach-Object { Write-Host ("         " + ([string]$_).Trim()) }
    }
}
Write-Host ("  {0} / {1}" -f $pass, $cases.Count)
}
Remove-Item -Recurse -Force $t -ErrorAction SilentlyContinue




